def _build_avatar_identity_contract(profile=None, palette=None):
    profile = dict(profile or {})
    runtime_appearance = _normalize_runtime_appearance(
        dict(profile.get("runtime_appearance") or {}),
        palette=[
            str((palette or {}).get("skin_hex", "#f2d2c2") or "#f2d2c2"),
            str((palette or {}).get("eye_hex", "#5c8f57") or "#5c8f57"),
            str((palette or {}).get("hair_hex", "#d8c08f") or "#d8c08f"),
        ],
        fallback_asset_key="aurion-signature"
    )
    body_morph = dict(profile.get("body_morph") or {})
    body_physics = dict(profile.get("body_physics") or {})
    palette = dict(palette or {})
    return {
        "mode": "unreal_reference_realism",
        "avatar_preset": "unreal_realistic_aurion",
        "body_preset": "soft_curvy",
        "reference_palette": palette,
        "reference_sources": _summarize_avatar_reference_sources(force_refresh=False),
        "runtime_appearance": runtime_appearance,
        "body_morph": body_morph,
        "body_physics": body_physics,
        "hair_color": str(runtime_appearance.get("hair_color", "blonde") or "blonde")[:40],
        "eye_color": str(runtime_appearance.get("eye_color", "green") or "green")[:40],
        "accent_color": str(runtime_appearance.get("accent_color", "midnight blue") or "midnight blue")[:40],
        "identity_lock": True,
        "last_applied_at": datetime.utcnow().isoformat(),
    }

