@app.route('/api/avatar/model/upload', methods=['POST'])
def api_avatar_model_upload():
    try:
        privileged = _require_local_privileged_access()
        if privileged is not None:
            return privileged
        if 'model' not in request.files:
            return jsonify({"success": False, "error": "No model file provided."}), 400
        file = request.files['model']
        if not file or not str(file.filename or '').strip():
            return jsonify({"success": False, "error": "No model file selected."}), 400
        source_name = Path(str(file.filename)).name
        suffix = Path(source_name).suffix.lower()
        if suffix not in _AURION_MODEL_EXTENSIONS:
            return jsonify({"success": False, "error": "Please upload a supported avatar/model asset: .glb, .gltf, .vrm, .fbx, .obj, .blend, .abc, .usd, .usda, .usdc, or .dae."}), 400
        file_data = file.read()
        if not file_data:
            return jsonify({"success": False, "error": "Uploaded model file was empty."}), 400
        ok_magic, reason = _validate_uploaded_magic_bytes(source_name, file_data)
        if not ok_magic:
            return jsonify({"success": False, "error": reason}), 400
        _AURION_MODEL_DIR.mkdir(parents=True, exist_ok=True)
        make_default = str(request.form.get("set_default", "1")).strip().lower() not in {"0", "false", "no", "off"}
        source_stem = re.sub(r"[^a-zA-Z0-9._-]+", "-", Path(source_name).stem).strip("-.") or f"aurion-avatar-{int(time.time())}"
        target_filename = f"{source_stem}{suffix}"
        target_path = _AURION_MODEL_DIR / target_filename
        target_path.write_bytes(file_data)
        default_path = target_path
        if make_default:
            default_path = _AURION_MODEL_DIR / f"{_AURION_MODEL_BASENAME}{suffix}"
            if target_path.resolve() != default_path.resolve():
                shutil.copy2(str(target_path), str(default_path))
        _record_runtime_event("avatar-upload", f"Avatar model updated: {target_path.name}", source="api")
        return jsonify({
            "success": True,
            "url": _make_aurion_default_model_url(default_path),
            "filename": default_path.name,
            "stored_filename": target_path.name,
            "set_default": make_default,
            "model": _build_avatar_model_record(target_path),
            "default_model": _build_avatar_model_record(default_path)
        })
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

