@app.route('/api/avatar/unreal/apply-reference', methods=['POST'])
def api_avatar_unreal_apply_reference():
    try:
        privileged = _require_local_privileged_access()
        if privileged is not None:
            return privileged
        data = request.get_json(force=True) or {}
        refresh_refs = bool(data.get("refresh", True))
        palette = _extract_avatar_reference_palette(force_refresh=refresh_refs)
        ref = _find_latest_avatar_reference_image()
        if not ref:
            return jsonify({"success": False, "error": "No reference image found for Unreal-driven customization."}), 404
        copied_ref = _copy_reference_image_to_unreal_source_assets(ref, target_name="aurion-reference-latest" + ref.suffix.lower())
        profile = _infer_aurion_unreal_identity_profile(palette)
        identity_contract = _build_avatar_identity_contract(profile=profile, palette=palette)
        identity_contract["reference_sources"] = _summarize_avatar_reference_sources(force_refresh=refresh_refs)
        identity_contract["reference_image"] = {
            "selected_file": ref.name,
            "copied_to_unreal": str(copied_ref),
        }

        wardrobe = _resolve_wardrobe_state()
        runtime_mesh_source = str((dict(identity_contract.get("runtime_appearance") or {})).get("mesh_source", "") or "").strip()
        runtime_mesh_hint = str((dict(identity_contract.get("runtime_appearance") or {})).get("mesh_hint", "") or "").strip()
        if not runtime_mesh_source:
            runtime_mesh_source = "aurion-meshy-baroque.glb"
        if not runtime_mesh_hint:
            runtime_mesh_hint = str((Path(str(_resolve_unreal_toolchain_state().get("source_assets_root") or "").strip()) / runtime_mesh_source))
        runtime_mesh_candidate = Path(runtime_mesh_source).name
        if Path(runtime_mesh_candidate).suffix.lower() in _AURION_MODEL_EXTENSIONS:
            identity_contract.setdefault("runtime_appearance", {})
            identity_contract["runtime_appearance"]["mesh_source"] = runtime_mesh_candidate
            identity_contract["runtime_appearance"]["mesh_hint"] = str(_AURION_MODEL_DIR / runtime_mesh_candidate)
            runtime_mesh_source = runtime_mesh_candidate
            runtime_mesh_hint = identity_contract["runtime_appearance"]["mesh_hint"]

        wardrobe["runtime_registry"]["aurion-signature"] = {
            "label": "Aurion Signature Meshy Baroque",
            "mesh_source": runtime_mesh_source,
            "mesh_hint": runtime_mesh_hint,
            "style_tags": ["unreal", "realistic", "signature", "aurion", "metahuman", "baroque", "meshy", "hero"],
            "supports": {
                "outfit_swap": True,
                "colorways": True,
                "hair_color": True,
                "eye_color": True
            }
        }
        active_outfit = dict(wardrobe.get("active_outfit") or {})
        active_outfit["runtime"] = dict(identity_contract.get("runtime_appearance") or {})
        if runtime_mesh_source:
            active_outfit["runtime"]["mesh_source"] = runtime_mesh_source
        if runtime_mesh_hint:
            active_outfit["runtime"]["mesh_hint"] = runtime_mesh_hint
        active_outfit["notes"] = f"{str(active_outfit.get('notes', '') or '').strip()} Unreal-driven realistic identity synced from latest reference image.".strip()
        wardrobe["active_outfit"] = active_outfit
        wardrobe["active_runtime_appearance"] = _resolve_wardrobe_runtime_appearance(active_outfit, wardrobe.get("runtime_registry"))
        wardrobe["identity_contract"] = identity_contract
        wardrobe["last_updated_at"] = datetime.utcnow().isoformat()
        app_state["wardrobe"] = wardrobe

        avatar_body = _resolve_avatar_body_state()
        avatar_body["morph"].update(dict(identity_contract.get("body_morph") or {}))
        avatar_body["physics"].update(dict(identity_contract.get("body_physics") or {}))
        avatar_body["identity_contract"] = identity_contract
        avatar_body["last_updated_at"] = datetime.utcnow().isoformat()
        app_state["avatar_body"] = avatar_body

        player_character = _resolve_player_character_state()

        unreal_state = _resolve_unreal_toolchain_state()
        unreal_state["last_project_sync_at"] = datetime.utcnow().isoformat()
        unreal_state["last_reference_image"] = str(copied_ref)
        unreal_state["last_avatar_sync_mode"] = "unreal_reference_realism"
        app_state["unreal_toolchain"] = unreal_state

        _record_runtime_event(
            "avatar-unreal",
            "Applied Unreal-driven Aurion reference profile",
            detail=f"Reference image copied to {copied_ref} and runtime appearance switched to Unreal realistic signature.",
            source="api"
        )
        return jsonify({
            "success": True,
            "mode": "unreal_reference_realism",
            "reference_image": str(copied_ref),
            "palette": palette,
            "runtime_appearance": wardrobe.get("active_runtime_appearance"),
            "avatar_body": avatar_body,
            "player_character": player_character,
            "unreal_toolchain": _scan_unreal_toolchain_state()
        })
    except Exception as e:
        _log_exception("Avatar Unreal Apply Reference", e)
        return jsonify({"success": False, "error": str(e)}), 500

def _log_exception(context, exc):
    print(f"[{context}] {exc}")
    if app.config.get('DEBUG'):
        import traceback
        traceback.print_exc()

def _sanitize_error_message(error, fallback="Internal server error"):
    if app.config.get('DEBUG'):
        return str(error)
    text = str(error or "").strip()
    if not text:
        return fallback
    lowered = text.lower()
    redaction_signals = (
        "\\", "/", "traceback", "filenotfound", "permissionerror", "winerror",
        "no such file", "errno", "line ", "__file__", "path", "directory", "drive"
    )
    if any(signal in lowered for signal in redaction_signals):
        return fallback
    return text[:240]

def _server_error_response(error, fallback="Internal server error"):
    return jsonify({"success": False, "error": _sanitize_error_message(error, fallback)}), 500

def _relative_workspace_path(value):
    try:
        workspace_root = Path(str(app_state.get("creative_workspace") or _resolve_creative_workspace_path())).resolve()
        target = Path(str(value or "")).resolve()
        return str(target.relative_to(workspace_root)).replace("\\", "/")
    except Exception:
        return Path(str(value or "")).name

