def _validate_uploaded_magic_bytes(filename: str, file_data: bytes):
    suffix = Path(str(filename or "")).suffix.lower()
    if suffix == ".glb":
        return file_data[:4] == b"glTF", "GLB files must start with glTF header bytes."
    if suffix == ".gltf":
        stripped = bytes(file_data[:256]).lstrip()
        return stripped.startswith(b"{"), "GLTF files must be JSON text."
    if suffix == ".vrm":
        return file_data[:4] == b"glTF", "VRM files must use the GLB container header."
    if suffix in {".fbx", ".obj", ".blend", ".abc", ".usd", ".usda", ".usdc", ".dae"}:
        return True, ""
    return False, "Unsupported model file type."

def _api_key_matches(provided: str) -> bool:
    expected = str(_API_KEY or "")
    candidate = str(provided or "")
    if not expected:
        return False
    return hmac.compare_digest(candidate.encode("utf-8"), expected.encode("utf-8"))

def _is_aurion_identity_prompt(text):
    lowered = str(text or "").strip().lower()
    if not lowered:
        return False
    has_version_terms = bool(re.search(r"\b(v1|v2|v3|v4|version|split|separate|multiple personalities)\b", lowered))
    has_identity_terms = bool(re.search(
        r"\b(who are you|what are you|your identity|are you split|are you separate|"
        r"which version are you|multiple personalities)\b",
        lowered,
    ))
    return has_version_terms and has_identity_terms

def _extract_media_action_request(user_text):
    text = str(user_text or "").strip()
    if not text:
        return None
    lower = text.lower()

    # Local music commands (D:\Music)
    local_music_kw = re.search(
        r"\b(?:play|listen|put\s+on|queue)\b.{0,60}?\b(?:local|from\s+(?:my\s+)?(?:pc|computer|files?|library|music))\b",
        lower
    )
    if local_music_kw:
        q = re.sub(r"\b(play|listen\s+to|put\s+on|queue|local|from\s+(my\s+)?(pc|computer|files?|library|music))\b", "", lower).strip(" .,!?:;\"'")
        return {"type": "local_music", "query": q}

    if "plex" not in lower:
        return None

    listen_match = re.search(r"\b(?:listen|play)\s+(?:to\s+)?(.+?)\s+on\s+plex\b", lower)
    if listen_match:
        query = listen_match.group(1).strip(" .,!?:;\"'")
        return {"type": "plex_play_music", "query": query, "max_items": 10}

    watch_match = re.search(r"\b(?:watch|play)\s+(?:the\s+)?(.+?)\s+on\s+plex\b", lower)
    if watch_match:
        query = watch_match.group(1).strip(" .,!?:;\"'")
        return {"type": "plex_play_video", "query": query, "max_items": 10}

    if re.search(r"\b(play|listen)\b.*\b(music|song|playlist|track)\b.*\bon\s+plex\b", lower):
        return {"type": "plex_play_music", "query": "", "max_items": 10}
    if re.search(r"\b(play|watch)\b.*\b(movie|show|video)\b.*\bon\s+plex\b", lower):
        return {"type": "plex_play_video", "query": "", "max_items": 10}
    return None

