def _hydrate_twilio_env_from_local_sources(force=False):
    global _twilio_env_hydrated_at
    now = datetime.utcnow()
    if not force and _twilio_env_hydrated_at and (now - _twilio_env_hydrated_at).total_seconds() < 45:
        return

    sid = str(os.getenv("TWILIO_ACCOUNT_SID", "")).strip()
    token = str(os.getenv("TWILIO_AUTH_TOKEN", "")).strip()
    from_number = str(os.getenv("TWILIO_FROM_NUMBER", "")).strip()
    if sid and token and from_number:
        _twilio_env_hydrated_at = now
        return

    merged = {}
    merged.update(_load_twilio_config_from_downloads())

    alias_map = {
        "TWILIO_ACCOUNT_SID": ["TWILIO_ACCOUNT_SID", "AURION_TWILIO_ACCOUNT_SID", "account_sid", "twilio_account_sid"],
        "TWILIO_AUTH_TOKEN": ["TWILIO_AUTH_TOKEN", "AURION_TWILIO_AUTH_TOKEN", "auth_token", "twilio_auth_token"],
        "TWILIO_FROM_NUMBER": ["TWILIO_FROM_NUMBER", "AURION_TWILIO_FROM_NUMBER", "from_number", "twilio_from_number"],
    }

    for target, aliases in alias_map.items():
        existing = str(os.getenv(target, "")).strip()
        if existing:
            continue
        for alias in aliases:
            candidate = str(merged.get(alias, "")).strip()
            if candidate:
                os.environ[target] = candidate
                break
    _twilio_env_hydrated_at = now

