def _is_preferred_feminine_voice_name(name):
    n = str(name or "").lower()
    feminine_markers = (
        "aria", "zira", "jenny", "sara", "sonia", "female", "woman", "girl",
        "eva", "emma", "olivia", "mia", "amy", "cora", "luna"
    )
    return any(marker in n for marker in feminine_markers)

def _is_english_voice(voice_obj):
    try:
        name = str(getattr(voice_obj, "name", "")).lower()
        vid = str(getattr(voice_obj, "id", "")).lower()
        langs = getattr(voice_obj, "languages", []) or []
        lang_text = " ".join([str(l).lower() for l in langs])
        return ("english" in name) or ("en-" in vid) or ("en_" in vid) or ("en-us" in vid) or ("en" in lang_text)
    except Exception:
        return False

def _pick_preferred_server_voice_index(voices, fallback_index=0):
    if not voices:
        return 0
    feminine_english = [i for i, v in enumerate(voices) if _is_preferred_feminine_voice_name(getattr(v, "name", "")) and _is_english_voice(v)]
    if feminine_english:
        for i in feminine_english:
            if "aria" in str(getattr(voices[i], "name", "")).lower():
                return i
        return feminine_english[0]
    for i, v in enumerate(voices):
        if _is_preferred_feminine_voice_name(getattr(v, "name", "")):
            return i
    for i, v in enumerate(voices):
        vid = str(getattr(v, "id", "")).lower()
        if "zira" in vid or "female" in vid:
            return i
    return max(0, min(len(voices) - 1, int(fallback_index)))

