# All window IDs flattened for quick lookup
def _get_all_windows():
    wins = {}
    for lvl in HOME_LAYOUT["levels"].values():
        for rid, room in lvl.get("rooms", {}).items():
            for w in room.get("windows", []):
                wins[w["id"]] = {"room": rid, **w}
    return wins


def _get_all_doors():
    doors = {}
    for idx, conn in enumerate(list(HOME_CONNECTIONS or []), start=1):
        kind = str((conn or {}).get("kind", "") or "").strip().lower()
        if kind not in HOME_DOOR_CONNECTION_KINDS:
            continue
        from_id = str((conn or {}).get("from", "") or "").strip()
        to_id = str((conn or {}).get("to", "") or "").strip()
        if not from_id or not to_id:
            continue
        door_id = str((conn or {}).get("id", "") or "").strip() or f"{from_id}__{to_id}__door_{idx}"
        doors[door_id] = {
            "id": door_id,
            "from": from_id,
            "to": to_id,
            "kind": kind,
            "label": str((conn or {}).get("label", "") or f"{from_id} to {to_id}"),
            "open": bool((conn or {}).get("open", False)),
        }
    return doors


def _get_home_room_index():
    rooms = {}
    for level_id, level in HOME_LAYOUT.get("levels", {}).items():
        for room_id, room in dict(level.get("rooms") or {}).items():
            rooms[room_id] = {
                "id": room_id,
                "level": level_id,
                "level_name": str(level.get("name", level_id) or level_id),
                **dict(room or {}),
            }
    return rooms


def _get_home_zone_index():
    zones = {}
    for zone in list(HOME_YARD_ZONES or []):
        item = dict(zone or {})
        zone_id = str(item.get("id", "") or "").strip()
        if zone_id:
            zones[zone_id] = item
    return zones


def _navigation_lookup_key(value):
    return re.sub(r"[^a-z0-9]+", "-", str(value or "").strip().lower()).strip("-")


def _resolve_navigation_target_id(target_id, rooms=None, zones=None, places=None, prefer=None):
    rooms = dict(rooms or _get_home_room_index())
    zones = dict(zones or _get_home_zone_index())
    world_builder = _resolve_world_builder_state()
    places = dict(places or {str((row or {}).get("id", "") or "").strip(): dict(row or {}) for row in list(world_builder.get("places") or [])})
    target_id = str(target_id or "").strip()
    if not target_id:
        return ""
    if prefer == "place" and target_id in places:
        return target_id
    if prefer == "zone" and target_id in zones:
        return target_id
    if prefer == "room" and target_id in rooms:
        return target_id

    lookup = _navigation_lookup_key(target_id)
    ordered = []
    if prefer == "place":
        ordered = [places, zones, rooms]
    elif prefer == "zone":
        ordered = [zones, places, rooms]
    else:
        ordered = [rooms, zones, places]
    for bucket in ordered:
        for key in bucket.keys():
            if _navigation_lookup_key(key) == lookup:
                return key
    if target_id in rooms or target_id in zones or target_id in places:
        return target_id
    return target_id


def _navigation_posture_from_actions(actions):
    actions = set(actions or [])
    if "sleep" in actions or "lie_down" in actions:
        return "lie"
    if "sit" in actions or "lounge" in actions or "read" in actions or "strategize" in actions:
        return "sit"
    return "stand"


def _build_room_affordances(room_id, room):
    room = dict(room or {})
    room_type = str(room.get("type", "") or "").strip().lower()
    name_bits = f"{room_id} {room.get('name', '')}".lower()
    features = set(str(x).strip().lower() for x in list(room.get("features") or []) if str(x).strip())
    actions = {"observe", "move_through"}
