def _build_place_affordances(place_id, place):
    place = dict(place or {})
    kind = str(place.get("kind", "place") or "place").strip().lower()
    actions = {str(x).strip().lower() for x in list(place.get("affordances") or []) if str(x).strip()}
    if not actions:
        actions = {"observe", "explore"}
    interaction_points = [str(x).strip()[:60] for x in list(place.get("interaction_points") or []) if str(x).strip()][:8]
    comfort_rating = float(place.get("comfort_rating", 6.8) or 6.8)
    acoustic_profile = str(place.get("acoustics", "") or "").strip()
    lighting_profile = str(place.get("lighting", "") or "").strip()
    cover = str(place.get("cover", "") or "").strip().lower()

    defaults = {
        "home": ({"sit", "lounge", "recover"}, 9.0, "warm domestic ambience", "balanced indoor daylight", "full"),
        "yard": ({"roam", "observe", "weather_exposure"}, 7.0, "open exterior ambience", "natural sky light", "open"),
        "garden": ({"garden", "tend", "harvest"}, 8.1, "soft exterior detail", "sun-shade mixed light", "open"),
        "road": ({"walk", "drive", "transition"}, 5.2, "traffic and movement wash", "dynamic exterior light", "open"),
        "city": ({"explore", "socialize", "shop"}, 6.5, "dense urban layers", "mixed practical lighting", "partial"),
        "forest": ({"roam", "hide", "observe", "breathe"}, 8.0, "canopy-filtered natural dampening", "dappled canopy light", "partial"),
        "coast": ({"observe", "walk", "rest"}, 7.7, "surf and wind field", "broad reflected light", "open"),
        "lab": ({"experiment", "analyze", "calibrate"}, 7.2, "instrumental quiet", "precision task lighting", "full"),
    }
    default_actions, default_comfort, default_acoustics, default_lighting, default_cover = defaults.get(kind, (set(), 6.8, "mixed ambience", "contextual light", "partial"))
    actions.update(default_actions)
    if not acoustic_profile:
        acoustic_profile = default_acoustics
    if not lighting_profile:
        lighting_profile = default_lighting
    if not cover:
        cover = default_cover

    action_list = sorted(actions)
    return {
        "actions": action_list,
        "interaction_points": interaction_points,
        "preferred_posture": _navigation_posture_from_actions(action_list),
        "comfort_rating": round(comfort_rating if comfort_rating else default_comfort, 1),
        "acoustic_profile": acoustic_profile,
        "lighting_profile": lighting_profile,
        "cover": cover,
    }


def _build_navigation_render_profile(location_id, node_kind, source):
    source = dict(source or {}) if isinstance(source, dict) else {}
    location_bits = f"{location_id} {source.get('name', '') if isinstance(source, dict) else ''}".lower()
    profile = {
        "fidelity_tier": "standard",
        "streaming_priority": "medium",
        "surface_materials": ["paint", "fabric", "wood"],
        "niagara_fx": [],
        "reflection_budget": "medium",
        "shadow_priority": "medium",
        "dimensionality": "3d",
        "render_medium": "world_geometry",
        "flat_exception": False,
    }
    if node_kind == "room":
        if any(token in location_bits for token in ("living", "master_bedroom", "library", "science_lab", "arcade", "board_game")):
            profile.update({
                "fidelity_tier": "hero",
                "streaming_priority": "critical",
                "reflection_budget": "high",
                "shadow_priority": "high",
            })
        elif "utility" in location_bits or "bathroom" in location_bits:
            profile.update({
                "fidelity_tier": "premium",
                "streaming_priority": "high",
                "surface_materials": ["tile", "metal", "paint"],
            })
        elif "kitchen" in location_bits or "dining" in location_bits:
            profile.update({
                "fidelity_tier": "premium",
                "streaming_priority": "high",
                "surface_materials": ["stone", "wood", "glass", "metal"],
                "reflection_budget": "high",
            })
        elif "bedroom" in location_bits:
            profile.update({
                "fidelity_tier": "hero",
                "streaming_priority": "high",
                "surface_materials": ["fabric", "wood", "glass"],
            })
    elif node_kind == "yard_zone":
        profile.update({
            "fidelity_tier": "premium",
            "streaming_priority": "high",
            "surface_materials": ["foliage", "soil", "stone"],
            "niagara_fx": ["wind", "ambient_pollen"],
            "reflection_budget": "low",
        })
        if "garden" in location_bits or "back_yard" in location_bits:
            profile["fidelity_tier"] = "hero"
            profile["streaming_priority"] = "critical"
        if "driveway" in location_bits:
            profile["surface_materials"] = ["asphalt", "concrete", "paint"]
    else:
        kind = str((source or {}).get("kind", node_kind) if isinstance(source, dict) else node_kind).lower()
        if kind in {"home", "forest", "coast", "city", "lab", "garden"}:
            profile.update({
                "fidelity_tier": "hero",
                "streaming_priority": "critical",
                "surface_materials": ["foliage", "stone", "glass", "fabric"] if kind != "lab" else ["metal", "glass", "polymer"],
                "niagara_fx": ["wind", "mist"] if kind in {"forest", "coast", "garden"} else [],
                "reflection_budget": "high",
                "shadow_priority": "high",
            })
    flat_tokens = {
        "paper", "page", "drawing", "drawings", "sketch", "sketchbook", "note", "notes",
        "letter", "document", "blueprint", "poster", "print", "painting", "canvas", "map", "photo"
    }
    source_text = " ".join(
        str(source.get(key, "") or "")
        for key in ("name", "kind", "summary", "render_medium", "dimensionality")
    ).lower()
    source_tags = {
        str(x).strip().lower()
        for key in ("tags", "affordances", "interaction_points")
        for x in list(source.get(key) or [])
        if str(x).strip()
    }
    explicit_medium = str(source.get("render_medium", "") or "").strip().lower()
    explicit_dimensionality = str(source.get("dimensionality", "") or "").strip().lower()
    is_flat_exception = (
        explicit_medium in {"flat", "2d", "2d-embedded", "paper", "drawing"}
        or explicit_dimensionality in {"2d", "flat", "2d-embedded"}
        or any(token in source_text for token in flat_tokens)
        or bool(flat_tokens.intersection(source_tags))
    )
    if is_flat_exception and node_kind not in {"room", "yard_zone"}:
        profile.update({
            "dimensionality": "2d-embedded",
            "render_medium": "paper_flat_artifact",
            "flat_exception": True,
            "reflection_budget": "low",
            "shadow_priority": "low",
        })
    return profile


def _get_navigation_node_snapshot(location_id, rooms=None, zones=None, places=None):
    rooms = dict(rooms or _get_home_room_index())
    zones = dict(zones or _get_home_zone_index())
    world_builder = _resolve_world_builder_state()
    places = dict(places or {str((row or {}).get("id", "") or "").strip(): dict(row or {}) for row in list(world_builder.get("places") or [])})
    location_id = _resolve_navigation_target_id(location_id, rooms=rooms, zones=zones, places=places)
    if location_id in rooms:
        room = dict(rooms.get(location_id) or {})
        affordances = _build_room_affordances(location_id, room)
        return {
            "id": location_id,
            "kind": "room",
            "label": str(room.get("name", location_id) or location_id),
            "level": str(room.get("level", "lower") or "lower"),
            "elevation_ft": float((HOME_LAYOUT.get("levels", {}).get(str(room.get("level", "lower")), {}) or {}).get("elevation_ft", 0.0) or 0.0),
            "summary": str(room.get("desc", "") or ""),
            "windows": [dict(w or {}) for w in list(room.get("windows") or [])],
            "affordances": affordances,
            "render_profile": _build_navigation_render_profile(location_id, "room", room),
        }
    if location_id in zones:
        zone = dict(zones.get(location_id) or {})
        affordances = _build_zone_affordances(location_id, zone)
        return {
            "id": location_id,
            "kind": "yard_zone",
            "label": str(zone.get("name", location_id) or location_id),
            "level": "outdoor",
            "elevation_ft": 0.0,
            "summary": str(zone.get("desc", "") or ""),
            "windows": [],
            "affordances": affordances,
            "render_profile": _build_navigation_render_profile(location_id, "yard_zone", zone),
        }
    if location_id in places:
        place = dict(places.get(location_id) or {})
        affordances = _build_place_affordances(location_id, place)
        return {
            "id": location_id,
            "kind": str(place.get("kind", "world_place") or "world_place"),
            "label": str(place.get("name", location_id) or location_id),
            "level": "world",
            "elevation_ft": float(place.get("vertical_transition_ft", 0.0) or 0.0),
            "summary": str(place.get("summary", "") or ""),
            "windows": [],
            "anchor_room": str(place.get("anchor_room", "") or "").strip(),
            "affordances": affordances,
            "tags": [str(x).strip() for x in list(place.get("tags") or []) if str(x).strip()][:24],
            "render_profile": _build_navigation_render_profile(location_id, "world_place", place),
        }
    return {
        "id": location_id,
        "kind": "unknown",
        "label": str(location_id or "unknown"),
        "level": "unknown",
        "elevation_ft": 0.0,
        "summary": "This node has not been mapped yet.",
        "windows": [],
        "affordances": _build_place_affordances(location_id, {}),
        "render_profile": _build_navigation_render_profile(location_id, "unknown", {}),
    }


def _build_traversal_profile(kind, label="", overrides=None):
    kind = str(kind or "walkway").strip().lower()
    profile = {
        "kind": kind,
        "label": str(label or kind.replace("_", " ")).strip(),
        "movement_mode": "walk",
        "traversal_cost": 1.0,
        "travel_seconds": 4.0,
        "requires_interaction": False,
        "weather_exposed": False,
        "occlusion": "soft",
        "cover": "full",
        "vertical_transition_ft": 0.0,
        "gait": "relaxed",
    }
    defaults = {
        "open_entry": {"travel_seconds": 2.0, "traversal_cost": 0.8, "occlusion": "soft"},
        "hall_opening": {"travel_seconds": 3.0, "traversal_cost": 1.0, "occlusion": "soft"},
        "open_plan": {"travel_seconds": 3.2, "traversal_cost": 1.0, "occlusion": "low"},
        "doorway": {"travel_seconds": 3.8, "traversal_cost": 1.2, "requires_interaction": True, "occlusion": "medium"},
        "service_door": {"travel_seconds": 4.5, "traversal_cost": 1.5, "requires_interaction": True, "occlusion": "medium"},
        "front_door": {"travel_seconds": 5.0, "traversal_cost": 1.7, "requires_interaction": True, "weather_exposed": True, "occlusion": "hard", "cover": "partial"},
        "exterior_threshold": {"travel_seconds": 4.8, "traversal_cost": 1.6, "requires_interaction": True, "weather_exposed": True, "occlusion": "medium", "cover": "partial"},
        "service_access": {"travel_seconds": 4.4, "traversal_cost": 1.5, "weather_exposed": True, "occlusion": "medium", "cover": "partial"},
        "staircase_up": {"travel_seconds": 8.5, "traversal_cost": 2.4, "vertical_transition_ft": 9.0, "gait": "careful", "occlusion": "medium"},
        "staircase_down": {"travel_seconds": 8.0, "traversal_cost": 2.2, "vertical_transition_ft": -9.0, "gait": "careful", "occlusion": "medium"},
        "elevator_up": {"travel_seconds": 5.2, "traversal_cost": 1.2, "vertical_transition_ft": 9.0, "gait": "guided", "occlusion": "soft", "requires_interaction": True},
        "elevator_down": {"travel_seconds": 5.2, "traversal_cost": 1.2, "vertical_transition_ft": -9.0, "gait": "guided", "occlusion": "soft", "requires_interaction": True},
        "yard_link": {"travel_seconds": 6.0, "traversal_cost": 1.8, "weather_exposed": True, "cover": "partial", "occlusion": "low"},
        "place_link": {"travel_seconds": 7.5, "traversal_cost": 2.0, "weather_exposed": True, "cover": "open", "occlusion": "low"},
        "anchor_room": {"travel_seconds": 4.5, "traversal_cost": 1.4, "requires_interaction": True, "occlusion": "medium"},
    }
    profile.update(defaults.get(kind, {}))
    if isinstance(overrides, dict):
        for key, value in overrides.items():
            profile[key] = value
    profile["travel_seconds"] = round(float(profile.get("travel_seconds", 4.0) or 4.0), 2)
    profile["traversal_cost"] = round(float(profile.get("traversal_cost", 1.0) or 1.0), 2)
    profile["vertical_transition_ft"] = round(float(profile.get("vertical_transition_ft", 0.0) or 0.0), 2)
    return profile


def _build_navigation_links():
    graph = {}
    links = []
    link_map = {}
    rooms = _get_home_room_index()
    zones = _get_home_zone_index()
    world_builder = _resolve_world_builder_state()
    places = {str((row or {}).get("id", "") or "").strip(): dict(row or {}) for row in list(world_builder.get("places") or [])}

    def connect(src, dst, kind, label="", **overrides):
        src_id = _resolve_navigation_target_id(src, rooms=rooms, zones=zones, places=places)
        dst_id = _resolve_navigation_target_id(dst, rooms=rooms, zones=zones, places=places)
        if not src_id or not dst_id:
            return
        profile = _build_traversal_profile(kind, label=label, overrides=overrides)
        graph.setdefault(src_id, set()).add(dst_id)
        graph.setdefault(dst_id, set()).add(src_id)
        edge_key = tuple(sorted((src_id, dst_id)))
        row = {"from": src_id, "to": dst_id, **profile}
        links.append(row)
        link_map[edge_key] = row

    for link in list(HOME_CONNECTIONS or []):
        connect(link.get("from"), link.get("to"), link.get("kind"), str(link.get("label", "") or ""))
    for zone in list(HOME_YARD_ZONES or []):
        zone_id = str((zone or {}).get("id", "") or "").strip()
        adjacent = str((zone or {}).get("adjacent_room", "") or "").strip()
        if zone_id and adjacent:
            connect(zone_id, adjacent, "yard_link", f"{zone_id.replace('_', ' ')} to {adjacent.replace('_', ' ')}")

    for place in list(world_builder.get("places") or []):
        place_id = str((place or {}).get("id", "") or "").strip()
        for linked in list((place or {}).get("links") or []):
            connect(
                place_id,
                linked,
                "place_link",
                str((place or {}).get("name", place_id) or place_id),
                traversal_cost=float((place or {}).get("traversal_cost", 2.0) or 2.0),
                weather_exposed=str((place or {}).get("cover", "open") or "open").strip().lower() == "open",
                cover=str((place or {}).get("cover", "open") or "open").strip().lower(),
            )
        anchor_room = str((place or {}).get("anchor_room", "") or "").strip()
        if place_id and anchor_room:
            connect(place_id, anchor_room, "anchor_room", f"{place_id.replace('_', ' ')} anchor to {anchor_room.replace('_', ' ')}")
    return {
        "graph": {key: sorted(values) for key, values in graph.items()},
        "links": links,
        "link_map": link_map,
        "rooms": rooms,
        "zones": zones,
        "places": places,
    }


def _build_navigation_graph():
    return dict(_build_navigation_links().get("graph") or {})


def _find_navigation_route(start_id, target_id, rooms=None, zones=None, places=None):
    nav_data = _build_navigation_links()
    graph = dict(nav_data.get("graph") or {})
    rooms = dict(rooms or nav_data.get("rooms") or {})
    zones = dict(zones or nav_data.get("zones") or {})
    places = dict(places or nav_data.get("places") or {})
    start_id = _resolve_navigation_target_id(start_id, rooms=rooms, zones=zones, places=places)
    target_id = _resolve_navigation_target_id(target_id, rooms=rooms, zones=zones, places=places)
    if not start_id or not target_id:
        return {"found": False, "error": "missing_target"}
    if start_id == target_id:
        node = _get_navigation_node_snapshot(start_id, rooms=rooms, zones=zones, places=places)
        return {
            "found": True,
            "start_id": start_id,
            "target_id": target_id,
            "node_path": [start_id],
            "segments": [],
            "travel_seconds": 0.0,
            "traversal_cost": 0.0,
            "movement_modes": [],
            "current_node": node,
            "target_node": node,
        }

    unvisited = {node_id: float("inf") for node_id in graph.keys()}
    previous = {}
    visited = set()
    unvisited[start_id] = 0.0
    link_map = dict(nav_data.get("link_map") or {})

    while unvisited:
        current_id = min((node_id for node_id in unvisited.keys() if node_id not in visited), key=lambda node_id: unvisited.get(node_id, float("inf")), default=None)
        if current_id is None or unvisited.get(current_id, float("inf")) == float("inf"):
            break
        if current_id == target_id:
            break
        visited.add(current_id)
        for neighbor in list(graph.get(current_id, []) or []):
            edge = dict(link_map.get(tuple(sorted((current_id, neighbor)))) or {})
            cost = float(edge.get("traversal_cost", 1.0) or 1.0)
            alt_cost = unvisited.get(current_id, float("inf")) + cost
            if alt_cost < unvisited.get(neighbor, float("inf")):
                unvisited[neighbor] = alt_cost
                previous[neighbor] = current_id

    if target_id not in previous and target_id != start_id:
        return {
            "found": False,
            "start_id": start_id,
            "target_id": target_id,
            "reachable_targets": list(graph.get(start_id, []) or []),
        }

    node_path = [target_id]
    while node_path[-1] != start_id:
        parent = previous.get(node_path[-1])
        if not parent:
            return {"found": False, "start_id": start_id, "target_id": target_id}
        node_path.append(parent)
    node_path.reverse()

    segments = []
    total_seconds = 0.0
    total_cost = 0.0
    movement_modes = set()
    for idx in range(len(node_path) - 1):
        src_id = node_path[idx]
        dst_id = node_path[idx + 1]
        edge = dict(link_map.get(tuple(sorted((src_id, dst_id)))) or {})
        total_seconds += float(edge.get("travel_seconds", 0.0) or 0.0)
        total_cost += float(edge.get("traversal_cost", 0.0) or 0.0)
        movement_modes.add(str(edge.get("movement_mode", "walk") or "walk"))
        segments.append({
            "from": src_id,
            "to": dst_id,
            "kind": str(edge.get("kind", "path") or "path"),
            "label": str(edge.get("label", "") or ""),
            "travel_seconds": round(float(edge.get("travel_seconds", 0.0) or 0.0), 2),
            "traversal_cost": round(float(edge.get("traversal_cost", 0.0) or 0.0), 2),
            "gait": str(edge.get("gait", "relaxed") or "relaxed"),
            "weather_exposed": bool(edge.get("weather_exposed", False)),
            "vertical_transition_ft": round(float(edge.get("vertical_transition_ft", 0.0) or 0.0), 2),
        })
    return {
        "found": True,
        "start_id": start_id,
        "target_id": target_id,
        "node_path": node_path,
        "segments": segments,
        "travel_seconds": round(total_seconds, 2),
        "traversal_cost": round(total_cost, 2),
        "movement_modes": sorted(movement_modes),
        "current_node": _get_navigation_node_snapshot(start_id, rooms=rooms, zones=zones, places=places),
        "target_node": _get_navigation_node_snapshot(target_id, rooms=rooms, zones=zones, places=places),
    }


def _build_navigation_sight(location_id):
    home = dict(app_state.get("home_environment") or _default_home_state())
    weather = dict(home.get("weather") or {})
    solar = dict(home.get("solar") or {})
    nav_data = _build_navigation_links()
    rooms = dict(nav_data.get("rooms") or {})
    zones = dict(nav_data.get("zones") or {})
    places = dict(nav_data.get("places") or {})
    location_id = _resolve_navigation_target_id(location_id, rooms=rooms, zones=zones, places=places)

    visible_targets = list((nav_data.get("graph") or {}).get(location_id, []))
    sight_lines = []
    windows = []
    label = location_id or "unknown"
    location_kind = "unknown"
    node = _get_navigation_node_snapshot(location_id, rooms=rooms, zones=zones, places=places)
    affordances = dict(node.get("affordances") or {})

    if location_id in rooms:
        room = dict(rooms.get(location_id) or {})
        label = str(room.get("name", location_id) or location_id)
        location_kind = "room"
        windows = [dict(w or {}) for w in list(room.get("windows") or [])]
        view_bits = [str((w or {}).get("view", "")).strip() for w in windows if str((w or {}).get("view", "")).strip()]
        sight_lines.append(str(room.get("desc", "")).strip())
        if view_bits:
            sight_lines.append(f"Visible sightlines include {', '.join(view_bits[:3])}.")
        if solar:
            sight_lines.append(
                f"Light phase is {str(solar.get('phase', 'steady')).replace('_', ' ')} with color temperature {float(solar.get('color_temp_k', 4000) or 4000):.0f}K."
            )
    elif location_id in zones:
        zone = dict(zones.get(location_id) or {})
        label = str(zone.get("name", location_id) or location_id)
        location_kind = "yard_zone"
        sight_lines.append(str(zone.get("desc", "")).strip())
        if weather:
            sight_lines.append(
                f"Outdoor conditions show {str(weather.get('weather_label', 'live weather')).strip()} at {float(weather.get('temp_f', 70.0) or 70.0):.0f}F with wind {float(weather.get('wind_speed_mph', 0.0) or 0.0):.0f} mph."
            )
    elif location_id in places:
        place = dict(places.get(location_id) or {})
        label = str(place.get("name", location_id) or location_id)
        location_kind = str(place.get("kind", "world_place") or "world_place")
        sight_lines.append(str(place.get("summary", "")).strip() or f"{label} is live and reachable.")
        anchor_room = str(place.get("anchor_room", "")).strip()
        if anchor_room and anchor_room in rooms:
            room = dict(rooms.get(anchor_room) or {})
            sight_lines.append(f"It anchors through {str(room.get('name', anchor_room) or anchor_room)} inside the house network.")
    else:
        sight_lines.append("Sight is available, but this location has not been mapped yet.")

    visible_labels = []
    visible_target_details = []
    for target_id in visible_targets:
        target_node = _get_navigation_node_snapshot(target_id, rooms=rooms, zones=zones, places=places)
        link_profile = dict((nav_data.get("link_map") or {}).get(tuple(sorted((location_id, target_id)))) or {})
        if target_id in rooms:
            visible_labels.append(str((rooms.get(target_id) or {}).get("name", target_id)))
        elif target_id in zones:
            visible_labels.append(str((zones.get(target_id) or {}).get("name", target_id)))
        elif target_id in places:
            visible_labels.append(str((places.get(target_id) or {}).get("name", target_id)))
        else:
            visible_labels.append(target_id)
        visible_target_details.append({
            "id": target_id,
            "label": str(target_node.get("label", target_id) or target_id),
            "kind": str(target_node.get("kind", "unknown") or "unknown"),
            "connection_kind": str(link_profile.get("kind", "path") or "path"),
            "travel_seconds": round(float(link_profile.get("travel_seconds", 0.0) or 0.0), 2),
            "weather_exposed": bool(link_profile.get("weather_exposed", False)),
            "occlusion": str(link_profile.get("occlusion", "soft") or "soft"),
            "fidelity_tier": str((dict(target_node.get("render_profile") or {})).get("fidelity_tier", "standard") or "standard"),
            "streaming_priority": str((dict(target_node.get("render_profile") or {})).get("streaming_priority", "medium") or "medium"),
            "dimensionality": str((dict(target_node.get("render_profile") or {})).get("dimensionality", "3d") or "3d"),
            "render_medium": str((dict(target_node.get("render_profile") or {})).get("render_medium", "world_geometry") or "world_geometry"),
            "flat_exception": bool((dict(target_node.get("render_profile") or {})).get("flat_exception", False)),
        })

    summary = " ".join(part for part in sight_lines if part).strip()
    if affordances.get("actions"):
        summary = f"{summary} Available actions include {', '.join(list(affordances.get('actions') or [])[:4])}.".strip()
    return {
        "location_id": location_id,
        "location_label": label,
        "location_kind": location_kind,
        "summary": summary or f"{label} is visible and ready.",
        "visible_targets": visible_targets,
        "visible_target_labels": visible_labels,
        "visible_target_details": visible_target_details,
        "windows": windows,
        "weather_label": str(weather.get("weather_label", "")).strip(),
        "light_phase": str(solar.get("phase", "")).strip(),
        "affordances": affordances,
        "elevation_ft": round(float(node.get("elevation_ft", 0.0) or 0.0), 2),
        "lighting_profile": str(affordances.get("lighting_profile", "") or ""),
        "acoustic_profile": str(affordances.get("acoustic_profile", "") or ""),
        "cover": str(affordances.get("cover", "") or ""),
        "render_profile": dict(node.get("render_profile") or {}),
    }


def _apply_navigation_state(location_id, source="navigation", route=None):
    location_id = str(location_id or "").strip()
    if not location_id:
        raise ValueError("location_id is required")

    rooms = _get_home_room_index()
    zones = _get_home_zone_index()
    world_builder = _resolve_world_builder_state()
    places = {str((row or {}).get("id", "") or "").strip(): dict(row or {}) for row in list(world_builder.get("places") or [])}
    home = dict(app_state.get("home_environment") or _default_home_state())
    wc = dict(app_state.get("world_continuity") or {})

    location_id = _resolve_navigation_target_id(location_id, rooms=rooms, zones=zones, places=places)
    resolved_location_id = location_id
    updated_world_builder = None
    home_updates = {}
    if location_id in places:
        place = dict(places.get(location_id) or {})
        anchor_room = str(place.get("anchor_room", "")).strip()
        if anchor_room in rooms:
            home_updates["current_room"] = anchor_room
            home_updates["current_level"] = str((rooms.get(anchor_room) or {}).get("level", home.get("current_level", "lower")) or "lower")
        builder = dict(world_builder)
        builder["active_place_id"] = location_id
        updated_world_builder = builder
    elif location_id in rooms:
        room = dict(rooms.get(location_id) or {})
        home_updates["current_room"] = location_id
        home_updates["current_level"] = str(room.get("level", home.get("current_level", "lower")) or "lower")
        builder = dict(world_builder)
        builder["active_place_id"] = ""
        updated_world_builder = builder
        resolved_location_id = location_id
    elif location_id in zones:
        zone = dict(zones.get(location_id) or {})
        adjacent_room = str(zone.get("adjacent_room", "")).strip()
        if adjacent_room in rooms:
            home_updates["current_room"] = adjacent_room
            home_updates["current_level"] = str((rooms.get(adjacent_room) or {}).get("level", home.get("current_level", "lower")) or "lower")
        builder = dict(world_builder)
        matching_place_id = _resolve_navigation_target_id(location_id, rooms=rooms, zones=zones, places=places, prefer="place")
        builder["active_place_id"] = matching_place_id if matching_place_id in places else ""
        updated_world_builder = builder
    else:
        raise ValueError("Unknown navigation target")
    wc["world_builder"] = updated_world_builder
    home.update(home_updates)

    sight = _build_navigation_sight(resolved_location_id)
    visual_perception = _build_visual_perception_payload(sight.get("summary", ""), source=f"navigation:{resolved_location_id}")
    app_state["visual_perception"] = visual_perception
    _sync_visual_emotion_runtime(visual_perception)

    route = dict(route or {})
    world_mobility = dict(wc.get("world_mobility") or {})
    movement_modes = list(route.get("movement_modes") or [])
    sight_affordances = dict(sight.get("affordances") or {})
    preferred_posture = str(sight_affordances.get("preferred_posture", "stand") or "stand")
    locomotion_mode = movement_modes[0] if movement_modes else ("walk" if sight.get("location_kind") != "world_place" else "explore")
    world_mobility.update({
        "current_location_id": resolved_location_id,
        "current_location_label": str(sight.get("location_label", resolved_location_id) or resolved_location_id),
        "current_location_kind": str(sight.get("location_kind", "unknown") or "unknown"),
        "locomotion_mode": locomotion_mode,
        "gait": str((((list(route.get("segments") or [{}]) or [{}])[-1]).get("gait", "relaxed")) or "relaxed"),
        "posture": preferred_posture,
        "cover": str(sight.get("cover", "") or ""),
        "available_actions": list(sight_affordances.get("actions") or [])[:12],
        "interaction_points": list(sight_affordances.get("interaction_points") or [])[:8],
        "traversal_state": "arrived",
        "route": route if route.get("found") else None,
        "last_arrival_at": datetime.utcnow().isoformat(),
    })
    player_character = _resolve_player_character_state()
    player_runtime = dict(player_character.get("runtime") or {})
    player_runtime["current_location_id"] = resolved_location_id
    player_runtime["current_room"] = str(home.get("current_room", "living_room") or "living_room")
    player_runtime["movement_mode"] = locomotion_mode
    player_runtime["pose"] = preferred_posture if preferred_posture != "stand" else "stand"
    player_runtime["manual_pose_override"] = False
    player_runtime["requested_action"] = locomotion_mode
    player_runtime["action_description"] = f"Moved through the world and arrived at {str(sight.get('location_label', resolved_location_id) or resolved_location_id)}."
    player_runtime["last_action_at"] = datetime.utcnow().isoformat()
    player_character["runtime"] = player_runtime
    player_character["last_updated_at"] = datetime.utcnow().isoformat()
    app_state["player_character"] = player_character

    saved_activity = {
        "activity": "navigation",
        "location": str(sight.get("location_label", resolved_location_id) or resolved_location_id),
        "source": str(source or "navigation")[:40],
        "details": str(sight.get("summary", "") or "")[:240],
        "savedAt": datetime.utcnow().isoformat(),
    }

    # Two separate atomic, per-key merge-writes (not one cross-key
    # transaction -- see _apply_navigation_state's note in
    # p1-lock-world-continuity-key/p1-lock-home-environment-key session
    # todos for why a true 3-key atomic write would need a bigger redesign).
    # Each write below is still a real improvement over the prior blind
    # whole-dict overwrite: it re-merges against whatever is currently in
    # app_state at write time instead of clobbering concurrent unrelated
    # field changes with a stale snapshot captured at the top of this call.
    # home_updates only contains current_room/current_level when this call
    # actually changed them, so a branch that didn't move rooms never
    # re-writes (and can't clobber a concurrent unrelated home change).
    resolved_home = _update_home_environment_state(**home_updates) if home_updates else dict(app_state.get("home_environment") or _default_home_state())

    def _apply_wc(wc_inner):
        wc_inner["world_builder"] = updated_world_builder
        wc_inner["world_mobility"] = world_mobility
        wc_inner["saved_activity"] = saved_activity
        wc_inner["last_navigation_target"] = resolved_location_id
        wc_inner["synced_at"] = datetime.utcnow().isoformat()
    resolved_wc = _mutate_world_continuity(_apply_wc)

    return {
        "current_room": str(resolved_home.get("current_room", "living_room") or "living_room"),
        "current_level": str(resolved_home.get("current_level", "lower") or "lower"),
        "active_place_id": str((((resolved_wc.get("world_builder") or {}).get("active_place_id")) or "")).strip(),
        "sight": sight,
        "player_character": player_character,
    }

def _build_home_scene_manifest():
    home = dict(app_state.get("home_environment") or _default_home_state())
    windows_open = set(str(x).strip() for x in list(home.get("windows_open") or []) if str(x).strip())
    doors_open = set(str(x).strip() for x in list(home.get("doors_open") or []) if str(x).strip())
    nav_runtime = _build_navigation_runtime_state()
    rooms = []
    for level_id, level in HOME_LAYOUT.get("levels", {}).items():
        for room_id, room in level.get("rooms", {}).items():
            room_dict = dict(room or {})
            windows = []
            for win in list(room_dict.get("windows") or []):
                row = dict(win or {})
                row["open"] = bool(row.get("open", False) or row.get("id") in windows_open)
                windows.append(row)
            features = []
            if room_dict.get("has_fireplace"):
                features.append("fireplace")
            if room_dict.get("has_furnace"):
                features.append("furnace")
            if room_dict.get("has_ac_unit"):
                features.append("ac_unit")
            if room_dict.get("type"):
                features.append(str(room_dict.get("type")))
            rooms.append({
                "id": room_id,
                "level": level_id,
                "level_name": str(level.get("name", level_id)),
                "name": str(room_dict.get("name", room_id)),
                "emoji": str(room_dict.get("emoji", "")),
                "area_sqft": int(room_dict.get("area_sqft", 0) or 0),
                "desc": str(room_dict.get("desc", "") or ""),
                "features": features,
                "windows": windows,
                "is_current_room": room_id == str(home.get("current_room", "")),
            })
    doors = []
    for door in _get_all_doors().values():
        row = dict(door or {})
        row["open"] = bool(row.get("open", False) or row.get("id") in doors_open)
        doors.append(row)
    return {
        "address": str(HOME_LAYOUT.get("address", "") or ""),
        "style": str(HOME_LAYOUT.get("style", "bilevel") or "bilevel"),
        "levels": [
            {
                "id": level_id,
                "name": str(level.get("name", level_id)),
                "elevation_ft": float(level.get("elevation_ft", 0.0) or 0.0),
                "room_ids": [room_id for room_id in list(level.get("rooms", {}).keys())],
            }
            for level_id, level in HOME_LAYOUT.get("levels", {}).items()
        ],
        "rooms": rooms,
        "doors": doors,
        "connections": list(HOME_CONNECTIONS),
        "yard_zones": list(HOME_YARD_ZONES),
        "dynamic_state": {
            "current_room": str(home.get("current_room", "living_room")),
            "current_level": str(home.get("current_level", "lower")),
            "windows_open": sorted(windows_open),
            "doors_open": sorted(doors_open),
            "navigation": nav_runtime,
            "player_character": _resolve_player_character_state(),
            "weather": dict(home.get("weather") or {}),
            "physics": dict(home.get("physics") or {}),
            "sensory": dict(home.get("sensory") or {}),
            "mobility": dict((app_state.get("world_continuity") or {}).get("world_mobility") or {}),
            "fireplace": dict(home.get("fireplace") or {}),
            "water_system": dict(home.get("water_system") or {}),
            "garden": dict(home.get("garden") or {}),
            "permaculture": dict(home.get("permaculture") or {}),
            "harmony": dict(home.get("harmony") or {}),
            "decor": dict(home.get("decor") or {}),
            "swimming": dict(home.get("swimming") or {}),
            "sleep_autonomy": dict(home.get("sleep_autonomy") or {}),
            "ambient_video_system": dict(home.get("ambient_video_system") or {}),
        },
        "last_updated_at": datetime.utcnow().isoformat(),
    }


def _build_navigation_runtime_state():
    home = dict(app_state.get("home_environment") or _default_home_state())
    wc = dict(app_state.get("world_continuity") or {})
    nav_data = _build_navigation_links()
    graph = dict(nav_data.get("graph") or {})
    current_room = str(home.get("current_room", "living_room") or "living_room")
    active_place_id = str((((wc.get("world_builder") or {}).get("active_place_id")) or "")).strip()
    current_location_id = active_place_id or current_room
    current_node = _get_navigation_node_snapshot(current_location_id, rooms=nav_data.get("rooms"), zones=nav_data.get("zones"), places=nav_data.get("places"))
    return {
        "current_room": current_room,
        "current_level": str(home.get("current_level", "lower") or "lower"),
        "active_place_id": active_place_id,
        "current_location_id": current_location_id,
        "current_node": current_node,
        "reachable_targets": list(graph.get(current_location_id, []) or []),
        "sight": _build_navigation_sight(current_location_id),
        "graph": graph,
        "links": list(nav_data.get("links") or []),
        "mobility": dict(wc.get("world_mobility") or {}),
    }


