def _build_unreal_property_push_list():
    contract = _collect_unreal_runtime_contract()
    return [(prop_name, {prop_name: value}) for prop_name, value in contract.items()]


def _record_unreal_bridge_failure(context, endpoint="", response=None, error=None, property_name="", actor_path=""):
    detail = {
        "context": _safe_text(context, default="unknown", limit=60),
        "endpoint": _safe_text(endpoint, default="", limit=160),
        "property": _safe_text(property_name, default="", limit=80),
        "actor_path": _safe_text(actor_path, default="", limit=240),
        "recorded_at": _iso_utc_now(),
    }
    if response is not None:
        status_value = getattr(response, "status_code", None)
        if status_value is None:
            status_value = getattr(response, "status", None)
        if status_value is None:
            status_value = getattr(response, "code", 0)
        detail["http_status"] = int(status_value or 0)
        detail["reason"] = _safe_text(getattr(response, "reason", ""), default="", limit=80)
    if error is not None:
        detail["error"] = _safe_text(error, default="", limit=320)
    bridge = _update_unreal_bridge_runtime(
        rc_status=f"{detail['context']}_failed",
        rc_last_error=detail,
        rc_last_error_at=detail["recorded_at"],
    )
    failures = list(bridge.get("rc_recent_failures") or [])
    failures.append(detail)
    bridge["rc_recent_failures"] = failures[-12:]
    app_state["unreal_bridge"] = bridge
    return detail


def _build_world_scene_manifest():
    home_manifest = _build_home_scene_manifest()
    world_cont = dict(app_state.get("world_continuity") or {})
    world_engine = _compute_live_world_engine_state()
    home = dict(app_state.get("home_environment") or _default_home_state())
    physics = dict(home.get("physics") or {})
    weather = dict(home.get("weather") or {})
    solar = dict(home.get("solar") or {})
    return {
        "home_scene": home_manifest,
        "world_runtime": _build_world_runtime_state(),
        "navigation_runtime": _build_navigation_runtime_state(),
        "player_character": _resolve_player_character_state(),
        "world_continuity": world_cont,
        "world_builder": _resolve_world_builder_state(),
        "world_engine": world_engine,
        "unreal_engine_directives": _build_unreal_engine_directives(),
        "render_directives": {
            "realistic_weather_sync": True,
            "realistic_sky_sync": True,
            "realistic_astrophysics_sync": True,
            "realistic_quantum_context_sync": True,
            "free_roam_live": True,
            "temperature_live": True,
            "five_senses_live": True,
            "unreal_max_fidelity": True,
            "route_driven_locomotion": True,
            "smart_object_affordances": True,
            "default_scene_dimensionality": "3d",
            "world_geometry_policy": "3d-by-default",
            "allow_flat_embedded_artifacts_only": True,
            "flat_exception_media": ["paper", "page", "drawing", "sketch", "note", "blueprint", "poster", "print", "painting", "canvas", "map", "photo"],
        },
        "live_environment": {
            "weather": weather,
            "solar": solar,
            "physics": physics,
            "astrophysics_summary": str(physics.get("astrophysics_summary", "") or ""),
            "quantum_summary": str(physics.get("quantum_summary", "") or ""),
            "atmosphere_summary": str(physics.get("atmosphere_summary", "") or ""),
        },
        "last_updated_at": datetime.utcnow().isoformat(),
    }


