def _normalize_vehicle_entry(entry):
    row = dict(entry or {})
    kind = str(row.get("kind", "car") or "car").strip().lower()
    if kind not in {"car", "motorcycle", "bike", "plane"}:
        kind = "car"
    name = str(row.get("name", "") or "Vehicle").strip() or "Vehicle"
    vehicle_id = str(row.get("id", "") or "").strip() or _slugify_filename(name, fallback="vehicle")
    door_ids = []
    for value in list(row.get("door_ids") or []):
        token = str(value or "").strip()
        if token and token.lower() not in {x.lower() for x in door_ids}:
            door_ids.append(token[:60])
    window_ids = []
    for value in list(row.get("window_ids") or []):
        token = str(value or "").strip()
        if token and token.lower() not in {x.lower() for x in window_ids}:
            window_ids.append(token[:60])
    doors_open = []
    for value in list(row.get("doors_open") or []):
        token = str(value or "").strip()
        if token and token in door_ids and token.lower() not in {x.lower() for x in doors_open}:
            doors_open.append(token[:60])
    windows_open = []
    for value in list(row.get("windows_open") or []):
        token = str(value or "").strip()
        if token and token in window_ids and token.lower() not in {x.lower() for x in windows_open}:
            windows_open.append(token[:60])
    return {
        "id": vehicle_id[:80],
        "name": name[:120],
        "kind": kind,
        "drivable": bool(row.get("drivable", True)),
        "owner_access": str(row.get("owner_access", "aurion_and_billy_only") or "aurion_and_billy_only")[:80],
        "location_layer_id": str(row.get("location_layer_id", "vehicle-atrium-layer") or "vehicle-atrium-layer")[:80],
        "seat_count": max(1, min(24, int(row.get("seat_count", 1) or 1))),
        "flight_capable": bool(row.get("flight_capable", kind == "plane")),
        "door_ids": door_ids[:12],
        "window_ids": window_ids[:16],
        "doors_open": doors_open[:12],
        "windows_open": windows_open[:16],
        "summary": str(row.get("summary", f"{name} ready for sovereign travel.") or f"{name} ready for sovereign travel.")[:240],
        "last_used_at": str(row.get("last_used_at", "") or "").strip() or None,
    }


