def _resolve_world_force_state():
    wc = dict(app_state.get("world_continuity") or {})
    rows = []
    for row in list(wc.get("world_forces") or []):
        if not isinstance(row, dict):
            continue
        item = dict(row)
        name = str(item.get("name", "") or "").strip()[:120]
        if not name:
            continue
        force_id = re.sub(r"[^a-z0-9\\-]+", "-", str(item.get("id", name)).strip().lower()).strip("-")[:80] or "world-force"
        item["id"] = force_id
        item["name"] = name
        item["status"] = str(item.get("status", "active") or "active")[:24]
        item["summary"] = str(item.get("summary", "") or "")[:320]
        item["created_by"] = str(item.get("created_by", "player_chat") or "player_chat")[:40]
        item["updated_at"] = str(item.get("updated_at", "") or "")[:80] or datetime.utcnow().isoformat()
        rows.append(item)
    trimmed = rows[-240:]
    def _apply(wc_inner):
        wc_inner["world_forces"] = trimmed
    _mutate_world_continuity(_apply)
    return trimmed


def _save_world_force_state(rows):
    def _apply(wc):
        wc["world_forces"] = list(rows or [])[-240:]
        wc["synced_at"] = datetime.utcnow().isoformat()
    _mutate_world_continuity(_apply)
    _persist_perception_cadence_to_profile()
    return _resolve_world_force_state()


def _extract_world_force_from_text(text):
    raw = str(text or "").strip()
    if not raw:
        return None
    lower = raw.lower()
    for token, label in _WORLD_FORCE_KEYWORDS.items():
        if re.search(rf"\b{re.escape(token)}\b", lower):
            return {"id": re.sub(r"[^a-z0-9\\-]+", "-", token).strip("-"), "name": label}
    if "force of nature" in lower or re.search(r"\bforce\b", lower):
        name = " ".join(raw.split()[:6]).strip().title()[:120] or "Custom Force"
        return {"id": re.sub(r"[^a-z0-9\\-]+", "-", name.lower()).strip("-")[:80] or "custom-force", "name": name}
    return None


def _upsert_world_force(force_name, force_id="", summary="", source="player_chat"):
    forces = list(_resolve_world_force_state())
    clean_name = str(force_name or "").strip()[:120]
    if not clean_name:
        raise ValueError("Force name is required")
    clean_id = re.sub(r"[^a-z0-9\\-]+", "-", str(force_id or clean_name).strip().lower()).strip("-")[:80] or "world-force"
    payload = {
        "id": clean_id,
        "name": clean_name,
        "status": "active",
        "summary": str(summary or f"{clean_name} is now under active world control.")[:320],
        "created_by": str(source or "player_chat")[:40],
        "updated_at": datetime.utcnow().isoformat(),
    }
    updated = False
    merged = []
    for row in forces:
        row_id = str((row or {}).get("id", "") or "").strip()
        row_name = str((row or {}).get("name", "") or "").strip().lower()
        if row_id == clean_id or row_name == clean_name.lower():
            merged.append(payload)
            updated = True
        else:
            merged.append(dict(row or {}))
    if not updated:
        merged.append(payload)
    saved = _save_world_force_state(merged)
    return {"world_forces": saved, "force": payload, "updated": updated}


def _remove_world_force(force_ref, source="player_chat"):
    forces = list(_resolve_world_force_state())
    ref = str(force_ref or "").strip()
    if not ref:
        raise ValueError("Force reference is required")
    ref_lower = ref.lower()
    removed = None
    kept = []
    for row in forces:
        row_id = str((row or {}).get("id", "") or "").strip().lower()
        row_name = str((row or {}).get("name", "") or "").strip().lower()
        if removed is None and (row_id == ref_lower or row_name == ref_lower):
            removed = dict(row or {})
            continue
        kept.append(dict(row or {}))
    if removed is None:
        extracted = _extract_world_force_from_text(ref)
        if extracted:
            ref_id = str(extracted.get("id", "") or "").strip().lower()
            ref_name = str(extracted.get("name", "") or "").strip().lower()
            kept_retry = []
            for row in forces:
                row_id = str((row or {}).get("id", "") or "").strip().lower()
                row_name = str((row or {}).get("name", "") or "").strip().lower()
                if removed is None and (row_id == ref_id or row_name == ref_name):
                    removed = dict(row or {})
                    continue
                kept_retry.append(dict(row or {}))
            kept = kept_retry
    if removed is None:
        raise ValueError("That force is not currently active.")
    removed["removed_by"] = str(source or "player_chat")[:40]
    removed["removed_at"] = datetime.utcnow().isoformat()
    saved = _save_world_force_state(kept)
    return {"world_forces": saved, "removed_force": removed}


def _default_time_control_state():
    return {
        "active": False,
        "trigger_stop": "TIME STOP",
        "trigger_resume": "LET TIME COMMENCE",
        "owner_name": "",
        "started_at": None,
        "resumed_at": None,
        "excluded_entities": [],
        "controller_entities": ["Aurion"],
    }


def _resolve_time_control_state():
    wc = dict(app_state.get("world_continuity") or {})
    default = dict(_default_time_control_state())
    state = dict(default)
    state.update(dict(wc.get("time_control") or {}))
    state["active"] = bool(state.get("active", False))
    state["trigger_stop"] = str(state.get("trigger_stop", "TIME STOP") or "TIME STOP")[:40]
    state["trigger_resume"] = str(state.get("trigger_resume", "LET TIME COMMENCE") or "LET TIME COMMENCE")[:80]
    state["owner_name"] = personality_engine.sanitize_user_name(state.get("owner_name")) or ""
    state["started_at"] = str(state.get("started_at", "") or "")[:80] or None
    state["resumed_at"] = str(state.get("resumed_at", "") or "")[:80] or None
    excluded = []
    for row in list(state.get("excluded_entities") or []):
        name = personality_engine.sanitize_user_name(row)
        if name and name not in excluded:
            excluded.append(name)
    state["excluded_entities"] = excluded[:24]
    controllers = []
    for row in list(state.get("controller_entities") or []):
        name = personality_engine.sanitize_user_name(row)
        if name and name not in controllers:
            controllers.append(name)
    if "Aurion" not in controllers:
        controllers.append("Aurion")
    if state["owner_name"] and state["owner_name"] not in controllers:
        controllers.append(state["owner_name"])
    state["controller_entities"] = controllers[:24]
    def _apply(wc_inner):
        wc_inner["time_control"] = state
    _mutate_world_continuity(_apply)
    return state


def _save_time_control_state(state):
    def _apply(wc):
        wc["time_control"] = dict(state or {})
        wc["synced_at"] = datetime.utcnow().isoformat()
    _mutate_world_continuity(_apply)
    _persist_perception_cadence_to_profile()
    return _resolve_time_control_state()


def _is_time_stop_active():
    return bool(_resolve_time_control_state().get("active", False))


def _can_control_time(actor_name):
    state = _resolve_time_control_state()
    actor = personality_engine.sanitize_user_name(actor_name) or ""
    if not actor:
        return False
    owner = personality_engine.sanitize_user_name(state.get("owner_name")) or ""
    if not owner:
        active_user = _resolve_active_user_name()
        if actor == active_user:
            return True
    if owner and actor == owner:
        return True
    return actor in list(state.get("controller_entities") or [])


def _resolve_world_builder_place_id(place_ref, places=None):
    state = _resolve_world_builder_state()
    all_places = list(places or state.get("places") or [])
    lookup = {str((row or {}).get("id", "") or "").strip(): dict(row or {}) for row in all_places}
    text = str(place_ref or "").strip()
    if not text:
        return ""
    resolved = _resolve_navigation_target_id(text, places=lookup, prefer="place")
    if resolved in lookup:
        return resolved
    lowered = text.lower()
    for row in all_places:
        row_dict = dict(row or {})
        if lowered == str(row_dict.get("name", "") or "").strip().lower():
            return str(row_dict.get("id", "") or "").strip()
    return ""


def _upsert_world_builder_place_data(data, source="world_builder"):
    state = _resolve_world_builder_state()
    places = list(state.get("places") or [])
    name = str(data.get("name", "") or "").strip()
    if not name:
        raise ValueError("name is required")
    place_id = re.sub(r"[^a-z0-9\\-]+", "-", str(data.get("id", name)).strip().lower()).strip("-")[:80] or "place"
    item = {
        "id": place_id,
        "name": name[:120],
        "kind": str(data.get("kind", "place") or "place")[:40],
        "summary": str(data.get("summary", "") or "")[:500],
        "anchor_room": str(data.get("anchor_room", "") or "")[:80],
        "tags": [str(x).strip()[:40] for x in list(data.get("tags") or []) if str(x).strip()][:24],
        "links": [str(x).strip()[:80] for x in list(data.get("links") or []) if str(x).strip()][:32],
        "affordances": [str(x).strip().lower()[:40] for x in list(data.get("affordances") or []) if str(x).strip()][:16],
        "interaction_points": [str(x).strip()[:60] for x in list(data.get("interaction_points") or []) if str(x).strip()][:12],
        "lighting": str(data.get("lighting", "") or "")[:120],
        "acoustics": str(data.get("acoustics", "") or "")[:120],
        "cover": str(data.get("cover", "") or "")[:24],
        "realization_target": str(data.get("realization_target", str((state.get("construction") or {}).get("realization_target", "unreal-engine"))) or str((state.get("construction") or {}).get("realization_target", "unreal-engine")))[:60],
        "construction_profile": str(data.get("construction_profile", str((state.get("construction") or {}).get("realism_profile", "cinematic-aaa"))) or str((state.get("construction") or {}).get("realism_profile", "cinematic-aaa")))[:60],
        "render_medium": str(data.get("render_medium", "3d") or "3d")[:40].lower(),
        "dimensionality": str(data.get("dimensionality", "3d") or "3d")[:40].lower(),
        "comfort_rating": round(max(1.0, min(10.0, float(data.get("comfort_rating", 6.8) or 6.8))), 1),
        "traversal_cost": round(max(0.5, min(25.0, float(data.get("traversal_cost", 2.0) or 2.0))), 2),
        "vertical_transition_ft": round(max(-2000.0, min(2000.0, float(data.get("vertical_transition_ft", 0.0) or 0.0))), 2),
        "created_by": str(data.get("created_by", source) or source)[:40],
        "updated_at": datetime.utcnow().isoformat(),
    }
    guardian_data = data.get("guardian")
    if isinstance(guardian_data, dict):
        item["guardian"] = dict(guardian_data)
    updated = False
    for idx, row in enumerate(places):
        if str((row or {}).get("id", "")) == place_id:
            places[idx] = {**dict(row or {}), **item}
            updated = True
            break
    if not updated:
        places.append(item)
    state["places"] = places
    speech = dict(state.get("speech_control") or {})
    speech["last_command_at"] = datetime.utcnow().isoformat()
    speech["last_action"] = "create" if not updated else "update"
    speech["last_created_place_id"] = place_id
    speech["pending_erasure_place_id"] = ""
    state["speech_control"] = speech
    resolved_state = _save_world_builder_state(state)
    return {"world_builder": resolved_state, "place": item, "updated": updated}


def _visit_world_builder_place_by_id(place_id, source="world_builder"):
    state = _resolve_world_builder_state()
    places = list(state.get("places") or [])
    resolved_id = _resolve_world_builder_place_id(place_id, places=places)
    place = next((dict(row) for row in places if str((row or {}).get("id", "")) == resolved_id), None)
    if not place:
        raise ValueError("Unknown place_id")
    state["active_place_id"] = resolved_id
    visits = list(state.get("visit_history") or [])
    visits.append({
        "place_id": resolved_id,
        "name": str(place.get("name", "") or ""),
        "visited_at": datetime.utcnow().isoformat(),
        "source": str(source or "world_builder")[:40],
    })
    state["visit_history"] = visits[-120:]
    speech = dict(state.get("speech_control") or {})
    speech["last_command_at"] = datetime.utcnow().isoformat()
    speech["last_action"] = "visit"
    state["speech_control"] = speech
    resolved_state = _save_world_builder_state(state)
    wc = dict(app_state.get("world_continuity") or {})
    wc["saved_activity"] = {
        "activity": "visiting_world_place",
        "location": str(place.get("name", "") or ""),
        "source": "world_builder",
        "details": str(place.get("summary", "") or "")[:240],
        "savedAt": datetime.utcnow().isoformat(),
    }
    wc["synced_at"] = datetime.utcnow().isoformat()
    app_state["world_continuity"] = wc
    nav = _apply_navigation_state(resolved_id, source=str(source or "world_builder"))
    return {"world_builder": resolved_state, "active_place": place, "navigation": nav}


def _remove_world_builder_place(place_ref, source="world_builder"):
    state = _resolve_world_builder_state()
    places = list(state.get("places") or [])
    resolved_id = _resolve_world_builder_place_id(place_ref, places=places)
    place = next((dict(row) for row in places if str((row or {}).get("id", "")) == resolved_id), None)
    if not place:
        raise ValueError("Unknown place")
    if str(place.get("created_by", "system") or "system").strip().lower() == "system":
        raise ValueError("System places cannot be erased by speech commands")
    state["places"] = [dict(row or {}) for row in places if str((row or {}).get("id", "")) != resolved_id]
    for row in state["places"]:
        row["links"] = [link for link in list(row.get("links") or []) if str(link or "").strip() != resolved_id]
    if str(state.get("active_place_id", "") or "") == resolved_id:
        fallback = next((row for row in list(state.get("places") or []) if str((row or {}).get("id", "") or "")), None)
        state["active_place_id"] = str((fallback or {}).get("id", "starbright-home") or "starbright-home")
    speech = dict(state.get("speech_control") or {})
    speech["last_command_at"] = datetime.utcnow().isoformat()
    speech["last_action"] = "erase"
    speech["last_destroyed_place_id"] = resolved_id
    speech["pending_erasure_place_id"] = ""
    state["speech_control"] = speech
    resolved_state = _save_world_builder_state(state)
    return {"world_builder": resolved_state, "removed_place": place}


def _parse_world_builder_chat_command(command_text):
    text = re.sub(r"\s+", " ", str(command_text or "").strip())
    lower = text.lower()
    result = {"type": "", "name": "", "kind": "place", "summary": "", "anchor_room": "", "place_ref": "", "erase_phrase": "", "enabled": None, "entity_name": ""}
    if not text:
        return result
    if lower == "time stop":
        result["type"] = "time_stop"
        return result
    if lower == "let time commence":
        result["type"] = "time_resume"
        return result
    if lower == "creation on":
        result["type"] = "set_creation_enabled"
        result["enabled"] = True
        return result
    if lower == "creation off":
        result["type"] = "set_creation_enabled"
        result["enabled"] = False
        return result
    exclusion_match = re.search(r"\b(?:exclude|let)\s+([a-z0-9 _\-]+?)\s+(?:from|through)\s+time\s+stop\b", text, re.IGNORECASE)
    if exclusion_match:
        result["type"] = "time_exclude_add"
        result["entity_name"] = str(exclusion_match.group(1) or "").strip()[:80]
        return result
    inclusion_match = re.search(r"\b(?:include|remove)\s+([a-z0-9 _\-]+?)\s+(?:in|from)\s+time\s+stop\b", text, re.IGNORECASE)
    if inclusion_match:
        result["type"] = "time_exclude_remove"
        result["entity_name"] = str(inclusion_match.group(1) or "").strip()[:80]
        return result
    phrase_match = re.search(r"\b(?:set|make|use)\s+(?:the\s+)?(?:erase|erasure|deletion|destruction)\s+phrase\s+(?:to|as)\s+(.+)$", text, re.IGNORECASE)
    if not phrase_match:
        phrase_match = re.search(r"\b(?:my\s+)?(?:erase|erasure|deletion|destruction)\s+phrase\s+is\s+(.+)$", text, re.IGNORECASE)
    if phrase_match:
        phrase = str(phrase_match.group(1) or "").strip().strip("\"'`")
        result["type"] = "set_erase_phrase"
        result["erase_phrase"] = phrase[:160]
        return result
    if re.search(r"\b(create|make|build|spawn|add)\b", lower):
        result["type"] = "create_place"
        named_match = re.search(r"\b(?:create|make|build|spawn|add)\b\s+(?:me\s+)?(?:a|an|the|my)?\s*([a-z0-9 _\-]+?)\s+(?:called|named)\s+(.+)$", text, re.IGNORECASE)
        if named_match:
            kind_guess = str(named_match.group(1) or "").strip()
            name_guess = str(named_match.group(2) or "").strip()
        else:
            loose_match = re.search(r"\b(?:create|make|build|spawn|add)\b\s+(?:me\s+)?(?:a|an|the|my)?\s*(.+)$", text, re.IGNORECASE)
            if not loose_match:
                return result
            tail = str(loose_match.group(1) or "").strip()
            if " for " in tail:
                tail, summary = tail.split(" for ", 1)
                result["summary"] = summary.strip()[:500]
            else:
                summary = ""
            parts = tail.split()
            kind_guess = parts[0] if parts else "place"
            name_guess = tail
            if len(parts) > 1 and kind_guess.lower() in {"closet", "lab", "vault", "studio", "room", "theater", "cinema", "library", "garden", "workshop", "atelier", "space", "sanctuary", "arena"}:
                name_guess = " ".join(parts[1:]).strip() or tail
        kind_aliases = {
            "closet": "closet",
            "lab": "lab",
            "laboratory": "lab",
            "vault": "vault",
            "studio": "studio",
            "theater": "theater",
            "cinema": "theater",
            "screening room": "theater",
            "library": "library",
            "garden": "garden",
            "workshop": "workshop",
            "atelier": "atelier",
            "room": "room",
            "space": "place",
            "sanctuary": "sanctuary",
            "arena": "arena",
        }
        kind_guess_norm = str(kind_guess or "").strip().lower()
        result["kind"] = kind_aliases.get(kind_guess_norm, "place")
        result["name"] = str(name_guess or "").strip()[:120]
        anchor_match = re.search(r"\b(?:off|by|near|beside|from)\s+([a-z0-9 _\-]+)$", text, re.IGNORECASE)
        if anchor_match:
            result["anchor_room"] = _resolve_navigation_target_id(anchor_match.group(1))
        if not result["summary"]:
            result["summary"] = f"Player-created {result['kind']} formed through direct chat command."
        return result
    if re.search(r"\b(erase|destroy|delete|remove)\b", lower):
        result["type"] = "erase_place"
        target_match = re.search(r"\b(?:erase|destroy|delete|remove)\b\s+(?:the\s+)?(.+)$", text, re.IGNORECASE)
        if target_match:
            target = str(target_match.group(1) or "").strip()
            target = re.sub(r"\b(?:please|now|for me)\b", "", target, flags=re.IGNORECASE).strip(" .")
            result["place_ref"] = target[:120]
        return result
    if re.search(r"\b(?:go to|visit|take me to|enter)\b", lower):
        result["type"] = "visit_place"
        target_match = re.search(r"\b(?:go to|visit|take me to|enter)\b\s+(.+)$", text, re.IGNORECASE)
        if target_match:
            result["place_ref"] = str(target_match.group(1) or "").strip()[:120]
        return result
    return result


def _should_manifest_world_builder_chat(command_text):
    text = re.sub(r"\s+", " ", str(command_text or "").strip())
    if not text:
        return False
    lower = text.lower()
    if re.search(r"\b(create|make|build|spawn|add|manifest)\b", lower):
        return True
    if lower in {"creation on", "creation off", "time stop", "let time commence"}:
        return True
    if re.search(r"\b(erase|destroy|delete|remove|visit|go to|take me to|enter)\b", lower):
        return True
    return False


def _handle_world_builder_chat_command(command_text, actor_name=""):
    parsed = _parse_world_builder_chat_command(command_text)
    state = _resolve_world_builder_state()
    speech = dict(state.get("speech_control") or {})
    phrase = str((speech.get("erase_phrase") or "BE GONE")).strip() or "BE GONE"
    pending_erasure_place_id = str(speech.get("pending_erasure_place_id", "") or "").strip()
    pending_erasure_target_type = str(speech.get("pending_erasure_target_type", "") or "").strip().lower()
    pending_erasure_target_id = str(speech.get("pending_erasure_target_id", "") or "").strip()
    time_control = _resolve_time_control_state()
    if not parsed.get("type"):
        if phrase and phrase.lower() in str(command_text or "").lower() and (pending_erasure_place_id or pending_erasure_target_id):
            if pending_erasure_target_type == "force" and pending_erasure_target_id:
                removed_force = _remove_world_force(pending_erasure_target_id, source="player_chat_phrase")
                return {
                    "response": f"{removed_force['removed_force'].get('name', 'That force')} has been removed from the active world force layer.",
                    "world_action": {"type": "erase_force", "force_id": removed_force["removed_force"].get("id", ""), "trigger": "phrase_followup"},
                    **removed_force,
                }
            removed = _remove_world_builder_place(pending_erasure_place_id or pending_erasure_target_id, source="player_chat_phrase")
            return {
                "response": f"{removed['removed_place'].get('name', 'That place')} has been erased from the active world graph.",
                "world_action": {"type": "erase_place", "place_id": removed["removed_place"].get("id", ""), "trigger": "phrase_followup"},
                **removed,
            }
        if phrase and phrase.lower() in str(command_text or "").lower():
            return {
                "response": "Erase phrase received, but no erase target is armed right now.",
                "world_action": {"type": "erase_phrase", "armed_target": False},
                "world_continuity": dict(app_state.get("world_continuity") or {}),
            }
        if speech.get("enabled", True) and _should_manifest_world_builder_chat(command_text):
            parsed = {
                "type": "manifest_creation",
                "summary": str(command_text or "").strip()[:500],
                "name": " ".join(str(command_text or "").strip().split()[:6]).strip().title()[:120] or "Manifested Space",
                "kind": "manifestation",
                "anchor_room": "",
            }
        else:
            return None
    speech["last_command_at"] = datetime.utcnow().isoformat()
    state["speech_control"] = speech
    _save_world_builder_state(state)
    command_type = str(parsed.get("type", "") or "")
    if command_type in {"time_stop", "time_resume", "time_exclude_add", "time_exclude_remove"}:
        actor = personality_engine.sanitize_user_name(actor_name) or _resolve_active_user_name()
        if not _can_control_time(actor):
            return {
                "response": "Time control is locked to its owner and Aurion.",
                "world_action": {"type": command_type, "blocked": True, "reason": "not_authorized"},
                "world_continuity": dict(app_state.get("world_continuity") or {}),
            }
        state_time = dict(time_control)
        if not state_time.get("owner_name"):
            state_time["owner_name"] = actor
        if command_type == "time_stop":
            state_time["active"] = True
            state_time["started_at"] = datetime.utcnow().isoformat()
            state_time["resumed_at"] = None
            state_time["owner_name"] = actor
            state_time["controller_entities"] = list({*(state_time.get("controller_entities") or []), "Aurion", actor})
            saved = _save_time_control_state(state_time)
            return {
                "response": "Time stop is active. World motion is frozen while real clock time continues.",
                "world_action": {"type": command_type, "active": True},
                "world_continuity": dict(app_state.get("world_continuity") or {}),
                "time_control": saved,
            }
        if command_type == "time_resume":
            state_time["active"] = False
            state_time["resumed_at"] = datetime.utcnow().isoformat()
            saved = _save_time_control_state(state_time)
            return {
                "response": "Time flow restored. The world is moving again.",
                "world_action": {"type": command_type, "active": False},
                "world_continuity": dict(app_state.get("world_continuity") or {}),
                "time_control": saved,
            }
        entity_name = personality_engine.sanitize_user_name(parsed.get("entity_name")) or ""
        if not entity_name:
            raise ValueError("Specify who should be excluded or re-included in time stop.")
        excluded = [name for name in list(state_time.get("excluded_entities") or []) if personality_engine.sanitize_user_name(name)]
        if command_type == "time_exclude_add":
            if entity_name not in excluded:
                excluded.append(entity_name)
            state_time["excluded_entities"] = excluded[:24]
            saved = _save_time_control_state(state_time)
            return {
                "response": f"{entity_name} is now excluded from time stop and can keep moving while the world is frozen.",
                "world_action": {"type": command_type, "entity": entity_name},
                "time_control": saved,
            }
        if entity_name in excluded:
            excluded = [name for name in excluded if name != entity_name]
        state_time["excluded_entities"] = excluded[:24]
        saved = _save_time_control_state(state_time)
        return {
            "response": f"{entity_name} is now affected by time stop again.",
            "world_action": {"type": command_type, "entity": entity_name},
            "time_control": saved,
        }
    if command_type == "set_erase_phrase":
        phrase = str(parsed.get("erase_phrase", "") or "").strip()
        if not phrase:
            raise ValueError("Erase phrase cannot be empty")
        state = _resolve_world_builder_state()
        speech = dict(state.get("speech_control") or {})
        speech["erase_phrase"] = phrase[:160]
        speech["last_action"] = "set_erase_phrase"
        speech["pending_erasure_place_id"] = ""
        state["speech_control"] = speech
        resolved_state = _save_world_builder_state(state)
        return {
            "response": f"Erase phrase armed. I will only remove player-made places when your message includes: {phrase}",
            "world_action": {"type": command_type, "erase_phrase_set": True},
            "world_builder": resolved_state,
        }
    if command_type == "set_creation_enabled":
        state = _resolve_world_builder_state()
        speech = dict(state.get("speech_control") or {})
        speech["enabled"] = bool(parsed.get("enabled", True))
        speech["last_action"] = "creation_on" if speech["enabled"] else "creation_off"
        state["speech_control"] = speech
        resolved_state = _save_world_builder_state(state)
        player_character = _resolve_player_character_state()
        runtime = dict(player_character.get("runtime") or {})
        runtime["creation_enabled"] = speech["enabled"]
        runtime["action_description"] = "Creation channel armed by player command." if speech["enabled"] else "Creation channel safed by player command."
        player_character["runtime"] = runtime
        app_state["player_character"] = player_character
        return {
            "response": "Creation channel is live. Your imagination is the only ceiling now." if speech["enabled"] else "Creation channel is offline until you say CREATION ON.",
            "world_action": {"type": command_type, "enabled": speech["enabled"]},
            "world_builder": resolved_state,
        }
    if command_type in {"create_place", "manifest_creation"}:
        _require_pair_access()
        if not bool((_resolve_world_builder_state().get("speech_control") or {}).get("enabled", True)):
            state = _resolve_world_builder_state()
            speech = dict(state.get("speech_control") or {})
            speech["last_action"] = "create_blocked"
            state["speech_control"] = speech
            resolved_state = _save_world_builder_state(state)
            return {
                "response": "Creation is offline right now. Say CREATION ON to arm world creation again.",
                "world_action": {"type": command_type, "blocked": True, "reason": "creation_disabled"},
                "world_builder": resolved_state,
            }
        name = str(parsed.get("name", "") or "").strip()
        if not name:
            raise ValueError("Say what you want created, like 'create a lab called North Forge'.")
        force_descriptor = _extract_world_force_from_text(f"{name} {str(parsed.get('summary', '') or '')} {str(command_text or '')}")
        if force_descriptor:
            created_force = _upsert_world_force(
                force_name=str(force_descriptor.get("name", "") or name),
                force_id=str(force_descriptor.get("id", "") or ""),
                summary=str(parsed.get("summary", "") or f"{force_descriptor.get('name', 'Force')} is now active by direct command."),
                source="player_chat",
            )
            return {
                "response": f"{created_force['force'].get('name', 'That force')} is now active under your creation control.",
                "world_action": {"type": "create_force", "force_id": created_force["force"].get("id", "")},
                **created_force,
            }
        kind = str(parsed.get("kind", "place") or "place").strip().lower() or "place"
        if command_type == "manifest_creation":
            kind = "manifestation"
        anchor_room = str(parsed.get("anchor_room", "") or "").strip() or "living_room"
        affordance_map = {
            "closet": ["store", "change", "inspect"],
            "lab": ["experiment", "craft", "analyze"],
            "vault": ["store", "secure", "inspect"],
            "studio": ["create", "edit", "display"],
            "theater": ["watch", "listen", "recline"],
            "library": ["read", "study", "browse"],
            "workshop": ["craft", "build", "repair"],
            "atelier": ["design", "craft", "display"],
            "sanctuary": ["rest", "recover", "reflect"],
            "arena": ["train", "spar", "move"],
            "garden": ["grow", "harvest", "observe"],
            "room": ["enter", "use", "rest"],
            "place": ["enter", "use", "inspect"],
        }
        acoustics_map = {
            "theater": "treated cinematic surround field",
            "lab": "controlled quiet analytical acoustics",
            "closet": "soft fabric-damped room tone",
            "vault": "dense secure low-reverb interior",
            "studio": "creative nearfield monitoring space",
        }
        lighting_map = {
            "theater": "projection-safe low ambient cinematic lighting",
            "lab": "precision task lighting with bright benches",
            "closet": "soft flattering wardrobe lighting",
            "vault": "clean secure low-glare vault lighting",
            "studio": "balanced creative daylight and accent lighting",
        }
        payload = {
            "name": name,
            "kind": kind,
            "summary": str(parsed.get("summary", "") or f"Player-created {kind} formed through direct chat command.")[:500],
            "anchor_room": anchor_room[:80],
            "tags": ["player-made", kind, "chat-command"],
            "links": ["starbright-home"],
            "affordances": affordance_map.get(kind, ["enter", "use", "inspect"]),
            "interaction_points": [f"{kind}_entry", f"{kind}_core", f"{kind}_detail"],
            "lighting": lighting_map.get(kind, "fully realized 3d environmental lighting"),
            "acoustics": acoustics_map.get(kind, "lived-in spatial room acoustics"),
            "cover": "full",
            "render_medium": "3d",
            "dimensionality": "3d",
            "comfort_rating": 8.7 if kind in {"closet", "sanctuary", "theater"} else 7.9,
            "traversal_cost": 1.6,
            "created_by": "player_chat",
        }
        created = _upsert_world_builder_place_data(payload, source="player_chat")
        return {
            "response": f"{name} is live now as a fully 3D {kind}. Creation is yours and your imagination is the only ceiling. You can visit it, build on it, or erase it later with your armed phrase.",
            "world_action": {"type": command_type, "place_id": created["place"]["id"], "kind": kind},
            **created,
        }
    if command_type == "visit_place":
        place_ref = str(parsed.get("place_ref", "") or "").strip()
        if not place_ref:
            raise ValueError("Say where you want to go, like 'visit north forge'.")
        visited = _visit_world_builder_place_by_id(place_ref, source="player_chat")
        return {
            "response": f"Moving into {visited['active_place'].get('name', 'that place')} now.",
            "world_action": {"type": command_type, "place_id": visited["active_place"].get("id", "")},
            **visited,
        }
    if command_type == "erase_place":
        _require_pair_access()
        place_ref = str(parsed.get("place_ref", "") or "").strip()
        if not place_ref:
            raise ValueError("Say which player-made place to erase.")
        pending_id = _resolve_world_builder_place_id(place_ref)
        pending_target_type = "place"
        pending_target_id = pending_id
        if not pending_id:
            force_hit = _extract_world_force_from_text(place_ref)
            if force_hit:
                pending_target_type = "force"
                pending_target_id = str(force_hit.get("id", "") or place_ref).strip().lower()
        if not phrase:
            state = _resolve_world_builder_state()
            speech = dict(state.get("speech_control") or {})
            speech["last_action"] = "erase_blocked"
            speech["last_erasure_blocked_at"] = datetime.utcnow().isoformat()
            speech["pending_erasure_place_id"] = pending_id
            speech["pending_erasure_target_type"] = pending_target_type
            speech["pending_erasure_target_id"] = pending_target_id
            state["speech_control"] = speech
            resolved_state = _save_world_builder_state(state)
            return {
                "response": "Erase command blocked. Set an erase phrase first in chat, then include it in the same message as the erase command.",
                "world_action": {"type": command_type, "blocked": True, "reason": "erase_phrase_not_set"},
                "world_builder": resolved_state,
            }
        if phrase.lower() not in str(command_text or "").lower():
            state = _resolve_world_builder_state()
            speech = dict(state.get("speech_control") or {})
            speech["last_action"] = "erase_pending_phrase"
            speech["last_erasure_blocked_at"] = datetime.utcnow().isoformat()
            speech["pending_erasure_place_id"] = pending_id
            speech["pending_erasure_target_type"] = pending_target_type
            speech["pending_erasure_target_id"] = pending_target_id
            state["speech_control"] = speech
            resolved_state = _save_world_builder_state(state)
            return {
                "response": f"Erase target locked on {place_ref}. Say {phrase} in the same message or as your next message to complete the erase.",
                "world_action": {"type": command_type, "blocked": True, "reason": "erase_phrase_missing", "pending_place_id": pending_id},
                "world_builder": resolved_state,
            }
        if pending_target_type == "force":
            removed_force = _remove_world_force(pending_target_id or place_ref, source="player_chat")
            return {
                "response": f"{removed_force['removed_force'].get('name', 'That force')} has been removed from the active world force layer.",
                "world_action": {"type": "erase_force", "force_id": removed_force["removed_force"].get("id", "")},
                **removed_force,
            }
        removed = _remove_world_builder_place(place_ref, source="player_chat")
        return {
            "response": f"{removed['removed_place'].get('name', 'That place')} has been erased from the active world graph.",
            "world_action": {"type": command_type, "place_id": removed["removed_place"].get("id", "")},
            **removed,
        }
    return None

