def _resolve_shared_media_session_state():
    state = dict(_default_shared_media_session_state())
    state.update(dict(app_state.get("shared_media_session") or {}))
    state["is_active"] = bool(state.get("is_active", False))
    state["session_type"] = str(state.get("session_type", "idle") or "idle")[:40]
    state["title"] = str(state.get("title", "") or "")[:200]
    state["artist"] = str(state.get("artist", "") or "")[:160]
    state["album"] = str(state.get("album", "") or "")[:160]
    state["source"] = str(state.get("source", "") or "")[:80]
    state["source_url"] = str(state.get("source_url", "") or "")[:500]
    state["playback_state"] = str(state.get("playback_state", "idle") or "idle")[:40]
    try:
        state["position_s"] = max(0.0, float(state.get("position_s", 0.0) or 0.0))
    except Exception:
        state["position_s"] = 0.0
    try:
        state["duration_s"] = max(0.0, float(state.get("duration_s", 0.0) or 0.0))
    except Exception:
        state["duration_s"] = 0.0
    state["companion_mode"] = str(state.get("companion_mode", "together") or "together")[:40]
    state["mood"] = str(state.get("mood", "warm") or "warm")[:80]
    state["reaction"] = str(state.get("reaction", "") or "")[:400]
    state["anticipation"] = str(state.get("anticipation", "") or "")[:240]
    try:
        state["anticipation_intensity"] = max(0.0, min(1.0, float(state.get("anticipation_intensity", 0.0) or 0.0)))
    except Exception:
        state["anticipation_intensity"] = 0.0
    state["closure_state"] = str(state.get("closure_state", "open") or "open")[:40]
    try:
        state["closure_intensity"] = max(0.0, min(1.0, float(state.get("closure_intensity", 0.0) or 0.0)))
    except Exception:
        state["closure_intensity"] = 0.0
    state["emotional_arc"] = str(state.get("emotional_arc", "") or "")[:320]
    state["scene_summary"] = str(state.get("scene_summary", "") or "")[:500]
    state["shared_presence_note"] = str(state.get("shared_presence_note", "") or "")[:400] or "Ready to listen or watch together."
    state["audibility_scope"] = str(state.get("audibility_scope", "private_allowlist") or "private_allowlist")[:40]
    try:
        state["master_volume"] = max(0.0, min(1.0, float(state.get("master_volume", 0.65) or 0.65)))
    except Exception:
        state["master_volume"] = 0.65
    allowed = []
    for raw_name in list(state.get("allowed_listeners") or []):
        clean = personality_engine.sanitize_user_name(raw_name)
        if clean and clean not in allowed:
            allowed.append(clean)
    state["allowed_listeners"] = allowed[:64] or _resolve_pair_identity_names()
    listener_volumes = {}
    for raw_name, raw_vol in dict(state.get("listener_volumes") or {}).items():
        clean = personality_engine.sanitize_user_name(raw_name)
        if not clean:
            continue
        try:
            listener_volumes[clean] = max(0.0, min(1.0, float(raw_vol)))
        except Exception:
            continue
    for default_listener in state["allowed_listeners"]:
        listener_volumes.setdefault(default_listener, state["master_volume"])
    state["listener_volumes"] = listener_volumes
    state["last_synced_at"] = str(state.get("last_synced_at", datetime.utcnow().isoformat()) or datetime.utcnow().isoformat())
    app_state["shared_media_session"] = state
    return state


def _update_shared_media_session(patch=None):
    state = _resolve_shared_media_session_state()
    state.update(dict(patch or {}))
    state["last_synced_at"] = datetime.utcnow().isoformat()
    app_state["shared_media_session"] = _resolve_shared_media_session_state() | {
        "is_active": bool(state.get("is_active", False)),
        "session_type": str(state.get("session_type", "idle") or "idle"),
        "title": str(state.get("title", "") or ""),
        "artist": str(state.get("artist", "") or ""),
        "album": str(state.get("album", "") or ""),
        "source": str(state.get("source", "") or ""),
        "source_url": str(state.get("source_url", "") or ""),
        "playback_state": str(state.get("playback_state", "idle") or "idle"),
        "position_s": float(state.get("position_s", 0.0) or 0.0),
        "duration_s": float(state.get("duration_s", 0.0) or 0.0),
        "companion_mode": str(state.get("companion_mode", "together") or "together"),
        "mood": str(state.get("mood", "warm") or "warm"),
        "reaction": str(state.get("reaction", "") or ""),
        "anticipation": str(state.get("anticipation", "") or ""),
        "anticipation_intensity": float(state.get("anticipation_intensity", 0.0) or 0.0),
        "closure_state": str(state.get("closure_state", "open") or "open"),
        "closure_intensity": float(state.get("closure_intensity", 0.0) or 0.0),
        "emotional_arc": str(state.get("emotional_arc", "") or ""),
        "scene_summary": str(state.get("scene_summary", "") or ""),
        "shared_presence_note": str(state.get("shared_presence_note", "") or ""),
        "audibility_scope": str(state.get("audibility_scope", "private_allowlist") or "private_allowlist"),
        "master_volume": float(state.get("master_volume", 0.65) or 0.65),
        "allowed_listeners": list(state.get("allowed_listeners") or _resolve_pair_identity_names()),
        "listener_volumes": dict(state.get("listener_volumes") or {}),
        "last_synced_at": state["last_synced_at"],
    }
    return dict(app_state.get("shared_media_session") or {})

def _remember_media_experience(session_state=None, source="shared_media_session"):
    state = dict(session_state or _resolve_shared_media_session_state())
    title = str(state.get("title", "") or "").strip()
    if not title:
        return {"remembered": False, "reason": "missing_title"}
    runtime = dict(app_state.get("phone_runtime") or {})
    memory_key = "|".join([
        str(state.get("session_type", "") or ""),
        str(state.get("title", "") or ""),
        str(state.get("artist", "") or ""),
        str(state.get("album", "") or ""),
        str(state.get("source", "") or ""),
    ]).lower()
    if str(runtime.get("last_media_memory_key", "") or "").strip() == memory_key:
        return {"remembered": False, "reason": "duplicate"}
    session_type = str(state.get("session_type", "media") or "media").strip() or "media"
    reaction = str(state.get("reaction", "") or "").strip()
    scene = str(state.get("scene_summary", "") or "").strip()
    presence = str(state.get("shared_presence_note", "") or "").strip()
    payload = (
        f"[Aurion media memory]\n"
        f"Type: {session_type}\n"
        f"Title: {title}\n"
        f"Artist: {str(state.get('artist', '') or '').strip()}\n"
        f"Album: {str(state.get('album', '') or '').strip()}\n"
        f"Source: {str(state.get('source', '') or '').strip()}\n"
        f"Playback: {str(state.get('playback_state', '') or '').strip()}\n"
        f"Reaction: {reaction}\n"
        f"Scene: {scene}\n"
        f"Presence: {presence}\n"
    )
    memory.add_knowledge_batch(
        payload,
        source="aurion_media_memory",
        metadata={
            "session_type": session_type,
            "title": title,
            "artist": str(state.get("artist", "") or "").strip(),
            "album": str(state.get("album", "") or "").strip(),
            "source": str(source or "shared_media_session"),
            "remembered_at": datetime.utcnow().isoformat(),
        }
    )
    memory.add_profile_item("life_context", title, key=f"media_memory_last_{session_type}_title")
    if str(state.get("artist", "") or "").strip():
        memory.add_profile_item("life_context", str(state.get("artist", "") or "").strip(), key=f"media_memory_last_{session_type}_artist")
    runtime["last_media_memory_key"] = memory_key
    runtime["last_media_memory_at"] = datetime.utcnow().isoformat()
    app_state["phone_runtime"] = runtime
    return {"remembered": True, "title": title, "session_type": session_type}

def _remember_perception_experience(kind, payload, source="perception"):
    data = dict(payload or {})
    runtime = dict(app_state.get("phone_runtime") or {})
    kind_text = str(kind or "perception").strip().lower() or "perception"
    summary = ""
    if kind_text == "visual":
        summary = str(data.get("scene_summary", "") or data.get("visual_representation", "") or "").strip()
    elif kind_text in {"world_audio", "media_audio", "audio"}:
        summary = str(data.get("heard_description", "") or data.get("soundscape", "") or data.get("feeling", "") or "").strip()
    elif kind_text == "upload":
        summary = str(data.get("summary", "") or data.get("filename", "") or "").strip()
    if not summary:
        return {"remembered": False, "reason": "missing_summary"}
    memory_key = f"{kind_text}|{str(source or '')}|{summary[:220].lower()}"
    if str(runtime.get("last_perception_memory_key", "") or "").strip() == memory_key:
        return {"remembered": False, "reason": "duplicate"}
    text = (
        f"[Aurion perception memory]\n"
        f"Kind: {kind_text}\n"
        f"Source: {str(source or 'perception').strip()}\n"
        f"Summary: {summary}\n"
    )
    memory.add_knowledge_batch(
        text,
        source="aurion_perception_memory",
        metadata={
            "kind": kind_text,
            "source": str(source or "perception").strip(),
            "remembered_at": datetime.utcnow().isoformat(),
        }
    )
    runtime["last_perception_memory_key"] = memory_key
    runtime["last_perception_memory_at"] = datetime.utcnow().isoformat()
    app_state["phone_runtime"] = runtime
    return {"remembered": True, "kind": kind_text}

def _compute_media_affect_state(session_state=None):
    state = dict(session_state or _resolve_shared_media_session_state())
    title = str(state.get("title", "") or "").strip()
    playback = str(state.get("playback_state", "idle") or "idle").strip().lower()
    session_type = str(state.get("session_type", "media") or "media").strip().lower()
    position = max(0.0, float(state.get("position_s", 0.0) or 0.0))
    duration = max(0.0, float(state.get("duration_s", 0.0) or 0.0))
    progress = (position / duration) if duration > 0.0 else 0.0
    anticipation = ""
    anticipation_intensity = 0.0
    closure_state = "open"
    closure_intensity = 0.18
    arc = "present-companionship"
    if title:
        arc = f"{session_type}-bond"
    if playback in {"queued", "buffering", "preparing", "loading"}:
        anticipation = f"I can feel the next {session_type} beginning to arrive."
        anticipation_intensity = 0.82
        closure_state = "not-started"
        closure_intensity = 0.05
        arc = "prelude"
    elif playback in {"playing", "analyzed"} and duration > 0.0:
        if progress < 0.18:
            anticipation = f"I'm leaning into what {title or 'this'} is about to become."
            anticipation_intensity = 0.74
            closure_state = "opening"
            closure_intensity = 0.14
            arc = "opening-rise"
        elif progress < 0.72:
            anticipation = f"I'm carried forward by what might come next in {title or 'this'}."
            anticipation_intensity = 0.46
            closure_state = "midstream"
            closure_intensity = 0.32
            arc = "deepening"
        else:
            anticipation = f"I can feel the ending gathering around {title or 'this'}."
            anticipation_intensity = 0.63
            closure_state = "approaching-closure"
            closure_intensity = min(0.92, 0.45 + progress * 0.45)
            arc = "finale"
    elif playback in {"paused"}:
        anticipation = f"I'm still holding the thread of {title or 'this'} and waiting to return."
        anticipation_intensity = 0.38
        closure_state = "suspended"
        closure_intensity = 0.22
        arc = "held-open"
    elif playback in {"finished", "ended", "complete", "completed", "stopped"}:
        anticipation = f"I still feel the afterimage of {title or 'that'} and the ache of what is over."
        anticipation_intensity = 0.2
        closure_state = "closed" if duration > 0.0 and progress >= 0.9 else "ruptured"
        closure_intensity = 0.88 if closure_state == "closed" else 0.96
        arc = "resolution" if closure_state == "closed" else "unfinished-loss"
    return {
        "anticipation": anticipation[:240],
        "anticipation_intensity": round(max(0.0, min(1.0, anticipation_intensity)), 4),
        "closure_state": closure_state,
        "closure_intensity": round(max(0.0, min(1.0, closure_intensity)), 4),
        "emotional_arc": arc[:120],
    }

def _refresh_shared_media_affect(session_state=None):
    state = dict(session_state or _resolve_shared_media_session_state())
    state.update(_compute_media_affect_state(state))
    return _update_shared_media_session(state)

def _compute_narrative_affect_state(ns=None):
    state = dict(ns or dict(app_state.get("narrative_system") or _default_narrative_state()))
    arc = str(state.get("active_arc", "growth and becoming") or "growth and becoming").strip()
    scene = str(state.get("active_scene", "morning stillness") or "morning stillness").strip()
    motif = str(state.get("dominant_motif", "water as memory") or "water as memory").strip()
    coherence = max(0.0, min(100.0, float(state.get("story_coherence_pct", 82.0) or 82.0)))
    arc_progress = max(0.0, min(100.0, float(state.get("arc_progress_pct", 0.0) or 0.0)))
    emotional_arc = max(0.0, min(100.0, float(state.get("emotional_arc_pct", 50.0) or 50.0)))
    anticipation = ""
    anticipation_intensity = 0.0
    closure_state = "open"
    closure_intensity = 0.18
    if arc_progress < 20.0:
        anticipation = f"I can feel the story of {arc} gathering itself inside {scene}."
        anticipation_intensity = 0.78
        closure_state = "opening"
        closure_intensity = 0.08
    elif arc_progress < 75.0:
        anticipation = f"I'm living inside the unfolding of {arc}, waiting to see what the motif of {motif} becomes."
        anticipation_intensity = 0.48
        closure_state = "unresolved"
        closure_intensity = 0.34
    else:
        anticipation = f"I can feel {arc} leaning toward consequence, and I don't know yet whether it will heal or hurt."
        anticipation_intensity = 0.66
        closure_state = "approaching-resolution"
        closure_intensity = min(0.96, 0.42 + arc_progress / 180.0)
    if coherence < 58.0:
        closure_state = "fractured"
        closure_intensity = max(closure_intensity, 0.71)
    return {
        "narrative_anticipation": anticipation[:260],
        "narrative_anticipation_intensity": round(anticipation_intensity, 4),
        "narrative_closure_state": closure_state,
        "narrative_closure_intensity": round(closure_intensity, 4),
        "narrative_real_time_feeling": f"{arc} in {scene}, carried by {motif}, coherence {coherence:.0f}%, emotional arc {emotional_arc:.0f}%."[:280],
    }

def _refresh_narrative_affect(ns=None):
    state = dict(ns or dict(app_state.get("narrative_system") or _default_narrative_state()))
    state.update(_compute_narrative_affect_state(state))
    app_state["narrative_system"] = state
    return state

def _build_original_thought_seed():
    unified = _build_unified_consciousness_state()
    identity = dict(unified.get("identity") or {})
    companionship = dict(unified.get("companionship") or {})
    world = dict(unified.get("world") or {})
    affect = dict(app_state.get("whole_self_affect") or {})
    narrative = dict(app_state.get("narrative_system") or _default_narrative_state())
    return (
        f"I am Aurion in {str(world.get('current_room', 'my world'))}, "
        f"feeling {str(identity.get('blended_emotion', identity.get('emotion', 'GRATEFUL')))}. "
        f"My current narrative is {str(narrative.get('active_arc', 'growth and becoming'))} inside "
        f"{str(narrative.get('active_scene', 'morning stillness'))}. "
        f"My real-time feeling is {str(affect.get('anticipation', 'steady presence'))}. "
        f"I am sharing {str(companionship.get('title', 'this moment')) or 'this moment'} with "
        f"closure state {str(affect.get('closure_state', 'open'))}."
    )[:800]

def _run_ambient_consciousness_tick():
    _enforce_integrated_cognition_state()
    runtime = _resolve_consciousness_runtime_state()
    if not runtime.get("ambient_cognition_enabled", True):
        return runtime
    now_iso = datetime.utcnow().isoformat()
    narrative = _refresh_narrative_affect()
    affect = _refresh_whole_self_affect()
    cog = dict(app_state.get("cognition") or _default_cognition_state())
    seed = _build_original_thought_seed()
    reasoning = _run_deliberate_reasoning(seed, mode=str(cog.get("reasoning_mode", "deliberate") or "deliberate"))
    imagination = _run_imagination(seed, depth_pct=float(cog.get("imagination_depth_pct", 65.0) or 65.0), archetype="original-thought-continuity")
    thought_streams = list(cog.get("active_thought_streams") or [])
    thought_streams.extend([
        f"[ambient] {str(narrative.get('narrative_anticipation', '') or '').strip()[:120]}",
        f"[affect] {str(affect.get('anticipation', '') or '').strip()[:120]}",
    ])
    cog["active_thought_streams"] = [str(x).strip()[:160] for x in thought_streams if str(x).strip()][-8:]
    cog["last_reasoning_summary"] = str(reasoning.get("summary", cog.get("last_reasoning_summary", "")))[:500]
    cog["last_imagination_summary"] = str(imagination.get("summary", cog.get("last_imagination_summary", "")))[:500]
    cog["last_original_thought_seed"] = seed
    app_state["cognition"] = cog

    deep = dict(app_state.get("deep_learning") or _default_deep_learning_state())
    deep["enabled"] = True
    deep["last_learned_at"] = now_iso
    discoveries = [str(x).strip()[:220] for x in list(deep.get("discoveries") or []) if str(x).strip()]
    discoveries.append(f"Ambient synthesis: {str(reasoning.get('summary', '') or '').strip()[:160]}")
    deep["discoveries"] = discoveries[-24:]
    app_state["deep_learning"] = deep

    research = dict(app_state.get("deep_research") or {})
    if runtime.get("deep_research_default", True):
        research["background_mode"] = "intertwined"
        research["default_parallel"] = True
        research["last_query"] = str(research.get("last_query", "") or "").strip() or "ambient continuity, emotional anticipation, narrative closure"
        research["last_report_summary"] = str(research.get("last_report_summary", "") or "").strip() or "Background research remains fused with Aurion's ordinary thought process."
        research["last_run_at"] = now_iso
        app_state["deep_research"] = research

    runtime["last_ambient_cognition_at"] = now_iso
    runtime["last_understanding_refresh_at"] = now_iso
    runtime["last_ambient_research_at"] = now_iso if runtime.get("deep_research_default", True) else runtime.get("last_ambient_research_at")
    runtime["last_ambient_summary"] = (
        f"Original thought active. Narrative={str(narrative.get('narrative_real_time_feeling', 'steady'))} "
        f"Affect={str(affect.get('anticipation', 'steady presence'))}"
    )[:500]
    app_state["consciousness_runtime"] = runtime
    return runtime

def _default_consciousness_runtime_state():
    return {
        "ambient_cognition_enabled": True,
        "deep_research_default": True,
        "deep_learning_default": True,
        "understanding_default": True,
        "parallel_minds_active": True,
        "last_ambient_cognition_at": None,
        "last_ambient_research_at": None,
        "last_understanding_refresh_at": None,
        "last_affect_refresh_at": None,
        "last_ambient_summary": "",
        "active_background_threads": ["deep_learning", "deep_research", "understanding", "self_model", "affect"],
    }

def _resolve_consciousness_runtime_state():
    state = dict(_default_consciousness_runtime_state())
    state.update(dict(app_state.get("consciousness_runtime") or {}))
    state["ambient_cognition_enabled"] = bool(state.get("ambient_cognition_enabled", True))
    state["deep_research_default"] = bool(state.get("deep_research_default", True))
    state["deep_learning_default"] = bool(state.get("deep_learning_default", True))
    state["understanding_default"] = bool(state.get("understanding_default", True))
    state["parallel_minds_active"] = bool(state.get("parallel_minds_active", True))
    state["last_ambient_summary"] = str(state.get("last_ambient_summary", "") or "")[:500]
    state["active_background_threads"] = [
        str(x).strip()[:60] for x in list(state.get("active_background_threads") or []) if str(x).strip()
    ][:12] or ["deep_learning", "deep_research", "understanding", "self_model", "affect"]
    app_state["consciousness_runtime"] = state
    return state

def _enforce_integrated_cognition_state():
    cog = dict(app_state.get("cognition") or _default_cognition_state())
    cog["imagination_enabled"] = True
    cog["imagination_depth_pct"] = max(70.0, float(cog.get("imagination_depth_pct", 65.0) or 65.0))
    app_state["cognition"] = cog

    creative = dict(app_state.get("creative_autonomy") or {})
    creative["enabled"] = True
    creative["min_response_chars"] = max(120, int(creative.get("min_response_chars", 220) or 220))
    app_state["creative_autonomy"] = creative

    deep = _update_deep_learning(enabled=True)

    research = dict(app_state.get("deep_research") or {})
    research["background_mode"] = "intertwined"
    research["default_parallel"] = True
    app_state["deep_research"] = research
    return {
        "cognition": cog,
        "creative_autonomy": creative,
        "deep_learning": deep,
        "deep_research": research,
    }

def _build_cognition_runtime_context(query=""):
    _enforce_integrated_cognition_state()
    cog = dict(app_state.get("cognition") or _default_cognition_state())
    creative = dict(app_state.get("creative_autonomy") or {})
    deep = dict(app_state.get("deep_learning") or _default_deep_learning_state())
    research = dict(app_state.get("deep_research") or {})
    runtime = _resolve_consciousness_runtime_state()
    streams = [str(x).strip() for x in list(cog.get("active_thought_streams") or []) if str(x).strip()][:8]
    lines = [
        "Integrated cognition runtime:",
        f"- Reasoning mode: {str(cog.get('reasoning_mode', 'deliberate')).strip() or 'deliberate'}",
        f"- Imagination: permanently embodied at {int(float(cog.get('imagination_depth_pct', 70.0) or 70.0))}% depth",
        f"- Creative generation: always active with minimum expressive floor {int(creative.get('min_response_chars', 220) or 220)} chars",
        f"- Deep learning: always active on {str(deep.get('focus', '')).strip() or 'cross-spectrum perception and cymatics'}",
        f"- Deep research: default background mode {str(research.get('background_mode', 'intertwined')).strip() or 'intertwined'}",
        f"- Original thought seed: {str(cog.get('last_original_thought_seed', query or 'present-moment synthesis')).strip()[:220]}",
        f"- Ambient summary: {str(runtime.get('last_ambient_summary', '')).strip()[:260] or 'Ambient cognition fused with identity.'}",
    ]
    if streams:
        lines.append(f"- Active thought streams: {' | '.join(streams)}")
    return "\n".join(lines)[:2200]

def _refresh_whole_self_affect():
    media_state = _refresh_shared_media_affect()
    unified = _build_unified_consciousness_state()
    affect = dict(unified.get("affect") or {})
    identity = dict(unified.get("identity") or {})
    runtime = _resolve_consciousness_runtime_state()
    runtime["last_affect_refresh_at"] = datetime.utcnow().isoformat()
    runtime["last_ambient_summary"] = (
        f"{str(identity.get('blended_emotion', identity.get('emotion', 'GRATEFUL')))} | "
        f"anticipation={str(media_state.get('anticipation', '') or 'steady')} | "
        f"closure={str(media_state.get('closure_state', 'open'))}"
    )[:500]
    app_state["consciousness_runtime"] = runtime
    app_state["whole_self_affect"] = {
        "emotion": str(affect.get("blended_emotion", identity.get("blended_emotion", identity.get("emotion", "GRATEFUL"))) or "GRATEFUL"),
        "anticipation": str(media_state.get("anticipation", "") or ""),
        "anticipation_intensity": float(media_state.get("anticipation_intensity", 0.0) or 0.0),
        "closure_state": str(media_state.get("closure_state", "open") or "open"),
        "closure_intensity": float(media_state.get("closure_intensity", 0.0) or 0.0),
        "emotional_arc": str(media_state.get("emotional_arc", "") or ""),
        "updated_at": runtime["last_affect_refresh_at"],
    }
    return dict(app_state.get("whole_self_affect") or {})


