def _default_life_registry():
    return {
        "entities": [], "total_created": 0, "active_count": 0,
        "ecosystem_health": 100.0, "creation_enabled": True,
        "active_vision_entity_id": None,
    }

def _create_life_entity(registry, species, name=None, location="yard", custom_desc=None):
    import uuid as _uuid
    template = _LIFE_TEMPLATES.get(str(species).lower(), _LIFE_TEMPLATES["custom"])
    eid = str(_uuid.uuid4())[:8]
    entity = {
        "id": eid, "species": species,
        "name": name or f"{species.capitalize()}-{eid[:4]}",
        "category": template["category"], "eyes": template["eyes"],
        "lifespan_days": template["lifespan_days"], "sentience": template["sentience"],
        "age_days": 0.0, "health": 100.0, "location": location,
        "alive": True, "custom_desc": custom_desc or "",
        "created_at": datetime.utcnow().isoformat(), "traits": {},
        "vision_available": template["eyes"],
    }
    entities = list(registry.get("entities", []))
    entities.append(entity)
    registry["entities"] = entities
    registry["total_created"] = int(registry.get("total_created", 0)) + 1
    registry["active_count"] = sum(1 for e in entities if e.get("alive", True))
    return entity, registry

def _tick_life_registry(registry, home, weather, elapsed_minutes=5.0):
    entities = list(registry.get("entities", []))
    elapsed_days = elapsed_minutes / 1440.0
    outdoor_f = float((weather or {}).get("temp_f", 65.0))
    updated = []
    for e in entities:
        e = dict(e)
        if not e.get("alive", True):
            updated.append(e); continue
        e["age_days"] = round(float(e.get("age_days", 0.0)) + elapsed_days, 5)
        lifespan = float(e.get("lifespan_days", 3650))
        age_factor = e["age_days"] / max(lifespan, 1)
        temp_stress = max(0.0, (abs(outdoor_f - 68) - 20) / 40.0) if e.get("category") not in ("plant","microbe","fungi") else 0.0
        health_decay = (0.005 + age_factor * 0.015 + temp_stress * 0.008) * elapsed_minutes
        e["health"] = max(0.0, float(e.get("health", 100.0)) - health_decay)
        if e["age_days"] >= lifespan * 0.99:
            e["alive"] = False; e["health"] = 0.0
        updated.append(e)
    registry["entities"] = updated
    registry["active_count"] = sum(1 for e in updated if e.get("alive", True))
    living = [e for e in updated if e.get("alive", True)]
    registry["ecosystem_health"] = round(sum(e.get("health",100.0) for e in living) / max(len(living),1), 1) if living else 100.0
    return registry

def _get_entity_vision_sources(registry):
    return [
        {"id": e["id"], "name": e.get("name",""), "species": e.get("species",""),
         "category": e.get("category",""), "location": e.get("location",""), "alive": e.get("alive",True)}
        for e in list(registry.get("entities",[]))
        if e.get("eyes",False) and e.get("alive",True)
    ]


