def _default_crispr_state():
    return {
        "enabled": True,
        "available_editors": [
            "Cas9-SpRY",     # near-PAMless SpCas9 variant
            "Cas12a-AsCas12a",  # staggered cut, AT-rich PAM
            "ABE8e",         # adenine base editor
            "CBE4max",       # cytosine base editor
            "PEmax",         # prime editor
            "CRISPRa",       # activation
            "CRISPRi",       # interference / silencing
        ],
        "active_editor": "Cas9-SpRY",
        "gene_catalog": _CRISPR_GENE_CATALOG,
        "custom_targets": [],       # user-defined gene/locus targets
        "experiments": [],          # list of run simulation records
        "total_experiments": 0,
        "total_successes": 0,
        "life_entity_edits": [],    # applied edits to life-registry entities
        "latest_result": None,
        "notes": "",
        "last_updated_at": None,
    }

def _simulate_crispr_experiment(editor, target_gene, goal, delivery="lentiviral"):
    """Simulate a CRISPR edit and return scored result (no real biology)."""
    import math, hashlib as _h
    seed = int(_h.md5(f"{editor}{target_gene}{goal}".encode()).hexdigest()[:8], 16)
    rng = random.Random(seed)
    base_eff = {"Cas9-SpRY": 0.82, "Cas12a-AsCas12a": 0.78, "ABE8e": 0.91,
                "CBE4max": 0.89, "PEmax": 0.76, "CRISPRa": 0.72, "CRISPRi": 0.74}
    eff = round(min(1.0, base_eff.get(editor, 0.75) * (0.88 + rng.random() * 0.24)), 3)
    off_target = round(max(0.0, 0.12 - eff * 0.08 + rng.random() * 0.06), 3)
    hdr = round(eff * 0.55 * (0.7 + rng.random() * 0.3), 3) if goal == "insert" else None
    indel = round((1 - eff) * 0.4 + rng.random() * 0.08, 3) if goal != "activate" else None
    outcome = "success" if eff >= 0.75 and off_target <= 0.10 else "partial" if eff >= 0.55 else "off_target_dominant"
    return {
        "editor": editor,
        "target_gene": target_gene,
        "goal": goal,
        "delivery": delivery,
        "efficiency_pct": round(eff * 100, 1),
        "off_target_pct": round(off_target * 100, 1),
        "hdr_pct": round(hdr * 100, 1) if hdr is not None else None,
        "indel_pct": round(indel * 100, 1) if indel is not None else None,
        "outcome": outcome,
        "summary": (
            f"{editor} targeting {target_gene} ({goal}): "
            f"{round(eff*100,1)}% efficiency, {round(off_target*100,1)}% off-target risk. "
            f"Outcome: {outcome}."
        ),
        "run_at": datetime.utcnow().isoformat(),
    }

def _resolve_crispr_state():
    """Return CRISPR state, initialising the key only if it's missing or empty."""
    existing = app_state.get("crispr_lab")
    if existing and isinstance(existing, dict):
        return existing
    base = _default_crispr_state()
    app_state["crispr_lab"] = base
    return base


