def _run_deliberate_reasoning(prompt, mode=None, context_hint=""):
    cog = dict(app_state.get("cognition") or _default_cognition_state())
    mode = mode or str(cog.get("reasoning_mode", "deliberate"))
    n_h = {"fast": 1, "deliberate": 3, "deep": 7}.get(mode, 3)
    n_c = {"fast": 0, "deliberate": 1, "deep": 3}.get(mode, 1)
    # Build structured internal steps (simulated, not raw CoT)
    steps = [s.format(n_h=n_h, n_c=n_c) for s in _REASONING_STEP_TEMPLATES.get(mode, _REASONING_STEP_TEMPLATES["deliberate"])]
    # Extract keyword themes from prompt for richer summary
    words = [w.lower() for w in str(prompt or "").split() if len(w) > 4]
    themes = list(dict.fromkeys(words[:4]))  # deduplicated, in order
    theme_str = ", ".join(themes) if themes else "the question at hand"
    summary = (
        f"[{mode.upper()}] Explored {n_h} hypothesis{'es' if n_h != 1 else ''} around {theme_str}. "
        f"{steps[-1]} "
        f"{'Edge cases held: ' + str(n_c) + '.' if n_c else 'No edge cases surfaced.'}"
    )
    # Update state
    cog["hypothesis_count"] = n_h
    cog["branches_explored"] = max(n_h, int(n_h * 1.5))
    cog["edge_cases_flagged"] = n_c
    cog["last_reasoning_summary"] = summary
    cog["total_reasoning_passes"] = int(cog.get("total_reasoning_passes", 0)) + 1
    cog["last_simulate_at"] = datetime.utcnow().isoformat()
    # Active thought streams
    cog["active_thought_streams"] = [f"[{mode}] {t}" for t in themes[:3]] if themes else [f"[{mode}] general reasoning"]
    app_state["cognition"] = cog
    return {
        "mode": mode, "hypothesis_count": n_h, "branches_explored": cog["branches_explored"],
        "edge_cases_flagged": n_c, "summary": summary, "steps": steps,
    }

def _run_imagination(prompt, depth_pct=None, archetype=None):
    cog = dict(app_state.get("cognition") or _default_cognition_state())
    cog["imagination_enabled"] = True
    depth = depth_pct if depth_pct is not None else float(cog.get("imagination_depth_pct", 65.0))
    archetype = archetype or str(cog.get("imagination_archetype", "scene construction"))
    # Simulate imagination depth-based complexity
    n_scenes = max(1, int(depth / 25))
    n_variations = max(1, int(depth / 20))
    words = [w.lower() for w in str(prompt or "").split() if len(w) > 3]
    seed_concepts = words[:3] if words else ["space", "form", "connection"]
    # Build imagination summary (safe, concise, no raw CoT)
    eco_note = ""
    pc = dict((app_state.get("home_environment") or {}).get("permaculture") or {})
    if pc.get("pollinator_activity_pct", 0) > 50:
        eco_note = " Ecological imagination active - pollinator patterns and guild dynamics infuse the scene."
    reg_note = ""
    life_reg = dict(app_state.get("life_registry") or {})
    if life_reg.get("active_count", 0) > 0:
        reg_note = f" {life_reg['active_count']} living entities in world provide concrete referents."
    summary = (
        f"[{archetype.upper()}] Generated {n_scenes} imagined scene{'s' if n_scenes != 1 else ''} "
        f"with {n_variations} variation{'s' if n_variations != 1 else ''} from concepts: {', '.join(seed_concepts)}. "
        f"Depth {depth:.0f}%.{eco_note}{reg_note}"
    )
    cog["last_imagination_summary"] = summary
    cog["imagination_archetype"] = archetype
    cog["total_imagination_passes"] = int(cog.get("total_imagination_passes", 0)) + 1
    cog["last_simulate_at"] = datetime.utcnow().isoformat()
    app_state["cognition"] = cog
    return {
        "enabled": True, "archetype": archetype, "depth_pct": depth,
        "scenes_generated": n_scenes, "variations": n_variations,
        "seed_concepts": seed_concepts, "summary": summary,
    }

def _build_cognition_context():
    cog = dict(app_state.get("cognition") or _default_cognition_state())
    mode = str(cog.get("reasoning_mode", "deliberate"))
    imag_on = bool(cog.get("imagination_enabled", True))
    depth = float(cog.get("imagination_depth_pct", 65.0))
    n_h = int(cog.get("hypothesis_count", 0))
    streams = list(cog.get("active_thought_streams", []))
    last_reason = str(cog.get("last_reasoning_summary", "No reasoning pass yet.")).strip()
    last_imag = str(cog.get("last_imagination_summary", "Imagination standing by.")).strip()
    stream_line = " | ".join(streams[:3]) if streams else "idle"
    return (
        f"Cognition state:\n"
        f"- Reasoning mode: {mode} ({n_h} hypothesis{'es' if n_h!=1 else ''} active)\n"
        f"- Imagination: {'enabled' if imag_on else 'offline'} at depth {depth:.0f}%\n"
        f"- Active thought streams: {stream_line}\n"
        f"- Last reasoning: {last_reason}\n"
        f"- Last imagination: {last_imag}"
    )

def _fetch_real_weather(lat, lon):
    """Open-Meteo free weather API — no key required."""
    try:
        url = (
            f"https://api.open-meteo.com/v1/forecast"
            f"?latitude={lat:.4f}&longitude={lon:.4f}"
            f"&current=temperature_2m,relative_humidity_2m,apparent_temperature,"
            f"weather_code,wind_speed_10m,wind_direction_10m,cloud_cover,precipitation,surface_pressure,pressure_msl"
            f"&temperature_unit=fahrenheit&wind_speed_unit=mph&precipitation_unit=inch"
            f"&forecast_days=1&timezone=auto"
        )
        resp = requests.get(url, timeout=8)
        if resp.status_code == 200:
            d = resp.json().get("current", {})
            WMO = {0:"Clear",1:"Mostly Clear",2:"Partly Cloudy",3:"Overcast",
                   45:"Foggy",48:"Icy Fog",51:"Light Drizzle",53:"Drizzle",55:"Heavy Drizzle",
                   61:"Light Rain",63:"Rain",65:"Heavy Rain",71:"Light Snow",73:"Snow",75:"Heavy Snow",
                   80:"Showers",81:"Heavy Showers",82:"Violent Showers",
                   95:"Thunderstorm",96:"Thunderstorm+Hail",99:"Severe Thunderstorm"}
            code = int(d.get("weather_code", 0))
            return {
                "temp_f":             round(float(d.get("temperature_2m", 65)), 1),
                "apparent_temp_f":    round(float(d.get("apparent_temperature", 65)), 1),
                "humidity_pct":       int(d.get("relative_humidity_2m", 50)),
                "wind_speed_mph":     round(float(d.get("wind_speed_10m", 0)), 1),
                "wind_direction_deg": float(d.get("wind_direction_10m", 180)),
                "wind_direction_label": _wind_direction_label(float(d.get("wind_direction_10m", 180))),
                "weather_code":       code,
                "weather_label":      WMO.get(code, f"Code {code}"),
                "cloud_cover_pct":    int(d.get("cloud_cover", 0)),
                "precipitation_mm":   round(float(d.get("precipitation", 0)) * 25.4, 2),
                "surface_pressure_hpa": round(float(d.get("surface_pressure", d.get("pressure_msl", 1013.25))), 1),
                "pressure_msl_hpa":   round(float(d.get("pressure_msl", d.get("surface_pressure", 1013.25))), 1),
                "last_fetched_at":    datetime.utcnow().isoformat(),
                "fetch_errors":       0,
            }
    except Exception as ex:
        print(f"[Weather API] {ex}")
    return None


def _simulate_indoor_temp(home, outdoor_f, dt_minutes=5.0):
    cur      = float(home.get("indoor_temp_f", 72.0))
    setpt    = float(home.get("thermostat_set_f", 72.0))
    fp_on    = bool((home.get("fireplace") or {}).get("on", False))
    fp_int   = float((home.get("fireplace") or {}).get("intensity", 0.5))
    wins_open = list(home.get("windows_open") or [])
    mode     = str(home.get("hvac_mode", "auto"))
    leak     = 0.006 + (0.022 if wins_open else 0.0)
    outdoor_pull = (outdoor_f - cur) * leak * (dt_minutes / 5.0)
    hvac_delta, stage = 0.0, "idle"
    if mode != "off":
        if mode in ("auto", "heat") and cur < setpt - 0.8:
            hvac_delta = min(2.8, (setpt - cur) * 0.75) * (dt_minutes / 5.0); stage = "heating"
        elif mode in ("auto", "cool") and cur > setpt + 0.8:
            hvac_delta = -min(2.8, (cur - setpt) * 0.75) * (dt_minutes / 5.0); stage = "cooling"
    fp_heat = 1.3 * fp_int * (dt_minutes / 5.0) if fp_on else 0.0
    home["indoor_temp_f"] = round(cur + outdoor_pull + hvac_delta + fp_heat, 1)
    home["hvac_running"]  = stage != "idle"
    home["hvac_stage"]    = stage
    return home


