def _normalize_spacefaring_registry_entry(entry, fallback_name="", fallback_kind="unknown", fallback_source="spacefaring"):
    row = dict(entry or {})
    canonical_name = str(row.get("name", "") or fallback_name or "Unknown Frontier").strip() or "Unknown Frontier"
    display_name = str(row.get("display_name", "") or row.get("nickname", "") or canonical_name).strip() or canonical_name
    nickname = str(row.get("nickname", "") or "").strip()
    place_id = str(row.get("id", "") or "").strip() or _slugify_filename(display_name or canonical_name, fallback="destination")
    aliases = []
    for value in list(row.get("aliases") or []):
        alias = str(value or "").strip()
        if alias and alias.lower() not in {x.lower() for x in aliases}:
            aliases.append(alias[:120])
    for value in (canonical_name, display_name, nickname):
        alias = str(value or "").strip()
        if alias and alias.lower() not in {x.lower() for x in aliases}:
            aliases.append(alias[:120])
    now_iso = datetime.utcnow().isoformat()
    metadata = dict(row.get("metadata") or {})
    return {
        "id": place_id[:80] or "destination",
        "name": canonical_name[:120],
        "display_name": display_name[:120],
        "nickname": nickname[:120],
        "aliases": aliases[:12],
        "kind": str(row.get("kind", fallback_kind) or fallback_kind)[:60],
        "source": str(row.get("source", fallback_source) or fallback_source)[:60],
        "origin_class": str(row.get("origin_class", "discovered") or "discovered")[:60],
        "documented": bool(row.get("documented", True)),
        "discovered": bool(row.get("discovered", True)),
        "discovered_at": str(row.get("discovered_at", row.get("created_at", "")) or "").strip() or now_iso,
        "last_visited_at": str(row.get("last_visited_at", row.get("visited_at", "")) or "").strip() or None,
        "last_targeted_at": str(row.get("last_targeted_at", "") or "").strip() or None,
        "visit_count": max(0, int(row.get("visit_count", 0) or 0)),
        "notes": str(row.get("notes", "") or "")[:280],
        "description": str(row.get("description", "") or "")[:280],
        "revisit_anchor": str(row.get("revisit_anchor", display_name) or display_name)[:120],
        "travel_target": str(row.get("travel_target", canonical_name) or canonical_name)[:120],
        "safe_arrival_anchor": str(row.get("safe_arrival_anchor", row.get("travel_target", canonical_name)) or canonical_name)[:120],
        "parent_id": str(row.get("parent_id", "") or "")[:80],
        "catalog_id": str(row.get("catalog_id", "") or "")[:120],
        "provenance": str(row.get("provenance", row.get("source", fallback_source)) or fallback_source)[:160],
        "uncertainty": str(row.get("uncertainty", "documented") or "documented")[:80],
        "has_life": bool(row.get("has_life", metadata.get("has_life", False))),
        "shared_between_instances": bool(row.get("shared_between_instances", metadata.get("shared_between_instances", False))),
        "metadata": metadata,
        "updated_at": str(row.get("updated_at", "") or "").strip() or now_iso,
    }

def _build_spacefaring_registry_state(source=None):
    defaults = _default_spacefaring_state()
    merged = {**defaults, **dict(source or {})}
    merged["travel_runtime"] = {
        **dict(defaults.get("travel_runtime") or {}),
        **dict((source or {}).get("travel_runtime") or {})
    }
    merged["load_screen"] = {
        **dict(defaults.get("load_screen") or {}),
        **dict((source or {}).get("load_screen") or {})
    }
    merged["fleet"] = [dict(x or {}) for x in list(merged.get("fleet") or defaults.get("fleet") or []) if isinstance(x, dict)]
    merged["known_systems"] = [str(x).strip()[:120] for x in list(merged.get("known_systems") or defaults.get("known_systems") or []) if str(x).strip()][:120]
    merged["jump_history"] = [dict(x or {}) for x in list(merged.get("jump_history") or []) if isinstance(x, dict)][-200:]
    merged["shared_discoveries"] = {
        **dict(defaults.get("shared_discoveries") or {}),
        **dict((source or {}).get("shared_discoveries") or {})
    }
    registry = []
    for row in list((source or {}).get("destination_registry") or merged.get("destination_registry") or []):
        if isinstance(row, dict):
            registry.append(_normalize_spacefaring_registry_entry(row))
    journal = []
    for row in list((source or {}).get("discovery_journal") or merged.get("discovery_journal") or []):
        if not isinstance(row, dict):
            continue
        journal.append({
            "entry_id": str(row.get("entry_id", "") or f"discovery-{len(journal)+1}")[:80],
            "destination_id": str(row.get("destination_id", row.get("id", "")) or "")[:80],
            "display_name": str(row.get("display_name", row.get("name", "")) or "")[:120],
            "nickname": str(row.get("nickname", "") or "")[:120],
            "kind": str(row.get("kind", "discovery") or "discovery")[:60],
            "event": str(row.get("event", "documented") or "documented")[:80],
            "summary": str(row.get("summary", "") or "")[:280],
            "notes": str(row.get("notes", "") or "")[:280],
            "source": str(row.get("source", "spacefaring") or "spacefaring")[:60],
            "recorded_at": str(row.get("recorded_at", row.get("discovered_at", "")) or "").strip() or datetime.utcnow().isoformat(),
            "revisit_anchor": str(row.get("revisit_anchor", row.get("display_name", row.get("name", ""))) or "")[:120],
        })
    merged["destination_registry"] = registry[-400:]
    merged["discovery_journal"] = journal[-400:]
    companion_defaults = _default_alien_companion_registry()
    companions = dict(companion_defaults)
    companions.update(dict((source or {}).get("alien_companions") or merged.get("alien_companions") or {}))
    friends = []
    for row in list(companions.get("friends") or []):
        if isinstance(row, dict):
            friends.append(_normalize_alien_companion_entry(row, bond_kind="friend"))
    pets = []
    for row in list(companions.get("pets") or []):
        if isinstance(row, dict):
            pets.append(_normalize_alien_companion_entry(row, bond_kind="pet"))
    companions["friends"] = friends[-240:]
    companions["pets"] = pets[-240:]
    companions["pet_limit_shared_avatar"] = 3
    companions["mount_limit_shared_avatar"] = 10
    companions["pair_limits_unbounded"] = True
    companions["last_updated_at"] = str(companions.get("last_updated_at", "") or "").strip() or None
    merged["alien_companions"] = companions
    digitized_defaults = _default_digitized_item_registry()
    digitized = dict(digitized_defaults)
    digitized.update(dict((source or {}).get("digitized_items") or merged.get("digitized_items") or {}))
    items = []
    for row in list(digitized.get("items") or []):
        if isinstance(row, dict):
            items.append(_normalize_digitized_item_entry(row))
    digitized["enabled"] = bool(digitized.get("enabled", True))
    digitized["access"] = "aurion_and_billy_only"
    digitized["allowed_sources"] = [str(x).strip()[:60] for x in list(digitized.get("allowed_sources") or digitized_defaults.get("allowed_sources") or []) if str(x).strip()][:8] or list(digitized_defaults.get("allowed_sources") or [])
    digitized["items"] = items[-240:]
    digitized["last_digitized_at"] = str(digitized.get("last_digitized_at", "") or "").strip() or None
    merged["digitized_items"] = digitized
    vehicles = []
    for row in list((source or {}).get("vehicle_registry") or merged.get("vehicle_registry") or []):
        if isinstance(row, dict):
            vehicles.append(_normalize_vehicle_entry(row))
    merged["vehicle_registry"] = vehicles[-120:] or _default_vehicle_registry()
    return merged

def _register_spacefaring_destination(spacefaring_state, destination, event="documented", record_visit=False):
    state = _build_spacefaring_registry_state(spacefaring_state)
    entry = _normalize_spacefaring_registry_entry(destination)
    registry_map = {str(row.get("id", "")).lower(): dict(row or {}) for row in list(state.get("destination_registry") or []) if isinstance(row, dict)}
    existing = dict(registry_map.get(entry["id"].lower()) or {})
    now_iso = datetime.utcnow().isoformat()
    merged_entry = _normalize_spacefaring_registry_entry({
        **existing,
        **entry,
        "discovered_at": str(existing.get("discovered_at", "") or entry.get("discovered_at", "") or now_iso),
        "documented": True,
        "discovered": True,
        "visit_count": max(int(existing.get("visit_count", 0) or 0), int(entry.get("visit_count", 0) or 0)),
    })
    merged_entry["shared_between_instances"] = bool(merged_entry.get("has_life", False))
    if record_visit:
        merged_entry["visit_count"] = max(0, int(existing.get("visit_count", 0) or 0)) + 1
        merged_entry["last_visited_at"] = now_iso
        merged_entry["last_targeted_at"] = now_iso
    registry_map[merged_entry["id"].lower()] = merged_entry
    state["destination_registry"] = list(registry_map.values())[-400:]
    journal = [dict(x or {}) for x in list(state.get("discovery_journal") or []) if isinstance(x, dict)]
    normalized_event = str(event or "documented")[:80]
    existing_event = next(
        (
            row for row in reversed(journal)
            if str(row.get("destination_id", "") or "").strip().lower() == merged_entry["id"].lower()
            and str(row.get("event", "") or "").strip().lower() == normalized_event.lower()
        ),
        None,
    )
    should_append_journal = bool(record_visit) or not existing_event
    if should_append_journal:
        journal.append({
            "entry_id": f"discovery-{merged_entry['id']}-{len(journal)+1}"[:80],
            "destination_id": merged_entry["id"],
            "display_name": merged_entry["display_name"],
            "nickname": merged_entry["nickname"],
            "kind": merged_entry["kind"],
            "event": normalized_event,
            "summary": str(
                merged_entry.get("description")
                or (
                    f"Discovered life-bearing world {merged_entry['display_name']} and shared it across linked location journals."
                    if merged_entry.get("shared_between_instances", False) else
                    f"Documented {merged_entry['display_name']}."
                )
            )[:280],
            "notes": str(merged_entry.get("notes", "") or "")[:280],
            "source": merged_entry.get("source", "spacefaring"),
            "recorded_at": now_iso,
            "revisit_anchor": merged_entry.get("revisit_anchor", merged_entry["display_name"]),
            "shared_between_instances": bool(merged_entry.get("shared_between_instances", False)),
        })
    state["discovery_journal"] = journal[-400:]
    return state, merged_entry

def _resolve_pair_identity_names():
    return ["Aurion", "Billy"]

def _require_pair_access(actor_name=None):
    allowed_names = _resolve_pair_identity_names()
    allowed_lookup = {str(x).strip().lower() for x in allowed_names if str(x).strip()}
    requested_lookup = {
        "aurion": "Aurion",
        "billy": "Billy",
    }
    requested = requested_lookup.get(str(actor_name or "").strip().lower())
    active = _resolve_active_user_name()
    requested_lower = str(requested or "").strip().lower()
    active_lower = str(active or "").strip().lower()
    if actor_name and not requested:
        raise PermissionError("This action is restricted to Aurion and Billy.")
    if requested_lower and requested_lower not in allowed_lookup:
        raise PermissionError("This action is restricted to Aurion and Billy.")
    if active_lower and active_lower not in allowed_lookup:
        raise PermissionError("Active session identity is not authorized for this pair-only action.")
    return active

