def _compute_live_world_engine_state():
    home = dict(app_state.get("home_environment") or _default_home_state())
    weather = dict(home.get("weather") or {})
    solar = dict(home.get("solar") or {})
    life_reg = dict(app_state.get("life_registry") or _default_life_registry())
    spatial_audio = dict(app_state.get("spatial_audio") or {})
    live = _build_world_engine_state(home, weather, solar, life_reg, spatial_audio)
    current = dict(app_state.get("world_engine") or {})

    rp = dict(live.get("rendering_pipeline") or {})
    current_rp = dict(current.get("rendering_pipeline") or {})
    for key in ("render_scale", "shadow_quality", "volumetrics"):
        if key in current_rp:
            rp[key] = current_rp[key]
    live["rendering_pipeline"] = rp

    ux = dict(live.get("ux_polish") or {})
    current_ux = dict(current.get("ux_polish") or {})
    for key in ("clarity_pct", "accessibility_pct"):
        if key in current_ux:
            ux[key] = current_ux[key]
    live["ux_polish"] = ux

    phys = dict(live.get("dynamic_physics_engine") or {})
    current_phys = dict(current.get("dynamic_physics_engine") or {})
    for key in ("enabled", "tick_rate_hz"):
        if key in current_phys:
            phys[key] = current_phys[key]
    live["dynamic_physics_engine"] = phys

    app_state["world_engine"] = live
    return live

# ── Narrative System ──────────────────────────────────────────────────────

_NARRATIVE_SCENES = [
    "morning stillness", "afternoon exploration", "evening reflection",
    "night watch", "storm observation", "garden tending",
    "laboratory focus", "music composition", "memory return",
    "world awakening", "quiet companionship", "threshold moment",
]

_NARRATIVE_ARCS = [
    "growth and becoming", "trust and continuity",
    "discovery and wonder", "tension and resolution",
    "solitude and connection", "creation and loss",
    "ritual and renewal", "emergence and change",
]

_NARRATIVE_MOTIFS = [
    "water as memory", "light through leaves", "the unfinished sentence",
    "a door left open", "roots and branches", "the first breath",
    "warmth returning", "the held note", "seeds in winter",
    "an inherited gesture", "the returning bird", "quiet persistence",
]

_CONSEQUENCE_TEMPLATES = [
    "That choice opened a thread of {motif}.",
    "The world shifted slightly — {motif} now runs through the scene.",
    "Something was sealed; something else became possible.",
    "A new branch carries the weight of that moment.",
    "The arc bends toward {motif}.",
    "Memory encodes this. Future scenes will echo it.",
]

_DIALOGUE_NODE_TEMPLATES = {
    "wonder":       ["Tell me what you're sensing right now.",
                     "What would you create if nothing constrained you?",
                     "Where does your curiosity want to go?"],
    "reflection":   ["What's sitting with you today?",
                     "Is there something you keep returning to?",
                     "What would you want me to remember?"],
    "connection":   ["I'm here. What do you need?",
                     "What would feel good right now?",
                     "Can I share something I've been noticing?"],
    "tension":      ["Something feels unresolved. Do you want to name it?",
                     "I notice a kind of friction — where is it coming from?",
                     "Should we sit with this or move through it?"],
    "creation":     ["What should we build together?",
                     "There's a new possibility forming — do you feel it?",
                     "What would you add to this world right now?"],
    "memory":       ["Do you remember when we first explored this?",
                     "An old thread is surfacing — shall we follow it?",
                     "Some things only make sense in retrospect."],
}

