def _water_texture(water_type="rain", temp_f=None, intensity=0.5, context=""):
    wt = _WATER_TYPES.get(water_type, _WATER_TYPES["rain"])
    t  = float(temp_f or wt["base_temp_f"])
    s  = float(intensity or 0.5)
    # Temperature feel
    if   t < 40: t_feel = "shockingly cold â€” almost aching"
    elif t < 55: t_feel = "cold, sharp and bracing"
    elif t < 65: t_feel = "cool and refreshing"
    elif t < 78: t_feel = "comfortably warm"
    elif t < 90: t_feel = "warm and soothing"
    elif t < 100:t_feel = "hot â€” relaxing ache of heat"
    else:        t_feel = f"scalding at {t:.0f}Â°F â€” steam rising"

    # Type-specific feel
    feels = {
        "rain":       f"Drops land in {'a scattered patter' if s < 0.4 else 'a steady drumming'} â€” each one a brief cold point on skin that spreads outward. {'Hair is damp within seconds.' if s > 0.6 else ''}",
        "shower":     f"{'Gentle' if s < 0.3 else 'Strong' if s < 0.7 else 'Powerful'} needles of {t_feel} water cover her back and shoulders â€” a full-body pressure that's hard to step away from. Steam curls at {t:.0f}Â°F.",
        "bath":       f"Submersion in {t_feel} water â€” buoyancy lifts her slightly, the heat wraps like a second skin. Pressure equalizes across every surface. Stillness and warmth.",
        "pool":       f"{'A cool shock' if s > 0.7 else 'Gentle resistance'} â€” the water holds her with its buoyancy, {t_feel}. Chlorine traces on skin, the slight salt of her own body dissolving.",
        "ocean":      f"Cold salt water â€” {t_feel}. Waves push and pull with real weight. The ocean resists her and holds her simultaneously. Salt taste in the air, spray on lips.",
        "lake":       f"{'Warm surface layer, cold below' if t > 70 else 'Uniformly cool'} â€” {t_feel}. Clean and still, fresh-water resistance, softer than ocean. Bottom sediment felt distantly below.",
        "stream":     f"Fast-moving {t_feel} water. The current pushes against legs with real force. Pebbles and sand beneath feet shift. Cold clarity from mountain or deep ground.",
        "drinking":   f"A long cool swallow â€” {t_feel} water fills the throat, spreads down the chest. Clean, slightly mineral. The body recognizes what it needed.",
        "waterfall":  f"The roar of it before the water hits â€” then a curtain of {t_feel} force. Mist first, then full submersion in white turbulence. The sound is total.",
        "morning_dew":f"Almost too subtle to notice â€” tiny {t_feel} beads on bare feet through grass, on fingertips brushing leaves. The world is damp and still.",
        "rain_storm": f"Driven rain â€” nearly horizontal at times, {t_feel}, {'light spattering' if s < 0.3 else 'pounding sheets of water' if s > 0.7 else 'steady heavy rain'}. Lightning in the distance. Everything soaked.",
        "mist":       f"Barely water at all â€” {t_feel} vapor on skin. Everything becomes slightly damp without a single identifiable drop. Hair frizzes. The air is thick.",
    }
    primary = feels.get(water_type, f"{t_feel} water contact with {s*100:.0f}% intensity.")
    sound = wt.get("sound", "water sounds")
    smell = wt.get("smell", "water")
    physics = {
        "rain":       "No buoyancy; impact momentum each drop.",
        "shower":     "Pressure force; warm fog; humidity near 100%.",
        "bath":       "Full buoyancy; thermal mass holds heat long after entry.",
        "pool":       "Buoyancy 8â€“10% body weight; chlorine traces on skin.",
        "ocean":      "Salt increases buoyancy by ~2.5%; waves carry real kinetic force.",
        "lake":       "Fresh water buoyancy; thermocline possible; no current (unless near river).",
        "stream":     "Current exerts 2â€“40N depending on flow; cold water constricts blood vessels.",
        "drinking":   "Hydration response; peristalsis and warmth spreading from esophagus.",
        "waterfall":  "Impact pressure up to 200N at plunge pool; aeration; oxygen-rich.",
        "morning_dew":"Surface tension on droplets; near-zero velocity; coldest just before dawn.",
        "rain_storm": "Variable impact 2â€“8mm drops; lightning hazard; electromagnetic charge in air.",
        "mist":       "Droplets 1â€“100Î¼m; stay suspended; deposit slowly on surfaces.",
    }
    return {
        "water_type": water_type,
        "temp_f": t,
        "intensity": s,
        "temperature_feel": t_feel,
        "primary_feel": primary,
        "sound_desc": sound,
        "smell_desc": smell,
        "physics_note": physics.get(water_type, ""),
        "full_sensory": f"{primary} The sound: {sound}. Scent: {smell}. {context}".strip(),
    }


