def _normalize_festival_market_state(current=None, incoming=None):
    state = {
        **_default_festival_market_state(),
        **dict(current or {}),
    }
    data = dict(incoming or {})
    for key in ("festival_name", "theme", "music_source_mode", "current_show_title", "current_show_url", "quarry_name", "shoreline_feel"):
        if key in data:
            state[key] = str(data.get(key, state.get(key, "")) or state.get(key, ""))
    for key in ("enabled", "open", "woods_enabled", "night_sky_enabled", "camping_enabled", "drum_circle_active", "quarry_beach_enabled", "swimming_open", "fishing_open"):
        if key in data:
            state[key] = bool(data.get(key))
    if "campfire_count" in data:
        try:
            state["campfire_count"] = max(0, min(64, int(data.get("campfire_count"))))
        except Exception:
            pass
    if "wallet_usd" in data:
        try:
            state["wallet_usd"] = round(max(0.0, float(data.get("wallet_usd"))), 2)
        except Exception:
            pass
    if "barter_credit" in data:
        try:
            state["barter_credit"] = max(0, int(data.get("barter_credit")))
        except Exception:
            pass
    for list_key in ("vendors", "npcs", "art_inventory", "sales_log", "barter_log", "glow_gear_stock", "camping_gear_stock", "fish_species"):
        if list_key in data and isinstance(data.get(list_key), list):
            if list_key in {"glow_gear_stock", "camping_gear_stock", "fish_species"}:
                state[list_key] = [str(x).strip() for x in list(data.get(list_key) or []) if str(x).strip()][:32]
            else:
                state[list_key] = [dict(x) for x in list(data.get(list_key) or []) if isinstance(x, dict)][:240]
    for list_key in ("fishing_log", "swim_log", "night_events", "swim_zones", "fishing_spots", "campgrounds", "camping_reservations"):
        if list_key in data and isinstance(data.get(list_key), list):
            state[list_key] = [dict(x) for x in list(data.get(list_key) or []) if isinstance(x, dict)][:240]
    normalized_npcs = []
    for npc in list(state.get("npcs") or []):
        if not isinstance(npc, dict):
            continue
        clean_npc = dict(npc)
        clean_npc["id"] = str(clean_npc.get("id", "") or "").strip()[:80]
        clean_npc["name"] = str(clean_npc.get("name", clean_npc.get("id", "Festival NPC")) or clean_npc.get("id", "Festival NPC"))[:120]
        clean_npc["role"] = str(clean_npc.get("role", "festival_npc") or "festival_npc")[:80]
        clean_npc["activity"] = str(clean_npc.get("activity", "") or "")[:240]
        clean_npc["dynamic_special_abilities"] = _get_special_abilities_for_entity(
            "festival_npc",
            clean_npc["id"],
            fallback_name=clean_npc["name"],
        )
        normalized_npcs.append(clean_npc)
    state["npcs"] = normalized_npcs[:240]
    return state

