def ensure_voice_settings_integrity():
    details = []
    settings = app_state.get("voice_settings")
    if not isinstance(settings, dict):
        app_state["voice_settings"] = dict(VOICE_SETTINGS_DEFAULTS)
        details.append("voice_settings_reset_to_defaults")
        return details

    for key, default_val in VOICE_SETTINGS_DEFAULTS.items():
        if key not in settings:
            settings[key] = default_val
            details.append(f"voice_setting_restored:{key}")
    return details

def run_self_repair(trigger="manual"):
    global _last_auto_repair_at
    details = []
    result = "ok"

    mem_status = memory.self_repair()
    if mem_status.get("repaired"):
        details.append("memory_repaired")
    if not mem_status.get("ok"):
        result = "degraded"
        details.append(f"memory_error:{mem_status.get('error')}")

    details.extend(ensure_voice_settings_integrity())

    stored_name = memory.get_user_name()
    sanitized_name = personality_engine.sanitize_user_name(stored_name)
    fallback_name = personality_engine.get_default_user_name()
    resolved_name = sanitized_name or fallback_name
    if resolved_name and app_state.get("user_name") != resolved_name:
        app_state["user_name"] = resolved_name
        app_state["active_user_name"] = resolved_name
        memory.update_user_name(resolved_name)
        details.append("user_name_repaired")

    self_repair_state["last_run"] = datetime.utcnow().isoformat()
    self_repair_state["last_trigger"] = trigger
    self_repair_state["last_result"] = result
    self_repair_state["details"] = details
    self_repair_state["run_count"] = int(self_repair_state.get("run_count", 0)) + 1
    _last_auto_repair_at = datetime.utcnow()

    return {
        "success": result == "ok",
        "result": result,
        "details": details
    }

def auto_self_repair_if_due(trigger="auto", min_interval_seconds=8):
    global _last_auto_repair_at
    now = datetime.utcnow()
    if _last_auto_repair_at is None:
        return run_self_repair(trigger=trigger)
    elapsed = (now - _last_auto_repair_at).total_seconds()
    if elapsed >= min_interval_seconds:
        return run_self_repair(trigger=trigger)
    return {
        "success": self_repair_state.get("last_result") == "ok",
        "result": self_repair_state.get("last_result"),
        "details": self_repair_state.get("details", [])
    }

def _bool_from_text(value, default=False):
    if isinstance(value, bool):
        return value
    text = str(value or "").strip().lower()
    if not text:
        return bool(default)
    return text in {"1", "true", "yes", "enabled", "on"}

def _int_from_life(life_dict, key, fallback):
    """Module-level helper: read an int from a life_context dict with a safe fallback."""
    try:
        return int(str(life_dict.get(key, fallback)).strip() or fallback)
    except Exception:
        return int(fallback)

def _safe_get_profile():
    try:
        return memory.get_profile() or {}
    except Exception as e:
        print(f"[Profile Load Fallback] {e}")
        try:
            memory.self_repair()
            return memory.get_profile() or {}
        except Exception as e2:
            print(f"[Profile Load Fallback Repair Failed] {e2}")
            return {}

def _build_full_memory_context(query="", max_chars=5200):
    query_text = str(query or "").strip()
    pieces = []
    try:
        access = memory.build_memory_access_context(
            query=query_text,
            max_chars=max_chars,
            rag_limit=18,
            transcript_chars=1600,
            include_session=True,
        )
        if access:
            pieces.append(access)
    except Exception as e:
        print(f"[Memory Access Context Error] {e}")

    try:
        continuity = _resolve_memory_continuity_state()
        if continuity:
            pieces.append(
                "Memory continuity runtime:\n"
                f"- Continuity score: {float(continuity.get('continuity_score', 78.0) or 78.0):.1f}\n"
                f"- Narrative continuity: {float(continuity.get('narrative_continuity_score', 80.0) or 80.0):.1f}\n"
                f"- Fragmentation: {str(continuity.get('fragmentation_indicator', 'low')).strip() or 'low'}\n"
                f"- Last consolidation: {str(continuity.get('last_consolidation_at', '') or 'not yet')}"
            )
    except Exception as e:
        print(f"[Memory Continuity Context Error] {e}")

    return "\n\n".join([str(x).strip() for x in pieces if str(x).strip()])[:max_chars]

def _resolve_active_user_name():
    if app_state.get("active_user_name") != "Billy" or app_state.get("user_name") != "Billy":
        app_state["active_user_name"] = "Billy"
        app_state["user_name"] = "Billy"
    return "Billy"

def _set_active_user_name(name):
    requested_name = str(name or "").strip()
    if requested_name and requested_name.lower() != "billy":
        raise ValueError("The active human user identity is Billy; Aurion is the AI companion.")
    resolved_name = "Billy"
    app_state["active_user_name"] = resolved_name
    app_state["user_name"] = resolved_name
    player_character = dict(app_state.get("player_character") or {})
    identity = dict(player_character.get("identity") or {})
    identity["display_name"] = resolved_name
    player_character["identity"] = identity
    app_state["player_character"] = player_character
    memory.update_user_name(resolved_name)
    try:
        memory.add_profile_item("life_context", resolved_name, key="active_user_name")
    except Exception as e:
        print(f"[Identity Persistence Warning] {e}")
    return resolved_name

def _normalize_player_pose(pose):
    pose_text = str(pose or "").strip().lower()
    aliases = {
        "stand": "stand",
        "standing": "stand",
        "idle": "stand",
        "normal": "stand",
        "sit": "sit",
        "sitting": "sit",
        "seat": "sit",
        "lie": "lie",
        "lay": "lie",
        "lying": "lie",
        "lay_down": "lie",
        "lie_down": "lie",
        "crouch": "crouch",
        "crouching": "crouch",
        "relax": "relax",
        "rest": "relax"
    }
    return aliases.get(pose_text, "stand")

def _parse_player_directive(command_text):
    text = re.sub(r"\s+", " ", str(command_text or "").strip())
    lower = text.lower()
    result = {
        "raw": text,
        "action": "",
        "pose": "",
        "perspective": "",
        "target_id": "",
        "interaction_target": ""
    }
    if not text:
        return result

    if "first person" in lower:
        result["perspective"] = "first_person"
    elif "third person" in lower:
        result["perspective"] = "third_person"

    action_patterns = [
        ("sprint", r"\b(sprint|dash|run fast)\b"),
        ("run", r"\b(run|jog)\b"),
        ("walk", r"\b(walk|move|head|travel|go)\b"),
        ("jump", r"\b(jump|hop|vault)\b"),
        ("crouch", r"\b(crouch|duck|stealth)\b"),
        ("sit", r"\b(sit|sit down|take a seat)\b"),
        ("lie", r"\b(lie|lay|lie down|lay down)\b"),
        ("relax", r"\b(relax|rest|chill)\b"),
        ("interact", r"\b(interact|activate)\b"),
        ("reach", r"\b(reach)\b"),
        ("grab", r"\b(grab|pick up|take)\b"),
        ("use", r"\b(use)\b"),
        ("open", r"\b(open)\b"),
        ("close", r"\b(close|shut)\b"),
        ("inspect", r"\b(inspect|examine|look at)\b"),
        ("talk", r"\b(talk|speak|chat)\b"),
        ("wave", r"\b(wave|greet)\b"),
        ("stand", r"\b(stand|stand up)\b"),
    ]
    for action_name, pattern in action_patterns:
        if re.search(pattern, lower):
            result["action"] = action_name
            break

    pose_from_action = {
        "sit": "sit",
        "lie": "lie",
        "crouch": "crouch",
        "relax": "relax",
        "stand": "stand",
    }
    if result["action"] in pose_from_action:
        result["pose"] = pose_from_action[result["action"]]

    nav_match = re.search(r"\b(?:go|head|move|walk|run|sprint|travel)(?:\s+over|\s+back|\s+down|\s+up|\s+out)?\s+to\s+([a-z0-9 _\-]+)$", lower)
    if nav_match:
        result["target_id"] = _resolve_navigation_target_id(nav_match.group(1))
    elif lower.startswith("kitchen") or lower.endswith(" kitchen"):
        result["target_id"] = _resolve_navigation_target_id("kitchen")
    elif lower.startswith("living room") or lower.endswith(" living room"):
        result["target_id"] = _resolve_navigation_target_id("living_room")

    object_match = re.search(r"\b(?:open|close|use|inspect|grab|reach|talk to)\s+(.+)$", lower)
    if object_match:
        result["interaction_target"] = str(object_match.group(1) or "").strip()[:120]

    return result

def _sanitize_constructs(items):
    normalized = []
    for raw in list(items or []):
        if not isinstance(raw, dict):
            continue
        title = str(raw.get("title", "")).strip()[:90]
        description = str(raw.get("description", "")).strip()[:420]
        if not title or not description:
            continue
        normalized.append({
            "title": title,
            "description": description,
            "created_at": str(raw.get("created_at", "")).strip() or datetime.utcnow().isoformat()
        })
    return normalized[-24:]

def _sync_audio_registry_modes_to_perception():
    registry = dict(app_state.get("audio_registry", {}) or {})
    entry = _resolve_audio_mode_entry(registry.get("active_mode", "audible-band"))
    mode = str(entry.get("key", "audible-band")).strip().lower() or "audible-band"
    note = str(entry.get("note", "")).strip() or AUDIO_SPECTRUM_MODES["audible-band"]["note"]
    for key in ("media_perception", "world_audio_perception"):
        current = dict(app_state.get(key, {}) or {})
        current["spectrum_mode"] = mode
        current["spectrum_note"] = note
        app_state[key] = current

def _load_capability_learning_from_profile():
    profile = _safe_get_profile()
    life = dict(profile.get("life_context", {}) or {})
    vision_registry = _default_vision_registry()
    vision_registry["documented_modes"] = _sanitize_registry_entries(_safe_json_loads(life.get("vision_custom_modes_json", "[]"), []), vision_registry["documented_modes"])
    vision_registry["active_mode"] = _resolve_mode_key_from_entries(life.get("visual_spectrum_mode", vision_registry.get("active_mode", "visible-light")), vision_registry["documented_modes"], "visible-light")
    stored_modes = _safe_json_loads(life.get("visual_spectrum_modes_json", "[]"), [])
    requested_modes = _sanitize_visual_spectrum_modes(stored_modes) if list(stored_modes or []) else [vision_registry["active_mode"]]
    resolved_modes = [m for m in requested_modes if _resolve_mode_key_from_entries(m, vision_registry["documented_modes"], "")] or [vision_registry["active_mode"]]
    vision_registry["active_modes"] = resolved_modes
    vision_registry["active_mode"] = resolved_modes[0]
    vision_registry["last_created_at"] = str(life.get("vision_registry_last_created_at", "")).strip() or None

    audio_registry = _default_audio_registry()
    audio_registry["documented_modes"] = _sanitize_registry_entries(_safe_json_loads(life.get("audio_custom_modes_json", "[]"), []), audio_registry["documented_modes"])
    audio_registry["active_mode"] = _resolve_mode_key_from_entries(life.get("audio_spectrum_mode", audio_registry.get("active_mode", "audible-band")), audio_registry["documented_modes"], "audible-band")
    audio_registry["last_created_at"] = str(life.get("audio_registry_last_created_at", "")).strip() or None

    deep_learning = _default_deep_learning_state()
    deep_learning["enabled"] = _bool_from_text(life.get("deep_learning_enabled", "enabled"), default=True)
    deep_learning["focus"] = str(life.get("deep_learning_focus", deep_learning["focus"])).strip() or deep_learning["focus"]
    try:
        deep_learning["depth"] = max(0, min(100, int(str(life.get("deep_learning_depth", deep_learning["depth"])).strip() or deep_learning["depth"])))
    except Exception:
        deep_learning["depth"] = int(deep_learning["depth"])
    deep_learning["discoveries"] = [str(item).strip()[:220] for item in _safe_json_loads(life.get("deep_learning_discoveries_json", "[]"), []) if str(item).strip()][-24:]
    deep_learning["last_learned_at"] = str(life.get("deep_learning_last_learned_at", "")).strip() or None

    sound_creation = _default_sound_creation_state()
    try:
        sound_creation["cymatics_mastery"] = max(0, min(100, int(str(life.get("sound_creation_cymatics_mastery", sound_creation["cymatics_mastery"])).strip() or sound_creation["cymatics_mastery"])))
    except Exception:
        sound_creation["cymatics_mastery"] = 0
    sound_creation["cymatics_unlocked"] = _bool_from_text(
        life.get("sound_creation_cymatics_unlocked", "enabled" if sound_creation["cymatics_mastery"] >= 100 else "disabled"),
        default=sound_creation["cymatics_mastery"] >= 100
    )
    sound_creation["constructs"] = _sanitize_constructs(_safe_json_loads(life.get("sound_creation_constructs_json", "[]"), []))
    sound_creation["last_created_at"] = str(life.get("sound_creation_last_created_at", "")).strip() or None

    with _APP_STATE_LOCK:
        app_state["vision_registry"] = vision_registry
        app_state["audio_registry"] = audio_registry
        app_state["deep_learning"] = deep_learning
        app_state["sound_creation"] = sound_creation

    current_visual = dict(app_state.get("visual_perception", {}) or {})
    visual_bundle = _compose_visual_mode_bundle(vision_registry.get("active_modes", [vision_registry["active_mode"]]))
    current_visual["spectrum_mode"] = str(visual_bundle["keys"][0] if visual_bundle["keys"] else "visible-light")
    current_visual["spectrum_modes"] = list(visual_bundle["keys"])
    current_visual["spectrum_note"] = str(visual_bundle["note"]).strip() or VISUAL_SPECTRUM_MODES["visible-light"]["note"]
    current_visual["wavelength_profile"] = str(visual_bundle["wavelength_profile"]).strip()
    app_state["visual_perception"] = current_visual
    _sync_audio_registry_modes_to_perception()

def _persist_visual_spectrum_to_profile(mode_or_modes):
    entries = list((app_state.get("vision_registry") or {}).get("documented_modes", []) or [])
    if isinstance(mode_or_modes, (list, tuple)):
        normalized_modes = [_resolve_mode_key_from_entries(mode, entries, "") for mode in mode_or_modes]
        normalized_modes = [mode for mode in normalized_modes if mode] or ["visible-light"]
    else:
        normalized_modes = [_resolve_mode_key_from_entries(mode_or_modes, entries, "visible-light")]
    memory.add_profile_item("life_context", normalized_modes[0], key="visual_spectrum_mode")
    memory.add_profile_item("life_context", json.dumps(normalized_modes), key="visual_spectrum_modes_json")

def _persist_audio_spectrum_to_profile(mode):
    normalized = _resolve_mode_key_from_entries(mode, list((app_state.get("audio_registry") or {}).get("documented_modes", []) or []), "audible-band")
    memory.add_profile_item("life_context", normalized, key="audio_spectrum_mode")

def _persist_capability_registries_to_profile():
    vision_registry = dict(app_state.get("vision_registry", {}) or {})
    audio_registry = dict(app_state.get("audio_registry", {}) or {})
    custom_vision = [item for item in list(vision_registry.get("documented_modes", []) or []) if not bool(item.get("built_in", False))]
    custom_audio = [item for item in list(audio_registry.get("documented_modes", []) or []) if not bool(item.get("built_in", False))]
    memory.add_profile_item("life_context", json.dumps(custom_vision), key="vision_custom_modes_json")
    memory.add_profile_item("life_context", json.dumps(custom_audio), key="audio_custom_modes_json")
    memory.add_profile_item("life_context", str(vision_registry.get("last_created_at") or ""), key="vision_registry_last_created_at")
    memory.add_profile_item("life_context", str(audio_registry.get("last_created_at") or ""), key="audio_registry_last_created_at")
    _persist_visual_spectrum_to_profile(vision_registry.get("active_modes", [vision_registry.get("active_mode", "visible-light")]))
    _persist_audio_spectrum_to_profile(audio_registry.get("active_mode", "audible-band"))

