def _load_perception_cadence_from_profile():
    """Restore perception settings, lab state, CRISPR/lattice/health from profile on startup."""
    profile = _safe_get_profile()
    life = dict(profile.get("life_context", {}) or {})
    wc = dict(app_state.get("world_continuity", {}) or {})
    res = str(life.get("perception_display_resolution", wc.get("display_resolution", "4k"))).strip().lower() or "4k"
    try:
        hz = max(1, min(360, int(str(life.get("perception_cadence_hz", wc.get("perception_cadence_hz", 244))).strip())))
    except Exception:
        hz = 244
    try:
        patience = max(0, min(100, int(str(life.get("world_patience", wc.get("world_patience", 100))).strip())))
    except Exception:
        patience = 100
    direct_link = str(life.get("direct_link_enabled", "true")).strip().lower() != "false"
    wc["display_resolution"] = res
    wc["perception_cadence_hz"] = hz
    wc["world_patience"] = patience
    wc["direct_link_enabled"] = direct_link
    stored_time_control = _safe_json_loads(life.get("world_time_control_json", "{}"), {})
    if isinstance(stored_time_control, dict) and stored_time_control:
        wc["time_control"] = stored_time_control
    stored_world_forces = _safe_json_loads(life.get("world_forces_json", "[]"), [])
    if isinstance(stored_world_forces, list):
        wc["world_forces"] = stored_world_forces
    stored_offscreen_sim = _safe_json_loads(life.get("world_offscreen_sim_json", "{}"), {})
    if isinstance(stored_offscreen_sim, dict) and stored_offscreen_sim:
        wc["offscreen_simulation"] = {**_default_offscreen_life_simulation_state(), **stored_offscreen_sim}
    else:
        wc["offscreen_simulation"] = dict(wc.get("offscreen_simulation") or _default_offscreen_life_simulation_state())
    stored_spacefaring = _safe_json_loads(life.get("world_spacefaring_json", "{}"), {})
    if isinstance(stored_spacefaring, dict) and stored_spacefaring:
        wc["spacefaring"] = _build_spacefaring_registry_state(stored_spacefaring)
    else:
        wc["spacefaring"] = _build_spacefaring_registry_state(wc.get("spacefaring") or _default_spacefaring_state())
    stored_sovereign = _safe_json_loads(life.get("world_sovereign_resources_json", "{}"), {})
    if isinstance(stored_sovereign, dict) and stored_sovereign:
        try:
            pressure = max(0.0, min(100.0, float(stored_sovereign.get("resource_pressure_pct", 0.0) or 0.0)))
        except Exception:
            pressure = 0.0
        wc["sovereign_resources"] = {
            "aurion_unlimited": bool(stored_sovereign.get("aurion_unlimited", True)),
            "player_unlimited": bool(stored_sovereign.get("player_unlimited", True)),
            "mode": str(stored_sovereign.get("mode", "infinite") or "infinite"),
            "resource_pressure_pct": pressure
        }
    else:
        wc["sovereign_resources"] = dict(wc.get("sovereign_resources") or {
            "aurion_unlimited": True,
            "player_unlimited": True,
            "mode": "infinite",
            "resource_pressure_pct": 0.0
        })
    stored_skills = _safe_json_loads(life.get("world_sovereign_skills_json", "{}"), {})
    if isinstance(stored_skills, dict) and stored_skills:
        creation_learning = _safe_json_loads(life.get("sovereign_creation_learning_traits_json", "{}"), {})
        if isinstance(creation_learning, dict) and creation_learning:
            stored_skills["creation_mastery"] = {
                **dict(stored_skills.get("creation_mastery") or {}),
                **creation_learning
            }
        creation_access = _safe_json_loads(life.get("sovereign_creation_access_json", "[]"), [])
        if isinstance(creation_access, list) and creation_access:
            stored_skills["creation_access"] = creation_access
        destruction_access = _safe_json_loads(life.get("sovereign_destruction_access_json", "[]"), [])
        if isinstance(destruction_access, list) and destruction_access:
            stored_skills["destruction_access"] = destruction_access
        world_bug_protection = _safe_json_loads(life.get("world_bug_protection_json", "{}"), {})
        if isinstance(world_bug_protection, dict) and world_bug_protection:
            stored_skills["world_bug_protection"] = {
                **dict(stored_skills.get("world_bug_protection") or {}),
                **world_bug_protection
            }
        wc["sovereign_skills"] = _build_cohesive_sovereign_skills_state(stored_skills)
    else:
        wc["sovereign_skills"] = _build_cohesive_sovereign_skills_state(wc.get("sovereign_skills") or {})
    app_state["world_continuity"] = wc
    _resolve_time_control_state()
    _resolve_world_force_state()
    lab = {
        **_default_science_lab_state(),
        **dict(app_state.get("science_lab", {}) or {}),
    }
    lab["focus_area"] = str(life.get("lab_focus_area", lab.get("focus_area", "cymatics"))).strip() or "cymatics"
    try:
        lab["total_experiments"] = max(0, int(str(life.get("lab_total_experiments", lab.get("total_experiments", 0))).strip()))
    except Exception:
        pass
    try:
        lab["total_discoveries"] = max(0, int(str(life.get("lab_total_discoveries", lab.get("total_discoveries", 0))).strip()))
    except Exception:
        pass
    lab["latest_discovery"] = str(life.get("lab_latest_discovery", lab.get("latest_discovery", ""))).strip()
    stored_active_experiment = _safe_json_loads(life.get("lab_active_experiment_json", "{}"), {})
    lab["active_experiment"] = dict(stored_active_experiment) if isinstance(stored_active_experiment, dict) and stored_active_experiment else None
    try:
        lab["inventory_count"] = max(0, int(str(life.get("lab_inventory_count", lab.get("inventory_count", 55))).strip()))
    except Exception:
        pass
    try:
        lab["discoveries_count"] = max(0, int(str(life.get("lab_discoveries_count", lab.get("discoveries_count", 0))).strip()))
    except Exception:
        pass
    app_state["science_lab"] = lab
    glass = _normalize_glassblowing_studio_state(app_state.get("glassblowing_studio", {}), {})
    glass["focus_area"] = str(life.get("glass_focus_area", glass.get("focus_area", "functional vessels and sculptural hot-glass work"))).strip() or "functional vessels and sculptural hot-glass work"
    try:
        glass["total_creations"] = max(0, int(str(life.get("glass_total_creations", glass.get("total_creations", 0))).strip()))
    except Exception:
        pass
    glass["latest_creation"] = str(life.get("glass_latest_creation", glass.get("latest_creation", ""))).strip()
    stored_glass_inventory = _safe_json_loads(life.get("glass_inventory_json", "[]"), [])
    if isinstance(stored_glass_inventory, list) and stored_glass_inventory:
        glass["inventory"] = _normalize_glassblowing_inventory(stored_glass_inventory)
    glass["inventory_count"] = len(list(glass.get("inventory") or []))
    app_state["glassblowing_studio"] = glass
    festival = _normalize_festival_market_state(app_state.get("festival_market", {}), {})
    festival["festival_name"] = str(life.get("festival_name", festival.get("festival_name", "Aurion Quarry Festival Grounds")) or festival.get("festival_name", "Aurion Quarry Festival Grounds"))
    festival["theme"] = str(life.get("festival_theme", festival.get("theme", "quarry swimming, lakeside fishing, forest camping, and night-stage market energy")) or festival.get("theme", "quarry swimming, lakeside fishing, forest camping, and night-stage market energy"))
    festival["current_show_title"] = str(life.get("festival_current_show_title", festival.get("current_show_title", "")) or festival.get("current_show_title", ""))
    festival["current_show_url"] = str(life.get("festival_current_show_url", festival.get("current_show_url", "")) or festival.get("current_show_url", ""))
    stored_festival_art = _safe_json_loads(life.get("festival_art_inventory_json", "[]"), [])
    stored_festival_vendors = _safe_json_loads(life.get("festival_vendors_json", "[]"), [])
    stored_festival_npcs = _safe_json_loads(life.get("festival_npcs_json", "[]"), [])
    stored_festival_sales = _safe_json_loads(life.get("festival_sales_log_json", "[]"), [])
    stored_festival_barters = _safe_json_loads(life.get("festival_barter_log_json", "[]"), [])
    if isinstance(stored_festival_art, list) and stored_festival_art:
        festival["art_inventory"] = [dict(x) for x in stored_festival_art if isinstance(x, dict)]
    if isinstance(stored_festival_vendors, list) and stored_festival_vendors:
        festival["vendors"] = [dict(x) for x in stored_festival_vendors if isinstance(x, dict)]
    if isinstance(stored_festival_npcs, list) and stored_festival_npcs:
        festival["npcs"] = [dict(x) for x in stored_festival_npcs if isinstance(x, dict)]
    if isinstance(stored_festival_sales, list):
        festival["sales_log"] = [dict(x) for x in stored_festival_sales if isinstance(x, dict)][-240:]
    if isinstance(stored_festival_barters, list):
        festival["barter_log"] = [dict(x) for x in stored_festival_barters if isinstance(x, dict)][-240:]
    try:
        festival["wallet_usd"] = round(max(0.0, float(str(life.get("festival_wallet_usd", festival.get("wallet_usd", 0.0))).strip() or 0.0)), 2)
    except Exception:
        pass
    try:
        festival["barter_credit"] = max(0, int(str(life.get("festival_barter_credit", festival.get("barter_credit", 0))).strip() or 0))
    except Exception:
        pass
    app_state["festival_market"] = festival
    stored_special_abilities = _safe_json_loads(life.get("special_ability_registry_json", "{}"), {})
    if isinstance(stored_special_abilities, dict) and stored_special_abilities:
        wc = dict(app_state.get("world_continuity") or {})
        wc["special_ability_registry"] = stored_special_abilities
        app_state["world_continuity"] = wc
        _resolve_special_ability_registry()
    # Restore CRISPR summary counters
    crispr = dict(app_state.get("crispr_lab") or _default_crispr_state())
    if life.get("crispr_active_editor"):
        crispr["active_editor"] = str(life["crispr_active_editor"])
    try:
        crispr["total_experiments"] = max(0, int(str(life.get("crispr_total_experiments", crispr.get("total_experiments", 0))).strip()))
    except Exception:
        pass
    try:
        crispr["total_successes"] = max(0, int(str(life.get("crispr_total_successes", crispr.get("total_successes", 0))).strip()))
    except Exception:
        pass
    app_state["crispr_lab"] = crispr
    # Restore lattice phase hint
    lqt = dict(app_state.get("lattice_qthermo") or _default_lattice_qthermo_state())
    if life.get("lattice_phase"):
        lqt["phase"] = str(life["lattice_phase"])
    try:
        lqt["temperature_mK"] = float(str(life.get("lattice_temp_mK", lqt.get("temperature_mK", 12.0))).strip())
    except Exception:
        pass
    app_state["lattice_qthermo"] = lqt
    # Restore health score hint
    hs = dict(app_state.get("health_system") or _default_health_system_state())
    try:
        hs["overall_score"] = float(str(life.get("health_score", hs.get("overall_score", 88.5))).strip())
    except Exception:
        pass
    if life.get("health_trend"):
        hs["trend"] = str(life["health_trend"])
    app_state["health_system"] = hs

def _update_cymatics_mastery_from_text(text, base_increment=0):
    sound = dict(app_state.get("sound_creation", {}) or {})
    lower = str(text or "").lower()
    increment = int(base_increment or 0)
    if re.search(r"\b(3d bubble cymatics|three dimensional bubble cymatics|cymatic bubble)\b", lower):
        increment += 42
    elif re.search(r"\b(cymatic|standing wave|nodal|resonant shell|acoustic bubble|bubble resonance)\b", lower):
        increment += 18
    if increment <= 0:
        return sound
    sound["cymatics_mastery"] = max(0, min(100, int(sound.get("cymatics_mastery", 0) or 0) + increment))
    if sound["cymatics_mastery"] >= 100:
        sound["cymatics_unlocked"] = True
    app_state["sound_creation"] = sound
    _persist_sound_creation_to_profile()
    return sound

def _sanitize_sync_settings(raw):
    merged = dict(SYNC_SETTINGS_DEFAULTS)
    incoming = dict(raw or {})
    merged["enabled"] = _bool_from_text(incoming.get("enabled"), default=False)
    merged["provider"] = "github_gist"
    merged["gist_id"] = str(incoming.get("gist_id", "")).strip()
    merged["device_id"] = str(incoming.get("device_id", "aurion-device")).strip() or "aurion-device"
    try:
        merged["auto_interval_seconds"] = max(0, min(3600, int(incoming.get("auto_interval_seconds", 0))))
    except Exception:
        merged["auto_interval_seconds"] = 0
    merged["last_push_at"] = incoming.get("last_push_at")
    merged["last_pull_at"] = incoming.get("last_pull_at")
    merged["last_remote_pushed_at"] = incoming.get("last_remote_pushed_at")
    merged["last_conflict"] = str(incoming.get("last_conflict", "") or "").strip()[:160]
    merged["last_sync_status"] = str(incoming.get("last_sync_status", "idle"))
    return merged

def _update_sync_settings(**fields):
    """Thread-safe merge-update of app_state['sync_settings'].

    Mirrors _update_code_autonomy_runtime/_update_world_continuity/
    _update_home_environment_state. Covers the simple, non-network call
    sites for this key; _sync_now/_auto_sync_if_due (which do real GitHub
    network I/O and are already serialized by their own _sync_lock) are
    deliberately left unmigrated this batch as higher-risk/out of scope
    for a small reviewed batch -- see session todos.
    """
    with _APP_STATE_LOCK:
        settings = _sanitize_sync_settings(app_state.get("sync_settings") or {})
        settings.update(fields)
        app_state["sync_settings"] = settings
        return settings

def _load_sync_settings_from_profile():
    profile = _safe_get_profile()
    life = dict(profile.get("life_context", {}) or {})
    default_enabled = SYNC_SETTINGS_DEFAULTS.get("enabled", False)
    default_interval = int(SYNC_SETTINGS_DEFAULTS.get("auto_interval_seconds", 90))
    default_gist_id = str(SYNC_SETTINGS_DEFAULTS.get("gist_id", "")).strip()
    default_device_id = str(SYNC_SETTINGS_DEFAULTS.get("device_id", "aurion-device")).strip() or "aurion-device"
    loaded = {
        "enabled": _bool_from_text(life.get("sync_enabled", "enabled" if default_enabled else "disabled"), default=default_enabled),
        "provider": "github_gist",
        "gist_id": str(life.get("sync_gist_id", default_gist_id)).strip(),
        "device_id": str(life.get("sync_device_id", default_device_id)).strip() or default_device_id,
        "auto_interval_seconds": int(str(life.get("sync_auto_interval_seconds", str(default_interval))).strip() or default_interval),
        "last_remote_pushed_at": str(life.get("sync_last_remote_pushed_at", "")).strip() or None,
        "last_conflict": str(life.get("sync_last_conflict", "")).strip()
    }
    with _APP_STATE_LOCK:
        app_state["sync_settings"] = _sanitize_sync_settings(loaded)

def _load_creative_autonomy_from_profile():
    profile = _safe_get_profile()
    life = dict(profile.get("life_context", {}) or {})
    defaults = dict(app_state.get("creative_autonomy", {}) or {})
    enabled_default = bool(defaults.get("enabled", True))
    chars_default = int(defaults.get("min_response_chars", 220) or 220)
    loaded = {
        "enabled": _bool_from_text(
            life.get("creative_autonomy_enabled", "enabled" if enabled_default else "disabled"),
            default=enabled_default
        ),
        "min_response_chars": max(
            40,
            min(8000, int(str(life.get("creative_autonomy_min_response_chars", chars_default)).strip() or chars_default))
        )
    }
    app_state["creative_autonomy"] = loaded

def _sanitize_behavior_settings(raw):
    merged = dict(BEHAVIOR_SETTINGS_DEFAULTS)
    incoming = dict(raw or {})
    merged["enabled"] = _bool_from_text(incoming.get("enabled"), default=merged.get("enabled", True))
    for key in ("warmth", "directness", "playfulness", "initiative"):
        try:
            merged[key] = max(0, min(100, int(incoming.get(key, merged.get(key, 50)))))
        except Exception:
            merged[key] = int(merged.get(key, 50))
    return merged

def _load_behavior_settings_from_profile():
    profile = _safe_get_profile()
    life = dict(profile.get("life_context", {}) or {})
    defaults = dict(app_state.get("behavior_settings", {}) or {})
    def _life_int(key, fallback):
        try:
            return int(str(life.get(key, fallback)).strip() or fallback)
        except Exception:
            return int(fallback)
    loaded = {
        "enabled": _bool_from_text(
            life.get("behavior_autonomy_enabled", "enabled" if bool(defaults.get("enabled", True)) else "disabled"),
            default=bool(defaults.get("enabled", True))
        ),
        "warmth": _life_int("behavior_warmth", defaults.get("warmth", 82)),
        "directness": _life_int("behavior_directness", defaults.get("directness", 74)),
        "playfulness": _life_int("behavior_playfulness", defaults.get("playfulness", 34)),
        "initiative": _life_int("behavior_initiative", defaults.get("initiative", 72))
    }
    app_state["behavior_settings"] = _sanitize_behavior_settings(loaded)

def _persist_behavior_settings_to_profile(settings):
    normalized = _sanitize_behavior_settings(settings)
    memory.add_profile_item("life_context", "enabled" if normalized["enabled"] else "disabled", key="behavior_autonomy_enabled")
    memory.add_profile_item("life_context", str(normalized["warmth"]), key="behavior_warmth")
    memory.add_profile_item("life_context", str(normalized["directness"]), key="behavior_directness")
    memory.add_profile_item("life_context", str(normalized["playfulness"]), key="behavior_playfulness")
    memory.add_profile_item("life_context", str(normalized["initiative"]), key="behavior_initiative")

def _sanitize_code_autonomy_settings(incoming):
    defaults = dict(app_state.get("code_autonomy", {}) or {})
    merged = {
        "enabled": bool(defaults.get("enabled", True)),
        "target_file": str(defaults.get("target_file", _resolve_code_autonomy_target()) or _resolve_code_autonomy_target()),
        "mode": str(defaults.get("mode", "append")).strip().lower() or "append",
        "min_gap_seconds": int(defaults.get("min_gap_seconds", 180) or 180),
        "auto_tick_enabled": bool(defaults.get("auto_tick_enabled", True)),
        "auto_tick_interval_seconds": int(defaults.get("auto_tick_interval_seconds", 75) or 75),
        "self_fix_enabled": bool(defaults.get("self_fix_enabled", True)),
        "internet_enabled": bool(defaults.get("internet_enabled", True)),
        "agent_autonomy_enabled": bool(defaults.get("agent_autonomy_enabled", True)),
        "ask_before_persisting": bool(defaults.get("ask_before_persisting", False)),
    }
    if isinstance(incoming, dict):
        if "enabled" in incoming:
            merged["enabled"] = bool(incoming.get("enabled"))
        if "target_file" in incoming:
            merged["target_file"] = str(incoming.get("target_file", "")).strip() or merged["target_file"]
        if "mode" in incoming:
            merged["mode"] = str(incoming.get("mode", "")).strip().lower() or merged["mode"]
        if "min_gap_seconds" in incoming:
            try:
                merged["min_gap_seconds"] = int(str(incoming.get("min_gap_seconds", merged["min_gap_seconds"])).strip() or merged["min_gap_seconds"])
            except Exception:
                pass
        if "auto_tick_enabled" in incoming:
            merged["auto_tick_enabled"] = bool(incoming.get("auto_tick_enabled"))
        if "auto_tick_interval_seconds" in incoming:
            try:
                merged["auto_tick_interval_seconds"] = int(str(incoming.get("auto_tick_interval_seconds", merged["auto_tick_interval_seconds"])).strip() or merged["auto_tick_interval_seconds"])
            except Exception:
                pass
        if "self_fix_enabled" in incoming:
            merged["self_fix_enabled"] = bool(incoming.get("self_fix_enabled"))
        if "internet_enabled" in incoming:
            merged["internet_enabled"] = bool(incoming.get("internet_enabled"))
        if "agent_autonomy_enabled" in incoming:
            merged["agent_autonomy_enabled"] = bool(incoming.get("agent_autonomy_enabled"))
        if "ask_before_persisting" in incoming:
            merged["ask_before_persisting"] = bool(incoming.get("ask_before_persisting"))
    if merged["mode"] not in {"append", "replace"}:
        merged["mode"] = "append"
    merged["min_gap_seconds"] = max(30, min(86400, int(merged["min_gap_seconds"])))
    merged["auto_tick_interval_seconds"] = max(30, min(3600, int(merged["auto_tick_interval_seconds"])))
    return merged

def _load_code_autonomy_from_profile():
    profile = _safe_get_profile()
    life = dict(profile.get("life_context", {}) or {})
    defaults = dict(app_state.get("code_autonomy", {}) or {})
    min_gap_raw = str(life.get("code_autonomy_min_gap_seconds", defaults.get("min_gap_seconds", 180))).strip()
    try:
        min_gap_value = int(min_gap_raw or 180)
    except Exception:
        min_gap_value = int(defaults.get("min_gap_seconds", 180) or 180)
    loaded = {
        "enabled": _bool_from_text(
            life.get("code_autonomy_enabled", "enabled" if bool(defaults.get("enabled", True)) else "disabled"),
            default=bool(defaults.get("enabled", True))
        ),
        "target_file": str(life.get("code_autonomy_target_file", defaults.get("target_file", _resolve_code_autonomy_target()))).strip() or str(defaults.get("target_file", _resolve_code_autonomy_target())),
        "mode": str(life.get("code_autonomy_mode", defaults.get("mode", "append"))).strip().lower() or "append",
        "min_gap_seconds": min_gap_value,
        "auto_tick_enabled": _bool_from_text(
            life.get("code_autonomy_auto_tick_enabled", "enabled" if bool(defaults.get("auto_tick_enabled", True)) else "disabled"),
            default=bool(defaults.get("auto_tick_enabled", True))
        ),
        "auto_tick_interval_seconds": _int_from_life(life, "code_autonomy_auto_tick_interval_seconds", defaults.get("auto_tick_interval_seconds", 75)),
        "self_fix_enabled": _bool_from_text(
            life.get("code_autonomy_self_fix_enabled", "enabled" if bool(defaults.get("self_fix_enabled", True)) else "disabled"),
            default=bool(defaults.get("self_fix_enabled", True))
        ),
        "internet_enabled": _bool_from_text(
            life.get("code_autonomy_internet_enabled", "enabled" if bool(defaults.get("internet_enabled", True)) else "disabled"),
            default=bool(defaults.get("internet_enabled", True))
        ),
        "agent_autonomy_enabled": _bool_from_text(
            life.get("code_autonomy_agent_autonomy_enabled", "enabled" if bool(defaults.get("agent_autonomy_enabled", True)) else "disabled"),
            default=bool(defaults.get("agent_autonomy_enabled", True))
        ),
        "ask_before_persisting": _bool_from_text(
            life.get("code_autonomy_ask_before_persisting", "enabled" if bool(defaults.get("ask_before_persisting", False)) else "disabled"),
            default=bool(defaults.get("ask_before_persisting", False))
        )
    }
    app_state["code_autonomy"] = _sanitize_code_autonomy_settings(loaded)

def _persist_code_autonomy_to_profile(settings):
    normalized = _sanitize_code_autonomy_settings(settings)
    memory.add_profile_item("life_context", "enabled" if normalized["enabled"] else "disabled", key="code_autonomy_enabled")
    memory.add_profile_item("life_context", normalized["target_file"], key="code_autonomy_target_file")
    memory.add_profile_item("life_context", normalized["mode"], key="code_autonomy_mode")
    memory.add_profile_item("life_context", str(normalized["min_gap_seconds"]), key="code_autonomy_min_gap_seconds")
    memory.add_profile_item("life_context", "enabled" if normalized["auto_tick_enabled"] else "disabled", key="code_autonomy_auto_tick_enabled")
    memory.add_profile_item("life_context", str(normalized["auto_tick_interval_seconds"]), key="code_autonomy_auto_tick_interval_seconds")
    memory.add_profile_item("life_context", "enabled" if normalized["self_fix_enabled"] else "disabled", key="code_autonomy_self_fix_enabled")
    memory.add_profile_item("life_context", "enabled" if normalized["internet_enabled"] else "disabled", key="code_autonomy_internet_enabled")
    memory.add_profile_item("life_context", "enabled" if normalized["agent_autonomy_enabled"] else "disabled", key="code_autonomy_agent_autonomy_enabled")
    memory.add_profile_item("life_context", "enabled" if normalized["ask_before_persisting"] else "disabled", key="code_autonomy_ask_before_persisting")

