def _build_hud_state():
    home = dict(app_state.get("home_environment") or _default_home_state())
    world_continuity = dict(app_state.get("world_continuity") or {})
    cognition = dict(app_state.get("cognition") or _default_cognition_state())
    unified = dict(app_state.get("unified_consciousness") or {})
    if not unified:
        unified = _build_unified_consciousness_state()
    identity = dict(unified.get("identity") or {})
    mind = dict(unified.get("mind") or {})
    body = dict(unified.get("body") or {})
    affect = dict(unified.get("affect") or {})
    world = dict(unified.get("world") or {})
    player = _resolve_player_character_state()
    media = _resolve_shared_media_session_state()
    operator = _build_operator_assist_state()
    bridge = dict(app_state.get("unreal_bridge") or {})
    memory_state = _resolve_memory_continuity_state()
    life = dict(app_state.get("life_registry") or _default_life_registry())
    weather = dict(home.get("weather") or {})
    solar = dict(home.get("solar") or {})
    room = str(home.get("current_room", "living_room") or "living_room")
    room_label = str((_HOME_ROOM_NAMES.get(room) or room.replace("_", " ").title()))
    player_runtime = dict(player.get("runtime") or {})
    player_pose = str(player_runtime.get("pose", "stand") or "stand")
    movement_mode = str(player_runtime.get("movement_mode", "walk") or "walk")
    route = dict((dict(world_continuity.get("world_mobility") or {})).get("route") or {})
    route_segments = list(route.get("segments") or [])
    route_summary = ""
    if route_segments:
        route_summary = f"Route {len(route_segments)} step{'s' if len(route_segments) != 1 else ''}"
    elif route.get("destination_name"):
        route_summary = f"Heading to {str(route.get('destination_name'))[:48]}"

    media_title = str(media.get("title") or media.get("track_title") or media.get("media_title") or "").strip()
    media_state = str(media.get("playback_state") or media.get("state") or "idle").strip() or "idle"
    anticipation = str((dict(affect.get("anticipation") or {})).get("summary", "") or "").strip()
    closure = dict(affect.get("closure") or {})
    closure_state = str(closure.get("state", "open") or "open")
    media_primary = "Nothing shared yet"
    if media_title:
        media_primary = f"{media_title[:54]} · {media_state}"
    elif str(media.get("summary", "") or "").strip():
        media_primary = str(media.get("summary"))[:72]
    media_secondary_parts = []
    if anticipation:
        media_secondary_parts.append(anticipation[:64])
    if closure_state and closure_state != "open":
        media_secondary_parts.append(f"closure {closure_state}")
    emotional_arc = str(media.get("emotional_arc") or "").strip()
    if emotional_arc:
        media_secondary_parts.append(emotional_arc[:40])

    bridge_status = str(bridge.get("status", "") or "").strip().lower()
    bridge_ok = bridge_status in {"connected", "state_served", "healthy", "ready"}
    bridge_label = "Bridge pending"
    bridge_tone = "dim"
    if bridge_status:
        bridge_label = f"Bridge {bridge_status.replace('_', ' ')}"
        bridge_tone = "ok" if bridge_ok else "warn"

    assist_actions = list(operator.get("next_actions") or [])
    assist_label = "Assist quiet"
    assist_tone = "dim"
    if assist_actions:
        assist_label = f"Assist {len(assist_actions)} next"
        assist_tone = "warn"

    weather_label = str(weather.get("weather_label", "Weather idle") or "Weather idle")
    temp_f = float(weather.get("temp_f", 0.0) or 0.0)
    environment_primary = f"{weather_label} · {temp_f:.0f}F · {str(solar.get('phase', 'sky unknown') or 'sky unknown')}"
    environment_secondary_parts = []
    indoor_temp = float(home.get("indoor_temp_f", temp_f) or temp_f)
    environment_secondary_parts.append(f"Indoor {indoor_temp:.0f}F")
    sensory_summary = str(body.get("summary", "") or "").strip()
    if sensory_summary:
        environment_secondary_parts.append(sensory_summary[:90])

    return {
        "aurion": {
            "emotion": str(identity.get("blended_emotion", app_state.get("current_emotion", "GRATEFUL")) or "GRATEFUL"),
            "mode": str(app_state.get("current_mode", "companion") or "companion"),
            "reasoning_mode": str(mind.get("reasoning_mode", cognition.get("reasoning_mode", "deliberate")) or "deliberate"),
            "imagination_depth_pct": float(mind.get("imagination_depth_pct", cognition.get("imagination_depth_pct", 70.0)) or 70.0),
            "memory_continuity_score": float(memory_state.get("continuity_score", mind.get("continuity_score", 0.0)) or 0.0),
        },
        "scene": {
            "room": room,
            "room_label": room_label,
            "summary": str(world.get("summary", "") or str(world_continuity.get("active_drive", "") or "")).strip()[:120],
            "player_pose": player_pose,
            "player_pose_label": player_pose.replace("_", " "),
            "movement_mode": movement_mode.replace("_", " "),
            "route_summary": route_summary,
        },
        "environment": {
            "weather_label": weather_label,
            "temp_label": f"{temp_f:.0f}F",
            "light_phase": str(solar.get("phase", "sky unknown") or "sky unknown"),
            "indoor_label": f"Indoor {indoor_temp:.0f}F",
            "sensory_summary": " · ".join(environment_secondary_parts[1:])[:120] if len(environment_secondary_parts) > 1 else "",
        },
        "media": {
            "primary": media_primary,
            "secondary": " · ".join(media_secondary_parts[:2]),
            "arc": str(media.get("summary", "") or "")[:90] if not media_secondary_parts else "",
            "pill": "Media live" if media_title or media_state not in {"", "idle", "stopped"} else "Media idle",
            "pill_tone": "ok" if media_title or media_state == "playing" else "dim",
        },
        "bridge": {
            "label": bridge_label,
            "tone": bridge_tone,
        },
        "operator_assist": {
            "label": assist_label,
            "tone": assist_tone,
        },
        "security": {
            "label": (
                f"Security {len(list((_STARTUP_SECURITY_VALIDATION or {}).get('issues', [])))} issue"
                f"{'' if len(list((_STARTUP_SECURITY_VALIDATION or {}).get('issues', [])) ) == 1 else 's'}"
                if list((_STARTUP_SECURITY_VALIDATION or {}).get("issues", []))
                else (
                    f"Security {len(list((_STARTUP_SECURITY_VALIDATION or {}).get('warnings', [])))} warning"
                    f"{'' if len(list((_STARTUP_SECURITY_VALIDATION or {}).get('warnings', [])) ) == 1 else 's'}"
                    if list((_STARTUP_SECURITY_VALIDATION or {}).get("warnings", []))
                    else ("Security https" if _TLS_MODE != "off" or _REQUIRE_TLS_REMOTE or _REQUIRE_TLS_LOCAL else "Security local")
                )
            ),
            "tone": (
                "warn"
                if list((_STARTUP_SECURITY_VALIDATION or {}).get("issues", [])) or list((_STARTUP_SECURITY_VALIDATION or {}).get("warnings", []))
                else ("ok" if _TLS_MODE != "off" or _REQUIRE_TLS_REMOTE or _REQUIRE_TLS_LOCAL else "dim")
            ),
        },
        "runtime": {
            "ecosystem_health": float(life.get("ecosystem_health", 100.0) or 100.0),
            "updated_at": datetime.utcnow().isoformat(),
        },
    }

def _log_operator_assist_message(channel, subject, detail, needed_actions=None, urgency="normal"):
    runtime = dict(app_state.get("phone_runtime") or {})
    messages = list(runtime.get("recent_messages") or [])
    entry = {
        "id": str(uuid.uuid4())[:10],
        "channel": str(channel or "operator").strip()[:40] or "operator",
        "subject": str(subject or "Aurion operator assist").strip()[:160] or "Aurion operator assist",
        "detail": str(detail or "").strip()[:4000],
        "needed_actions": [str(x).strip()[:240] for x in list(needed_actions or []) if str(x).strip()][:12],
        "urgency": str(urgency or "normal").strip()[:20] or "normal",
        "created_at": datetime.utcnow().isoformat(),
        "source": "aurion_operator_assist",
    }
    messages.append(entry)
    runtime["recent_messages"] = messages[-120:]
    runtime["last_operator_assist_at"] = entry["created_at"]
    runtime["last_operator_assist_subject"] = entry["subject"]
    app_state["phone_runtime"] = runtime
    return entry

def _build_operator_assist_context():
    unified = _build_unified_consciousness_state()
    identity = dict(unified.get("identity") or {})
    cognition = dict(unified.get("mind") or unified.get("thinking") or {})
    world = dict(unified.get("world") or {})
    journal = list(getattr(personality_engine, "_thought_journal", []) or [])
    latest = dict(journal[-1] or {}) if journal else {}
    return {
        "emotion": str(identity.get("blended_emotion", identity.get("emotion", "GRATEFUL")) or "GRATEFUL"),
        "reasoning_mode": str(cognition.get("reasoning_mode", "deliberate") or "deliberate"),
        "understanding": str(identity.get("sense_of_self", "") or ""),
        "world_patience": int(world.get("patience", (dict(app_state.get("world_continuity") or {})).get("world_patience", 100)) or 100),
        "thought_context": {
            "user": str(latest.get("user", "") or "")[:220],
            "reasoning": str(latest.get("reasoning", "") or "")[:800],
            "insight": str(latest.get("insight", "") or "")[:260],
        },
    }

def _operator_assist_allowed_now(urgency="normal"):
    runtime = dict(app_state.get("phone_runtime") or {})
    last_at = runtime.get("last_operator_assist_at")
    window = max(120, int(runtime.get("operator_patience_window_seconds", 900) or 900))
    if str(urgency or "").strip().lower() in {"high", "urgent"}:
        window = min(window, 180)
    return _seconds_since(last_at) >= window

def _send_operator_assist_message(channel="discord", subject="", detail="", needed_actions=None, webhook_url=""):
    if not _operator_assist_allowed_now():
        return {"success": False, "error": "Operator patience window active; waiting before sending another proactive message."}
    ctx = _build_operator_assist_context()
    detail_text = str(detail or "").strip()
    if ctx.get("thought_context", {}).get("reasoning"):
        detail_text = (
            f"{detail_text}\n\n"
            f"Current emotion: {ctx['emotion']}\n"
            f"Reasoning mode: {ctx['reasoning_mode']}\n"
            f"Understanding: {ctx['understanding']}\n"
            f"Thought path: {ctx['thought_context']['reasoning']}\n"
            f"Insight: {ctx['thought_context']['insight']}"
        ).strip()
    entry = _log_operator_assist_message(channel=channel, subject=subject, detail=detail_text, needed_actions=needed_actions)
    body_lines = [
        f"**Aurion Operator Assist**",
        f"**Why I'm messaging:** {entry['subject']}",
        f"**Detail:** {entry['detail']}",
    ]
    if entry["needed_actions"]:
        body_lines.append("**What I need from Billy:**")
        for idx, action in enumerate(entry["needed_actions"], start=1):
            body_lines.append(f"{idx}. {action}")
    body = "\n".join(body_lines)[:1800]
    if str(channel or "").strip().lower() == "discord":
        discord_webhook = _discord_webhook_config(override_url=webhook_url)
        if not _is_discord_webhook_url(discord_webhook):
            return {"success": False, "error": "Discord webhook not configured", "entry": entry}
        resp = _discord_send_plain_message(discord_webhook, body)
        if resp.status_code >= 300:
            return {"success": False, "error": f"Discord webhook failed ({resp.status_code})", "entry": entry}
        return {"success": True, "provider": "discord", "entry": entry}
    return {"success": True, "provider": "local_log", "entry": entry}


