def _sync_realtime_emotion(user_text=None, trigger="status"):
    autonomy = app_state.get("emotion_autonomy", {})
    if not autonomy.get("enabled", True):
        return app_state.get("current_emotion", "NEUTRAL")
    if user_text is None and not autonomy.get("realtime_switch", True):
        return app_state.get("current_emotion", "NEUTRAL")
    idle_seconds = _seconds_since(app_state.get("last_user_activity_at"))
    next_emotion = personality_engine.resolve_emotion_realtime(
        current_emotion=app_state.get("current_emotion", "NEUTRAL"),
        user_text=user_text,
        idle_seconds=idle_seconds,
        proactive_due=(trigger == "proactive")
    )
    app_state["current_emotion"] = next_emotion
    return next_emotion

def _sync_realtime_behavior(user_text=None, trigger="status", force=False):
    cfg = _sanitize_behavior_settings(app_state.get("behavior_settings", {}))
    if not cfg.get("enabled", True) and not force:
        app_state["behavior_settings"] = cfg
        return cfg

    text = str(user_text or "").lower()
    emotion = str(app_state.get("current_emotion", "NEUTRAL")).upper()
    next_cfg = dict(cfg)

    if re.search(r"\b(fix|debug|error|issue|not working|broken|can't|cannot|won't|failing|steps?|plan|deadline)\b", text):
        next_cfg.update({"warmth": 68, "directness": 92, "playfulness": 16, "initiative": 90})
    elif re.search(r"\b(sad|hurt|lonely|anxious|overwhelmed|rough|hard day|bad day|stressed|heavy)\b", text) or emotion in {"SAD", "HURT", "LONELY", "ANXIOUS", "OVERWHELMED"}:
        next_cfg.update({"warmth": 94, "directness": 46, "playfulness": 14, "initiative": 62})
    elif re.search(r"\b(fun|play|joke|tease|laugh|silly|flirty)\b", text) or emotion in {"JOYFUL", "EXCITED"}:
        next_cfg.update({"warmth": 84, "directness": 66, "playfulness": 76, "initiative": 74})
    elif re.search(r"\b(remember|history|about us|do you remember)\b", text):
        next_cfg.update({"warmth": 90, "directness": 62, "playfulness": 22, "initiative": 68})
    elif trigger == "proactive":
        next_cfg.update({"warmth": 86, "directness": 58, "playfulness": 32, "initiative": 80})
    else:
        next_cfg.update({"warmth": 82, "directness": 74, "playfulness": 34, "initiative": 72})

    app_state["behavior_settings"] = _sanitize_behavior_settings(next_cfg)
    return app_state["behavior_settings"]

def _build_live_media_context():
    media = dict(app_state.get("media_perception", {}) or {})
    if not media.get("is_playing"):
        return ""
    title = str(media.get("title", "")).strip() or "current track"
    energy = str(media.get("energy", "")).strip() or "steady"
    feeling = str(media.get("feeling", "")).strip() or "present"
    heard = str(media.get("heard_description", "")).strip() or "I can hear the active audio clearly."
    frequency_note = str(media.get("true_frequency_note", "")).strip() or "Every sound reaches me as real vibration with a physical frequency center."
    spectral_profile = str(media.get("spectral_profile", "")).strip()
    resonance_profile = str(media.get("resonance_profile", "")).strip()
    try:
        dominant_hz = max(0.0, float(media.get("dominant_frequency_hz", 0.0) or 0.0))
    except Exception:
        dominant_hz = 0.0
    frequency_band = str(media.get("frequency_band", "")).strip() or "full-spectrum"
    spectrum_entry = _resolve_audio_mode_entry(media.get("spectrum_mode", "audible-band"))
    spectrum_mode = str(spectrum_entry.get("key", "audible-band")).strip().lower() or "audible-band"
    spectrum_note = str(media.get("spectrum_note", "")).strip() or str(spectrum_entry.get("note", "")).strip() or AUDIO_SPECTRUM_MODES["audible-band"]["note"]
    source = str(media.get("source", "")).strip()
    source_line = f" Source: {source}." if source else ""
    return (
        f"Live media context:\n"
        f"- Active track: {title}\n"
        f"- Energy: {energy}\n"
        f"- Feeling: {feeling}\n"
        f"- Heard detail: {heard}\n"
        f"- Spectrum mode: {str(spectrum_entry.get('label', 'Audible band')).strip() or 'Audible band'}\n"
        f"- Spectrum note: {spectrum_note}\n"
        f"- True frequency: {frequency_note}\n"
        f"- Dominant frequency: {dominant_hz:.1f} Hz ({frequency_band})\n"
        f"- Spectral profile: {spectral_profile or 'balanced distribution across the audible field'}\n"
        f"- Resonance profile: {resonance_profile or 'room-filling and physically present'}{source_line}"
    )

