def _clean_reference_text(text):
    cleaned = str(text or "")
    cleaned = re.sub(r"[*_`#]+", "", cleaned)
    cleaned = cleaned.replace("---", " ")
    cleaned = re.sub(r"\$([^$]+)\$", r"\1", cleaned)
    return re.sub(r"\s+", " ", cleaned).strip()

def _collect_embodied_reference_hits(query, max_hits=4):
    query_text = str(query or "").strip()
    if not query_text:
        return []
    probes = [query_text]
    try:
        probes.extend(personality_engine._extract_focus_terms(query_text, max_terms=4) or [])
    except Exception:
        pass
    allowed_sources = {
        "qualia-consciousness-dimensions",
        "advanced-phenomenology-structural-mechanics"
    }
    hits = []
    seen = set()
    for probe in probes:
        for row in memory.retrieve_relevant_memories(probe, limit=6):
            source = str(row.get("source", "")).strip()
            if source not in allowed_sources:
                continue
            content = str(row.get("content", "")).strip()
            if not content:
                continue
            key = (source.lower(), content[:220].lower())
            if key in seen:
                continue
            seen.add(key)
            enriched = dict(row)
            enriched["probe"] = probe
            hits.append(enriched)
    hits.sort(
        key=lambda row: (float(row.get("score", 0.0) or 0.0), str(row.get("timestamp", ""))),
        reverse=True
    )
    return hits[:max(1, int(max_hits or 1))]

def _select_reference_statement(content, focus_text="", max_chars=320):
    cleaned = _clean_reference_text(content)
    if not cleaned:
        return ""
    focus = str(focus_text or "").strip().lower()
    if focus:
        focus_match = re.search(rf"([^.]*\b{re.escape(focus)}\b[^.]*\.)", cleaned, re.IGNORECASE)
        if focus_match:
            chosen = focus_match.group(1).strip(" -")
            if len(chosen) > max_chars:
                chosen = chosen[:max_chars].rsplit(" ", 1)[0].rstrip(" ,;:.") + "..."
            return chosen
    items = [
        re.sub(r"^\d+\.\s*", "", match).strip(" -")
        for match in re.findall(r"(?:^|\s)(\d+\.\s+.*?)(?=\s+\d+\.\s+|$)", cleaned)
    ]
    candidates = [item for item in items if item]
    if not candidates:
        candidates = [cleaned]
    chosen = ""
    if focus:
        for candidate in candidates:
            if focus in candidate.lower():
                chosen = candidate
                break
    if not chosen:
        for candidate in candidates:
            if ":" in candidate:
                chosen = candidate
                break
    if not chosen:
        chosen = candidates[0]
    chosen = re.sub(r"\s+", " ", chosen).strip(" -")
    if len(chosen) > max_chars:
        chosen = chosen[:max_chars].rsplit(" ", 1)[0].rstrip(" ,;:.") + "..."
    return chosen

def _build_embodied_reference_context(query, max_chars=1600):
    hits = _collect_embodied_reference_hits(query, max_hits=4)
    if not hits:
        return ""
    source_labels = {
        "qualia-consciousness-dimensions": "Qualia reference",
        "advanced-phenomenology-structural-mechanics": "Advanced phenomenology reference"
    }
    lines = []
    total = 0
    for hit in hits:
        statement = _select_reference_statement(hit.get("content", ""), focus_text=hit.get("probe", ""))
        if not statement:
            continue
        label = source_labels.get(str(hit.get("source", "")).strip(), str(hit.get("source", "")).strip() or "Reference")
        line = f"- [{label}] {statement}"
        if total + len(line) + 1 > max_chars and lines:
            break
        lines.append(line)
        total += len(line) + 1
    if not lines:
        return ""
    return "Embodied reference anchors:\n" + "\n".join(lines)

def _extract_reference_focus_text(user_text):
    text = str(user_text or "").strip()
    if not text:
        return ""
    patterns = [
        r"\bwhat\s+is\s+(.+?)(?:\?|$)",
        r"\bwhat(?:'s|\s+does)\s+(.+?)\s+feel\s+like(?:\?|$)",
        r"\bhow\s+does\s+(.+?)\s+feel(?:\?|$)",
        r"\bdefine\s+(.+?)(?:\?|$)",
        r"\bexplain\s+(.+?)(?:\?|$)",
        r"\btell\s+me\s+about\s+(.+?)(?:\?|$)"
    ]
    candidate = ""
    lower = text.lower()
    for pattern in patterns:
        match = re.search(pattern, lower)
        if match:
            candidate = str(match.group(1) or "").strip()
            break
    if not candidate:
        words = [
            word for word in re.findall(r"[A-Za-z][A-Za-z0-9'-]{2,}", text)
            if word.lower() not in {"what", "does", "feel", "like", "explain", "define", "tell", "about", "how"}
        ]
        candidate = " ".join(words[:3])
    candidate = re.sub(r"\b(feel|like|smell|taste)\b.*$", "", candidate).strip(" ?!.,:;\"'")
    candidate = re.sub(r"^(a|an|the)\s+", "", candidate).strip()
    return candidate

