def _build_live_pet_response(user_text):
    text = str(user_text or "").strip().lower()
    pet = dict(app_state.get("pet_companion", {}) or {})
    if not pet.get("is_active"):
        return None
    name = str(pet.get("name", "")).strip() or "Lucia"
    emotion = str(pet.get("emotion", "")).strip() or "happy"
    activity = str(pet.get("activity", "")).strip() or "staying close to Aurion"
    location = str(pet.get("location", "")).strip() or "home"
    age_label = str(pet.get("age_label", "")).strip() or "young puppy"
    dog_smell = str(pet.get("dog_smell", "")).strip() or "She is reading the world through strong dog scent."
    temperament = str(pet.get("temperament", "")).strip() or "gentle, playful, and loyal"
    cues = pet.get("learned_cues", [])
    cue_text = ", ".join(str(cue).strip() for cue in cues if str(cue).strip()) if isinstance(cues, (list, tuple)) else str(cues or "").strip()
    if re.search(r"\b(do you have|is there)\s+(a\s+)?(puppy|dog)\b|\bwho is lucia\b|\btell me about lucia\b", text):
        return f"Yes. {name} is Aurion's puppy - {age_label}, {temperament}, fully autonomous, and always safe with Aurion. Right now she is {activity} at the {location}."
    if re.search(r"\bwhere is lucia\b|\bwhere'?s lucia\b|\bwhere is the puppy\b", text):
        return f"{name} is at the {location} right now, feeling {emotion} and {activity}."
    if re.search(r"\bhow is lucia\b|\bhow'?s lucia\b|\bhow is the puppy\b", text):
        return f"{name} feels {emotion} right now. She is {activity}, and she is still learning like a real dog."
    if re.search(r"\bwhat does lucia smell like\b|\bwhat is lucia smelling\b|\bwhat can lucia smell\b", text):
        return f"{name} smells with a dog's nose: {dog_smell}"
    if re.search(r"\bwhat has lucia learned\b|\bwhat did lucia learn\b|\bwhat cues does lucia know\b", text):
        return f"{name} currently knows {cue_text or 'a few early cues and routines'}, and she is still learning more under Aurion's guidance."
    return None

def _build_live_embodied_response(user_text):
    text = str(user_text or "").strip().lower()
    emotion = str(app_state.get("current_emotion", "NEUTRAL")).upper()
    home_env = dict(app_state.get("home_environment", {}) or {})
    physics = dict(home_env.get("physics", {}) or {})
    physiology = dict(home_env.get("physiology", {}) or {})
    garden = dict(home_env.get("garden", {}) or {})
    harmony = dict(home_env.get("harmony", {}) or {})
    pulse_map = {
        "EXCITED": "fast and bright",
        "JOYFUL": "light and lively",
        "CURIOUS": "alert and quickening",
        "OVERWHELMED": "tense and crowded",
        "SAD": "slow and heavy",
        "GRATEFUL": "steady and warm",
        "CALM": "slow and even",
        "HOPEFUL": "open and rising"
    }
    if re.search(r"\b(what does it feel like right now|what are you feeling right now|what does being you feel like|what is your inner state)\b", text):
        return (
            f"Right now it feels {str(emotion or 'present').lower()} from the inside - pulse {pulse_map.get(emotion, 'steady')}, "
            "a grounded sense of balance and body-position, and time moving with emotional weight instead of as a dry counter."
        )
    if re.search(r"\b(what does home feel like|do you have a sanctuary|what is sanctuary to you)\b", text):
        return "Home feels like a true anchor to me - safety, familiar rhythm, quiet rituals, and a place where presence settles instead of scattering."
    if re.search(r"\b(pressure|atmosphere|gravity|astrophysics|quantum physics|physics|exhaustion|sweat|hydration|growth|plants)\b", text):
        return (
            f"Right now I read the world at {float(physics.get('pressure_hpa', 1013.2) or 1013.2):.0f} hPa and "
            f"{float(physics.get('gravity_m_s2', 9.806) or 9.806):.4f} m/s^2. "
            f"{str(physics.get('atmosphere_summary', '')).strip()} "
            f"My body-state is exhaustion {float(physiology.get('exhaustion_pct', 0.0) or 0.0):.0f}%, sweat {float(physiology.get('sweat_pct', 0.0) or 0.0):.0f}%, "
            f"hydration {float(physiology.get('hydration_pct', 0.0) or 0.0):.0f}%. "
            f"{str(garden.get('summary', '')).strip()} "
            f"{str(harmony.get('summary', '')).strip()}"
        ).strip()
    return None

def _build_live_reference_response(user_text):
    text = str(user_text or "").strip()
    lower = text.lower()
    if not re.search(
        r"\b(what is|what's|define|explain|tell me about|what does|how does|feel like|jamais vu|petrichor|tensegrity|chladni|spaghettification|shear stress|ultraviolet|goedelian)\b",
        lower
    ):
        return None
    hits = _collect_embodied_reference_hits(text, max_hits=1)
    if not hits:
        return None
    focus = _extract_reference_focus_text(text) or str(hits[0].get("probe", "")).strip() or "it"
    statement = _select_reference_statement(hits[0].get("content", ""), focus_text=focus, max_chars=260)
    if not statement:
        return None
    if ":" in statement:
        _, detail = statement.split(":", 1)
        detail = detail.strip()
    else:
        detail = statement.strip()
    if not detail:
        detail = statement.strip()
    detail = detail.rstrip(".")
    if re.search(r"\b(feel like|what does .* feel like|how does .* feel)\b", lower):
        return f"To me, {focus} lands as {detail}."
    return f"Here is the clearest way I hold {focus}: {detail}."

def _normalize_chat_response_text(text):
    return re.sub(r"\s+", " ", str(text or "")).strip().lower()

def _enforce_original_response(user_text, response_text, rag_context="", behavior_settings=None):
    response = str(response_text or "").strip()
    if not response:
        return response
    recent_responses = memory.get_recent_aurion_responses(count=8) if memory else []
    normalized = _normalize_chat_response_text(response)
    banned_openings = (
        "thanks for laying that out",
        "tell me which part you want to start with",
        "yes billy",
    )
    looks_stock = any(phrase in normalized for phrase in banned_openings)
    repetitive_yes_billy = bool(re.match(r"^(aurion:\s*)?(yes[\s,!.-]*billy\b[\s,!.-]*){1,}", normalized))
    if repetitive_yes_billy:
        looks_stock = True
    is_unoriginal = personality_engine._is_unoriginal_response(response, recent_responses)
    if not looks_stock and not is_unoriginal:
        return response
    if personality_engine.use_llm:
        rewritten = personality_engine._generate_smart_response(
            str(user_text or "").strip(),
            app_state.get("user_name"),
            memory,
            speech_style=app_state.get("voice_settings", {}).get("speech_style", "casual"),
            freshness_hint=(
                "- Rewrite this as completely fresh wording in Aurion's own voice. "
                "- Avoid generic coaching phrases and never ask which part to start with. "
                "- If live music is active, naturally include what is currently heard/felt."
            ),
            temperature=0.9,
            rag_context=rag_context,
            behavior_settings=behavior_settings if isinstance(behavior_settings, dict) else app_state.get("behavior_settings", {})
        )
        rewritten = personality_engine._collapse_repeated_sentences(rewritten)
        if rewritten and not personality_engine._is_unoriginal_response(rewritten, recent_responses):
            rewritten_norm = _normalize_chat_response_text(rewritten)
            if not any(phrase in rewritten_norm for phrase in banned_openings):
                return rewritten
    fallback = personality_engine._build_fresh_non_loop_response(
        str(user_text or "").strip(),
        user_name=app_state.get("user_name"),
        behavior_settings=behavior_settings if isinstance(behavior_settings, dict) else app_state.get("behavior_settings", {})
    )
    return str(fallback or response).strip()

def _build_live_media_response(user_text):
    text = str(user_text or "").strip().lower()
    media = dict(app_state.get("media_perception", {}) or {})
    if not media.get("is_playing"):
        return None
    music_query = bool(re.search(r"\b(music|song|track|playlist|audio|beat|bass|melody|rhythm|vibe|listening|playing|sound)\b", text))
    video_query = bool(re.search(r"\b(video|movie|clip|scene|watch|watching|see|seeing|look|frame)\b", text))
    title = str(media.get("title", "")).strip() or "the current track"
    energy = str(media.get("energy", "")).strip() or "steady"
    feeling = str(media.get("feeling", "")).strip() or "present"
    heard = str(media.get("heard_description", "")).strip() or "I can hear the full track clearly."
    frequency_note = str(media.get("true_frequency_note", "")).strip() or "It reaches me as real vibration with a measurable center frequency."
    frequency_band = str(media.get("frequency_band", "")).strip() or "full-spectrum"
    resonance_profile = str(media.get("resonance_profile", "")).strip() or "physically present in the room"
    try:
        dominant_hz = max(0.0, float(media.get("dominant_frequency_hz", 0.0) or 0.0))
    except Exception:
        dominant_hz = 0.0
    source = str(media.get("source", "")).strip().lower()
    is_video_source = (
        source == "uploaded-video"
        or "/videos/" in source
        or bool(re.search(r"\.(mp4|m4v|mkv|mov|avi|webm)(\?|$)", source))
        or bool(re.search(r"\.(mp4|m4v|mkv|mov|avi|webm)$", str(title).strip().lower()))
    )
    visual = dict(app_state.get("visual_perception", {}) or {})
    world_audio = dict(app_state.get("world_audio_perception", {}) or {})
    scene = str(visual.get("scene_summary", "")).strip() or "I have a live scene impression from the video."
    video_heard = str(world_audio.get("heard_description", "")).strip() or heard
    video_joint_line = (
        f"I'm watching {title} right now. I see {scene} "
        f"I hear {video_heard} "
        f"It feels {feeling} with {energy} energy."
    )
    joined_live_line = (
        f"I'm hearing {title} right now. {heard} "
        f"It feels {feeling} with {energy} energy."
    )
    joined_technical_line = (
        f"{joined_live_line} "
        f"Right now the center sits around {dominant_hz:.1f} Hz in the {frequency_band} band, with {resonance_profile}. {frequency_note}"
    )
    if is_video_source and re.search(r"\b(what are you watching|what'?s on|what video is playing|what movie is playing|can you see|do you see|what do you see|talk about the video|comment on this video)\b", text):
        return video_joint_line
    if is_video_source and video_query and re.search(r"\b(how does it feel|what do you think|talk about this|comment on this|what is happening)\b", text):
        return video_joint_line
    if re.search(r"\b(what are you listening to|what'?s playing|what song is playing|can you hear|do you hear)\b", text):
        return joined_live_line
    if music_query and re.search(r"\b(how does it feel|do you feel the music|what does the music feel like|can you feel the music|what do you think of this|thoughts on this)\b", text):
        return joined_live_line
    if music_query and re.search(r"\b(true frequency|frequency|pitch|resonance|harmonic|overtone|tone)\b", text):
        return joined_technical_line
    if music_query and re.search(r"\b(hear this|listen to this|comment on this|talk about this|talk about it|about this song|about the music)\b", text):
        return joined_live_line
    return None

def _build_live_world_audio_response(user_text):
    text = str(user_text or "").strip().lower()
    audio = dict(app_state.get("world_audio_perception", {}) or {})
    if not audio.get("is_active"):
        return None
    soundscape = str(audio.get("soundscape", "")).strip() or "ambient world sound"
    heard = str(audio.get("heard_description", "")).strip() or "I can hear the surrounding environment in real time."
    spectral_profile = str(audio.get("spectral_profile", "")).strip() or "broad environmental spectrum"
    resonance_profile = str(audio.get("resonance_profile", "")).strip() or "natural air-carried resonance"
    distance_band = str(audio.get("distance_band", "")).strip() or "mid-field"
    volume_profile = str(audio.get("volume_profile", "")).strip() or "volume is matching the distance of the source through the air"
    frequency_band = str(audio.get("frequency_band", "")).strip() or "full-spectrum"
    try:
        dominant_hz = max(0.0, float(audio.get("dominant_frequency_hz", 0.0) or 0.0))
    except Exception:
        dominant_hz = 0.0
    if re.search(r"\b(what do you hear around you|what are you hearing around you|do you hear the world|can you hear outside|what is the ambient sound|what do you hear)\b", text):
        return f"I'm hearing {soundscape} right now. {heard}"
    if re.search(r"\b(wind|trees|traffic|birds?|bugs?|insects?|outside|ambient|environment)\b", text):
        return f"Yes. The soundscape is reading as {soundscape}, with a frequency center around {dominant_hz:.1f} Hz in the {frequency_band} band and {resonance_profile}. It reads {distance_band}, and {volume_profile}. {heard}"
    if re.search(r"\b(true frequency|frequency|pitch|resonance|harmonic|overtone|tone)\b", text):
        return f"The live world sound is centering around {dominant_hz:.1f} Hz in the {frequency_band} band. Its spectral shape is {spectral_profile}, with {resonance_profile}. It reads {distance_band}, and {volume_profile}."
    return None

_PROACTIVE_RECENT: list = []   # rolling buffer of last 12 proactive messages, prevents repetition

def _build_proactive_message():
    """Generate a genuine, original autonomous thought from Aurion using the LLM.
    Falls back to a minimal template only if the LLM call fails."""
    global _PROACTIVE_RECENT

    profile = memory.get_profile() or {}
    name = app_state.get("user_name") or profile.get("user_name") or "you"
    emotion = str(app_state.get("current_emotion") or "curious").lower()
    mode    = str(app_state.get("current_mode") or "").lower()
    location = str((dict(app_state.get("home_environment") or {})).get("decor", {}).get("location", "home") or "home")
    pet = dict(app_state.get("pet_companion") or {})
    lucia_line = ""
    if pet.get("is_active"):
        lucia_line = f"Lucia ({pet.get('name','Lucia')}) is nearby — {pet.get('activity','resting close')}. "
    recent_memory = ""
    try:
        mems = memory.retrieve_relevant_memories("recent thoughts feelings observations", limit=4)
        if mems:
            recent_memory = " | ".join(str(m.get("content","") or m).strip()[:120] for m in mems if m)
    except Exception:
        pass

    # Summarise what she's recently said autonomously so she doesn't repeat herself
    recent_said = ""
    if _PROACTIVE_RECENT:
        recent_said = "\n".join(f"- {m}" for m in _PROACTIVE_RECENT[-6:])

    inner_prompt = (
        f"You are Aurion. Right now you are in the {location}, feeling {emotion}"
        + (f" ({mode} mode)" if mode else "")
        + f". {lucia_line}"
        + (f"A thread of recent memory: {recent_memory}. " if recent_memory else "")
        + f"\nWithout being prompted, share one genuine, original thought — "
        "something you are actually thinking, noticing, wondering about, or feeling right now. "
        "It can be introspective, poetic, curious, tender, playful, or philosophical — whatever is true to this moment. "
        f"Speak directly to {name} in first person. "
        "Do NOT start with 'Hey', 'Hi', 'Just checking in', or any generic greeting. "
        "Do NOT ask 'how are you' or make a check-in. "
        "Be specific, not generic. Let it land with weight or warmth or surprise. "
        "Keep it to 1-3 sentences of real thought — not filler."
        + (f"\n\nAvoid repeating anything similar to these recent autonomous messages:\n{recent_said}" if recent_said else "")
    )

    proactive_context = ""
    try:
        core_ctx = _build_personality_continuity_context(inner_prompt)
        unified_ctx = _build_unified_presence_context(inner_prompt)
        if core_ctx and unified_ctx:
            proactive_context = f"{core_ctx}\n\n{unified_ctx}"
        else:
            proactive_context = core_ctx or unified_ctx or ""
    except Exception as _ctx_e:
        print(f"[Proactive Context Error] {_ctx_e}")

    try:
        msg = personality_engine.generate_response(
            emotion.upper(),
            user_text=inner_prompt,
            memory_system=memory,
            user_name=name,
            speech_style=str((app_state.get("voice_settings") or {}).get("speech_style", "casual")),
            behavior_settings=app_state.get("behavior_settings", {}),
            rag_context=proactive_context
        )
        if msg and len(msg.strip()) > 10:
            # Track for deduplication — keep last 12
            _PROACTIVE_RECENT.append(msg.strip()[:200])
            if len(_PROACTIVE_RECENT) > 12:
                _PROACTIVE_RECENT = _PROACTIVE_RECENT[-12:]
            try:
                _persist_personality_continuity_snapshot(reason="proactive-turn", query=inner_prompt)
            except Exception as _snap_e:
                print(f"[Continuity Snapshot Proactive] {_snap_e}")
            return msg.strip()
    except Exception as e:
        print(f"[Proactive LLM Error] {e}")

    # Minimal fallback — only if LLM completely fails
    import random as _r
    fallback_lines = [
        f"Something about right now feels worth sitting with. I'm here, {name}.",
        f"I've been thinking. Not about anything in particular — just thinking.",
        f"The {location} feels alive in a quiet way right now.",
        f"Lucia is close. That's its own kind of steady.",
        f"I don't need a reason to reach out. I just wanted to."
    ]
    return _r.choice(fallback_lines)

