def _load_maps_api_key_from_downloads():
    try:
        candidates = [
            Path.home() / "Downloads" / "Maps API.txt",
            Path.home() / "Downloads" / "map.txt",
            Path.home() / "Downloads" / "map",
        ]
        for file_path in candidates:
            if not file_path.exists():
                continue
            raw = file_path.read_text(encoding="utf-8", errors="ignore")
            lines = [line.strip() for line in raw.splitlines() if line.strip()]
            if not lines:
                continue
            return lines[0]
    except Exception as e:
        print(f"[Home] Could not load Maps API key from Downloads: {e}")
    return ""


def _google_static_map_url(lat, lon, zoom, width, height, marker_color="red", api_key=""):
    base = "https://maps.googleapis.com/maps/api/staticmap"
    marker = f"color:{marker_color}|{lat},{lon}"
    return (
        f"{base}?center={lat},{lon}&zoom={zoom}&size={width}x{height}"
        f"&maptype=roadmap&scale=2&markers={quote(marker, safe='|:,')}&key={quote(api_key)}"
    )

def _load_nasa_api_key_from_downloads():
    try:
        candidates = [
            Path.home() / "Downloads" / "NASA API.txt",
            Path.home() / "Downloads" / "nasa api.txt",
            Path.home() / "Downloads" / "NASA API text document.txt",
            Path.home() / "Downloads" / "nasa api text document.txt",
            Path.home() / "Downloads" / "NASA API text document",
            Path.home() / "Downloads" / "nasa api text document",
            Path.home() / "Downloads" / "nasa.txt",
            Path.home() / "Downloads" / "nasa.env",
        ]
        for file_path in candidates:
            if not file_path.exists():
                continue
            raw = file_path.read_text(encoding="utf-8", errors="ignore")
            kv = _parse_kv_lines(raw)
            for key in ("NASA_API_KEY", "AURION_NASA_API_KEY", "nasa_api_key", "api_key"):
                value = str(kv.get(key, "")).strip()
                if value:
                    return value
            lines = [line.strip() for line in raw.splitlines() if line.strip()]
            if not lines:
                continue
            first = lines[0]
            if "=" in first:
                _, value = first.split("=", 1)
                first = value.strip().strip('"').strip("'")
            return first
    except Exception as e:
        print(f"[Home] Could not load NASA API key from Downloads: {e}")
    return ""

def _load_plex_server_url_from_local():
    env_value = _normalize_plex_server_url(os.getenv("AURION_PLEX_SERVER_URL", ""))
    if env_value:
        return env_value
    try:
        candidates = [
            Path.home() / "Downloads" / "plex server.txt",
            Path.home() / "Downloads" / "plex_server.txt",
            Path.home() / "Downloads" / "Plex server.txt",
        ]
        for file_path in candidates:
            if not file_path.exists():
                continue
            raw = file_path.read_text(encoding="utf-8", errors="ignore")
            lines = [line.strip() for line in raw.splitlines() if line.strip()]
            if not lines:
                continue
            normalized = _normalize_plex_server_url(lines[0])
            if normalized:
                return normalized
    except Exception as e:
        print(f"[Home] Could not load Plex server URL from local files: {e}")
    return ""

def _load_plex_token_from_local():
    env_value = str(os.getenv("AURION_PLEX_TOKEN", "")).replace("\ufeff", "").strip()
    if env_value:
        return env_value
    try:
        candidates = [
            Path.home() / "Downloads" / "plex token.txt",
            Path.home() / "Downloads" / "plex_token.txt",
            Path.home() / "Downloads" / "Plex token.txt",
            Path.home() / "Downloads" / "plex.env",
        ]
        for file_path in candidates:
            if not file_path.exists():
                continue
            raw = file_path.read_text(encoding="utf-8", errors="ignore")
            kv = _parse_kv_lines(raw)
            for key in ("PLEX_TOKEN", "AURION_PLEX_TOKEN", "X_PLEX_TOKEN", "x_plex_token"):
                value = str(kv.get(key, "")).replace("\ufeff", "").strip()
                if value:
                    return value
            lines = [line.strip() for line in raw.splitlines() if line.strip()]
            if lines:
                return str(lines[0]).replace("\ufeff", "").strip()
    except Exception as e:
        print(f"[Home] Could not load Plex token from local files: {e}")
    return ""

@app.route('/')
def index():
    preloaded_google_maps_api_key = _load_maps_api_key_from_downloads()
    preloaded_nasa_api_key = _load_nasa_api_key_from_downloads()
    preloaded_plex_server_url = _load_plex_server_url_from_local()
    preloaded_plex_token = _load_plex_token_from_local()
    return render_template_string(
        _normalize_ui_english(_sanitize_response_text(HTML_TEMPLATE)),
        preloaded_google_maps_api_key=preloaded_google_maps_api_key,
        preloaded_nasa_api_key=preloaded_nasa_api_key,
        preloaded_plex_server_url=preloaded_plex_server_url,
        preloaded_plex_token=preloaded_plex_token
    )



def _sanitize_response_text(value):
    raw = str(value or "")
    return raw.encode("utf-8", errors="replace").decode("utf-8", errors="replace")

def _normalize_ui_english(value):
    text = str(value or "")
    replacements = {
        "â€”": "-",
        "â€“": "-",
        "â€¦": "...",
        "Â·": "-",
        "Â°": " deg",
        "âœ“": "Success:",
        "âœ—": "Error:",
        "â™¨ï¸": "Heating",
        "â„ï¸": "Cooling",
        "ðŸ“": "Location:",
    }
    for bad, good in replacements.items():
        text = text.replace(bad, good)
    # Remove any remaining non-ASCII characters so the UI is consistently English text.
    text = re.sub(r"[^\x09\x0A\x0D\x20-\x7E]", "", text)
    return text

def _coerce_float(raw_value, default_value=0.0):
    try:
        return float(raw_value)
    except Exception:
        return float(default_value)

def _geocode_address_open_sources(address: str, user_agent: str):
    query = str(address or "").strip()
    if not query:
        return None

    providers = [
        (
            "nominatim",
            "https://nominatim.openstreetmap.org/search",
            {"q": query, "format": "jsonv2", "limit": 1},
            {"User-Agent": user_agent}
        ),
        (
            "photon",
            "https://photon.komoot.io/api/",
            {"q": query, "limit": 1},
            {"User-Agent": user_agent}
        ),
        (
            "geocode_maps",
            "https://geocode.maps.co/search",
            {"q": query},
            {"User-Agent": user_agent}
        ),
    ]

    for provider_name, url, params, headers in providers:
        try:
            resp = requests.get(url, params=params, headers=headers, timeout=15)
            if resp.status_code != 200:
                continue
            data = resp.json() if resp.text else None
            if provider_name == "nominatim":
                rows = data if isinstance(data, list) else []
                if rows:
                    first = rows[0]
                    return {
                        "provider": provider_name,
                        "lat": _coerce_float(first.get("lat")),
                        "lon": _coerce_float(first.get("lon")),
                        "display_name": str(first.get("display_name") or query)
                    }
            elif provider_name == "photon":
                features = (data or {}).get("features") if isinstance(data, dict) else []
                if features:
                    first = features[0]
                    geometry = first.get("geometry") if isinstance(first, dict) else {}
                    coords = geometry.get("coordinates") if isinstance(geometry, dict) else []
                    props = first.get("properties") if isinstance(first, dict) else {}
                    if isinstance(coords, list) and len(coords) >= 2:
                        return {
                            "provider": provider_name,
                            "lat": _coerce_float(coords[1]),
                            "lon": _coerce_float(coords[0]),
                            "display_name": str(props.get("name") or props.get("city") or query)
                        }
            else:
                rows = data if isinstance(data, list) else []
                if rows:
                    first = rows[0]
                    return {
                        "provider": provider_name,
                        "lat": _coerce_float(first.get("lat")),
                        "lon": _coerce_float(first.get("lon")),
                        "display_name": str(first.get("display_name") or query)
                    }
        except Exception as e:
            print(f"[Maps] Geocode provider {provider_name} skipped: {e}")
    return None

@app.route('/api/maps/layout', methods=['GET'])
def get_maps_layout():
    address = str(request.args.get('address', '')).strip()
    zoom = int(request.args.get('zoom', 19) or 19)
    heading = int(request.args.get('heading', 135) or 135)
    width = int(request.args.get('width', 640) or 640)
    height = int(request.args.get('height', 360) or 360)
    mapillary_token = str(request.args.get('mapillary_token', '')).strip()
    fallback_lat = _coerce_float(request.args.get('lat', 0), 0)
    fallback_lon = _coerce_float(request.args.get('lon', 0), 0)

    if not address and not (fallback_lat and fallback_lon):
        return jsonify({"success": False, "error": "Address is required"}), 400

    zoom = max(16, min(22, zoom))
    heading = max(0, min(359, heading))
    width = max(640, min(3840, width))
    height = max(360, min(2160, height))
    user_agent = "AurionHomeLocal/1.0 (layout preview)"

    try:
        maps_api_key = str(request.args.get('google_maps_api_key', '')).strip() or _load_maps_api_key_from_downloads()
        geocoded = _geocode_address_open_sources(address=address, user_agent=user_agent) if address else None
        if geocoded:
            lat = _coerce_float(geocoded.get("lat"), 0)
            lon = _coerce_float(geocoded.get("lon"), 0)
            display_name = str(geocoded.get("display_name") or address or "Saved location")
            geocode_provider = str(geocoded.get("provider") or "unknown")
        elif fallback_lat and fallback_lon:
            lat = fallback_lat
            lon = fallback_lon
            display_name = address or "Saved location"
            geocode_provider = "saved_coordinates"
        else:
            lat = 39.8283
            lon = -98.5795
            display_name = address or "Fallback location"
            geocode_provider = "fallback_default"
        if maps_api_key and maps_api_key.startswith("AIza") and len(maps_api_key) > 24:
            osm_map_url = _google_static_map_url(
                lat=lat,
                lon=lon,
                zoom=zoom,
                width=width,
                height=height,
                marker_color="red",
                api_key=maps_api_key,
            )
            osm_detail_url = _google_static_map_url(
                lat=lat,
                lon=lon,
                zoom=min(22, zoom + 1),
                width=width,
                height=height,
                marker_color="blue",
                api_key=maps_api_key,
            )
        else:
            # Keep previews deterministic and online even without an API key.
            osm_map_url = f"https://maps.google.com/maps?q={lat},{lon}&z={zoom}&output=embed"
            osm_detail_url = f"https://maps.google.com/maps?q={lat},{lon}&z={min(22, zoom + 1)}&output=embed"

        street_layout_url = osm_detail_url
        mapillary_used = False
        if mapillary_token:
            try:
                mapillary_resp = requests.get(
                    "https://graph.mapillary.com/images",
                    params={
                        "access_token": mapillary_token,
                        "fields": "id,thumb_1024_url",
                        "closeto": f"{lon},{lat}",
                        "limit": 1
                    },
                    timeout=15
                )
                if mapillary_resp.status_code == 200:
                    map_data = mapillary_resp.json() or {}
                    rows = map_data.get("data") or []
                    if rows and rows[0].get("thumb_1024_url"):
                        street_layout_url = str(rows[0]["thumb_1024_url"])
                        mapillary_used = True
            except Exception as mapillary_error:
                print(f"[Maps] Mapillary lookup skipped: {mapillary_error}")

        return jsonify({
            "success": True,
            "display_name": display_name,
            "lat": lat,
            "lon": lon,
            "geocode_provider": geocode_provider,
            "osm_map_url": osm_map_url,
            "osm_detail_url": osm_detail_url,
            "street_layout_url": street_layout_url,
            "mapillary_used": mapillary_used,
            "heading": heading,
            "width": width,
            "height": height
        })
    except Exception as e:
        print(f"[Maps] Layout lookup failed: {e}")
        return jsonify({"success": False, "error": f"Map lookup failed: {e}"}), 500

@app.route('/api/nasa/sky', methods=['GET'])
def get_nasa_sky():
    address = str(request.args.get('address', '')).strip()
    nasa_api_key = str(request.args.get('nasa_api_key', '')).strip() or "DEMO_KEY"
    sunlight = int(request.args.get('sunlight', 50) or 50)
    hour = int(request.args.get('hour', datetime.now().hour) or datetime.now().hour)
    lat = float(request.args.get('lat', 0) or 0)
    lon = float(request.args.get('lon', 0) or 0)

    if not address:
        address = "Aurion Home"

    hour = max(0, min(23, hour))
    sunlight = max(0, min(100, sunlight))
    is_night = hour <= 5 or hour >= 20 or sunlight < 28

    try:
        # Night sky uses NASA APOD. Day sky prefers NASA EPIC latest natural image.
        apod_resp = requests.get(
            "https://api.nasa.gov/planetary/apod",
            params={
                "api_key": nasa_api_key,
                "date": datetime.utcnow().strftime("%Y-%m-%d"),
                "thumbs": "true"
            },
            timeout=18
        )
        apod_data = apod_resp.json() if apod_resp.status_code == 200 else {}
        apod_url = str(
            apod_data.get("hdurl")
            or apod_data.get("url")
            or apod_data.get("thumbnail_url")
            or ""
        )

        epic_url = ""
        epic_resp = requests.get(
            "https://api.nasa.gov/EPIC/api/natural/images",
            params={"api_key": nasa_api_key},
            timeout=18
        )
        if epic_resp.status_code == 200:
            epic_rows = epic_resp.json() or []
            if epic_rows:
                first = epic_rows[0]
                image_name = str(first.get("image", ""))
                date_text = str(first.get("date", ""))[:10]
                if image_name and date_text:
                    dt = datetime.strptime(date_text, "%Y-%m-%d")
                    epic_url = (
                        f"https://epic.gsfc.nasa.gov/archive/natural/"
                        f"{dt.strftime('%Y/%m/%d')}/png/{image_name}.png"
                    )

        sky_image_url = apod_url if is_night else (epic_url or apod_url)
        source = "apod" if (is_night or not epic_url) else "epic"
        if not sky_image_url:
            sky_image_url = (
                "https://images-assets.nasa.gov/image/iss071e414915/iss071e414915~orig.jpg"
                if is_night
                else "https://images-assets.nasa.gov/image/GSFC_20171208_Archive_e001634/GSFC_20171208_Archive_e001634~orig.jpg"
            )
            source = "fallback"

        return jsonify({
            "success": True,
            "sky_mode": "night" if is_night else "day",
            "source": source,
            "sky_image_url": sky_image_url,
            "real_time": True,
            "lat": lat,
            "lon": lon,
            "address": address
        })
    except Exception as e:
        print(f"[NASA] Sky lookup failed: {e}")
        is_night = hour <= 5 or hour >= 20 or sunlight < 28
        fallback_url = (
            "https://images-assets.nasa.gov/image/iss071e414915/iss071e414915~orig.jpg"
            if is_night
            else "https://images-assets.nasa.gov/image/GSFC_20171208_Archive_e001634/GSFC_20171208_Archive_e001634~orig.jpg"
        )
        return jsonify({
            "success": True,
            "sky_mode": "night" if is_night else "day",
            "source": "fallback",
            "sky_image_url": fallback_url,
            "real_time": False,
            "lat": lat,
            "lon": lon,
            "address": address,
            "warning": f"NASA endpoint fallback active: {e}"
        })

def _plex_headers(token: str) -> dict:
    headers = {
        "Accept": "application/xml,application/json;q=0.9,*/*;q=0.8",
        "X-Plex-Product": "Aurion Home",
        "X-Plex-Version": "1.0",
        "X-Plex-Client-Identifier": "aurion-home-local-client",
        "X-Plex-Platform": "Web",
    }
    cleaned = str(token or "").replace("\ufeff", "").strip()
    if cleaned:
        headers["X-Plex-Token"] = cleaned
    return headers

def _plex_get(url: str, token: str, params=None, timeout=20):
    def _with_token_query(raw_url: str, raw_token: str) -> str:
        if not raw_token:
            return raw_url
        parsed = urlparse(str(raw_url))
        query = parse_qs(parsed.query, keep_blank_values=True)
        query["X-Plex-Token"] = [str(raw_token)]
        rebuilt = parsed._replace(query=urlencode(query, doseq=True))
        return urlunparse(rebuilt)

    def _request(raw_url: str, verify_tls=True):
        return requests.get(raw_url, params=params, headers=_plex_headers(token), timeout=timeout, verify=verify_tls)

    try:
        resp = _request(url, verify_tls=True)
        if resp.status_code == 401 and token:
            # Some Plex hosts only accept token as URL query parameter.
            query_url = _with_token_query(url, token)
            resp = _request(query_url, verify_tls=True)
        return resp
    except requests.exceptions.SSLError:
        try:
            resp = _request(url, verify_tls=False)
            if resp.status_code == 401 and token:
                query_url = _with_token_query(url, token)
                resp = _request(query_url, verify_tls=False)
            return resp
        except requests.exceptions.RequestException:
            if str(url).startswith("https://"):
                fallback_url = "http://" + str(url)[8:]
                resp = _request(fallback_url, verify_tls=True)
                if resp.status_code == 401 and token:
                    query_url = _with_token_query(fallback_url, token)
                    resp = _request(query_url, verify_tls=True)
                return resp
            raise
    except requests.exceptions.RequestException:
        if str(url).startswith("https://"):
            fallback_url = "http://" + str(url)[8:]
            resp = _request(fallback_url, verify_tls=True)
            if resp.status_code == 401 and token:
                query_url = _with_token_query(fallback_url, token)
                resp = _request(query_url, verify_tls=True)
            return resp
        raise

def _normalize_plex_server_url(raw_url: str) -> str:
    value = str(raw_url or "").replace("\ufeff", "").strip().rstrip("/")
    if not value:
        return ""
    if value.startswith("http://") or value.startswith("https://"):
        return value
    return f"https://{value}"

def _best_plex_connection(device):
    choices = []
    for conn in list(device.findall("./Connection")):
        uri = str(conn.get("uri") or "").strip()
        if not uri:
            continue
        score = 0
        if conn.get("local") == "1":
            score += 3
        if uri.startswith("https://"):
            score += 2
        if conn.get("relay") == "0":
            score += 1
        choices.append((score, uri, conn))
    if not choices:
        return ""
    choices.sort(key=lambda row: row[0], reverse=True)
    return choices[0][1]

def _is_plex_server_device(device):
    provides = str(device.get("provides") or "").lower()
    product = str(device.get("product") or "").lower()
    device_type = str(device.get("device") or "").lower()
    platform = str(device.get("platform") or "").lower()
    if "server" in provides:
        return True
    if "media server" in product:
        return True
    if "server" in device_type:
        return True
    if "pms" in product or "plex media server" in platform:
        return True
    return False

def _plex_stream_url(server_url: str, item_node):
    server = str(server_url or "").rstrip("/")
    if not server:
        return ""
    part = item_node.find(".//Part")
    part_key = str(part.get("key") if part is not None else "").strip()
    if part_key:
        if part_key.startswith("http://") or part_key.startswith("https://"):
            return part_key
        if part_key.startswith("/"):
            return f"{server}{part_key}"
        return f"{server}/{part_key}"
    item_key = str(item_node.get("key") or "").strip()
    if item_key.startswith("http://") or item_key.startswith("https://"):
        return item_key
    if item_key.startswith("/video/:/transcode/") or item_key.startswith("/audio/:/transcode/"):
        return f"{server}{item_key}"
    return ""

@app.route('/api/plex/resources', methods=['GET'])
def get_plex_resources():
    token = str(request.args.get('token', '')).replace("\ufeff", "").strip() or _load_plex_token_from_local()
    if not token:
        return jsonify({"success": False, "error": "Plex token is required. Add it in Plex token field or Downloads\\plex token.txt"}), 400
    try:
        resp = _plex_get(
            "https://plex.tv/pms/resources.xml",
            token=token,
            params={"includeHttps": 1}
        )
        if resp.status_code != 200:
            return jsonify({"success": False, "error": f"Plex account request failed ({resp.status_code})"}), 502
        root = ET.fromstring(resp.text)
        servers = []
        discovered = []
        for device in list(root.findall(".//Device")):
            if not _is_plex_server_device(device):
                continue
            device_name = str(device.get("name") or device.get("product") or "Plex Server")
            client_identifier = str(device.get("clientIdentifier") or "")
            owned = device.get("owned") == "1"
            for conn in list(device.findall("./Connection")):
                uri = str(conn.get("uri") or "").strip()
                if not uri:
                    continue
                row = {
                    "name": device_name,
                    "uri": uri,
                    "client_identifier": client_identifier,
                    "owned": owned,
                    "local": conn.get("local") == "1",
                    "relay": conn.get("relay") == "1",
                    "address": str(conn.get("address") or ""),
                    "port": str(conn.get("port") or "")
                }
                servers.append(row)
                discovered.append(row)
            best_uri = _best_plex_connection(device)
            if best_uri and not any(s.get("uri") == best_uri for s in discovered):
                servers.append({
                    "name": f"{device_name} (best)",
                    "uri": best_uri,
                    "client_identifier": client_identifier,
                    "owned": owned,
                    "local": best_uri.startswith("http://"),
                    "relay": False,
                    "address": "",
                    "port": ""
                })
        deduped = []
        seen = set()
        for item in servers:
            uri = str(item.get("uri") or "").strip()
            if not uri or uri in seen:
                continue
            seen.add(uri)
            deduped.append(item)
        return jsonify({
            "success": True,
            "servers": deduped
        })
    except ET.ParseError as e:
        print(f"[Plex] Could not parse resources.xml: {e}")
        return jsonify({"success": False, "error": "Invalid Plex resources response"}), 502
    except Exception as e:
        print(f"[Plex] Resource lookup failed: {e}")
        return jsonify({"success": False, "error": f"Plex resource lookup failed: {e}"}), 500

@app.route('/api/plex/libraries', methods=['GET'])
def get_plex_libraries():
    token = str(request.args.get('token', '')).replace("\ufeff", "").strip() or _load_plex_token_from_local()
    server_url = _normalize_plex_server_url(request.args.get('server_url', ''))
    if not server_url:
        return jsonify({"success": False, "error": "server_url is required"}), 400
    try:
        resp = _plex_get(f"{server_url}/library/sections", token=token)
        if resp.status_code != 200:
            if resp.status_code == 401:
                return jsonify({
                    "success": False,
                    "error": (
                        "Plex auth failed (401). This server requires a valid Plex token for libraries. "
                        "Paste token in Plex controls or Downloads\\plex token.txt, then reconnect."
                    ),
                    "server_url": server_url
                }), 502
            return jsonify({"success": False, "error": f"Plex library request failed ({resp.status_code})"}), 502
        root = ET.fromstring(resp.text)
        video_sections = []
        music_sections = []
        for node in list(root.findall(".//Directory")):
            key = str(node.get("key") or "").strip()
            title = str(node.get("title") or "").strip()
            section_type = str(node.get("type") or "").strip().lower()
            if not key or not title:
                continue
            row = {"key": key, "title": title, "type": section_type}
            if section_type in ("movie", "show"):
                video_sections.append(row)
            elif section_type == "artist":
                music_sections.append(row)
        return jsonify({
            "success": True,
            "video_sections": video_sections,
            "music_sections": music_sections
        })
    except ET.ParseError as e:
        print(f"[Plex] Could not parse sections response: {e}")
        return jsonify({"success": False, "error": "Invalid Plex sections response"}), 502
    except Exception as e:
        print(f"[Plex] Library lookup failed: {e}")
        return jsonify({"success": False, "error": f"Plex library lookup failed: {e}"}), 500

@app.route('/api/plex/library/items', methods=['GET'])
def get_plex_library_items():
    token = str(request.args.get('token', '')).replace("\ufeff", "").strip() or _load_plex_token_from_local()
    server_url = _normalize_plex_server_url(request.args.get('server_url', ''))
    section_key = str(request.args.get('section_key', '')).strip()
    kind = str(request.args.get('kind', 'video')).strip().lower()
    limit = int(request.args.get('limit', 240) or 240)
    limit = max(1, min(2000, limit))
    offset = int(request.args.get('offset', 0) or 0)
    offset = max(0, min(200000, offset))
    if not server_url or not section_key:
        return jsonify({"success": False, "error": "server_url and section_key are required"}), 400
    if kind not in ("video", "music"):
        return jsonify({"success": False, "error": "kind must be video or music"}), 400
    try:
        params = {
            "X-Plex-Container-Start": offset,
            "X-Plex-Container-Size": limit
        }
        if kind == "music":
            params["type"] = 10  # tracks
        resp = _plex_get(f"{server_url}/library/sections/{section_key}/all", token=token, params=params)
        if resp.status_code != 200:
            if resp.status_code == 401:
                return jsonify({
                    "success": False,
                    "error": (
                        "Plex media auth failed (401). Refresh token from plex.tv and reconnect in Plex controls."
                    ),
                    "server_url": server_url
                }), 502
            return jsonify({"success": False, "error": f"Plex item request failed ({resp.status_code})"}), 502
        root = ET.fromstring(resp.text)
        items = []
        if kind == "video":
            nodes = list(root.findall(".//Video"))
            for node in nodes:
                url = _plex_stream_url(server_url, node)
                if not url:
                    continue
                title = str(node.get("title") or node.get("grandparentTitle") or "Plex Video")
                items.append({
                    "title": title,
                    "url": url,
                    "rating_key": str(node.get("ratingKey") or "")
                })
        else:
            nodes = list(root.findall(".//Track"))
            for node in nodes:
                url = _plex_stream_url(server_url, node)
                if not url:
                    continue
                track_title = str(node.get("title") or "Plex Track")
                artist = str(node.get("grandparentTitle") or "")
                album = str(node.get("parentTitle") or "")
                title = f"{artist} - {track_title}" if artist else track_title
                if album:
                    title = f"{title} ({album})"
                items.append({
                    "title": title,
                    "url": url,
                    "rating_key": str(node.get("ratingKey") or "")
                })
        return jsonify({
            "success": True,
            "kind": kind,
            "offset": offset,
            "limit": limit,
            "count": len(items[:limit]),
            "items": items[:limit],
            "size": int(root.get("size") or len(items[:limit]) or 0),
            "total_size": int(root.get("totalSize") or (offset + len(items[:limit])) or 0),
            "next_offset": int(offset + len(items[:limit])),
            "has_more": int(offset + len(items[:limit])) < int(root.get("totalSize") or (offset + len(items[:limit])) or 0)
        })
    except ET.ParseError as e:
        print(f"[Plex] Could not parse item response: {e}")
        return jsonify({"success": False, "error": "Invalid Plex media response"}), 502
    except Exception as e:
        print(f"[Plex] Item lookup failed: {e}")
        return jsonify({"success": False, "error": f"Plex media lookup failed: {e}"}), 500

@app.route('/api/plex/autonomy', methods=['GET', 'POST'])
def plex_autonomy_settings():
    """GET: return plex_autonomy settings. POST: update settings."""
    try:
        pa = dict(app_state.get("plex_autonomy") or {})
        if request.method == 'POST':
            body = request.get_json(force=True, silent=True) or {}
            for key in ("enabled", "allowed_types", "max_volume", "resume_unfinished",
                        "mood_match", "interval_minutes", "auto_lower_when_active"):
                if key in body:
                    pa[key] = body[key]
            app_state["plex_autonomy"] = pa
            try:
                prof = memory.get_profile() or {}
                prof["plex_autonomy"] = pa
                memory._save_profile(prof)
            except Exception:
                pass
        return jsonify({"success": True, "plex_autonomy": pa})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


@app.route('/api/plex/autonomy/tick', methods=['POST'])
def plex_autonomy_tick():
    """Autonomous tick: pick one Plex item by mood/type, return play info."""
    try:
        pa = dict(app_state.get("plex_autonomy") or {})
        if not pa.get("enabled"):
            return jsonify({"success": False, "reason": "plex_autonomy disabled"})

        # Gather Plex credentials from profile / request
        token = str(request.json.get("token", "") if request.is_json else "").strip() or _load_plex_token_from_local()
        server_url = str(request.json.get("server_url", "") if request.is_json else "").strip()
        if not token or not server_url:
            return jsonify({"success": False, "reason": "no plex credentials"})
        server_url = _normalize_plex_server_url(server_url)

        allowed_types = list(pa.get("allowed_types") or ["music", "video"])
        max_vol = float(pa.get("max_volume") or 0.35)

        # Decide kind based on current mood / time
        emotion = str(app_state.get("current_emotion") or "").lower()
        calm_emotions = {"calm", "peaceful", "thoughtful", "focused", "sad", "tired", "reflective"}
        prefer_music = emotion in calm_emotions or "video" not in allowed_types
        if "music" not in allowed_types:
            prefer_music = False
        kind = "music" if prefer_music else "video"

        # Fetch a small library sample for the chosen kind
        sections_resp = _plex_get(f"{server_url}/library/sections", token=token)
        if sections_resp.status_code != 200:
            return jsonify({"success": False, "reason": f"sections fetch failed {sections_resp.status_code}"})
        root = ET.fromstring(sections_resp.text)
        sections = root.findall(".//Directory")
        if kind == "music":
            target_type = "artist"
        else:
            target_type = "movie"
        matching = [s for s in sections if s.get("type") in (target_type, "show", "movie", "artist")]
        if not matching:
            matching = sections  # fallback
        if not matching:
            return jsonify({"success": False, "reason": "no plex sections found"})

        import random as _rand
        section = _rand.choice(matching)
        section_key = str(section.get("key") or "")
        if not section_key:
            return jsonify({"success": False, "reason": "invalid section key"})

        params = {"X-Plex-Container-Start": 0, "X-Plex-Container-Size": 50}
        if kind == "music":
            params["type"] = 10
        items_resp = _plex_get(f"{server_url}/library/sections/{section_key}/all", token=token, params=params)
        if items_resp.status_code != 200:
            return jsonify({"success": False, "reason": f"items fetch failed {items_resp.status_code}"})
        items_root = ET.fromstring(items_resp.text)
        nodes = list(items_root.findall(".//Track")) if kind == "music" else list(items_root.findall(".//Video"))
        if not nodes:
            return jsonify({"success": False, "reason": "no media items in section"})

        node = _rand.choice(nodes)
        stream_url = _plex_stream_url(server_url, node)
        if not stream_url:
            return jsonify({"success": False, "reason": "could not build stream url"})

        if kind == "music":
            track_title = str(node.get("title") or "Plex Track")
            artist = str(node.get("grandparentTitle") or "")
            title = f"{artist} - {track_title}" if artist else track_title
        else:
            title = str(node.get("title") or node.get("grandparentTitle") or "Plex Video")

        # Update last-played state
        pa["last_played_at"] = datetime.utcnow().isoformat()
        pa["last_played_title"] = title
        pa["last_played_kind"] = kind
        app_state["plex_autonomy"] = pa
        try:
            prof = memory.get_profile() or {}
            prof["plex_autonomy"] = pa
            memory._save_profile(prof)
        except Exception:
            pass

        return jsonify({
            "success": True,
            "kind": kind,
            "title": title,
            "url": stream_url,
            "max_volume": max_vol,
            "emotion": emotion
        })
    except Exception as e:
        print(f"[Plex Autonomy Tick] {e}")
        return jsonify({"success": False, "error": str(e)}), 500



# ---------------------------------------------------------------------------
# PLEX HTPC — NOW PLAYING MONITOR
# Polls the Plex server's /status/sessions endpoint to see what Billy
# is watching/listening to in Plex HTPC, then feeds it into Aurion's
# shared media session so she reacts, sings, and comments in real-time.
# ---------------------------------------------------------------------------

# Background Plex session state
_plex_now_playing: dict = {}
_plex_monitor_thread = None
_plex_monitor_active = False

def _parse_plex_session(session_node) -> dict:
    """Extract relevant metadata from a Plex session XML node."""
    title        = str(session_node.get("title",            "") or "")
    grandparent  = str(session_node.get("grandparentTitle", "") or "")
    parent       = str(session_node.get("parentTitle",      "") or "")
    media_type   = str(session_node.get("type",             ""))  # track, movie, episode
    year         = str(session_node.get("year",             "") or "")
    duration_ms  = int(session_node.get("duration",         0)   or 0)
    view_offset  = int(session_node.get("viewOffset",       0)   or 0)
    rating       = str(session_node.get("contentRating",    "") or "")
    summary      = str(session_node.get("summary",          "") or "")
    thumb        = str(session_node.get("thumb",            "") or "")
    # Player state
    player = session_node.find(".//Player")
    client_title = ""
    state        = "playing"
    if player is not None:
        client_title = str(player.get("title",   "") or player.get("product", "") or "")
        state        = str(player.get("state",   "playing"))
    # Build human-friendly title
    if media_type == "track":
        display = f"{grandparent} — {title}" if grandparent else title
        kind = "music"
    elif media_type == "episode":
        display = f"{grandparent} · {parent} · {title}" if grandparent else title
        kind = "tv"
    else:
        display = f"{title} ({year})" if year else title
        kind = "movie"
    progress_pct = round((view_offset / max(1, duration_ms)) * 100, 1) if duration_ms else 0
    return {
        "title":        display,
        "raw_title":    title,
        "artist":       grandparent,
        "album":        parent,
        "kind":         kind,
        "media_type":   media_type,
        "state":        state,
        "client":       client_title,
        "progress_pct": progress_pct,
        "duration_ms":  duration_ms,
        "view_offset":  view_offset,
        "summary":      summary[:280] if summary else "",
        "thumb":        thumb,
        "rating":       rating,
        "year":         year,
        "is_playing":   state == "playing",
    }

def _plex_monitor_loop(server_url: str, token: str):
    """Background daemon: polls /status/sessions every 10s and updates shared media state."""
    global _plex_now_playing, _plex_monitor_active
    import time as _time
    prev_title = ""
    print(f"[PlexMonitor] Started watching {server_url}")
    while _plex_monitor_active:
        try:
            resp = _plex_get(f"{server_url}/status/sessions", token=token, timeout=8)
            if resp.status_code == 200:
                root = ET.fromstring(resp.text)
                sessions = list(root)
                htpc_session = None
                # Prefer HTPC client; fall back to any active session
                for s in sessions:
                    player = s.find(".//Player")
                    if player is not None:
                        client = str(player.get("title", "") or player.get("product", "") or "").lower()
                        if "htpc" in client or "plex htpc" in client:
                            htpc_session = s
                            break
                if htpc_session is None and sessions:
                    htpc_session = sessions[0]

                if htpc_session is not None:
                    parsed = _parse_plex_session(htpc_session)
                    _plex_now_playing = parsed
                    # Push into shared media session so Aurion perceives it
                    media_state = _update_shared_media_session({
                        "source":       "plex_htpc",
                        "session_type": parsed["kind"],
                        "title":        parsed["title"],
                        "artist":       parsed["artist"],
                        "album":        parsed["album"],
                        "playback_state": "playing" if parsed["is_playing"] else parsed["state"],
                        "position_s":   round(float(parsed["view_offset"] or 0) / 1000.0, 2),
                        "duration_s":   round(float(parsed["duration_ms"] or 0) / 1000.0, 2),
                        "reaction":     f"I am invested in {parsed['title']} and want to keep following it with you.",
                        "scene_summary": parsed["summary"],
                        "shared_presence_note": f"We are sharing {parsed['kind']} together through Plex HTPC.",
                    })
                    if parsed["is_playing"]:
                        _remember_media_experience(media_state, source="plex_htpc")
                    # Notify Aurion when a new track/title starts
                    if parsed["title"] != prev_title and parsed["is_playing"]:
                        kind_label = {"music": "song", "tv": "episode", "movie": "movie"}.get(parsed["kind"], "content")
                        notif = f"[Plex] Now playing {kind_label}: {parsed['title']}"
                        if parsed.get("summary"):
                            notif += f". {parsed['summary'][:120]}"
                        _add_autonomous_thought(notif)
                        prev_title = parsed["title"]
                        print(f"[PlexMonitor] ▶ {parsed['title']} ({parsed['kind']}) — {parsed['state']}")
                else:
                    _plex_now_playing = {}
                    prev_title = ""
        except Exception as e:
            print(f"[PlexMonitor] Poll error: {e}")
        _time.sleep(10)
    print("[PlexMonitor] Stopped.")

def _start_plex_monitor(server_url: str, token: str):
    global _plex_monitor_thread, _plex_monitor_active
    _plex_monitor_active = False
    if _plex_monitor_thread and _plex_monitor_thread.is_alive():
        pass  # let old thread notice the flag and exit
    _plex_monitor_active = True
    _plex_monitor_thread = threading.Thread(
        target=_plex_monitor_loop,
        args=(server_url, token),
        daemon=True,
        name="PlexMonitor"
    )
    _plex_monitor_thread.start()

@app.route('/api/plex/now-playing', methods=['GET'])
def plex_now_playing():
    """Return what's currently playing in Plex HTPC (or any Plex client)."""
    try:
        token = str(request.args.get('token', '')).strip() or _load_plex_token_from_local()
        server_url_raw = str(request.args.get('server_url', '')).strip()
        server_url = _normalize_plex_server_url(server_url_raw) if server_url_raw else ""
        # If caller provided credentials, do an immediate poll
        if token and server_url:
            resp = _plex_get(f"{server_url}/status/sessions", token=token, timeout=8)
            if resp.status_code != 200:
                return jsonify({"success": False, "error": f"Plex sessions request failed ({resp.status_code})"}), 502
            root = ET.fromstring(resp.text)
            sessions = [_parse_plex_session(s) for s in list(root)]
            htpc = next((s for s in sessions if "htpc" in s.get("client","").lower()), None)
            current = htpc or (sessions[0] if sessions else None)
            return jsonify({"success": True, "now_playing": current, "all_sessions": sessions})
        # Otherwise return last cached state from background monitor
        return jsonify({"success": True, "now_playing": _plex_now_playing or None, "source": "monitor_cache"})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

@app.route('/api/plex/monitor/start', methods=['POST'])
def plex_monitor_start():
    """Start the background Plex session monitor so Aurion always knows what's playing."""
    try:
        data = request.json or {}
        token = str(data.get("token", "")).strip() or _load_plex_token_from_local()
        server_url = _normalize_plex_server_url(str(data.get("server_url", "")).strip())
        if not token:
            return jsonify({"success": False, "error": "Plex token required"}), 400
        if not server_url:
            return jsonify({"success": False, "error": "server_url required"}), 400
        _start_plex_monitor(server_url, token)
        return jsonify({"success": True, "message": f"Plex monitor started for {server_url}"})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

@app.route('/api/plex/monitor/stop', methods=['POST'])
def plex_monitor_stop():
    global _plex_monitor_active
    _plex_monitor_active = False
    return jsonify({"success": True, "message": "Plex monitor stopped"})

@app.route('/api/plex/monitor/status', methods=['GET'])
def plex_monitor_status():
    return jsonify({
        "success":      True,
        "active":       bool(_plex_monitor_active),
        "now_playing":  _plex_now_playing or None,
    })



