@app.route('/api/aurion/exec', methods=['POST'])
def aurion_exec_route():
    """
    Execute Python code Aurion generated (base64-encoded).
    Body: {code_b64: str, description: str}
    """
    if not _ALLOW_CODE_EXEC:
        logger.warning("Blocked /api/aurion/exec: code exec disabled (remote_addr=%s)", request.remote_addr)
        return jsonify({"success": False, "error": "Code execution is disabled. Set AURION_ENABLE_CODE_EXEC=1 to opt in."}), 403
    guard = _require_local_privileged_access()
    if guard is not None:
        return guard
    try:
        data    = request.json or {}
        code_b64 = str(data.get("code_b64", "")).strip()
        desc     = str(data.get("description", "")).strip()
        if not code_b64:
            return jsonify({"success": False, "error": "code_b64 is required"}), 400
        result = _aurion_exec_code(code_b64, desc)
        return jsonify({"success": result.get("success", False), "result": result})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

