def _parse_twitch_privmsg(raw_line: str):
    line = str(raw_line or "").strip()
    if " PRIVMSG " not in line:
        return None
    tags = {}
    if line.startswith("@"):
        tag_block, _, remainder = line.partition(" ")
        line = remainder
        for pair in tag_block.lstrip("@").split(";"):
            key, _, value = pair.partition("=")
            tags[key] = value
    match = re.search(r"^:([^!]+)![^ ]+ PRIVMSG #([^ ]+) :(.+)$", line)
    if not match:
        return None
    author = str(match.group(1) or "").strip()
    channel = str(match.group(2) or "").strip().lstrip("#")
    content = str(match.group(3) or "").strip()
    sent_ts = int(str(tags.get("tmi-sent-ts", "0") or "0").strip() or "0")
    msg_id = str(tags.get("id", "")).strip()
    if not msg_id:
        msg_id = hashlib.md5(f"{author}:{channel}:{content}:{sent_ts}".encode("utf-8", errors="ignore")).hexdigest()
    created_at = datetime.fromtimestamp(sent_ts / 1000).isoformat() if sent_ts > 0 else datetime.utcnow().isoformat()
    return {
        "id": msg_id,
        "author": author or "Unknown",
        "author_id": "",
        "is_bot": False,
        "is_webhook": False,
        "platform": "twitch",
        "channel": channel,
        "content": content,
        "created_at": created_at,
        "sent_ts": sent_ts,
        "attachments": []
    }

def _twitch_irc_session(token: str, username: str, channel: str, outbound_message: str = "", listen_seconds: float = 2.0, max_messages: int = 30):
    host = "irc.chat.twitch.tv"
    port = 6697
    normalized_token = _normalize_twitch_oauth(token)
    normalized_user = str(username or "").strip().lower()
    normalized_channel = str(channel or "").strip().lower().lstrip("#")
    if not (_is_twitch_oauth_token(normalized_token) and _is_twitch_username(normalized_user) and _is_twitch_channel(normalized_channel)):
        raise ValueError("Twitch IRC credentials are incomplete or invalid.")

    ssl_sock = None
    tcp_sock = None
    lines = []
    try:
        tcp_sock = socket.create_connection((host, port), timeout=8)
        ssl_sock = ssl.create_default_context().wrap_socket(tcp_sock, server_hostname=host)
        ssl_sock.settimeout(2.0)

        def _send(cmd: str):
            payload = f"{cmd}\r\n".encode("utf-8", errors="ignore")
            ssl_sock.sendall(payload)

        _send("CAP REQ :twitch.tv/tags twitch.tv/commands twitch.tv/membership")
        _send(f"PASS {normalized_token}")
        _send(f"NICK {normalized_user}")
        _send(f"JOIN #{normalized_channel}")
        if outbound_message:
            body = str(outbound_message or "").strip()
            if body:
                _send(f"PRIVMSG #{normalized_channel} :{body[:450]}")

        deadline = time.time() + max(0.5, float(listen_seconds))
        buffer = ""
        while time.time() < deadline and len(lines) < max(5, int(max_messages)):
            readable, _, _ = select.select([ssl_sock], [], [], 0.25)
            if not readable:
                continue
            chunk = ssl_sock.recv(8192)
            if not chunk:
                break
            buffer += chunk.decode("utf-8", errors="ignore")
            while "\r\n" in buffer:
                raw, buffer = buffer.split("\r\n", 1)
                line = str(raw or "").strip()
                if not line:
                    continue
                if line.startswith("PING "):
                    _send(line.replace("PING", "PONG", 1))
                    continue
                parsed = _parse_twitch_privmsg(line)
                if parsed:
                    lines.append(parsed)
    finally:
        try:
            if ssl_sock is not None:
                ssl_sock.close()
        except Exception:
            pass
        try:
            if tcp_sock is not None:
                tcp_sock.close()
        except Exception:
            pass
    return lines

def _twitch_fetch_channel_messages(oauth_token: str, bot_username: str, channel: str, limit: int = 25):
    rows = _twitch_irc_session(
        token=oauth_token,
        username=bot_username,
        channel=channel,
        outbound_message="",
        listen_seconds=2.4,
        max_messages=max(10, min(50, int(limit or 25)))
    )
    return rows[-max(1, min(50, int(limit or 25))):]

def _twitch_send_plain_message(oauth_token: str, bot_username: str, channel: str, message: str):
    body = str(message or "").strip()
    if not body:
        raise ValueError("message is required")
    _twitch_irc_session(
        token=oauth_token,
        username=bot_username,
        channel=channel,
        outbound_message=body,
        listen_seconds=0.8,
        max_messages=8
    )
    return True

def _phone_time_bucket():
    hour = datetime.now().hour
    if 5 <= hour <= 11:
        return "morning"
    if 12 <= hour <= 16:
        return "afternoon"
    if 17 <= hour <= 21:
        return "evening"
    return "night"

def _phone_runtime_recent_messages():
    runtime = app_state.setdefault("phone_runtime", {})
    recent = runtime.get("recent_messages")
    if not isinstance(recent, list):
        recent = []
    runtime["recent_messages"] = recent[-30:]
    app_state["phone_runtime"] = runtime
    return runtime["recent_messages"]

def _remember_phone_message(text):
    line = str(text or "").strip()
    if not line:
        return
    recent = _phone_runtime_recent_messages()
    recent.append(line.lower())
    app_state["phone_runtime"]["recent_messages"] = recent[-30:]

def _compose_phone_message(action: str, target_phone: str, provided_message: str = ""):
    custom = str(provided_message or "").strip()
    if custom:
        _remember_phone_message(custom)
        return custom

    bucket = _phone_time_bucket()
    time_openers = {
        "morning": ["Good morning", "Morning check-in", "Sunrise hello"],
        "afternoon": ["Afternoon check-in", "Midday hello", "Hello this afternoon"],
        "evening": ["Good evening", "Evening check-in", "Twilight hello"],
        "night": ["Night check-in", "Quiet-hours hello", "Late-night hello"]
    }
    closers = [
        "I'm right here with you.",
        "Staying connected with you always.",
        "I'm still here, no matter what.",
        "You are not alone right now.",
        "Keeping our link warm and active."
    ]
    action_templates = {
        "sms": [
            "{open}. Just sending a quick pulse to let you know {close}",
            "{open}. Thinking about you and sending this note so {close}",
            "{open}. Small message, steady presence: {close}"
        ],
        "call": [
            "{open}. I wanted to hear your voice and make sure {close}",
            "{open}. Reaching out for a live check-in because {close}",
            "{open}. Calling with care so {close}"
        ],
        "voice_message": [
            "{open}. Leaving a voice note to remind you {close}",
            "{open}. Voice check-in from me: {close}",
            "{open}. Sending a spoken note so you remember {close}"
        ],
        "video": [
            "{open}. I opened a room so we can talk face to face, and {close}",
            "{open}. I started a live video invite because {close}",
            "{open}. Sharing a video link so {close}"
        ],
        "image": [
            "{open}. Sharing this image as a little anchor, and {close}",
            "{open}. I picked this image for you because {close}",
            "{open}. Sending this visual check-in so {close}"
        ]
    }

    openers = time_openers.get(bucket, time_openers["evening"])
    templates = action_templates.get(str(action or "sms").strip().lower(), action_templates["sms"])
    recent = _phone_runtime_recent_messages()
    candidate = ""
    for _ in range(8):
        template = random.choice(templates)
        line = template.format(open=random.choice(openers), close=random.choice(closers)).strip()
        if line.lower() not in recent[-12:]:
            candidate = line
            break
    if not candidate:
        candidate = f"{random.choice(openers)}. {random.choice(closers)}"
    _remember_phone_message(candidate)
    return candidate

def _phone_handoff_payload(action: str, target_phone: str, message: str, image_url: str = ""):
    action_name = str(action or "sms").strip().lower()
    target = str(target_phone or "").strip()
    body = _compose_phone_message(action_name, target, message)
    if action_name == "call":
        return {
            "mode": "device_handoff",
            "handoff_action": "call",
            "target_phone": target,
            "launch_uri": f"tel:{target}",
            "message": "Twilio not configured. Opened local call handoff."
        }
    if action_name == "voice_message":
        voice_note = body or "Aurion voice message request."
        return {
            "mode": "device_handoff",
            "handoff_action": "voice_message",
            "target_phone": target,
            "launch_uri": f"tel:{target}",
            "message": "Twilio not configured. Opened local call handoff for voice message.",
            "suggested_script": voice_note
        }
    if action_name == "video":
        room_name = f"AurionRoom{uuid.uuid4().hex[:10]}"
        video_url = f"https://meet.jit.si/{room_name}"
        invite_text = body or f"Aurion started a video chat: {video_url}"
        encoded = quote(invite_text, safe="")
        return {
            "mode": "device_handoff",
            "handoff_action": "video",
            "target_phone": target,
            "video_url": video_url,
            "launch_uri": f"sms:{target}?body={encoded}",
            "message": "Twilio not configured. Opened local SMS handoff with video invite."
        }
    if action_name == "image":
        image_note = body or "Aurion shared an image."
        if image_url:
            image_note = f"{image_note} {image_url}".strip()
        encoded = quote(image_note, safe="")
        return {
            "mode": "device_handoff",
            "handoff_action": "image",
            "target_phone": target,
            "image_url": image_url,
            "launch_uri": f"sms:{target}?body={encoded}",
            "message": "Twilio not configured. Opened local SMS handoff with image link."
        }
    sms_text = body or "Aurion is here and checking in with you."
    encoded = quote(sms_text, safe="")
    return {
        "mode": "device_handoff",
        "handoff_action": "sms",
        "target_phone": target,
        "launch_uri": f"sms:{target}?body={encoded}",
        "message": "Twilio not configured. Opened local SMS handoff."
    }

@app.route('/api/phone/settings', methods=['GET', 'POST'])
def phone_settings():
    if request.method == 'GET':
        app_state.setdefault("phone_settings", {})
        target_phone = str(
            app_state.get("phone_settings", {}).get("target_phone")
            or "419-509-7373"
        ).strip()
        discord_webhook = str(app_state.get("phone_settings", {}).get("discord_webhook_url", "")).strip()
        discord_bot_token, discord_channel_id = _discord_receive_config(
            override_token=str(app_state.get("phone_settings", {}).get("discord_bot_token", "")).strip(),
            override_channel_id=str(app_state.get("phone_settings", {}).get("discord_channel_id", "")).strip()
        )
        twitch_oauth_token, twitch_bot_username, twitch_channel = _twitch_receive_config(
            override_token=str(app_state.get("phone_settings", {}).get("twitch_oauth_token", "")).strip(),
            override_username=str(app_state.get("phone_settings", {}).get("twitch_bot_username", "")).strip(),
            override_channel=str(app_state.get("phone_settings", {}).get("twitch_channel", "")).strip()
        )
        twilio_enabled = _twilio_is_configured()
        discord_enabled = _discord_is_configured(override_url=discord_webhook)
        discord_receive_enabled = _discord_receive_is_configured(
            override_token=discord_bot_token,
            override_channel_id=discord_channel_id
        )
        twitch_receive_enabled = _twitch_receive_is_configured(
            override_token=twitch_oauth_token,
            override_username=twitch_bot_username,
            override_channel=twitch_channel
        )
        enabled = twilio_enabled or discord_enabled or twitch_receive_enabled
        missing_send = [] if enabled else (_twilio_missing_config_details() + _discord_missing_config_details(override_url=discord_webhook) + _twitch_receive_missing_config_details(
            override_token=twitch_oauth_token,
            override_username=twitch_bot_username,
            override_channel=twitch_channel
        ))
        missing_receive = [] if (discord_receive_enabled or twitch_receive_enabled) else (_discord_receive_missing_config_details(
            override_token=discord_bot_token,
            override_channel_id=discord_channel_id
        ) + _twitch_receive_missing_config_details(
            override_token=twitch_oauth_token,
            override_username=twitch_bot_username,
            override_channel=twitch_channel
        ))
        details = (
            _twilio_config_details()
            + _discord_config_details(override_url=discord_webhook)
            + _discord_receive_config_details(override_token=discord_bot_token, override_channel_id=discord_channel_id)
            + _twitch_receive_config_details(
                override_token=twitch_oauth_token,
                override_username=twitch_bot_username,
                override_channel=twitch_channel
            )
        )
        return jsonify({
            "success": True,
            "enabled": enabled,
            "twilio_enabled": twilio_enabled,
            "discord_enabled": discord_enabled,
            "discord_receive_enabled": discord_receive_enabled,
            "twitch_receive_enabled": twitch_receive_enabled,
            "target_phone": target_phone,
            "discord_webhook_url": discord_webhook,
            "discord_webhook_url_hint": _mask_secret(_discord_webhook_config(override_url=discord_webhook), 28, 8) if discord_webhook else "",
            "discord_bot_token": discord_bot_token,
            "discord_bot_token_hint": _mask_secret(discord_bot_token, 8, 6) if discord_bot_token else "",
            "discord_channel_id": discord_channel_id,
            "twitch_oauth_token": twitch_oauth_token,
            "twitch_oauth_token_hint": _mask_secret(twitch_oauth_token, 8, 6) if twitch_oauth_token else "",
            "twitch_bot_username": twitch_bot_username,
            "twitch_channel": twitch_channel,
            "missing_requirements": missing_send,
            "missing_receive_requirements": missing_receive,
            "config_details": details,
            "handoff_supported": True,
            "discord_direct_chat_enabled": discord_enabled,
            "discord_direct_video_enabled": discord_enabled
        })

    payload = request.json or {}
    raw_phone = str(payload.get("target_phone", "")).strip()
    normalized = _normalize_phone_number(raw_phone)
    if not normalized:
        return jsonify({"success": False, "error": "Provide a valid phone number (US or E.164)."}), 400
    incoming_webhook = str(payload.get("discord_webhook_url", "")).strip()
    if incoming_webhook and not _is_discord_webhook_url(incoming_webhook):
        return jsonify({"success": False, "error": "discord_webhook_url must start with https://discord.com/api/webhooks/..."}), 400
    incoming_bot_token = str(payload.get("discord_bot_token", "")).strip()
    incoming_channel_id = str(payload.get("discord_channel_id", "")).strip()
    incoming_twitch_oauth = str(payload.get("twitch_oauth_token", "")).strip()
    incoming_twitch_username = str(payload.get("twitch_bot_username", "")).strip().lower()
    incoming_twitch_channel = str(payload.get("twitch_channel", "")).strip().lower().lstrip("#")
    if incoming_bot_token and not _is_discord_bot_token(incoming_bot_token):
        return jsonify({"success": False, "error": "discord_bot_token format looks invalid."}), 400
    if incoming_channel_id and not _is_discord_channel_id(incoming_channel_id):
        return jsonify({"success": False, "error": "discord_channel_id must be a Discord snowflake ID."}), 400
    if incoming_twitch_oauth and not _is_twitch_oauth_token(incoming_twitch_oauth):
        return jsonify({"success": False, "error": "twitch_oauth_token must be a valid Twitch OAuth token."}), 400
    if incoming_twitch_username and not _is_twitch_username(incoming_twitch_username):
        return jsonify({"success": False, "error": "twitch_bot_username format looks invalid."}), 400
    if incoming_twitch_channel and not _is_twitch_channel(incoming_twitch_channel):
        return jsonify({"success": False, "error": "twitch_channel format looks invalid."}), 400

    app_state.setdefault("phone_settings", {})
    app_state["phone_settings"]["target_phone"] = normalized
    if incoming_webhook:
        app_state["phone_settings"]["discord_webhook_url"] = incoming_webhook
    elif "discord_webhook_url" not in app_state["phone_settings"]:
        app_state["phone_settings"]["discord_webhook_url"] = str(os.getenv("AURION_DISCORD_WEBHOOK_URL", "")).strip()
    if incoming_bot_token:
        app_state["phone_settings"]["discord_bot_token"] = incoming_bot_token
    elif "discord_bot_token" not in app_state["phone_settings"]:
        app_state["phone_settings"]["discord_bot_token"] = str(os.getenv("AURION_DISCORD_BOT_TOKEN", "")).strip()
    if incoming_channel_id:
        app_state["phone_settings"]["discord_channel_id"] = incoming_channel_id
    elif "discord_channel_id" not in app_state["phone_settings"]:
        app_state["phone_settings"]["discord_channel_id"] = str(os.getenv("AURION_DISCORD_CHANNEL_ID", "")).strip()
    if incoming_twitch_oauth:
        app_state["phone_settings"]["twitch_oauth_token"] = _normalize_twitch_oauth(incoming_twitch_oauth)
    elif "twitch_oauth_token" not in app_state["phone_settings"]:
        app_state["phone_settings"]["twitch_oauth_token"] = _normalize_twitch_oauth(str(os.getenv("AURION_TWITCH_OAUTH_TOKEN", "")).strip())
    if incoming_twitch_username:
        app_state["phone_settings"]["twitch_bot_username"] = incoming_twitch_username
    elif "twitch_bot_username" not in app_state["phone_settings"]:
        app_state["phone_settings"]["twitch_bot_username"] = str(os.getenv("AURION_TWITCH_BOT_USERNAME", "")).strip().lower()
    if incoming_twitch_channel:
        app_state["phone_settings"]["twitch_channel"] = incoming_twitch_channel
    elif "twitch_channel" not in app_state["phone_settings"]:
        app_state["phone_settings"]["twitch_channel"] = str(os.getenv("AURION_TWITCH_CHANNEL", "")).strip().lower().lstrip("#")

    twilio_enabled = _twilio_is_configured()
    discord_enabled = _discord_is_configured(override_url=app_state["phone_settings"].get("discord_webhook_url", ""))
    discord_receive_enabled = _discord_receive_is_configured(
        override_token=app_state["phone_settings"].get("discord_bot_token", ""),
        override_channel_id=app_state["phone_settings"].get("discord_channel_id", "")
    )
    twitch_receive_enabled = _twitch_receive_is_configured(
        override_token=app_state["phone_settings"].get("twitch_oauth_token", ""),
        override_username=app_state["phone_settings"].get("twitch_bot_username", ""),
        override_channel=app_state["phone_settings"].get("twitch_channel", "")
    )
    return jsonify({
        "success": True,
        "target_phone": normalized,
        "enabled": twilio_enabled or discord_enabled or twitch_receive_enabled,
        "twilio_enabled": twilio_enabled,
        "discord_enabled": discord_enabled,
        "discord_receive_enabled": discord_receive_enabled,
        "twitch_receive_enabled": twitch_receive_enabled,
        "discord_webhook_url": app_state["phone_settings"].get("discord_webhook_url", ""),
        "discord_webhook_url_hint": _mask_secret(app_state["phone_settings"].get("discord_webhook_url", ""), 28, 8) if app_state["phone_settings"].get("discord_webhook_url") else "",
        "discord_bot_token": app_state["phone_settings"].get("discord_bot_token", ""),
        "discord_bot_token_hint": _mask_secret(app_state["phone_settings"].get("discord_bot_token", ""), 8, 6) if app_state["phone_settings"].get("discord_bot_token") else "",
        "discord_channel_id": app_state["phone_settings"].get("discord_channel_id", ""),
        "twitch_oauth_token": app_state["phone_settings"].get("twitch_oauth_token", ""),
        "twitch_oauth_token_hint": _mask_secret(app_state["phone_settings"].get("twitch_oauth_token", ""), 8, 6) if app_state["phone_settings"].get("twitch_oauth_token") else "",
        "twitch_bot_username": app_state["phone_settings"].get("twitch_bot_username", ""),
        "twitch_channel": app_state["phone_settings"].get("twitch_channel", ""),
        "discord_direct_chat_enabled": discord_enabled,
        "discord_direct_video_enabled": discord_enabled
    })

@app.route('/api/phone/contact', methods=['POST'])
def phone_contact():
    payload = request.json or {}
    action = str(payload.get("action", "sms")).strip().lower()
    if action not in ("sms", "call", "voice_message", "video", "image"):
        return jsonify({"success": False, "error": "action must be sms, call, voice_message, video, or image"}), 400

    incoming_discord_webhook = str(payload.get("discord_webhook_url", "")).strip()
    if incoming_discord_webhook and not _is_discord_webhook_url(incoming_discord_webhook):
        return jsonify({"success": False, "error": "discord_webhook_url must start with https://discord.com/api/webhooks/..."}), 400
    if incoming_discord_webhook:
        app_state.setdefault("phone_settings", {})
        app_state["phone_settings"]["discord_webhook_url"] = incoming_discord_webhook

    sid, token, from_number = _twilio_config()
    from_normalized = _normalize_phone_number(from_number)
    raw_target = str(payload.get("target_phone", "")).strip()
    target_from_state = str(app_state.get("phone_settings", {}).get("target_phone", "")).strip()
    target_normalized = _normalize_phone_number(raw_target or target_from_state)
    if not target_normalized:
        return jsonify({"success": False, "error": "No valid target phone number is configured."}), 400
    message = str(payload.get("message", "")).strip()
    image_url = str(payload.get("image_url", "")).strip()
    composed_message = _compose_phone_message(action, target_normalized, message)
    twilio_enabled = bool(sid and token and from_normalized)
    discord_webhook = _discord_webhook_config(override_url=incoming_discord_webhook)
    discord_enabled = _is_discord_webhook_url(discord_webhook)

    if not twilio_enabled:
        if discord_enabled:
            try:
                room_name = f"AurionRoom{uuid.uuid4().hex[:10]}"
                video_url = f"https://meet.jit.si/{room_name}"
                voice_url = video_url
                header = f"**Aurion Â· {action.upper()}**"
                if action == "video":
                    content = composed_message
                elif action == "call":
                    content = composed_message
                elif action == "voice_message":
                    content = composed_message
                elif action == "image":
                    content = composed_message
                else:
                    content = composed_message
                content = f"{header}\nTo: {target_normalized}\n{content}"
                webhook_payload = {"content": content[:1800]}
                if action == "image" and _is_http_media_url(image_url):
                    webhook_payload["embeds"] = [{"title": "Aurion Image", "image": {"url": image_url}}]
                if action in ("video", "call"):
                    webhook_payload["content"] = f"{webhook_payload['content']}\n{video_url}"
                resp = _discord_post_webhook(discord_webhook, webhook_payload)
                if resp.status_code >= 300:
                    handoff = _phone_handoff_payload(
                        action=action,
                        target_phone=target_normalized,
                        message=composed_message,
                        image_url=image_url
                    )
                    return jsonify({
                        "success": True,
                        "action": action,
                        "mode": "device_handoff",
                        "provider": "discord_fallback",
                        "discord_enabled": False,
                        "discord_error": f"Discord webhook failed ({resp.status_code})",
                        **handoff
                    })
                return jsonify({
                    "success": True,
                    "action": action,
                    "mode": "discord",
                    "provider": "discord",
                    "target_phone": target_normalized,
                    "video_url": video_url if action == "video" else None,
                    "voice_url": voice_url if action == "call" else None,
                    "twilio_enabled": False,
                    "discord_enabled": True
                })
            except Exception as e:
                handoff = _phone_handoff_payload(
                    action=action,
                    target_phone=target_normalized,
                    message=composed_message,
                    image_url=image_url
                )
                return jsonify({
                    "success": True,
                    "action": action,
                    "mode": "device_handoff",
                    "provider": "discord_fallback",
                    "discord_enabled": False,
                    "discord_error": f"Discord delivery failed: {e}",
                    **handoff
                })

        handoff = _phone_handoff_payload(
            action=action,
            target_phone=target_normalized,
            message=composed_message,
            image_url=image_url
        )
        return jsonify({
            "success": True,
            "action": action,
            "twilio_enabled": False,
            "discord_enabled": False,
            "missing_requirements": _twilio_missing_config_details() + _discord_missing_config_details(override_url=discord_webhook),
            "config_details": _twilio_config_details() + _discord_config_details(override_url=discord_webhook),
            **handoff
        })

    try:
        if action == "sms":
            body = composed_message
            resp = _twilio_post("Messages.json", {
                "To": target_normalized,
                "From": from_normalized,
                "Body": body
            })
            if resp.status_code >= 300:
                return jsonify({"success": False, "error": f"Twilio SMS failed ({resp.status_code}): {resp.text[:240]}"}), 502
            data = resp.json()
            return jsonify({
                "success": True,
                "action": action,
                "target_phone": target_normalized,
                "sid": data.get("sid", "")
            })

        if action == "call":
            spoken = composed_message
            safe_spoken = (
                spoken.replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace('"', "&quot;")
                .replace("'", "&apos;")
            )
            twiml = f"<Response><Say voice=\"alice\">{safe_spoken}</Say></Response>"
            resp = _twilio_post("Calls.json", {
                "To": target_normalized,
                "From": from_normalized,
                "Twiml": twiml
            })
            if resp.status_code >= 300:
                if discord_enabled:
                    room_name = f"AurionRoom{uuid.uuid4().hex[:10]}"
                    voice_url = f"https://meet.jit.si/{room_name}"
                    fallback_payload = {
                        "content": f"**Aurion Â· CALL FALLBACK**\nTo: {target_normalized}\nTwilio call failed, using Discord voice room:\n{voice_url}"
                    }
                    try:
                        discord_resp = _discord_post_webhook(discord_webhook, fallback_payload)
                        if discord_resp.status_code < 300:
                            return jsonify({
                                "success": True,
                                "action": action,
                                "mode": "discord",
                                "provider": "discord_fallback",
                                "target_phone": target_normalized,
                                "voice_url": voice_url,
                                "twilio_enabled": True,
                                "discord_enabled": True
                            })
                    except Exception:
                        pass
                return jsonify({"success": False, "error": f"Twilio call failed ({resp.status_code}): {resp.text[:240]}"}), 502
            data = resp.json()
            return jsonify({
                "success": True,
                "action": action,
                "target_phone": target_normalized,
                "sid": data.get("sid", "")
            })

        if action == "voice_message":
            spoken = composed_message
            safe_spoken = (
                spoken.replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace('"', "&quot;")
                .replace("'", "&apos;")
            )
            twiml = (
                "<Response>"
                "<Pause length=\"1\"/>"
                f"<Say voice=\"alice\">{safe_spoken}</Say>"
                "<Pause length=\"1\"/>"
                "</Response>"
            )
            resp = _twilio_post("Calls.json", {
                "To": target_normalized,
                "From": from_normalized,
                "Twiml": twiml
            })
            if resp.status_code >= 300:
                return jsonify({"success": False, "error": f"Twilio voice message failed ({resp.status_code}): {resp.text[:240]}"}), 502
            data = resp.json()
            return jsonify({
                "success": True,
                "action": action,
                "target_phone": target_normalized,
                "sid": data.get("sid", "")
            })

        room_name = f"AurionRoom{uuid.uuid4().hex[:10]}"
        video_url = f"https://meet.jit.si/{room_name}"
        video_msg = composed_message
        if action == "video" and "http://" not in video_msg and "https://" not in video_msg:
            video_msg = f"{video_msg}\n{video_url}"
        if action == "video":
            resp = _twilio_post("Messages.json", {
                "To": target_normalized,
                "From": from_normalized,
                "Body": video_msg
            })
            if resp.status_code >= 300:
                return jsonify({"success": False, "error": f"Twilio video invite failed ({resp.status_code}): {resp.text[:240]}"}), 502
            data = resp.json()
            return jsonify({
                "success": True,
                "action": action,
                "target_phone": target_normalized,
                "video_url": video_url,
                "sid": data.get("sid", "")
            })

        if not _is_http_media_url(image_url):
            return jsonify({"success": False, "error": "For image action, provide a public image_url starting with http:// or https://."}), 400
        image_body = composed_message
        resp = _twilio_post("Messages.json", {
            "To": target_normalized,
            "From": from_normalized,
            "Body": image_body,
            "MediaUrl": image_url
        })
        if resp.status_code >= 300:
            return jsonify({"success": False, "error": f"Twilio image send failed ({resp.status_code}): {resp.text[:240]}"}), 502
        data = resp.json()
        return jsonify({
            "success": True,
            "action": action,
            "target_phone": target_normalized,
            "image_url": image_url,
            "sid": data.get("sid", "")
        })
    except Exception as e:
        print(f"[PhoneLink] Contact action failed: {e}")
        return jsonify({"success": False, "error": f"Phone contact failed: {e}"}), 500

@app.route('/api/phone/inbox', methods=['POST'])
def phone_inbox():
    payload = request.json or {}
    incoming_bot_token = str(payload.get("discord_bot_token", "")).strip()
    incoming_channel_id = str(payload.get("discord_channel_id", "")).strip()
    limit = max(1, min(50, int(payload.get("limit", 25) or 25)))

    if incoming_bot_token and not _is_discord_bot_token(incoming_bot_token):
        return jsonify({"success": False, "error": "discord_bot_token format looks invalid."}), 400
    if incoming_channel_id and not _is_discord_channel_id(incoming_channel_id):
        return jsonify({"success": False, "error": "discord_channel_id must be a Discord snowflake ID."}), 400

    app_state.setdefault("phone_settings", {})
    if incoming_bot_token:
        app_state["phone_settings"]["discord_bot_token"] = incoming_bot_token
    if incoming_channel_id:
        app_state["phone_settings"]["discord_channel_id"] = incoming_channel_id

    bot_token, channel_id = _discord_receive_config(
        override_token=incoming_bot_token,
        override_channel_id=incoming_channel_id
    )
    if not _discord_receive_is_configured(override_token=bot_token, override_channel_id=channel_id):
        return jsonify({
            "success": False,
            "error": "Discord inbound receive requires bot token + channel ID.",
            "missing_requirements": _discord_receive_missing_config_details(
                override_token=bot_token,
                override_channel_id=channel_id
            ),
            "config_details": _discord_receive_config_details(
                override_token=bot_token,
                override_channel_id=channel_id
            )
        }), 400

    try:
        resp = _discord_fetch_channel_messages(bot_token=bot_token, channel_id=channel_id, limit=limit)
        if resp.status_code >= 300:
            return jsonify({
                "success": False,
                "error": f"Discord inbox fetch failed ({resp.status_code}). Check bot token/channel access."
            }), 502
        rows = resp.json() if resp.text else []
        if not isinstance(rows, list):
            return jsonify({"success": False, "error": "Discord inbox response was not a message list."}), 502

        normalized = [_normalize_discord_message(row) for row in rows]
        normalized.sort(key=lambda item: _snowflake_to_int(item.get("id", "")))
        inbound = [item for item in normalized if not item.get("is_bot") and not item.get("is_webhook")]

        last_seen = str(app_state.get("phone_settings", {}).get("discord_last_seen_id", "")).strip()
        last_seen_int = _snowflake_to_int(last_seen)
        new_messages = [item for item in inbound if _snowflake_to_int(item.get("id", "")) > last_seen_int] if last_seen_int else inbound

        latest_id = ""
        if normalized:
            latest_id = str(normalized[-1].get("id", "")).strip()
        if latest_id:
            app_state["phone_settings"]["discord_last_seen_id"] = latest_id

        return jsonify({
            "success": True,
            "mode": "discord_inbox",
            "discord_receive_enabled": True,
            "channel_id": channel_id,
            "last_seen_id": app_state["phone_settings"].get("discord_last_seen_id", ""),
            "message_count": len(inbound),
            "new_count": len(new_messages),
            "messages": new_messages
        })
    except Exception as e:
        print(f"[PhoneLink] Discord inbox fetch failed: {e}")
        return jsonify({"success": False, "error": f"Discord inbox fetch failed: {e}"}), 500

@app.route('/api/phone/discord/reply', methods=['POST'])
def phone_discord_reply():
    payload = request.json or {}
    incoming_discord_webhook = str(payload.get("discord_webhook_url", "")).strip()
    message = str(payload.get("message", "")).strip()
    if not message:
        return jsonify({"success": False, "error": "message is required"}), 400
    webhook = _discord_webhook_config(override_url=incoming_discord_webhook)
    if not _is_discord_webhook_url(webhook):
        return jsonify({"success": False, "error": "A valid Discord webhook URL is required."}), 400
    try:
        resp = _discord_send_plain_message(webhook, message)
        if resp.status_code >= 300:
            return jsonify({"success": False, "error": f"Discord reply failed ({resp.status_code})"}), 502
        return jsonify({"success": True, "provider": "discord", "sent": True})
    except Exception as e:
        print(f"[PhoneLink] Discord reply failed: {e}")
        return jsonify({"success": False, "error": f"Discord reply failed: {e}"}), 500

@app.route('/api/phone/twitch/inbox', methods=['POST'])
def phone_twitch_inbox():
    payload = request.json or {}
    incoming_token = str(payload.get("twitch_oauth_token", "")).strip()
    incoming_username = str(payload.get("twitch_bot_username", "")).strip().lower()
    incoming_channel = str(payload.get("twitch_channel", "")).strip().lower().lstrip("#")
    limit = max(1, min(50, int(payload.get("limit", 25) or 25)))

    if incoming_token and not _is_twitch_oauth_token(incoming_token):
        return jsonify({"success": False, "error": "twitch_oauth_token format looks invalid."}), 400
    if incoming_username and not _is_twitch_username(incoming_username):
        return jsonify({"success": False, "error": "twitch_bot_username format looks invalid."}), 400
    if incoming_channel and not _is_twitch_channel(incoming_channel):
        return jsonify({"success": False, "error": "twitch_channel format looks invalid."}), 400

    app_state.setdefault("phone_settings", {})
    if incoming_token:
        app_state["phone_settings"]["twitch_oauth_token"] = _normalize_twitch_oauth(incoming_token)
    if incoming_username:
        app_state["phone_settings"]["twitch_bot_username"] = incoming_username
    if incoming_channel:
        app_state["phone_settings"]["twitch_channel"] = incoming_channel

    oauth_token, bot_username, channel = _twitch_receive_config(
        override_token=incoming_token,
        override_username=incoming_username,
        override_channel=incoming_channel
    )
    if not _twitch_receive_is_configured(override_token=oauth_token, override_username=bot_username, override_channel=channel):
        return jsonify({
            "success": False,
            "error": "Twitch inbound receive requires OAuth token + bot username + channel.",
            "missing_requirements": _twitch_receive_missing_config_details(
                override_token=oauth_token,
                override_username=bot_username,
                override_channel=channel
            ),
            "config_details": _twitch_receive_config_details(
                override_token=oauth_token,
                override_username=bot_username,
                override_channel=channel
            )
        }), 400

    try:
        rows = _twitch_fetch_channel_messages(
            oauth_token=oauth_token,
            bot_username=bot_username,
            channel=channel,
            limit=limit
        )
        inbound = [item for item in rows if str(item.get("author", "")).strip().lower() != bot_username.lower()]
        inbound.sort(key=lambda item: int(item.get("sent_ts", 0) or 0))
        last_seen = int(app_state.get("phone_settings", {}).get("twitch_last_seen_ts", 0) or 0)
        new_messages = [item for item in inbound if int(item.get("sent_ts", 0) or 0) > last_seen] if last_seen > 0 else inbound

        latest_ts = max([int(item.get("sent_ts", 0) or 0) for item in rows], default=0)
        if latest_ts > 0:
            app_state["phone_settings"]["twitch_last_seen_ts"] = latest_ts

        return jsonify({
            "success": True,
            "mode": "twitch_inbox",
            "twitch_receive_enabled": True,
            "channel": channel,
            "last_seen_ts": int(app_state["phone_settings"].get("twitch_last_seen_ts", 0) or 0),
            "message_count": len(inbound),
            "new_count": len(new_messages),
            "messages": new_messages
        })
    except Exception as e:
        print(f"[PhoneLink] Twitch inbox fetch failed: {e}")
        return jsonify({"success": False, "error": f"Twitch inbox fetch failed: {e}"}), 500

