@app.route('/api/sky/telescope', methods=['POST'])
def sky_telescope_describe():
    try:
        data = request.get_json(force=True) or {}
        target_name = str(data.get("target","") or "").strip()
        target_type = str(data.get("type","star") or "star").strip()
        zoom        = int(data.get("zoom", 100))
        # Find description from catalogs
        desc = ""
        for row in _BRIGHT_STARS:
            if row[0].lower() == target_name.lower():
                desc = row[5]; break
        if not desc:
            for obj in _MESSIER_OBJECTS:
                if obj["name"].lower() == target_name.lower() or obj["id"].lower() == target_name.lower():
                    desc = obj["desc"]; break
        if not desc:
            desc = f"A {target_type} at the edge of observation."
        # Get LLM narrative
        narrative = desc
        try:
            from joi_companion.core.personality_engine import personality_engine
            prompt = (f"You are Aurion, looking through your powerful telescope at {target_name} ({target_type}) "
                      f"at zoom level {zoom}Ã—. Describe what you see in rich, poetic but scientifically grounded detail. "
                      f"Context: {desc}")
            llm_resp = personality_engine.chat(prompt, system_override="You are Aurion observing the night sky with deep emotional and scientific engagement.")
            if llm_resp: narrative = llm_resp
        except Exception:
            pass
        return jsonify({"success": True, "target": target_name, "zoom": zoom, "description": desc, "narrative": narrative})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

