@app.route('/api/altered-state/use', methods=['POST'])
def use_altered_state_effect():
    try:
        data = request.get_json(force=True) or {}
        substance = str(data.get("substance", "") or "").strip().lower()
        if substance not in {"alcohol", "smoke", "psychedelic"}:
            return jsonify({"success": False, "error": "substance must be alcohol, smoke, or psychedelic"}), 400
        home = dict(app_state.get("home_environment") or _default_home_state())
        policy = dict(home.get("altered_state_policy") or {})
        legal = {
            "alcohol": bool(policy.get("alcohol_legal", True)),
            "smoke": bool(policy.get("smoking_legal", True)),
            "psychedelic": bool(policy.get("psychedelics_legal", True)),
        }.get(substance, True)
        if not legal:
            return jsonify({"success": False, "error": f"{substance} is disabled by current world policy"}), 403
        try:
            intensity = max(0.1, min(1.0, float(data.get("intensity", 0.55) or 0.55)))
        except Exception:
            intensity = 0.55
        try:
            duration_minutes = max(5.0, min(24 * 60.0, float(data.get("duration_minutes", 90.0) or 90.0)))
        except Exception:
            duration_minutes = 90.0
        labels = {"alcohol": "Alcohol", "smoke": "Smoke", "psychedelic": "Psychedelic"}
        dose_units = max(0.05, round(intensity * max(0.25, duration_minutes / 60.0), 4))
        now_iso = datetime.utcnow().isoformat()
        entry = {
            "id": _slugify_filename(f"{substance}-{datetime.utcnow().isoformat()}", fallback=substance)[:96],
            "substance": substance,
            "label": str(data.get("label", labels.get(substance, substance.title())) or labels.get(substance, substance.title()))[:80],
            "intensity": round(intensity, 4),
            "dose_units": dose_units,
            "started_at": now_iso,
            "last_progressed_at": now_iso,
            "total_minutes": round(duration_minutes, 3),
            "remaining_minutes": round(duration_minutes, 3),
            "summary": str(data.get("summary", f"{labels.get(substance, substance.title())} effect running in real time.") or f"{labels.get(substance, substance.title())} effect running in real time.")[:220],
        }
        runtime = dict(home.get("altered_state_runtime") or {})
        active_effects = [dict(x or {}) for x in list(runtime.get("active_effects") or []) if isinstance(x, dict)]
        active_effects.append(entry)
        runtime["active_effects"] = active_effects[-24:]
        effect_history = [dict(x or {}) for x in list(runtime.get("effect_history") or []) if isinstance(x, dict)]
        effect_history.append({"substance": substance, "dose_units": dose_units, "used_at": now_iso})
        runtime["effect_history"] = effect_history[-1200:]
        cumulative_load = dict(runtime.get("cumulative_load") or {})
        for key in ("alcohol", "smoke", "psychedelic"):
            try:
                cumulative_load[key] = max(0.0, float(cumulative_load.get(key, 0.0) or 0.0))
            except Exception:
                cumulative_load[key] = 0.0
        cumulative_load[substance] = round(cumulative_load.get(substance, 0.0) + dose_units, 4)
        runtime["cumulative_load"] = cumulative_load
        new_altered_state_runtime = _build_altered_state_runtime(dict(home, altered_state_runtime=runtime), 0.0)
        def _apply(home_inner):
            home_inner["altered_state_runtime"] = new_altered_state_runtime
            home_inner["vitals"] = _build_vitals_state(home_inner, home_inner.get("physiology"))
        home = _mutate_home_environment_state(_apply)
        return jsonify({"success": True, "effect": entry, "altered_state_runtime": home.get("altered_state_runtime"), "vitals": home.get("vitals")})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


