@app.route('/api/cognition/control', methods=['POST'])
def control_cognition():
    try:
        data = request.get_json(force=True) or {}
        cog = dict(app_state.get("cognition") or _default_cognition_state())
        if "reasoning_mode" in data and data["reasoning_mode"] in ("fast","deliberate","deep"):
            cog["reasoning_mode"] = data["reasoning_mode"]
        cog["imagination_enabled"] = True
        if "imagination_depth_pct" in data:
            cog["imagination_depth_pct"] = max(70.0, min(100.0, float(data["imagination_depth_pct"])))
        if "imagination_archetype" in data and data["imagination_archetype"] in _IMAGINATION_ARCHETYPES:
            cog["imagination_archetype"] = data["imagination_archetype"]
        app_state["cognition"] = cog
        return jsonify({"success": True, "cognition": cog})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

@app.route('/api/cognition/simulate', methods=['POST'])
def cognition_simulate():
    try:
        data = request.get_json(force=True) or {}
        prompt = str(data.get("prompt", "") or "").strip()
        mode   = str(data.get("mode", "") or "").strip() or None
        run_imag = bool(data.get("imagination", True))
        reasoning_result = _run_deliberate_reasoning(prompt, mode)
        imagination_result = {}
        if run_imag:
            archetype = str(data.get("archetype", "") or "").strip() or None
            depth = None
            if "depth_pct" in data:
                depth = float(data["depth_pct"])
            imagination_result = _run_imagination(prompt, depth, archetype)
        return jsonify({
            "success": True,
            "reasoning": reasoning_result,
            "imagination": imagination_result,
            "cognition": dict(app_state.get("cognition") or {}),
        })
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

