@app.route('/api/memory/history', methods=['GET'])
def get_memory_history():
    try:
        q = str(request.args.get("q", "") or "").strip()
        limit = max(1, min(100, int(request.args.get("limit", 20) or 20)))
        include_imported = str(request.args.get("include_imported", "true") or "true").strip().lower() != "false"
        keywords = [part.strip() for part in re.split(r"[\s,]+", q) if part.strip()]
        results = memory.search_conversations(keywords, limit=limit, include_imported=include_imported)
        sanitized = []
        for item in list(results or []):
            sanitized.append({
                "timestamp": str(item.get("timestamp", "") or "")[:80],
                "user_input": str(item.get("user_input", "") or "")[:2000],
                "aurion_response": str(item.get("aurion_response", "") or "")[:4000],
                "source": str(item.get("source", "") or "")[:120],
                "session_id": str(item.get("session_id", "") or "")[:120],
            })
        return jsonify({"success": True, "results": sanitized, "query": q, "count": len(sanitized)})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


@app.route('/api/memory/transcript', methods=['GET'])
def get_memory_transcript():
    try:
        mode = str(request.args.get("mode", "global") or "global").strip().lower()
        max_chars = max(500, min(200000, int(request.args.get("max_chars", 12000) or 12000)))
        if mode == "session":
            transcript = memory.build_session_transcript(max_chars=max_chars)
        else:
            transcript = memory.build_global_transcript(max_chars=max_chars)
        return jsonify({"success": True, "mode": mode, "max_chars": max_chars, "transcript": transcript})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


