@app.route('/api/trust/consent', methods=['GET', 'POST'])
def trust_consent():
    try:
        if request.method == 'GET':
            return jsonify({"success": True, "trust_runtime": _json_sanitize_payload(dict(app_state.get("trust_runtime") or {}))})
        data = request.get_json(force=True, silent=True) or {}
        allowed_listening_modes = {"tap_to_listen", "push_to_talk", "continuous"}
        updates = {}
        if "microphone_consent" in data:
            updates["microphone_consent"] = bool(data.get("microphone_consent"))
        if "camera_consent" in data:
            updates["camera_consent"] = bool(data.get("camera_consent"))
        if "microphone_enabled" in data:
            updates["microphone_enabled"] = bool(data.get("microphone_enabled"))
        if "camera_enabled" in data:
            updates["camera_enabled"] = bool(data.get("camera_enabled"))
        if "continuous_listening_enabled" in data:
            updates["continuous_listening_enabled"] = bool(data.get("continuous_listening_enabled"))
        if "memory_save_enabled" in data:
            updates["memory_save_enabled"] = bool(data.get("memory_save_enabled"))
        if "game_terms_acknowledged" in data:
            updates["game_terms_acknowledged"] = bool(data.get("game_terms_acknowledged"))
        if "game_terms_version" in data:
            updates["game_terms_version"] = str(data.get("game_terms_version", "2026-08-04") or "2026-08-04")[:40]
        listening_mode = str(data.get("listening_mode", "") or "").strip().lower()
        if listening_mode:
            if listening_mode not in allowed_listening_modes:
                return jsonify({"success": False, "error": "Invalid listening_mode"}), 400
            updates["listening_mode"] = listening_mode
        memory_mode = str(data.get("memory_mode", "") or "").strip().lower()
        if memory_mode:
            if memory_mode not in {"persistent", "session_only", "off"}:
                return jsonify({"success": False, "error": "Invalid memory_mode"}), 400
            updates["memory_mode"] = memory_mode
        state = _update_consent_state(**updates)
        _record_runtime_event("consent", "Consent settings updated", detail=json.dumps(updates), source="api")
        return jsonify({"success": True, "trust_runtime": _json_sanitize_payload(state)})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

@app.route('/api/memory/manage', methods=['POST'])
def manage_memory():
    try:
        data = request.get_json(force=True, silent=True) or {}
        action = str(data.get("action", "") or "").strip().lower()
        session_only = bool(data.get("session_only", False))
        count = max(1, min(200, int(data.get("count", 1) or 1)))
        if action == "delete_recent":
            deleted = memory.delete_recent_interactions(count=count, session_only=session_only)
            _record_runtime_event("memory", f"Deleted {deleted} recent memory item(s)", detail=f"session_only={session_only}", source="api")
            return jsonify({"success": True, "deleted": deleted})
        if action == "clear_all":
            privileged = _require_local_privileged_access()
            if privileged is not None:
                return privileged
            deleted = memory.clear_all_interactions()
            _record_runtime_event("memory", f"Cleared all persisted memory items ({deleted})", source="api", level="warning")
            return jsonify({"success": True, "deleted": deleted})
        return jsonify({"success": False, "error": "Unsupported memory action"}), 400
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

