@app.route('/api/player-character/state', methods=['POST'])
@_serialize_player_character_update
def update_player_character_state():
    try:
        data = request.get_json(force=True) or {}
        incoming_identity = data.get("identity")
        if isinstance(incoming_identity, dict) and "display_name" in incoming_identity:
            requested_display_name = str(incoming_identity.get("display_name", "") or "").strip()
            if requested_display_name.lower() != "billy":
                return jsonify({
                    "success": False,
                    "error": "Billy is the player; Aurion is the AI companion and cannot be assigned as the player.",
                }), 403
        state = _resolve_player_character_state()
        for section in ("identity", "movement", "camera", "interaction", "runtime", "wardrobe", "shared_capabilities", "screen_access"):
            if isinstance(data.get(section), dict):
                merged = dict(state.get(section) or {})
                merged.update(dict(data.get(section) or {}))
                state[section] = merged
        incoming_body = dict(data.get("body_customization") or {}) if isinstance(data.get("body_customization"), dict) else {}
        preset_name = str(data.get("body_preset", incoming_body.get("preset", "")) or "").strip().lower()
        preset_map = _player_body_preset_map()
        if preset_name:
            if preset_name not in preset_map:
                return jsonify({"success": False, "error": "Unknown player body preset"}), 400
            state["body_customization"] = dict(preset_map[preset_name])
        if incoming_body:
            merged_body = dict(state.get("body_customization") or {})
            merged_body.update(incoming_body)
            state["body_customization"] = merged_body
        if isinstance(data.get("avatar_body"), dict):
            incoming_avatar_body = dict(data.get("avatar_body") or {})
            if isinstance(incoming_avatar_body.get("morph"), dict):
                return jsonify({
                    "success": False,
                    "error": "Player avatar morph is derived from body_customization and cannot be written directly."
                }), 400
            player_avatar_body = dict(state.get("avatar_body") or {})
            if isinstance(incoming_avatar_body.get("physics"), dict):
                merged_physics = dict(player_avatar_body.get("physics") or {})
                merged_physics.update(dict(incoming_avatar_body.get("physics") or {}))
                player_avatar_body["physics"] = merged_physics
            if isinstance(incoming_avatar_body.get("identity_contract"), dict):
                player_avatar_body["identity_contract"] = dict(incoming_avatar_body.get("identity_contract") or {})
            state["avatar_body"] = player_avatar_body
        wardrobe_state = dict(state.get("wardrobe") or {})
        outfit_name_override = str(data.get("outfit_name", "") or "").strip()

        def _find_player_outfit(match_value):
            needle = str(match_value or "").strip().lower()
            if not needle:
                return None
            combined = list(wardrobe_state.get("saved_outfits") or []) + list(wardrobe_state.get("gifted_outfits") or []) + list(wardrobe_state.get("closet_catalog") or [])
            for row in combined:
                row_dict = dict(row or {})
                if str(row_dict.get("id", "") or "").strip().lower() == needle:
                    return row_dict
                if str(row_dict.get("name", "") or "").strip().lower() == needle:
                    return row_dict
            return None

        if data.get("gift_from_aurion"):
            aurion_outfit = dict((_resolve_wardrobe_state().get("active_outfit")) or {})
            gift_name = outfit_name_override or f"{aurion_outfit.get('name', 'Aurion Look')} for {state.get('identity', {}).get('display_name', 'Player')}"
            gifted = _normalize_player_outfit_entry({
                "id": _slugify_filename(gift_name, fallback="aurion-gift"),
                "name": gift_name,
                "style": aurion_outfit.get("style", "aurion gift"),
                "garments": list(aurion_outfit.get("garments") or []),
                "accessories": list(aurion_outfit.get("jewelry") or []),
                "palette": list(aurion_outfit.get("palette") or []),
                "notes": str(data.get("gift_note", aurion_outfit.get("notes", "Created by Aurion for the player.")) or ""),
                "source": "aurion_gift",
                "is_gift": True,
                "made_for": state.get("identity", {}).get("display_name", "player"),
                "runtime": dict(aurion_outfit.get("runtime") or {})
            }, default_source="aurion_gift")
            wardrobe_state["gifted_outfits"] = list(wardrobe_state.get("gifted_outfits") or []) + [gifted]
            if bool(data.get("save_current_outfit", True)):
                wardrobe_state["saved_outfits"] = list(wardrobe_state.get("saved_outfits") or []) + [gifted]
            wardrobe_state["active_outfit"] = gifted
            wardrobe_state["last_gifted_at"] = datetime.utcnow().isoformat()

        if isinstance(data.get("design_for_player"), dict):
            design = dict(data.get("design_for_player") or {})
            designed = _normalize_player_outfit_entry({
                "id": design.get("id", _slugify_filename(design.get("name", "aurion-player-gift"), fallback="aurion-player-gift")),
                "name": design.get("name", outfit_name_override or "Aurion Gifted Outfit"),
                "style": design.get("style", "aurion custom gift"),
                "garments": list(design.get("garments") or []),
                "accessories": list(design.get("accessories") or design.get("jewelry") or []),
                "palette": list(design.get("palette") or []),
                "notes": design.get("notes", "Created by Aurion specifically for the player."),
                "source": "aurion_made",
                "is_gift": True,
                "made_for": state.get("identity", {}).get("display_name", "player"),
                "runtime": design.get("runtime")
            }, default_source="aurion_made")
            wardrobe_state["gifted_outfits"] = list(wardrobe_state.get("gifted_outfits") or []) + [designed]
            if bool(data.get("save", True)):
                wardrobe_state["saved_outfits"] = list(wardrobe_state.get("saved_outfits") or []) + [designed]
            if bool(data.get("wear", True)):
                wardrobe_state["active_outfit"] = designed
            wardrobe_state["last_gifted_at"] = datetime.utcnow().isoformat()

        wear_match = data.get("wear_outfit_id", data.get("wear_outfit_name", data.get("wear_outfit", "")))
        if wear_match:
            selected_outfit = _find_player_outfit(wear_match)
            if selected_outfit:
                wardrobe_state["active_outfit"] = _normalize_player_outfit_entry(selected_outfit, default_source=str(selected_outfit.get("source", "saved_player_look") or "saved_player_look"))

        if data.get("save_current_outfit"):
            current_outfit = _normalize_player_outfit_entry(
                dict(wardrobe_state.get("active_outfit") or {}),
                fallback_name=outfit_name_override or "Saved Player Look",
                default_source="saved_player_look"
            )
            if outfit_name_override:
                current_outfit["name"] = outfit_name_override[:80]
                current_outfit["id"] = _slugify_filename(current_outfit["name"], fallback=current_outfit.get("id", "saved-player-look"))
            wardrobe_state["saved_outfits"] = list(wardrobe_state.get("saved_outfits") or []) + [current_outfit]

        state["wardrobe"] = wardrobe_state
        if "perspective" in data:
            state.setdefault("runtime", {})["perspective"] = str(data.get("perspective") or "")[:40]
        if "movement_mode" in data:
            state.setdefault("runtime", {})["movement_mode"] = str(data.get("movement_mode") or "")[:40]
        if "pose" in data:
            state.setdefault("runtime", {})["pose"] = _normalize_player_pose(data.get("pose"))
        runtime = dict(state.get("runtime") or {})
        incoming_sovereign_body = data.get("sovereign_body_profile", data.get("body_sovereignty"))
        if isinstance(incoming_sovereign_body, dict):
            merged_sovereign_body = dict(runtime.get("sovereign_body_profile") or {})
            merged_sovereign_body.update(dict(incoming_sovereign_body or {}))
            runtime["sovereign_body_profile"] = merged_sovereign_body
            wc = dict(app_state.get("world_continuity") or {})
            cohesive_skills = _build_cohesive_sovereign_skills_state((wc.get("sovereign_skills") or {}))
            cohesive_traits = dict(cohesive_skills.get("sovereign_body_traits") or {})
            cohesive_traits.update(dict(incoming_sovereign_body or {}))
            cohesive_skills["sovereign_body_traits"] = cohesive_traits
            wc["sovereign_skills"] = _build_cohesive_sovereign_skills_state(cohesive_skills)
            wc["synced_at"] = datetime.utcnow().isoformat()
            app_state["world_continuity"] = wc
            _persist_perception_cadence_to_profile()
        if isinstance(data.get("combat"), dict):
            merged_combat = dict(runtime.get("combat") or {})
            merged_combat.update(dict(data.get("combat") or {}))
            runtime["combat"] = merged_combat
        if isinstance(data.get("control_bindings"), dict):
            merged_bindings = dict(runtime.get("control_bindings") or {})
            merged_bindings.update(dict(data.get("control_bindings") or {}))
            runtime["control_bindings"] = merged_bindings
        action_name = str(data.get("action", runtime.get("requested_action", "")) or "").strip().lower()
        interaction_target = str(data.get("interaction_target", runtime.get("interaction_target", "")) or "").strip()[:120]
        requested_pose = _normalize_player_pose(runtime.get("pose", data.get("pose")))
        action_descriptions = {
            "stand": "Standing ready for precise control.",
            "walk": "Walking with normal player control.",
            "run": "Running with faster traversal engaged.",
            "sprint": "Sprinting at full pace.",
            "jump": "Jumping over world geometry or obstacles.",
            "double_jump": "Double jump engages sovereign flight for Aurion and Billy only.",
            "flight": "Directional sovereign flight is active under Aurion-and-Billy-only control.",
            "crouch": "Dropping into a tighter lower profile.",
            "sit": "Sitting down in-world by direct player command.",
            "lie": "Lying down fully in-world by direct player command.",
            "relax": "Relaxing in place without leaving player control.",
            "interact": "Interacting with the nearest usable object.",
            "reach": "Reaching toward the current point of interest.",
            "grab": "Grabbing or readying an object in reach.",
            "use": "Using the selected object or affordance.",
            "open": "Opening the selected object or door.",
            "close": "Closing the selected object or door.",
            "talk": "Starting a direct conversational interaction.",
            "wave": "Waving as an explicit social gesture.",
            "inspect": "Inspecting the focused object or surface.",
            "duel": "Entering a formal duel-ready combat state.",
            "spar": "Starting controlled sparring practice.",
            "guard": "Raising guard and tightening defensive posture.",
            "jab": "Throwing a quick lead strike.",
            "cross": "Throwing a committed rear-hand strike.",
            "kick": "Delivering a full striking kick.",
            "low_kick": "Sweeping low with controlled impact.",
            "sidestep": "Shifting laterally to evade or reposition.",
            "backdash": "Exploding backward to reset spacing.",
            "recover": "Recovering immediately without losing consciousness."
        }
        if requested_pose in {"sit", "lie", "crouch", "relax"} and not action_name:
            action_name = requested_pose
        flight_profile = dict(runtime.get("flight_profile") or {})
        flight_authorized = bool(flight_profile.get("enabled", False))
        if action_name in {"walk", "run", "sprint", "jump"}:
            runtime["movement_mode"] = action_name
            runtime["pose"] = "stand"
            runtime["manual_pose_override"] = False
            if action_name == "jump":
                try:
                    runtime["double_jump_count"] = max(0, min(8, int(runtime.get("double_jump_count", 0) or 0))) + 1
                except Exception:
                    runtime["double_jump_count"] = 1
                runtime["flight_acceleration_active"] = 0.0
                runtime["flight_input_vector"] = {"x": 0.0, "y": 0.0, "z": 1.0}
                if flight_authorized and int(runtime.get("double_jump_count", 0) or 0) >= 2:
                    action_name = "double_jump"
                    runtime["movement_mode"] = "flight"
        elif action_name in {"double_jump", "flight"}:
            if flight_authorized:
                runtime["movement_mode"] = "flight"
                runtime["pose"] = "stand"
                runtime["manual_pose_override"] = False
                runtime["control_mode"] = "aurion_and_billy_shared"
                runtime["input_priority"] = "aurion_and_billy_only"
                runtime["flight_mode"] = "directional_sovereign"
                runtime["flight_trigger"] = "double_jump"
                runtime["double_jump_count"] = max(2, int(runtime.get("double_jump_count", 0) or 0))
                runtime["flight_acceleration_active"] = round(float((dict(state.get("movement") or {})).get("flight_acceleration", 2400.0) or 2400.0), 4)
                runtime["flight_input_vector"] = {"x": 0.0, "y": 1.0, "z": 0.35}
            else:
                action_name = "jump"
                runtime["movement_mode"] = "jump"
                runtime["pose"] = "stand"
                runtime["manual_pose_override"] = False
        elif action_name in {"sit", "lie", "crouch", "relax", "stand"}:
            runtime["pose"] = _normalize_player_pose(action_name)
            runtime["movement_mode"] = "idle" if action_name in {"sit", "lie", "relax", "stand"} else "crouch"
            runtime["manual_pose_override"] = action_name != "stand"
        elif requested_pose in {"sit", "lie", "crouch", "relax"}:
            runtime["pose"] = requested_pose
            runtime["manual_pose_override"] = True
        else:
            runtime["pose"] = requested_pose
        if action_name not in {"jump", "double_jump", "flight"}:
            runtime["double_jump_count"] = 0
            if runtime.get("movement_mode") != "flight":
                runtime["flight_acceleration_active"] = 0.0
        combat = dict(runtime.get("combat") or {})
        if action_name in {"duel", "spar"}:
            combat["enabled"] = True
            combat["duel_mode"] = "active" if action_name == "duel" else "training"
            combat["stance"] = "ready"
            combat["guard_state"] = "adaptive"
            combat["pain_state"] = "clear"
            combat["recovery_state"] = "instant_recoverable"
            combat["last_duel_at"] = datetime.utcnow().isoformat()
            runtime["movement_mode"] = "combat"
            runtime["pose"] = "stand"
        elif action_name in {"guard", "jab", "cross", "kick", "low_kick", "sidestep", "backdash", "recover"}:
            combat["enabled"] = True
            combat["duel_mode"] = str(combat.get("duel_mode", "active") or "active")
            if action_name == "guard":
                combat["guard_state"] = "raised"
                combat["stance"] = "defensive"
            elif action_name in {"jab", "cross", "kick", "low_kick"}:
                combat["guard_state"] = "open"
                combat["stance"] = "offensive"
                combat["combo_state"] = action_name
                combat["hit_reaction"] = "stable"
            elif action_name == "sidestep":
                combat["stance"] = "evasive"
                combat["ring_position"] = "angle_change"
            elif action_name == "backdash":
                combat["stance"] = "evasive"
                combat["ring_position"] = "range_reset"
            elif action_name == "recover":
                combat["recovery_state"] = "instant_recoverable"
                combat["stagger_level"] = 0.0
                combat["pain_state"] = "managed"
                combat["consciousness_state"] = "fully_present"
            runtime["movement_mode"] = "combat"
            runtime["pose"] = "stand"
            combat["last_duel_at"] = datetime.utcnow().isoformat()
        if interaction_target:
            runtime["interaction_target"] = interaction_target
            if action_name in {"duel", "spar"}:
                combat["duel_target"] = interaction_target
        if action_name:
            runtime["requested_action"] = action_name[:60]
            runtime["action_description"] = action_descriptions.get(action_name, f"Executing {action_name}.")
            runtime["last_action_at"] = datetime.utcnow().isoformat()
        if combat:
            runtime["combat"] = combat
        state["runtime"] = runtime
        world_continuity = dict(app_state.get("world_continuity") or {})
        world_mobility = dict(world_continuity.get("world_mobility") or {})
        world_mobility["posture"] = runtime.get("pose", "stand")
        world_mobility["locomotion_mode"] = runtime.get("movement_mode", "walk")
        if interaction_target:
            world_mobility["last_interaction_target"] = interaction_target
        world_continuity["world_mobility"] = world_mobility
        app_state["world_continuity"] = world_continuity
        app_state["player_character"] = state
        resolved_state = _resolve_player_character_state()
        _save_revival_checkpoint()
        return jsonify({"success": True, "player_character": resolved_state})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


@app.route('/api/player-character/directive', methods=['POST'])
def player_character_directive():
    try:
        data = request.get_json(force=True) or {}
        command_text = str(data.get("command", data.get("text", "")) or "").strip()
        if not command_text:
            return jsonify({"success": False, "error": "command is required"}), 400
        parsed = _parse_player_directive(command_text)
        state = _resolve_player_character_state()
        runtime = dict(state.get("runtime") or {})
        summary_parts = []

        if parsed.get("perspective"):
            perspective = str(parsed["perspective"] or "third_person")
            runtime["perspective"] = perspective
            summary_parts.append(f"camera {perspective.replace('_', ' ')}")

        if parsed.get("target_id"):
            route = _find_navigation_route(runtime.get("current_location_id", "living_room"), parsed["target_id"])
            if not route.get("found"):
                return jsonify({"success": False, "error": f"No route found to {parsed['target_id']}.", "parsed": parsed}), 400
            nav_result = _apply_navigation_state(parsed["target_id"], source="player_directive", route=route)
            state = _resolve_player_character_state()
            runtime = dict(state.get("runtime") or {})
            if parsed.get("action") in {"walk", "run", "sprint"}:
                verb_text = {
                    "walk": "Walking",
                    "run": "Running",
                    "sprint": "Sprinting"
                }.get(parsed["action"], "Moving")
                runtime["movement_mode"] = parsed["action"]
                runtime["requested_action"] = parsed["action"]
                runtime["action_description"] = f"{verb_text} to {parsed['target_id'].replace('_', ' ')} by player directive."
                runtime["last_action_at"] = datetime.utcnow().isoformat()
                state["runtime"] = runtime
                app_state["player_character"] = state
            summary_parts.append(f"moving to {parsed['target_id'].replace('_', ' ')}")
        else:
            nav_result = None

        if parsed.get("pose"):
            runtime["pose"] = _normalize_player_pose(parsed["pose"])
            runtime["manual_pose_override"] = runtime["pose"] != "stand"
            runtime["movement_mode"] = "idle" if runtime["pose"] in {"stand", "sit", "lie", "relax"} else "crouch"
            summary_parts.append(f"pose {runtime['pose']}")

        if parsed.get("action"):
            runtime["requested_action"] = parsed["action"]
            runtime["last_action_at"] = datetime.utcnow().isoformat()
            if parsed["action"] in {"walk", "run", "sprint", "jump"}:
                runtime["movement_mode"] = parsed["action"]
            runtime["action_description"] = (
                f"Player directive: {command_text[:180]}"
            )
            summary_parts.append(f"action {parsed['action']}")

        if parsed.get("interaction_target"):
            runtime["interaction_target"] = parsed["interaction_target"]
            summary_parts.append(f"target {parsed['interaction_target']}")

        runtime["control_mode"] = "player_manual"
        runtime["input_priority"] = "player"
        runtime["allow_keyboard_input"] = True
        runtime["allow_click_to_move"] = True
        runtime["allow_pointer_interaction"] = True
        state["runtime"] = runtime
        state["last_updated_at"] = datetime.utcnow().isoformat()
        app_state["player_character"] = state
        resolved = _resolve_player_character_state()
        summary = "; ".join(summary_parts) if summary_parts else "Directive understood, but no matching gameplay verb was found."
        return jsonify({
            "success": True,
            "command": command_text,
            "parsed": parsed,
            "summary": summary,
            "navigation": nav_result,
            "player_character": resolved
        })
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500




