@app.route('/api/system/strict-debug', methods=['GET'])
def system_strict_debug():
    if not app.config.get('DEBUG') and not _is_local_request():
        return jsonify({"success": False, "error": "Not found"}), 404
    try:
        health = _build_system_health_snapshot(strict=True)
        failures = [c for c in list(health.get("checks") or []) if not c.get("ok")]
        debug = {
            "strict_mode": True,
            "health": health,
            "failures": failures,
            "pass": len(failures) == 0,
            "timestamp": datetime.utcnow().isoformat()
        }
        return jsonify({"success": True, "strict_debug": debug})
    except Exception as e:
        return _server_error_response(e)


