def _festival_population_request_time():
    raw = str(request.args.get("at", "") or "").strip()
    if not raw:
        return datetime.now().astimezone()
    try:
        value = datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except ValueError as exc:
        raise InvalidCommandError("at must be an ISO-8601 datetime") from exc
    if value.tzinfo is None:
        raise InvalidCommandError("at must include a timezone")
    return value


