def _active_lumen_city_context():
    at = datetime.now().astimezone()
    journey = _resolve_world_journey_state(at)
    if journey.get("active_area_id") != CITY_AREA_ID:
        raise InvalidLumenCityCommand("Lumen City actions require an active city location")
    atmosphere = _resolve_festival_atmosphere_state(at)
    return at, journey, atmosphere


