def transfer_world_area():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"success": False, "error": "request body must be a JSON object"}), 400
    try:
        with _serialized_world_command():
            exploration = _resolve_festival_exploration_state()
            transaction, replayed = world_journey_service.transfer(
                data.get("gateway_id"),
                data.get("idempotency_key"),
                data.get("expected_sequence"),
                exploration,
            )
            location = world_journey_service.state(exploration)
        if not replayed:
            event = transaction["event"]
            _record_runtime_event(
                "world_area_transfer",
                f"Transferred to {event['area_after']}",
                detail=f"node={event['node_after']};gateway={event['gateway_id']}",
                source="world_journey",
            )
        return jsonify({
            "success": True,
            "created": not replayed,
            "transaction_id": transaction["transaction_id"],
            "event": transaction["event"],
            "location": location,
        }), 200 if replayed else 201
    except Exception as error:
        return _world_journey_error(error)


