def _commit_world_consequence_payload(data):
    transaction, replayed = world_consequence_service.commit({
        "idempotency_key": data.get("idempotency_key"),
        "action_code": data.get("action_code"),
        "target_entity_id": data.get("target_entity_id", "npc-vendor-runner"),
        "location_id": data.get("location_id", "festival_market"),
        "zone_id": data.get("zone_id", "vendor_row"),
    })
    consequence = dict(transaction.get("consequence") or {})
    if not replayed:
        world_continuity = dict(app_state.get("world_continuity") or {})
        world_continuity["recent_world_ripple"] = consequence.get("summary", "")
        world_continuity["phase2_consequence_sequence"] = consequence.get("last_sequence", 0)
        app_state["world_continuity"] = world_continuity
        _record_runtime_event(
            "world_consequence",
            consequence.get("summary", "Festival consequence committed"),
            detail=f"transaction={transaction.get('transaction_id', '')}",
            source="world_consequences",
        )
    return transaction, replayed, consequence


@app.route('/api/world/festival/interactables/<path:object_key>/interact', methods=['POST'])
def interact_with_festival_object(object_key):
    data = request.get_json(silent=True) or {}
    try:
        state = _resolve_festival_interactable_state()
        interaction = resolve_festival_interaction(
            object_key,
            str(data.get("verb", "") or "").strip(),
            state,
        )
        action_code = interaction.get("consequence_action", "")
        if action_code:
            transaction, replayed, consequence = _commit_world_consequence_payload({
                "idempotency_key": data.get("idempotency_key"),
                "action_code": action_code,
                "target_entity_id": "npc-vendor-runner",
                "location_id": "festival_market",
                "zone_id": "vendor_row",
            })
            return jsonify({
                "success": True,
                "created": not replayed,
                "interaction": interaction,
                "transaction_id": transaction.get("transaction_id"),
                "consequence": consequence,
            }), 200 if replayed else 201
        _record_runtime_event(
            "festival_interaction",
            interaction["message"],
            detail=f"object={object_key};verb={interaction['verb']}",
            source="festival_affordances",
        )
        return jsonify({"success": True, "interaction": interaction})
    except Exception as error:
        if isinstance(error, (IdempotencyConflictError, InvalidCommandError, ReadOnlyStoreError)):
            return _world_consequence_error(error)
        return _festival_affordance_error(error)


