def _push_state_to_unreal():
    """Push Aurion's live state to Unreal Engine via the Remote Control API.
    Discovers BP_AurionBridge actor path, then sets its Blueprint variables."""
    try:
        import urllib.request as _urllib_req, json as _json_mod
        rc_base = _resolve_unreal_rc_base_url()
        _update_unreal_bridge_runtime(
            rc_base_url=rc_base,
            rc_last_attempt_at=_iso_utc_now(),
            rc_last_error=None
        )

        # --- 1. Discover the bridge actor path ---
        search_url = f"{rc_base}/remote/search/actors"
        search_body = _json_mod.dumps({"Query": "BP_AurionBridge", "Types": ["Actor"]}).encode()
        try:
            req = _urllib_req.Request(search_url, data=search_body,
                                      headers={"Content-Type": "application/json"}, method="PUT")
            with _urllib_req.urlopen(req, timeout=1.5) as r:
                found = _json_mod.loads(r.read()).get("results") or []
        except Exception as e:
            _record_unreal_bridge_failure("actor_search", endpoint=search_url, error=e)
            found = []

        if not found:
            _record_unreal_bridge_failure("actor_search", endpoint=search_url, error="actor_not_found")
            return False

        actor_path = found[0].get("path") or ""
        _update_unreal_bridge_runtime(rc_actor_path=actor_path)
        props = _build_unreal_property_push_list()

        prop_url = f"{rc_base}/remote/object/property"
        ok_count = 0
        failed = []
        for prop_name, prop_val in props:
            body = _json_mod.dumps({
                "objectPath": actor_path,
                "propertyName": prop_name,
                "propertyValue": prop_val,
                "access": "WRITE_ACCESS"
            }).encode()
            try:
                req = _urllib_req.Request(prop_url, data=body,
                                          headers={"Content-Type": "application/json"}, method="PUT")
                with _urllib_req.urlopen(req, timeout=1.0) as r:
                    r.read()
                ok_count += 1
            except Exception as e:
                failed.append(prop_name)
                _record_unreal_bridge_failure("property_write", endpoint=prop_url, error=e, property_name=prop_name, actor_path=actor_path)

        summary = {
            "attempted": len(props),
            "succeeded": ok_count,
            "failed": len(failed),
            "failed_properties": failed[:24],
            "actor_path": actor_path,
            "pushed_at": _iso_utc_now(),
        }
        status = f"pushed_{ok_count}/{len(props)}" if ok_count else "push_failed"
        _update_unreal_bridge_runtime(
            rc_status=status,
            rc_last_push_at=summary["pushed_at"],
            rc_last_success_at=summary["pushed_at"] if ok_count else app_state.get("unreal_bridge", {}).get("rc_last_success_at"),
            rc_last_push_summary=summary,
        )
        return ok_count > 0

    except Exception as e:
        _record_unreal_bridge_failure("push_runtime", error=e)
        return False


def _unreal_rc_push_loop():
    """Background thread: push Aurion state to Unreal every 1.5s."""
    import time as _time
    while True:
        try:
            _push_state_to_unreal()
        except Exception:
            pass
        _time.sleep(1.5)


# Start the Remote Control push thread (daemon — exits with process)
_rc_push_thread = None
if _ENABLE_AUTONOMY_THREADS:
    _rc_push_thread = threading.Thread(target=_unreal_rc_push_loop, daemon=True, name="UnrealRCPush")
    _rc_push_thread.start()


