@app.route('/api/world/offscreen-life', methods=['POST'])
def update_offscreen_life_state():
    try:
        data = request.get_json(force=True) or {}
        wc = dict(app_state.get("world_continuity") or {})
        state = dict(wc.get("offscreen_simulation") or _default_offscreen_life_simulation_state())
        if "enabled" in data:
            state["enabled"] = bool(data.get("enabled"))
        if "total_npcs_estimate" in data:
            state["total_npcs_estimate"] = max(100, min(5000000, int(data.get("total_npcs_estimate") or state.get("total_npcs_estimate", 2800))))
        if "active_story_threads" in data:
            state["active_story_threads"] = max(1, min(state.get("total_npcs_estimate", 2800), int(data.get("active_story_threads") or state.get("active_story_threads", 360))))
        if "procedural_density" in data:
            density = str(data.get("procedural_density", state.get("procedural_density", "high")) or "high").strip().lower()
            if density in {"low", "medium", "high", "ultra"}:
                state["procedural_density"] = density
        def _apply(wc_inner):
            wc_inner["offscreen_simulation"] = state
            wc_inner["synced_at"] = datetime.utcnow().isoformat()
        _mutate_world_continuity(_apply)
        _persist_perception_cadence_to_profile()
        return jsonify({"success": True, "offscreen_simulation": state})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

