@app.route('/api/world/spacefaring/travel', methods=['POST'])
def set_spacefaring_travel():
    try:
        data = request.get_json(force=True) or {}
        action = str(data.get("action", "hyperjump") or "hyperjump").strip().lower()
        destination = str(data.get("destination", "") or "").strip() or "Unknown Sector"
        wc = dict(app_state.get("world_continuity") or {})
        sovereign = dict(wc.get("sovereign_resources") or {})
        unlimited_mode = bool(sovereign.get("aurion_unlimited", True)) and bool(sovereign.get("player_unlimited", True))
        state = _build_spacefaring_registry_state(wc.get("spacefaring") or _default_spacefaring_state())
        travel = dict(state.get("travel_runtime") or {})
        load = dict(state.get("load_screen") or {})
        load["loop_until_render_complete"] = bool(load.get("loop_until_render_complete", True))
        now_iso = datetime.utcnow().isoformat()
        origin = str(state.get("current_sector", "Sol-Home") or "Sol-Home")
        if action == "launch":
            try:
                eta_minutes = max(0.2, min(1200.0, float(data.get("eta_minutes", 18.0) or 18.0)))
            except Exception:
                eta_minutes = 18.0
            travel.update({
                "in_transit": True,
                "mode": "rocket",
                "requested_mode": "rocket",
                "origin": origin,
                "destination": destination,
                "eta_total_minutes": round(eta_minutes, 3),
                "eta_remaining_minutes": round(eta_minutes, 3),
                "fuel_remaining_pct": 100.0 if unlimited_mode else max(1.0, float(travel.get("fuel_remaining_pct", 100.0) or 100.0) - max(0.5, eta_minutes * 0.12)),
                "travel_progress_pct": 0.0,
                "started_at": now_iso
            })
            load.update({
                "active": True,
                "label": "Rocket transit in progress",
                "detail": "Streaming world sectors and procedural entities.",
                "progress_pct": 0.0,
                "loop_until_render_complete": True
            })
        else:
            # Hyperdrive: instant relocation while still exposing a load-screen pulse for large sectors.
            if not bool(state.get("instant_hyperdrive_enabled", True)):
                return jsonify({"success": False, "error": "instant hyperdrive is disabled for this world"}), 403
            state["current_sector"] = destination
            travel.update({
                "in_transit": False,
                "mode": "hyperdrive",
                "requested_mode": "hyperdrive",
                "origin": origin,
                "destination": destination,
                "eta_total_minutes": 0.0,
                "eta_remaining_minutes": 0.0,
                "fuel_remaining_pct": 100.0 if unlimited_mode else float(travel.get("fuel_remaining_pct", 100.0) or 100.0),
                "travel_progress_pct": 100.0,
                "started_at": now_iso
            })
            load.update({
                "active": True,
                "label": "Hyperdrive jump complete",
                "detail": "Finalizing procedural world stream for destination sector.",
                "progress_pct": 100.0,
                "loop_until_render_complete": True
            })
            history = [dict(x or {}) for x in list(state.get("jump_history") or []) if isinstance(x, dict)]
            history.append({"from": origin, "to": destination, "mode": "hyperdrive", "arrived_at": now_iso})
            state["jump_history"] = history[-200:]
            state, _ = _register_spacefaring_destination(state, {
                "id": _slugify_filename(destination, fallback="destination"),
                "name": destination,
                "display_name": destination,
                "kind": "sector_destination",
                "source": "hyperdrive",
                "origin_class": "travel_history",
                "documented": True,
                "discovered": True,
                "last_targeted_at": now_iso,
                "revisit_anchor": destination,
                "travel_target": destination,
                "description": f"Hyperdrive destination documented at {destination}."
            }, event="hyperdrive_arrival", record_visit=True)
        if action == "teleport":
            focus_target = _resolve_documented_sky_target(
                data.get("focus_target", data.get("target", destination)),
                data.get("focus_type", data.get("target_type", "star"))
            )
            state["current_sector"] = str((focus_target or {}).get("name", destination) or destination)
            travel.update({
                "in_transit": False,
                "mode": "teleport",
                "requested_mode": "teleport",
                "origin": origin,
                "destination": str((focus_target or {}).get("name", destination) or destination),
                "eta_total_minutes": 0.0,
                "eta_remaining_minutes": 0.0,
                "fuel_remaining_pct": 100.0 if unlimited_mode else float(travel.get("fuel_remaining_pct", 100.0) or 100.0),
                "travel_progress_pct": 100.0,
                "started_at": now_iso,
                "focused_target": dict(focus_target or {})
            })
            load.update({
                "active": True,
                "label": "Teleport focus locked",
                "detail": f"Loading-video render path is materializing {str((focus_target or {}).get('name', destination) or destination)[:120]}.",
                "progress_pct": 100.0,
                "loop_until_render_complete": True
            })
            history = [dict(x or {}) for x in list(state.get("jump_history") or []) if isinstance(x, dict)]
            history.append({
                "from": origin,
                "to": str((focus_target or {}).get("name", destination) or destination),
                "mode": "teleport",
                "arrived_at": now_iso,
                "documented": bool((focus_target or {}).get("source", "") != "manual_focus"),
                "focused_target": dict(focus_target or {})
            })
            state["jump_history"] = history[-200:]
            state, _ = _register_spacefaring_destination(state, {
                **dict(focus_target or {}),
                "name": str((focus_target or {}).get("name", destination) or destination),
                "display_name": str((focus_target or {}).get("name", destination) or destination),
                "travel_target": str((focus_target or {}).get("name", destination) or destination),
                "revisit_anchor": str((focus_target or {}).get("name", destination) or destination),
                "last_targeted_at": now_iso,
                "documented": bool((focus_target or {}).get("source", "") != "manual_focus"),
                "origin_class": "teleport_focus",
            }, event="teleport_arrival", record_visit=True)
        state["travel_runtime"] = travel
        state["infinite_fuel"] = bool(unlimited_mode or state.get("infinite_fuel", True))
        state["load_screen"] = load
        state["last_updated_at"] = now_iso
        state["summary"] = (
            f"Sector {state.get('current_sector', 'Sol-Home')} · "
            f"{'in transit' if travel.get('in_transit') else 'ready'} · "
            f"mode {travel.get('requested_mode', travel.get('mode', 'idle'))} · "
            f"{'infinite fuel' if state.get('infinite_fuel', True) else 'finite fuel'}."
        )
        def _apply(wc_inner):
            wc_inner["spacefaring"] = state
            wc_inner["synced_at"] = now_iso
        _mutate_world_continuity(_apply)
        _persist_perception_cadence_to_profile()
        return jsonify({"success": True, "spacefaring": state})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

