@app.route('/api/world/spacefaring/destinations', methods=['POST'])
def update_spacefaring_destination():
    try:
        data = request.get_json(force=True) or {}
        destination_id = str(data.get("id", data.get("destination_id", "")) or "").strip()
        wc = dict(app_state.get("world_continuity") or {})
        state = _build_spacefaring_registry_state(wc.get("spacefaring") or _default_spacefaring_state())
        registry = [dict(x or {}) for x in list(state.get("destination_registry") or []) if isinstance(x, dict)]
        existing = None
        for row in registry:
            if str(row.get("id", "") or "").strip().lower() == destination_id.lower():
                existing = row
                break
        if not existing and not destination_id:
            return jsonify({"success": False, "error": "id or destination_id is required"}), 400
        if not existing:
            existing = {
                "id": destination_id,
                "name": str(data.get("name", destination_id) or destination_id),
                "display_name": str(data.get("display_name", data.get("name", destination_id)) or destination_id),
                "kind": str(data.get("kind", "frontier_discovery") or "frontier_discovery"),
                "source": str(data.get("source", "manual_discovery") or "manual_discovery"),
                "origin_class": str(data.get("origin_class", "frontier_discovery") or "frontier_discovery"),
                "documented": bool(data.get("documented", False)),
                "discovered": True,
            }
        merged = _normalize_spacefaring_registry_entry({
            **dict(existing or {}),
            **dict(data or {}),
            "id": destination_id or str((existing or {}).get("id", "") or ""),
            "updated_at": datetime.utcnow().isoformat(),
        })
        state, saved_entry = _register_spacefaring_destination(
            state,
            merged,
            event=str(data.get("event", "named_destination") or "named_destination"),
            record_visit=bool(data.get("record_visit", False))
        )
        def _apply(wc_inner):
            wc_inner["spacefaring"] = state
            wc_inner["synced_at"] = datetime.utcnow().isoformat()
        _mutate_world_continuity(_apply)
        _persist_perception_cadence_to_profile()
        return jsonify({"success": True, "destination": saved_entry, "spacefaring": state})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

