@app.route('/api/world/spacefaring/vehicles', methods=['POST'])
def update_spacefaring_vehicle():
    try:
        data = request.get_json(force=True) or {}
        _require_pair_access(data.get("actor", data.get("requested_by", data.get("active_user_name", ""))))
        vehicle_id = str(data.get("id", data.get("vehicle_id", "")) or "").strip()
        wc = dict(app_state.get("world_continuity") or {})
        state = _build_spacefaring_registry_state(wc.get("spacefaring") or _default_spacefaring_state())
        vehicles = [dict(x or {}) for x in list(state.get("vehicle_registry") or []) if isinstance(x, dict)]
        existing = None
        for row in vehicles:
            if str(row.get("id", "") or "").strip().lower() == vehicle_id.lower():
                existing = row
                break
        if not existing and not vehicle_id:
            return jsonify({"success": False, "error": "id or vehicle_id is required"}), 400
        action = str(data.get("action", "update") or "update").strip().lower()
        if not existing:
            existing = {
                "id": vehicle_id,
                "name": str(data.get("name", vehicle_id) or vehicle_id),
                "kind": str(data.get("kind", "car") or "car"),
                "drivable": True,
                "owner_access": "aurion_and_billy_only",
                "location_layer_id": "vehicle-atrium-layer",
            }
        merged = _normalize_vehicle_entry({
            **dict(existing or {}),
            **dict(data or {}),
            "id": vehicle_id or str((existing or {}).get("id", "") or ""),
            "last_used_at": datetime.utcnow().isoformat() if action in {"drive", "ride", "fly"} else existing.get("last_used_at"),
        })
        doors_open = [str(x).strip() for x in list(merged.get("doors_open") or []) if str(x).strip()]
        windows_open = [str(x).strip() for x in list(merged.get("windows_open") or []) if str(x).strip()]
        part_target = str(data.get("part_id", data.get("door_id", data.get("window_id", ""))) or "").strip()
        if action in {"open_door", "close_door", "toggle_door"} and part_target:
            if part_target not in list(merged.get("door_ids") or []):
                return jsonify({"success": False, "error": "Unknown door id"}), 400
            if action == "open_door" and part_target not in doors_open:
                doors_open.append(part_target)
            elif action == "close_door" and part_target in doors_open:
                doors_open.remove(part_target)
            elif action == "toggle_door":
                if part_target in doors_open:
                    doors_open.remove(part_target)
                else:
                    doors_open.append(part_target)
        if action in {"open_window", "close_window", "toggle_window"} and part_target:
            if part_target not in list(merged.get("window_ids") or []):
                return jsonify({"success": False, "error": "Unknown window id"}), 400
            if action == "open_window" and part_target not in windows_open:
                windows_open.append(part_target)
            elif action == "close_window" and part_target in windows_open:
                windows_open.remove(part_target)
            elif action == "toggle_window":
                if part_target in windows_open:
                    windows_open.remove(part_target)
                else:
                    windows_open.append(part_target)
        merged["doors_open"] = doors_open
        merged["windows_open"] = windows_open
        registry_map = {str(row.get("id", "")).strip().lower(): dict(row or {}) for row in vehicles if isinstance(row, dict)}
        registry_map[merged["id"].lower()] = merged
        state["vehicle_registry"] = list(registry_map.values())[-120:]
        active_drive_update = None
        if action in {"drive", "ride", "fly"}:
            active_drive_update = {
                "vehicle": merged["name"],
                "vehicle_id": merged["id"],
                "kind": merged["kind"],
                "road": str(data.get("road", "open route") or "open route")[:120],
                "destination": str(data.get("destination", "wherever Aurion and Billy choose") or "wherever Aurion and Billy choose")[:120],
                "control_access": "aurion_and_billy_only",
                "started_at": datetime.utcnow().isoformat(),
            }
        def _apply(wc_inner):
            if active_drive_update is not None:
                wc_inner["active_drive"] = active_drive_update
            wc_inner["spacefaring"] = state
            wc_inner["synced_at"] = datetime.utcnow().isoformat()
        wc = _mutate_world_continuity(_apply)
        _persist_perception_cadence_to_profile()
        _persist_live_senses_snapshot(reason="spacefaring-vehicle")
        return jsonify({"success": True, "vehicle": merged, "spacefaring": state, "active_drive": wc.get("active_drive")})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

