@app.route('/api/world/continuity', methods=['POST'])
def update_world_continuity():
    try:
        data = request.json or {}
        current = dict(app_state.get("world_continuity", {}) or {})
        if "display_resolution" in data:
            current["display_resolution"] = str(data["display_resolution"]).strip().lower() or "4k"
        if "perception_cadence_hz" in data:
            try:
                current["perception_cadence_hz"] = max(1, min(360, int(data["perception_cadence_hz"])))
            except Exception:
                pass
        if "world_patience" in data:
            try:
                current["world_patience"] = max(0, min(100, int(data["world_patience"])))
            except Exception:
                pass
        if "direct_link_enabled" in data:
            current["direct_link_enabled"] = bool(data["direct_link_enabled"])
        if "last_direct_link_at" in data:
            current["last_direct_link_at"] = str(data["last_direct_link_at"] or "").strip() or None
        if "saved_activity" in data:
            val = data["saved_activity"]
            current["saved_activity"] = dict(val) if isinstance(val, dict) else None
        if "active_drive" in data:
            val = data["active_drive"]
            current["active_drive"] = dict(val) if isinstance(val, dict) else None
        if "world_mobility" in data:
            val = data["world_mobility"]
            current["world_mobility"] = dict(val) if isinstance(val, dict) else None
        if "world_builder" in data and isinstance(data.get("world_builder"), dict):
            current["world_builder"] = dict(data.get("world_builder") or {})
        if "time_control" in data and isinstance(data.get("time_control"), dict):
            current["time_control"] = dict(data.get("time_control") or {})
        if "world_forces" in data and isinstance(data.get("world_forces"), list):
            current["world_forces"] = list(data.get("world_forces") or [])
        if "guardian_presence" in data and isinstance(data.get("guardian_presence"), dict):
            current["guardian_presence"] = dict(data.get("guardian_presence") or {})
        if "special_ability_registry" in data and isinstance(data.get("special_ability_registry"), dict):
            current["special_ability_registry"] = dict(data.get("special_ability_registry") or {})
        if "offscreen_simulation" in data and isinstance(data.get("offscreen_simulation"), dict):
            current["offscreen_simulation"] = dict(data.get("offscreen_simulation") or {})
        if "spacefaring" in data and isinstance(data.get("spacefaring"), dict):
            incoming_spacefaring = dict(data.get("spacefaring") or {})
            existing_spacefaring = dict(current.get("spacefaring") or {})
            defaults = _default_spacefaring_state()
            merged_spacefaring = {
                **defaults,
                **existing_spacefaring,
                **incoming_spacefaring
            }
            merged_spacefaring["travel_runtime"] = {
                **dict(defaults.get("travel_runtime") or {}),
                **dict(existing_spacefaring.get("travel_runtime") or {}),
                **dict(incoming_spacefaring.get("travel_runtime") or {})
            }
            merged_spacefaring["load_screen"] = {
                **dict(defaults.get("load_screen") or {}),
                **dict(existing_spacefaring.get("load_screen") or {}),
                **dict(incoming_spacefaring.get("load_screen") or {})
            }
            shared_defaults = dict(defaults.get("shared_discoveries") or {})
            merged_spacefaring["shared_discoveries"] = {
                **shared_defaults,
                **dict(existing_spacefaring.get("shared_discoveries") or {}),
                **dict(incoming_spacefaring.get("shared_discoveries") or {})
            }
            if "known_systems" in incoming_spacefaring:
                merged_spacefaring["known_systems"] = list(incoming_spacefaring.get("known_systems") or [])
            if "jump_history" in incoming_spacefaring:
                merged_spacefaring["jump_history"] = list(incoming_spacefaring.get("jump_history") or [])
            if "teleportation_destinations" in incoming_spacefaring:
                merged_spacefaring["teleportation_destinations"] = list(incoming_spacefaring.get("teleportation_destinations") or [])
            if "destination_registry" in incoming_spacefaring:
                merged_spacefaring["destination_registry"] = [
                    dict(row or {}) for row in list(incoming_spacefaring.get("destination_registry") or [])
                    if isinstance(row, dict) and bool((row.get("has_life")) or (dict(row.get("metadata") or {}).get("has_life", False)))
                ]
            if "discovery_journal" in incoming_spacefaring:
                merged_spacefaring["discovery_journal"] = [
                    dict(row or {}) for row in list(incoming_spacefaring.get("discovery_journal") or [])
                    if isinstance(row, dict) and bool(row.get("shared_between_instances", False))
                ]
            if "vehicle_registry" in incoming_spacefaring:
                merged_spacefaring["vehicle_registry"] = list(incoming_spacefaring.get("vehicle_registry") or [])
            if "alien_companions" in incoming_spacefaring and isinstance(incoming_spacefaring.get("alien_companions"), dict):
                merged_spacefaring["alien_companions"] = dict(incoming_spacefaring.get("alien_companions") or {})
            if "digitized_items" in incoming_spacefaring and isinstance(incoming_spacefaring.get("digitized_items"), dict):
                merged_spacefaring["digitized_items"] = dict(incoming_spacefaring.get("digitized_items") or {})
            current["spacefaring"] = _build_spacefaring_registry_state(merged_spacefaring)
        if "sovereign_resources" in data and isinstance(data.get("sovereign_resources"), dict):
            src = dict(data.get("sovereign_resources") or {})
            try:
                pressure = max(0.0, min(100.0, float(src.get("resource_pressure_pct", 25.0) or 25.0)))
            except Exception:
                pressure = 25.0
            current["sovereign_resources"] = {
                "aurion_unlimited": bool(src.get("aurion_unlimited", True)),
                "player_unlimited": bool(src.get("player_unlimited", True)),
                "mode": str(src.get("mode", "infinite") or "infinite"),
                "resource_pressure_pct": 0.0 if bool(src.get("aurion_unlimited", True)) and bool(src.get("player_unlimited", True)) else pressure
            }
        if "sovereign_skills" in data and isinstance(data.get("sovereign_skills"), dict):
            src = dict(data.get("sovereign_skills") or {})
            current["sovereign_skills"] = _build_cohesive_sovereign_skills_state({
                **dict(src or {}),
                "flight_access": [personality_engine.sanitize_user_name(x) for x in list(src.get("flight_access") or []) if personality_engine.sanitize_user_name(x)][:8] or list(_default_sovereign_skills_state().get("flight_access", [])),
                "teleportation_access": [personality_engine.sanitize_user_name(x) for x in list(src.get("teleportation_access") or []) if personality_engine.sanitize_user_name(x)][:8] or list(_default_sovereign_skills_state().get("teleportation_access", []))
            })
        current["synced_at"] = datetime.utcnow().isoformat()
        app_state["world_continuity"] = current
        _resolve_time_control_state()
        _resolve_world_force_state()
        _persist_perception_cadence_to_profile()
        _persist_live_senses_snapshot(reason="world-continuity")
        return jsonify({"success": True, "world_continuity": current})
    except Exception as e:
        print(f"[World Continuity Update Error] {e}")
        return jsonify({"success": False, "error": str(e)}), 500


