@app.route('/api/navigation/path', methods=['POST'])
def path_navigation_state():
    try:
        data = request.get_json(force=True) or {}
        start_id = str(data.get("start_id", "") or "").strip()
        target_id = str(data.get("target_id", "") or data.get("room", "") or data.get("place_id", "")).strip()
        if not target_id:
            return jsonify({"success": False, "error": "target_id is required"}), 400
        if not start_id:
            runtime = _build_navigation_runtime_state()
            start_id = str(runtime.get("current_location_id", "") or "").strip()
        route = _find_navigation_route(start_id, target_id)
        if not route.get("found"):
            return jsonify({"success": False, "error": "No route found.", "route": route}), 404
        return jsonify({"success": True, "route": route})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


@app.route('/api/navigation/move', methods=['POST'])
def move_navigation_state():
    try:
        data = request.get_json(force=True) or {}
        target_id = str(data.get("target_id", "") or data.get("room", "") or data.get("place_id", "")).strip()
        if not target_id:
            return jsonify({"success": False, "error": "target_id is required"}), 400
        home = dict(app_state.get("home_environment") or _default_home_state())
        wc = dict(app_state.get("world_continuity") or {})
        current_id = str((((wc.get("world_builder") or {}).get("active_place_id")) or "")).strip() or str(home.get("current_room", "living_room") or "living_room")
        canonical_target = _resolve_navigation_target_id(target_id)
        allow_any = bool(data.get("allow_non_adjacent", False))
        route = _find_navigation_route(current_id, canonical_target)
        if not route.get("found"):
            return jsonify({
                "success": False,
                "error": "No route found to the requested target.",
                "current_location_id": current_id,
                "reachable_targets": list((_build_navigation_graph().get(current_id, [])) or []),
            }), 400
        if not allow_any and canonical_target != current_id and len(list(route.get("segments") or [])) > 1:
            return jsonify({
                "success": False,
                "error": "Target requires a routed traversal. Retry with allow_non_adjacent=true or call /api/navigation/path first.",
                "current_location_id": current_id,
                "route": route,
            }), 400
        nav = _apply_navigation_state(canonical_target, source=str(data.get("source", "navigation") or "navigation"), route=route)
        return jsonify({"success": True, "navigation": nav, "route": route})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


