@app.route('/api/festival-market/transaction', methods=['POST'])
def apply_festival_market_transaction():
    try:
        data = request.get_json(force=True) or {}
        market = _normalize_festival_market_state(app_state.get("festival_market", {}), {})
        item_id = str(data.get("item_id", "") or "").strip()
        mode = str(data.get("mode", "money") or "money").strip().lower()
        buyer = str(data.get("buyer", "festival_guest") or "festival_guest").strip() or "festival_guest"
        if mode not in {"money", "barter"}:
            return jsonify({"success": False, "error": "mode must be money or barter"}), 400
        item = None
        for row in list(market.get("art_inventory") or []):
            if str(row.get("id", "") or "").strip() == item_id:
                item = row
                break
        if not item:
            return jsonify({"success": False, "error": "Unknown art item"}), 404
        if str(item.get("status", "available") or "available") != "available":
            return jsonify({"success": False, "error": "Item is not available"}), 400
        now_iso = datetime.utcnow().isoformat()
        if mode == "money":
            amount = round(max(0.0, float(item.get("price_usd", 0.0) or 0.0)), 2)
            market["wallet_usd"] = round(float(market.get("wallet_usd", 0.0) or 0.0) + amount, 2)
            market["sales_log"] = list(market.get("sales_log") or []) + [{
                "item_id": item_id,
                "title": str(item.get("title", "") or ""),
                "buyer": buyer,
                "mode": "money",
                "amount_usd": amount,
                "transacted_at": now_iso,
            }]
        else:
            offered = [str(x).strip() for x in list(data.get("offered_items") or []) if str(x).strip()][:12]
            if not offered and not str(data.get("offer_note", "") or "").strip():
                return jsonify({"success": False, "error": "Barter requires offered_items or offer_note"}), 400
            credit = max(1, int(item.get("barter_value", 1) or 1))
            market["barter_credit"] = int(market.get("barter_credit", 0) or 0) + credit
            market["barter_log"] = list(market.get("barter_log") or []) + [{
                "item_id": item_id,
                "title": str(item.get("title", "") or ""),
                "buyer": buyer,
                "mode": "barter",
                "offered_items": offered,
                "offer_note": str(data.get("offer_note", "") or "").strip(),
                "barter_credit_delta": credit,
                "transacted_at": now_iso,
            }]
        item["status"] = "sold"
        item["sold_via"] = mode
        item["sold_at"] = now_iso
        market["synced_at"] = now_iso
        app_state["festival_market"] = market
        _persist_perception_cadence_to_profile()
        _persist_live_senses_snapshot(reason=f"festival-market-{mode}")
        return jsonify({"success": True, "festival_market": market, "item": item, "mode": mode})
    except Exception as e:
        print(f"[Festival Market Transaction Error] {e}")
        return jsonify({"success": False, "error": str(e)}), 500

