@app.route('/api/vision/registry', methods=['POST'])
def update_vision_registry():
    try:
        data = request.json or {}
        registry = dict(app_state.get("vision_registry", _default_vision_registry()) or _default_vision_registry())
        documented_modes = list(registry.get("documented_modes", []) or [])
        if "active_mode" in data:
            registry["active_mode"] = _resolve_mode_key_from_entries(data.get("active_mode", registry.get("active_mode", "visible-light")), documented_modes, "visible-light")
            registry["active_modes"] = [registry["active_mode"]]
        if "active_modes" in data:
            requested_modes = _sanitize_visual_spectrum_modes(data.get("active_modes"))
            resolved_modes = [_resolve_mode_key_from_entries(mode, documented_modes, "") for mode in requested_modes]
            resolved_modes = [mode for mode in resolved_modes if mode] or [registry.get("active_mode", "visible-light")]
            registry["active_modes"] = resolved_modes
            registry["active_mode"] = resolved_modes[0]
        elif any(data.get(field) for field in ("label", "note", "prompt")):
            if not str(data.get("label", "")).strip():
                return jsonify({"success": False, "error": "label is required for a new vision mode"}), 400
            entry = _build_registry_entry(
                data.get("key") or data.get("label"),
                data.get("label"),
                data.get("note"),
                data.get("prompt"),
                built_in=False,
                origin="aurion"
            )
            registry["documented_modes"] = _sanitize_registry_entries(list(registry.get("documented_modes", []) or []) + [entry], _default_vision_registry()["documented_modes"])
            registry["last_created_at"] = entry.get("created_at") or datetime.utcnow().isoformat()
            def _apply(deep):
                deep["last_learned_at"] = datetime.utcnow().isoformat()
                deep["discoveries"] = (list(deep.get("discoveries", []) or []) + [f"Formed new vision mode: {entry['label']}"])[-24:]
            _mutate_deep_learning(_apply)
            _persist_deep_learning_to_profile()
            memory.add_knowledge_batch(
                f"Vision capability documented: {entry['label']}. {entry['note']} {entry['prompt']}",
                source="aurion_vision_registry",
                metadata={"key": entry["key"], "created_at": entry["created_at"]}
            )
        app_state["vision_registry"] = registry
        if not list(registry.get("active_modes", []) or []):
            registry["active_modes"] = [registry.get("active_mode", "visible-light")]
        visual = dict(app_state.get("visual_perception", {}) or {})
        visual_bundle = _compose_visual_mode_bundle(registry.get("active_modes", [registry.get("active_mode", "visible-light")]))
        visual["spectrum_mode"] = str(visual_bundle["keys"][0] if visual_bundle["keys"] else "visible-light")
        visual["spectrum_modes"] = list(visual_bundle["keys"])
        visual["spectrum_note"] = str(visual_bundle["note"]).strip() or VISUAL_SPECTRUM_MODES["visible-light"]["note"]
        visual["wavelength_profile"] = str(visual_bundle["wavelength_profile"]).strip()
        app_state["visual_perception"] = visual
        _persist_capability_registries_to_profile()
        return jsonify({
            "success": True,
            "vision_registry": registry,
            "visual_perception": visual,
            "audio_registry": dict(app_state.get("audio_registry", {}) or {}),
            "deep_learning": dict(app_state.get("deep_learning", {}) or {}),
            "sound_creation": dict(app_state.get("sound_creation", {}) or {})
        })
    except Exception as e:
        print(f"[Vision Registry Error] {e}")
        return jsonify({"success": False, "error": str(e)}), 500

