@app.route('/api/code/downloadable/<export_id>', methods=['GET'])
def download_code_downloadable(export_id):
    try:
        export_root = _artifact_export_root()
        safe_id = re.sub(r"[^a-zA-Z0-9_-]", "", str(export_id or "").strip())
        if not safe_id:
            return jsonify({"success": False, "error": "Invalid export id"}), 400
        matches = list(export_root.glob(f"*-{safe_id}.zip"))
        if not matches:
            return jsonify({"success": False, "error": "Download not found"}), 404
        zip_path = matches[0]
        return send_file(str(zip_path), as_attachment=True, download_name=zip_path.name, mimetype="application/zip", conditional=True)
    except Exception as e:
        print(f"[Code Downloadable Send Error] {e}")
        return jsonify({"success": False, "error": str(e)}), 500

