@app.route('/api/release/packaging', methods=['POST'])
def update_release_packaging_state():
    try:
        data = request.json or {}
        state = _resolve_release_packaging_state()
        for key in (
            "enabled", "server_ready", "website_ready", "desktop_program_ready",
            "apk_ready", "installer_ready", "portable_zip_ready"
        ):
            if key in data:
                state[key] = bool(data.get(key))
        for key in ("release_channel", "current_version", "release_notes"):
            if key in data:
                state[key] = str(data.get(key, state.get(key, "")) or state.get(key, "")).strip()
        if isinstance(data.get("targets"), dict):
            merged_targets = dict(state.get("targets") or {})
            for target_key, target_value in dict(data.get("targets") or {}).items():
                prior = dict(merged_targets.get(target_key) or {})
                if isinstance(target_value, dict):
                    prior.update(target_value)
                merged_targets[str(target_key)] = prior
            state["targets"] = merged_targets
        app_state["release_packaging"] = state
        return jsonify({"success": True, "release_packaging": state})
    except Exception as e:
        print(f"[Release Packaging Update Error] {e}")
        return jsonify({"success": False, "error": str(e)}), 500

