@app.route('/api/llm/settings', methods=['POST'])
def update_llm_settings():
    try:
        data = request.json or {}
        provider = str(data.get("provider", "")).strip().lower()
        model = str(data.get("model", "")).strip()
        base_url = str(data.get("base_url", "")).strip()
        cot_enabled = bool(data.get("cot_enabled", True))
        orchestration_mode = str(data.get("orchestration_mode", "auto")).strip().lower() or "auto"
        combo_mode = str(data.get("combo_mode", "dual_synthesize")).strip().lower() or "dual_synthesize"
        available_providers = ["ollama", "sillytavern", "oobabooga", "openrouter", "cohere", "openai", "anthropic", "gemini", "m365copilot"]
        enabled_providers = [
            str(p).strip().lower()
            for p in list(data.get("enabled_providers", []) or [])
            if str(p).strip()
        ]
        enabled_providers = [p for p in enabled_providers if p in available_providers]
        allowed_modes = {"single", "auto", "round_robin", "combo"}
        allowed_combo = {"off", "dual_synthesize"}
        if orchestration_mode not in allowed_modes:
            orchestration_mode = "auto"
        if combo_mode not in allowed_combo:
            combo_mode = "dual_synthesize"
        selected_provider = provider

        # Update CoT flag immediately (no restart needed)
        personality_engine.cot_enabled = cot_enabled

        # Update model alias â€” check custom models first
        if model:
            custom = dict(app_state.get("custom_models", {}) or {})
            custom_entry = custom.get(model.lower())
            resolved = custom_entry["model_id"] if custom_entry else personality_engine._normalize_model_alias(model)
            personality_engine.llm_model = resolved
            if not selected_provider and custom_entry:
                hinted = str(custom_entry.get("provider_hint", "auto")).strip().lower()
                if hinted in available_providers:
                    selected_provider = hinted

        # Apply base URL overrides (per selected provider)
        if selected_provider and base_url:
            if selected_provider == "ollama":
                os.environ["AURION_OLLAMA_URL"] = base_url
            elif selected_provider == "sillytavern":
                os.environ["AURION_SILLYTAVERN_URL"] = base_url
            elif selected_provider == "oobabooga":
                os.environ["AURION_OOBABOOGA_URL"] = base_url
            elif selected_provider == "openrouter":
                os.environ["OPENROUTER_BASE_URL"] = base_url
            elif selected_provider == "gemini":
                os.environ["GEMINI_BASE_URL"] = base_url
            elif selected_provider == "m365copilot":
                os.environ["M365_COPILOT_BASE_URL"] = base_url

        # Refresh all clients so orchestration can use any available provider in real time
        clients = personality_engine._refresh_llm_clients()
        if selected_provider and selected_provider in clients:
            personality_engine.llm_provider = selected_provider
            personality_engine.llm_client = clients[selected_provider]
        elif not getattr(personality_engine, "llm_provider", None) or personality_engine.llm_provider not in clients:
            first = next(iter(clients.keys()), None)
            if first:
                personality_engine.llm_provider = first
                personality_engine.llm_client = clients[first]
        personality_engine.use_llm = bool(clients)

        # Persist orchestration runtime config
        app_state["llm_orchestration"] = {
            "mode": orchestration_mode,
            "combo_mode": combo_mode,
            "enabled_providers": enabled_providers
        }
        personality_engine.llm_orchestration = dict(app_state["llm_orchestration"])
        _persist_llm_orchestration_to_profile()
        if _sanitize_compute_boost_settings(app_state.get("compute_boost", {})).get("enabled", True):
            _apply_cloud_compute_boost(force=True)

        return jsonify({
            "success": True,
            "provider": getattr(personality_engine, "llm_provider", "none"),
            "model": str(getattr(personality_engine, "llm_model", "") or ""),
            "cot_enabled": getattr(personality_engine, "cot_enabled", True),
            "orchestration_mode": orchestration_mode,
            "combo_mode": combo_mode,
            "enabled_providers": enabled_providers,
            "connected_providers": sorted(list(getattr(personality_engine, "llm_clients", {}).keys()))
        })
    except Exception as e:
        print(f"[LLM Settings Error] {e}")
        return jsonify({"success": False, "error": str(e)}), 500

