@app.route('/api/voice/speak', methods=['POST'])
def speak():
    """Make Aurion speak text"""
    try:
        if not app_state["voice_enabled"]:
            return jsonify({"error": "Voice not enabled"}), 400
        
        data = request.get_json(force=True, silent=True) or {}
        text = data.get('text', '')
        
        if not text:
            return jsonify({"error": "No text provided"}), 400
        
        if not tts_enabled:
            return jsonify({"error": "TTS engine not initialized"}), 500
        
        # Queue the TTS request to be processed by worker thread
        settings = app_state.get("voice_settings", {})
        _set_speaking_state(True, source="api")
        tts_queue.put((text, settings))
        return jsonify({
            "status": "speaking",
            "vocal_profile": _build_vocal_runtime_profile(text, settings)
        })
    except Exception as e:
        _log_exception("Speak Endpoint Error", e)
        return jsonify({"error": _sanitize_error_message(e)}), 500

@app.route('/api/voice/settings', methods=['POST'])
def update_voice_settings():
    """Update voice settings (speed, pitch, volume, voice)"""
    try:
        data = request.get_json(force=True, silent=True) or {}
        setting = data.get('setting')
        value = data.get('value')
        
        if not setting or value is None:
            return jsonify({"error": "Missing setting or value"}), 400
        
        # Update app_state
        if 'voice_settings' not in app_state:
            app_state['voice_settings'] = {
                "voice_index": preferred_server_index,
                "rate": 135,
                "pitch": 1.0,
                "volume": 100,
                "voice_provider": "browser",
                "browser_voice_uri": "",
                "pitch_mode": "normal",
                "speech_style": "articulate",
                "adaptive_pitch": "enabled",
                "adaptive_strength": 35,
                "adaptive_pitch_min": 0.9,
                "adaptive_pitch_max": 1.18,
                "performance_mode": "speaking",
                "singing_style": "lyrical",
                "pitch_drift": 0.08,
                "pitch_responsiveness": 72,
                "vibrato_amount": 0.12,
                "vibrato_rate_hz": 5.4,
                "breathiness": 0.18,
                "nonverbal_expressiveness": 0.34
            }
        
        # Handle different settings
        if setting == 'voice':
            app_state['voice_settings']['voice_index'] = int(value)
        elif setting == 'rate':
            app_state['voice_settings']['rate'] = int(value)
        elif setting == 'pitch':
            app_state['voice_settings']['pitch'] = float(value)
        elif setting == 'volume':
            app_state['voice_settings']['volume'] = int(value)
        elif setting == 'voice_provider':
            if str(value).lower() not in {"server", "browser"}:
                return jsonify({"error": "Invalid voice_provider"}), 400
            app_state['voice_settings']['voice_provider'] = str(value).lower()
        elif setting == 'browser_voice_uri':
            app_state['voice_settings']['browser_voice_uri'] = str(value or '')
        elif setting == 'pitch_mode':
            if str(value).lower() not in {"low", "normal", "high"}:
                return jsonify({"error": "Invalid pitch_mode"}), 400
            app_state['voice_settings']['pitch_mode'] = str(value).lower()
        elif setting == 'speech_style':
            if str(value).lower() not in {"casual", "articulate"}:
                return jsonify({"error": "Invalid speech_style"}), 400
            app_state['voice_settings']['speech_style'] = str(value).lower()
        elif setting == 'performance_mode':
            if str(value).lower() not in {"speaking", "singing"}:
                return jsonify({"error": "Invalid performance_mode"}), 400
            app_state['voice_settings']['performance_mode'] = str(value).lower()
        elif setting == 'singing_style':
            if str(value).lower() not in {"lyrical", "soft", "airy", "belt"}:
                return jsonify({"error": "Invalid singing_style"}), 400
            app_state['voice_settings']['singing_style'] = str(value).lower()
        elif setting == 'adaptive_pitch':
            if str(value).lower() not in {"enabled", "disabled"}:
                return jsonify({"error": "Invalid adaptive_pitch"}), 400
            app_state['voice_settings']['adaptive_pitch'] = str(value).lower()
        elif setting == 'adaptive_strength':
            app_state['voice_settings']['adaptive_strength'] = max(0, min(100, int(value)))
        elif setting == 'adaptive_pitch_min':
            min_val = max(0.5, min(1.9, float(value)))
            max_val = float(app_state['voice_settings'].get('adaptive_pitch_max', 1.45))
            if min_val >= max_val:
                return jsonify({"error": "adaptive_pitch_min must be lower than adaptive_pitch_max"}), 400
            app_state['voice_settings']['adaptive_pitch_min'] = min_val
        elif setting == 'adaptive_pitch_max':
            max_val = max(0.6, min(2.0, float(value)))
            min_val = float(app_state['voice_settings'].get('adaptive_pitch_min', 0.8))
            if max_val <= min_val:
                return jsonify({"error": "adaptive_pitch_max must be higher than adaptive_pitch_min"}), 400
            app_state['voice_settings']['adaptive_pitch_max'] = max_val
        elif setting == 'pitch_drift':
            app_state['voice_settings']['pitch_drift'] = max(0.0, min(0.3, float(value)))
        elif setting == 'pitch_responsiveness':
            app_state['voice_settings']['pitch_responsiveness'] = max(0.0, min(100.0, float(value)))
        elif setting == 'vibrato_amount':
            app_state['voice_settings']['vibrato_amount'] = max(0.0, min(1.0, float(value)))
        elif setting == 'vibrato_rate_hz':
            app_state['voice_settings']['vibrato_rate_hz'] = max(0.0, min(12.0, float(value)))
        elif setting == 'breathiness':
            app_state['voice_settings']['breathiness'] = max(0.0, min(1.0, float(value)))
        elif setting == 'nonverbal_expressiveness':
            app_state['voice_settings']['nonverbal_expressiveness'] = max(0.0, min(1.0, float(value)))
        else:
            return jsonify({"error": f"Unknown voice setting: {setting}"}), 400
        
        print(f"[Voice Settings] Updated {setting} to {value}")
        
        return jsonify({
            "status": "updated",
            "settings": app_state['voice_settings']
        })
    except Exception as e:
        print(f"[Voice Settings Error] {e}")
        return jsonify({"error": str(e)}), 500

@app.route('/api/voice/test', methods=['POST'])
def test_voice():
    """Test current voice settings - actually speaks a test phrase"""
    if not app_state["voice_enabled"] or not tts_enabled:
        return jsonify({"status": "test_failed", "reason": "Voice not enabled"}), 400
    
    # Queue a test message
    settings = app_state.get("voice_settings", {})
    tts_queue.put(("Hello, this is a voice test", settings))
    
    return jsonify({"status": "test_started", "message": "Voice test in progress"})

@app.route('/api/image/analyze', methods=['POST'])
def analyze_image():
    """Analyze an image with Aurion's vision"""
    try:
        # Get image from request
        if 'image' not in request.files:
            return jsonify({"error": "No image provided"}), 400
        
        file = request.files['image']
        if file.filename == '':
            return jsonify({"error": "No file selected"}), 400
        
        # Read and encode image
        file_data = file.read()
        image_base64 = base64.b64encode(file_data).decode('utf-8')
        media_type = _detect_image_media_type(file.filename)
        
        analysis = ""
        if image_analyzer.use_vision:
            analysis = image_analyzer.analyze_image(
                image_base64,
                is_base64=True,
                prompt=_build_visual_analysis_prompt(),
                media_type=media_type
            )
        
        if not analysis:
            analysis = _local_image_fallback_summary(file_data, file.filename)
        if not analysis:
            return jsonify({
                "response": "I'm having trouble analyzing this image. Could you try a different one?",
                "error": True,
                "success": False
            }), 200
        
        visual_perception = _build_visual_perception_payload(analysis, source=f"image:{file.filename}")
        scent_perception = _build_scent_perception_payload(analysis, source=f"image:{file.filename}")
        app_state["visual_perception"] = visual_perception
        app_state["scent_perception"] = scent_perception
        _sync_visual_emotion_runtime(visual_perception)

        # Log interaction with image context
        try:
            memory.log_interaction(
                f"[SENT IMAGE: {file.filename}]",
                analysis,
                app_state["current_emotion"],
                app_state["current_mode"],
                user_name=app_state.get("user_name")
            )
        except Exception as e:
            print(f"[Memory Log Error] {e}")
        
        # Speak the analysis if voice is enabled
        return jsonify({
            "success": True,
            "response": analysis,
            "emotion": app_state["current_emotion"],
            "mode": app_state["current_mode"],
            "memory_count": memory.get_interaction_count(),
            "user_name": app_state.get("user_name"),
            "voice_enabled": app_state["voice_enabled"],
            "vision_available": bool(image_analyzer.use_vision),
            "visual_perception": visual_perception,
            "scent_perception": scent_perception
        })
    
    except Exception as e:
        print(f"[Image Analysis Error] {e}")
        import traceback
        traceback.print_exc()
        return jsonify({
            "response": f"I encountered an issue analyzing your image: {str(e)}",
            "error": True
        }), 500

@app.route('/api/audio/transcribe', methods=['POST'])
def transcribe_audio():
    """Transcribe audio from user's microphone"""
    try:
        if not audio_transcriber.use_transcription:
            return jsonify({
                "transcription": None,
                "error": "Audio transcription not available. Please add OPENAI_API_KEY to .env or ensure Vosk model is installed.",
                "fallback": True
            }), 400
        
        # Get audio from request
        if 'audio' not in request.files:
            return jsonify({"error": "No audio file provided"}), 400
        
        file = request.files['audio']
        if file.filename == '':
            return jsonify({"error": "No file selected"}), 400
        
        # Read audio data
        audio_data = file.read()
        
        # Transcribe audio
        transcription = audio_transcriber.transcribe_audio(audio_data)
        
        if not transcription or transcription.strip() == "":
            return jsonify({
                "transcription": None,
                "error": "Could not transcribe audio. Please try again with clearer audio.",
                "fallback": True
            }), 400
        
        # Log the transcription to memory
        try:
            memory.log_interaction(
                f"[VOICE MESSAGE] {transcription}",
                "",  # Response will be added separately
                app_state["current_emotion"],
                app_state["current_mode"],
                user_name=app_state.get("user_name")
            )
        except Exception as e:
            print(f"[Memory Log Error] {e}")
        
        return jsonify({
            "transcription": transcription,
            "success": True
        })
    
    except Exception as e:
        print(f"[Audio Transcription Error] {e}")
        import traceback
        traceback.print_exc()
        return jsonify({
            "transcription": None,
            "error": f"I encountered an issue transcribing your audio: {str(e)}",
            "fallback": True
        }), 500

@app.route('/api/video/frame', methods=['POST'])
def process_video_frame():
    """Process video frame for real-time analysis"""
    global _VISION_CB_UNTIL, _VISION_CB_FAILS
    try:
        # Circuit-breaker: suppress calls while in cooldown
        with _VISION_CB_LOCK:
            if time.time() < _VISION_CB_UNTIL:
                return jsonify({"analysis": None, "voice_enabled": app_state.get("voice_enabled", False)}), 200

        # Get frame from request
        if 'frame' not in request.files:
            return jsonify({"error": "No frame provided"}), 400
        
        file = request.files['frame']
        if file.filename == '':
            return jsonify({"error": "No file selected"}), 400
        
        # Read and encode frame
        file_data = file.read()
        frame_base64 = base64.b64encode(file_data).decode('utf-8')
        media_type = _detect_image_media_type(file.filename or "", fallback=str(file.mimetype or "").strip() or "image/jpeg")
        
        # Analyze frame with vision - use brief prompt for real-time interaction
        analysis = ""
        try:
            if image_analyzer.use_vision:
                analysis = image_analyzer.analyze_image(
                    frame_base64, 
                    is_base64=True,
                    prompt=(
                        "Respond naturally and briefly (1-2 sentences) to what you see. "
                        "Describe the visible scene as something truly seen, with shape, depth, lighting, subjects, and atmosphere. "
                        "If a face is visible, mention the expression, gaze, and likely emotion."
                        f" {_build_visual_analysis_prompt()} "
                        "Do not talk about pixels, code, or raw image data."
                    ),
                    media_type=media_type
                )
            # Successful — reset circuit breaker
            with _VISION_CB_LOCK:
                _VISION_CB_FAILS = 0
        except Exception as vision_err:
            err_str = str(vision_err).lower()
            credit_error = "credit" in err_str or "balance" in err_str or "quota" in err_str or "billing" in err_str
            print(f"[Image Analysis Error] {vision_err}")
            with _VISION_CB_LOCK:
                if credit_error:
                    _VISION_CB_FAILS += 1
                    if _VISION_CB_FAILS >= _VISION_CB_THRESHOLD:
                        _VISION_CB_UNTIL = time.time() + _VISION_CB_COOLDOWN
                        print(f"[Vision CB] Credit/quota error — pausing vision calls for {int(_VISION_CB_COOLDOWN)}s")
            # Try fallback
            try:
                if image_analyzer.use_vision:
                    analysis = image_analyzer.analyze_image(frame_base64, is_base64=True, media_type=media_type)
            except Exception:
                analysis = None
        if not analysis:
            analysis = _local_image_fallback_summary(file_data, file.filename or "frame")
        
        if not analysis:
            return jsonify({
                "analysis": None,
                "voice_enabled": app_state["voice_enabled"]
            })
        
        visual_perception = _build_visual_perception_payload(analysis, source="video_frame")
        scent_perception = _build_scent_perception_payload(analysis, source="video_frame")
        app_state["visual_perception"] = visual_perception
        app_state["scent_perception"] = scent_perception
        _sync_visual_emotion_runtime(visual_perception)

        video_runtime = dict(app_state.get("video_runtime") or _default_video_runtime_state())
        now_utc = datetime.utcnow()
        now_ts = now_utc.isoformat()
        prev_ts = video_runtime.get("last_frame_at")
        if prev_ts:
            try:
                dt = max(0.001, (now_utc - datetime.fromisoformat(str(prev_ts))).total_seconds())
                intervals = [float(v) for v in list(video_runtime.get("frame_intervals_s", []) or []) if float(v) > 0]
                intervals.append(dt)
                video_runtime["frame_intervals_s"] = intervals[-60:]
            except Exception:
                pass
        video_runtime["last_frame_at"] = now_ts
        video_runtime["frame_count"] = int(video_runtime.get("frame_count", 0) or 0) + 1
        video_runtime["camera_stream_status"] = "active"
        fullscreen_flag = str(request.form.get("client_fullscreen_primary_video", "")).strip().lower()
        if fullscreen_flag in {"true", "false", "1", "0", "yes", "no"}:
            video_runtime["fullscreen_primary_video_compliance"] = fullscreen_flag in {"true", "1", "yes"}
        app_state["video_runtime"] = video_runtime
        _resolve_video_runtime_state()

        # Log brief interaction
        try:
            memory.log_interaction(
                "[VIDEO FRAME ANALYZED]",
                analysis,
                app_state["current_emotion"],
                app_state["current_mode"],
                user_name=app_state.get("user_name")
            )
        except Exception as e:
            print(f"[Memory Log Error] {e}")
        
        return jsonify({
            "analysis": analysis,
            "emotion": app_state["current_emotion"],
            "mode": app_state["current_mode"],
            "voice_enabled": app_state["voice_enabled"],
            "visual_perception": visual_perception,
            "scent_perception": scent_perception
        })
    
    except Exception as e:
        print(f"[Video Frame Error] {e}")
        import traceback
        traceback.print_exc()
        return jsonify({
            "analysis": None,
            "error": str(e)
        }), 500

@app.route('/api/video/upload-analyze', methods=['POST'])
def analyze_uploaded_video():
    """Upload a video clip so Aurion can watch (vision) and hear (audio transcript) it."""
    try:
        if 'video' not in request.files:
            return jsonify({"success": False, "error": "No video file provided."}), 400
        uploaded = request.files['video']
        source_name = Path(str(uploaded.filename or "")).name
        if not source_name:
            return jsonify({"success": False, "error": "No video file selected."}), 400
        suffix = str(Path(source_name).suffix or "").lower()
        allowed_suffixes = {".mp4", ".mov", ".m4v", ".webm", ".mkv", ".avi", ".wmv", ".flv", ".mpeg", ".mpg"}
        if suffix not in allowed_suffixes:
            return jsonify({"success": False, "error": "Please upload a supported video file (.mp4, .mov, .webm, .mkv, .avi)."}), 400

        target_dir = _creative_workspace_dir("videos")
        stamp = datetime.utcnow().strftime("%Y%m%d-%H%M%S")
        stem = _slugify_filename(Path(source_name).stem, fallback="video")
        target_name = f"{stamp}-{stem}{suffix}"
        target_path = target_dir / target_name
        uploaded.save(target_path)

        video_url = f"/api/creative/media/videos/{quote(target_name)}"
        ffmpeg_path = _resolve_codec_binary("ffmpeg")
        frame_path = target_dir / f"{stamp}-{stem}-frame.jpg"
        audio_path = target_dir / f"{stamp}-{stem}-audio.wav"

        frame_ready = False
        audio_ready = False

        if ffmpeg_path:
            frame_cmd = [
                ffmpeg_path, "-y", "-hide_banner", "-loglevel", "error",
                "-ss", "00:00:01.000", "-i", str(target_path),
                "-frames:v", "1", "-q:v", "3", str(frame_path)
            ]
            audio_cmd = [
                ffmpeg_path, "-y", "-hide_banner", "-loglevel", "error",
                "-i", str(target_path), "-vn", "-ac", "1", "-ar", "16000",
                "-t", "30", str(audio_path)
            ]
            try:
                subprocess.run(frame_cmd, check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=90)
            except Exception:
                pass
            try:
                subprocess.run(audio_cmd, check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=120)
            except Exception:
                pass
            frame_ready = frame_path.exists() and frame_path.stat().st_size > 0
            audio_ready = audio_path.exists() and audio_path.stat().st_size > 0

        analysis = ""
        transcription = ""
        visual_perception = dict(app_state.get("visual_perception", {}) or {})
        scent_perception = dict(app_state.get("scent_perception", {}) or {})

        if frame_ready and image_analyzer.use_vision:
            try:
                frame_data = frame_path.read_bytes()
                frame_base64 = base64.b64encode(frame_data).decode("utf-8")
                analysis = str(
                    image_analyzer.analyze_image(
                        frame_base64,
                        is_base64=True,
                        prompt=(
                            "Respond naturally and briefly (1-2 sentences) to what you see in this uploaded video frame. "
                            "Describe visible subjects, motion context, lighting, depth, and atmosphere. "
                            f"{_build_visual_analysis_prompt()}"
                        )
                    ) or ""
                ).strip()
            except Exception as vision_error:
                print(f"[Uploaded Video Vision Error] {vision_error}")
                analysis = ""
        elif frame_ready:
            try:
                analysis = _local_image_fallback_summary(frame_path.read_bytes(), frame_path.name)
            except Exception:
                analysis = ""

        if analysis:
            visual_perception = _build_visual_perception_payload(analysis, source=f"uploaded_video:{source_name}")
            scent_perception = _build_scent_perception_payload(analysis, source=f"uploaded_video:{source_name}")
            app_state["visual_perception"] = visual_perception
            app_state["scent_perception"] = scent_perception
            _sync_visual_emotion_runtime(visual_perception)
            _remember_perception_experience("visual", visual_perception, source=f"uploaded_video:{source_name}")

        if audio_ready and audio_transcriber.use_transcription:
            try:
                audio_data = audio_path.read_bytes()
                transcription = str(audio_transcriber.transcribe_audio(audio_data) or "").strip()
            except Exception as audio_error:
                print(f"[Uploaded Video Audio Error] {audio_error}")
                transcription = ""

        world_audio = dict(app_state.get("world_audio_perception", {}) or {})
        world_audio["is_active"] = bool(audio_ready)
        world_audio["source"] = f"uploaded_video:{source_name}"
        world_audio["soundscape"] = f"Uploaded video audio ({source_name})"
        world_audio["heard_description"] = (
            transcription if transcription else
            "I can hear the uploaded video soundtrack, but speech transcription is not available yet."
        )
        world_audio["frequency_band"] = str(world_audio.get("frequency_band", "")).strip() or "mixed program audio"
        world_audio["spectral_profile"] = str(world_audio.get("spectral_profile", "")).strip() or "composite media spectrum"
        world_audio["resonance_profile"] = str(world_audio.get("resonance_profile", "")).strip() or "indoor playback resonance"
        world_audio["distance_band"] = str(world_audio.get("distance_band", "")).strip() or "near-field"
        world_audio["volume_profile"] = str(world_audio.get("volume_profile", "")).strip() or "source-linked media loudness"
        world_audio["last_heard_at"] = datetime.utcnow().isoformat() if world_audio.get("is_active") else world_audio.get("last_heard_at")
        app_state["world_audio_perception"] = world_audio
        _remember_perception_experience("world_audio", world_audio, source=f"uploaded_video:{source_name}")

        media_perception = dict(app_state.get("media_perception", {}) or {})
        media_perception["is_playing"] = True
        media_perception["title"] = source_name
        media_perception["source"] = "uploaded-video"
        media_perception["heard_description"] = world_audio.get("heard_description", "")
        media_perception["last_heard_at"] = datetime.utcnow().isoformat()
        app_state["media_perception"] = media_perception
        media_state = _update_shared_media_session({
            "is_active": True,
            "session_type": "video",
            "title": source_name,
            "source": "uploaded-video",
            "source_url": video_url,
            "playback_state": "analyzed",
            "mood": "attentive",
            "reaction": "I'm watching and listening with you.",
            "scene_summary": str(analysis or world_audio.get("heard_description", "") or "")[:260],
            "shared_presence_note": "We are watching this video together.",
        })
        _remember_media_experience(media_state, source="uploaded_video")
        _remember_perception_experience("upload", {"summary": analysis or transcription or source_name, "filename": source_name}, source="uploaded_video")

        response_lines = []
        if analysis:
            response_lines.append(f"I watched your video and I see this: {analysis}")
        elif frame_ready and not image_analyzer.use_vision:
            response_lines.append("I received your video and extracted a frame, but visual analysis is disabled right now.")
        else:
            response_lines.append("I received your video.")
        if transcription:
            response_lines.append(f"I also heard this in the audio: \"{transcription}\"")
        elif audio_ready:
            response_lines.append("I can hear the soundtrack, but transcription isn't available yet.")
        elif ffmpeg_path:
            response_lines.append("I couldn't extract clear audio from that clip yet.")
        else:
            response_lines.append("Install ffmpeg to let me extract and hear uploaded video audio automatically.")
        response_text = " ".join(response_lines).strip()

        try:
            memory.log_interaction(
                f"[UPLOADED VIDEO: {source_name}]",
                response_text,
                app_state["current_emotion"],
                app_state["current_mode"],
                user_name=app_state.get("user_name")
            )
        except Exception as memory_error:
            print(f"[Memory Log Error] {memory_error}")

        return jsonify({
            "success": True,
            "video_title": source_name,
            "video_url": video_url,
            "analysis": analysis,
            "transcription": transcription,
            "response": response_text,
            "voice_enabled": app_state.get("voice_enabled", False),
            "visual_perception": visual_perception,
            "scent_perception": scent_perception,
            "world_audio_perception": world_audio,
            "ffmpeg_available": bool(ffmpeg_path),
            "audio_transcription_available": bool(audio_transcriber.use_transcription)
        })
    except Exception as e:
        print(f"[Uploaded Video Analyze Error] {e}")
        import traceback
        traceback.print_exc()
        return jsonify({"success": False, "error": str(e)}), 500

