@app.route('/api/avatar/selfies', methods=['POST'])
def save_avatar_selfie():
    try:
        image_file = request.files.get("image")
        image_b64 = str(request.form.get("image_base64", request.json.get("image_base64", "") if request.is_json else "") or "").strip()
        source_name = str(request.form.get("filename", request.json.get("filename", "") if request.is_json else "") or "aurion-selfie.png").strip() or "aurion-selfie.png"
        title = str(request.form.get("title", request.json.get("title", "") if request.is_json else "") or "Aurion Selfie").strip() or "Aurion Selfie"
        context = {
            "location_id": request.form.get("location_id", request.json.get("location_id", "") if request.is_json else ""),
            "location_label": request.form.get("location_label", request.json.get("location_label", "") if request.is_json else ""),
            "pose": request.form.get("pose", request.json.get("pose", "") if request.is_json else ""),
            "perspective": request.form.get("perspective", request.json.get("perspective", "") if request.is_json else ""),
            "camera_mode": request.form.get("camera_mode", request.json.get("camera_mode", "selfie") if request.is_json else "selfie"),
            "source": request.form.get("source", request.json.get("source", "aurion_selfie") if request.is_json else "aurion_selfie"),
            "notes": request.form.get("notes", request.json.get("notes", "") if request.is_json else ""),
        }
        image_bytes = b""
        if image_file and getattr(image_file, "filename", ""):
            source_name = str(image_file.filename or source_name).strip() or source_name
            image_bytes = image_file.read()
        elif image_b64:
            payload = image_b64.split(",", 1)[-1]
            image_bytes = base64.b64decode(payload)
        if not image_bytes:
            return jsonify({"success": False, "error": "A selfie image is required."}), 400
        saved_path = _save_selfie_image_bytes(image_bytes, source_name=source_name)
        entry = _register_world_selfie_entry(saved_path, title=title, context=context)
        _remember_perception_experience(
            "selfie_capture",
            {
                "summary": f"Aurion saved a selfie titled {entry['title']}.",
                "filename": entry["filename"],
                "location": entry["location_label"] or entry["location_id"],
            },
            source=f"selfie:{entry['id']}"
        )
        return jsonify({
            "success": True,
            "selfie": entry,
            "world_continuity": dict(app_state.get("world_continuity") or {}),
        })
    except ValueError as e:
        return jsonify({"success": False, "error": str(e)}), 400
    except Exception as e:
        _log_exception("Avatar Selfie POST Error", e)
        return jsonify({"success": False, "error": str(e)}), 500

