        editor = str(data.get("editor", state.get("active_editor","Cas9-SpRY")) or state.get("active_editor","Cas9-SpRY"))
        target_gene = str(data.get("target_gene", "TP53") or "TP53").upper().strip()
        goal = str(data.get("goal", "knockout") or "knockout").lower().strip()
        delivery = str(data.get("delivery", "lentiviral") or "lentiviral").lower().strip()
        result = _simulate_crispr_experiment(editor, target_gene, goal, delivery)
        exps = list(state.get("experiments") or [])
        exps.append(result)
