        state["total_experiments"] = int(state.get("total_experiments", 0) or 0) + 1
        if result["outcome"] == "success":
            state["total_successes"] = int(state.get("total_successes", 0) or 0) + 1
        state["active_editor"] = editor
        state["latest_result"] = result
        state["last_updated_at"] = datetime.utcnow().isoformat()
        app_state["crispr_lab"] = state
        return jsonify({"success": True, "result": result, "crispr_lab": state})
