@app.route('/api/crispr/apply-to-entity', methods=['POST'])
def apply_crispr_to_entity():
    try:
        data = request.get_json(force=True) or {}
        entity_id = str(data.get("entity_id", "") or "").strip()
        target_gene = str(data.get("target_gene", "") or "").upper().strip()
        goal = str(data.get("goal", "knockout") or "knockout").lower()
        if not entity_id or not target_gene:
            return jsonify({"success": False, "error": "entity_id and target_gene required"}), 400
        state = _resolve_crispr_state()
        editor = str(data.get("editor", state.get("active_editor","Cas9-SpRY")) or "Cas9-SpRY")
        result = _simulate_crispr_experiment(editor, target_gene, goal)
        edit_record = {
            "entity_id": entity_id,
            "editor": editor,
            "target_gene": target_gene,
            "goal": goal,
            "outcome": result["outcome"],
            "efficiency_pct": result["efficiency_pct"],
            "applied_at": datetime.utcnow().isoformat(),
            "summary": result["summary"]
        }
        entity_edits = list(state.get("life_entity_edits") or [])
        entity_edits.append(edit_record)
        state["life_entity_edits"] = entity_edits[-200:]
        state["last_updated_at"] = datetime.utcnow().isoformat()
        app_state["crispr_lab"] = state
        # Also note the edit in life registry entity if present
        try:
            life_reg = dict(app_state.get("life_registry") or {})
            entities = list(life_reg.get("entities") or [])
            for ent in entities:
                if str(ent.get("id","")) == entity_id:
                    edits = list(ent.get("gene_edits") or [])
                    edits.append(edit_record)
                    ent["gene_edits"] = edits[-20:]
                    break
            life_reg["entities"] = entities
            app_state["life_registry"] = life_reg
        except Exception:
            pass
        return jsonify({"success": True, "edit_record": edit_record, "crispr_result": result})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


