@app.route('/api/physics/lattice-quantum', methods=['GET'])
def get_lattice_qthermo():
    try:
        return jsonify({"success": True, "lattice_qthermo": _resolve_lattice_qthermo_state()})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

@app.route('/api/physics/lattice-quantum', methods=['POST'])
def update_lattice_qthermo():
    try:
        data = request.get_json(force=True) or {}
        state = _resolve_lattice_qthermo_state()
        numeric_fields = [
            "temperature_mK", "coupling_strength_J", "hopping_amplitude_t",
            "chemical_potential_mu", "magnetic_flux_phi", "lattice_sites"
        ]
        string_fields = ["lattice_type", "notes"]
        for f in numeric_fields:
            if f in data:
                try:
                    state[f] = float(data[f])
                except Exception:
                    pass
        for f in string_fields:
            if f in data:
                state[f] = str(data[f] or "")[:200]
        # Run simulation with new params
        sim = _simulate_lattice_qthermo(state)
        for k in ("phase","order_parameter","entropy_per_site","specific_heat_R",
                  "correlation_length_sites","entanglement_entropy_bits",
                  "quasiparticle_gap_meV","topological_invariant"):
            state[k] = sim[k]
        if sim.get("insight"):
            insights = list(state.get("insights") or [])
            if sim["insight"] not in insights:
                insights.append(sim["insight"])
            state["insights"] = insights[-50:]
        hist = list(state.get("simulation_history") or [])
        hist.append(sim)
        state["simulation_history"] = hist[-20:]
        state["last_simulation_at"] = sim["simulated_at"]
        app_state["lattice_qthermo"] = state
        return jsonify({"success": True, "lattice_qthermo": state, "simulation": sim})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

@app.route('/api/physics/lattice-quantum/simulate', methods=['POST'])
def simulate_lattice_qthermo():
    try:
        data = request.get_json(force=True) or {}
        state = _resolve_lattice_qthermo_state()
        params = {**state, **{k: v for k, v in data.items() if k in (
            "temperature_mK","coupling_strength_J","hopping_amplitude_t",
            "chemical_potential_mu","magnetic_flux_phi","lattice_type","lattice_sites"
        )}}
        sim = _simulate_lattice_qthermo(params)
        hist = list(state.get("simulation_history") or [])
        hist.append(sim)
        state["simulation_history"] = hist[-20:]
        state["last_simulation_at"] = sim["simulated_at"]
        for k in ("phase","order_parameter","entropy_per_site","specific_heat_R",
                  "correlation_length_sites","entanglement_entropy_bits",
                  "quasiparticle_gap_meV","topological_invariant"):
            state[k] = sim[k]
        if sim.get("insight"):
            insights = list(state.get("insights") or [])
            if sim["insight"] not in insights:
                insights.append(sim["insight"])
            state["insights"] = insights[-50:]
        app_state["lattice_qthermo"] = state
        return jsonify({"success": True, "simulation": sim, "lattice_qthermo": state})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


